/* TRONWELL Conversation Club · Pronunciation Lab · 63 units */
var PRON = [{"id":"a0-1","lv":"A0","n":1,"title":"The English alphabet: spelling your name","focus":"sounds","goal":"Say and understand the English letter names, and spell your name and email.","goal_es":"Decir y entender los nombres de las letras en inglés, y deletrear tu nombre y tu correo.","explain":["English letters have their own names. Three vowels are very different from Spanish: A sounds like 'ei' (like say), E like 'ii' (like see) and I like 'ai' (like my). Learn these three first!","Watch these letters too: G and J start like 'job', but G rhymes with see and J rhymes with say. Y is 'why', W is 'double U', H is 'aitch' and R is 'ar' (like car). For emails, say 'at' (@) and 'dot' (.)."],"explain_es":["Las letras en inglés tienen sus propios nombres. Tres vocales son muy distintas al español: A suena 'ei' (como say), E suena 'ii' (como see) e I suena 'ai' (como my). ¡Aprende estas tres primero!","Cuidado también: G y J empiezan como 'job', pero G suena 'yii' (rima con see) y J suena 'yei' (rima con say). Y es 'uai' (como why), W es 'dábel iu', H es 'eich' y R es 'ar' (como car). En un correo, di 'at' (@) y 'dot' (.)."],"spanish":"Because of Spanish, when you hear 'ii' you may write I, and when you hear 'ei' you may write E. Remember: 'ei' = A, 'ii' = E, 'ai' = I, 'yii' = G, 'yei' = J.","spanish_es":"Por el español, cuando escuchas 'ii' es fácil escribir I, y cuando escuchas 'ei', escribir E. Recuerda: 'ei' = A, 'ii' = E, 'ai' = I, 'yii' = G, 'yei' = J.","ex":[{"t":"A, E, I","how":"ei | ii | ai","note":"A like say, E like see, I like my"},{"t":"G, J","how":"yii | yei","note":"G rhymes with see; J rhymes with say"},{"t":"Y, W","how":"uai | DA-bel-iu","note":"Y = why; W = double U"},{"t":"H, R","how":"eich | ar","note":"R like car (British: 'ah')"},{"t":"P, A, Z","how":"pii | ei | zii","note":"Paz · Z = zee (British: zed)"},{"t":"D, I, E, G, O","how":"dii | ai | ii | yii | ou","note":"Diego"},{"t":"J, A, V, I, E, R, A","how":"yei | ei | vii | ai | ii | ar | ei","note":"Javiera"},{"t":"ana at gmail dot com","how":"ana at yii-meil dot com","note":"ana@gmail.com · @ = at, . = dot"}],"listen":[{"q":"Which letter do you hear?","o":["E","I"],"pick":true,"why":"E sounds 'ii'; I sounds 'ai'."},{"q":"Which letter do you hear?","o":["G","J"],"pick":true,"why":"G sounds 'yii' (like see); J sounds 'yei' (like say)."},{"q":"Which name do you hear?","o":["I, V, A, N","E, V, A, N"],"pick":true,"why":"I = 'ai' (Ivan); E = 'ii' (Evan)."},{"q":"Which name do you hear?","o":["S, A, R, A","S, A, R, A, H"],"pick":true,"why":"Sarah ends in H = 'eich'; Sara ends in A = 'ei'."},{"q":"Which name do you hear?","o":["D, A, N, I","D, A, N, Y"],"pick":true,"why":"I = 'ai'; Y = 'uai' (like why)."},{"q":"Which letter is it?","say":"W","o":["U","V","W"],"a":2,"why":"W is 'double U' (DA-bel-iu), not 'doble ve'."},{"q":"Which letter is it?","say":"H","o":["A","H","J"],"a":1,"why":"H = 'eich'; A = 'ei'; J = 'yei'."},{"q":"Which name is it?","say":"M, A, R, Y","o":["Mary","Mery","Mari"],"a":0,"why":"M-A-R-Y: A = 'ei', R = 'ar', Y = 'uai'."}],"mark":[{"mode":"find","q":"Tap the letters with an 'ii' sound (like see).","w":["A","B","E","I","P"],"a":[1,2,4],"why":"B = 'bii', E = 'ii', P = 'pii'. A = 'ei', I = 'ai'."},{"mode":"find","q":"Tap the letters with an 'ei' sound (like say).","w":["A","E","H","J","K","Y"],"a":[0,2,3,4],"why":"A = 'ei', H = 'eich', J = 'yei', K = 'kei'."},{"mode":"find","q":"Tap the letters with an 'ai' sound (like my).","w":["I","E","Y","R","A"],"a":[0,2],"why":"I = 'ai' and Y = 'uai'. R = 'ar'."},{"mode":"find","q":"Tap the letters that start like 'job'.","w":["G","J","Y","H","K"],"a":[0,1],"why":"G = 'yii' and J = 'yei' start like job."},{"mode":"stress","q":"Tap the stressed syllable.","w":["al","pha","bet"],"word":true,"a":[0],"why":"AL-pha-bet: stress at the start (Spanish: alfaBEto)."}],"dict":[{"say":"J, O, R, G, E","a":"Jorge","alt":["J O R G E"],"how":"yei | ou | ar | yii | ii","why":"J = 'yei', R = 'ar', G = 'yii', E = 'ii'."},{"say":"I, G, N, A, C, I, O","a":"Ignacio","alt":["I G N A C I O"],"how":"ai | yii | en | ei | sii | ai | ou","why":"I = 'ai', G = 'yii', A = 'ei', C = 'sii'."},{"say":"W, A, L, T, E, R","a":"Walter","alt":["W A L T E R"],"how":"DA-bel-iu | ei | el | tii | ii | ar","why":"W = 'double U', E = 'ii', R = 'ar'."},{"say":"sofia at gmail dot com","a":"sofia@gmail.com","alt":["sofia at gmail dot com"],"how":"so-FII-a at yii-meil dot com","why":"@ = 'at', . = 'dot'; gmail starts with G = 'yii'."},{"say":"Can you spell that?","a":"Can you spell that?","how":"k'n-yu SPELL that?","why":"can you joins: k'n-yu; the stress is on spell."}],"tip":"In class: pairs spell their full name and email to each other and write them down, then check every A, E, I, G and J together."},{"id":"a0-2","lv":"A0","n":2,"title":"Numbers: thirteen or thirty?","focus":"stress","goal":"Hear and say the difference between -teen and -ty numbers, and say prices and phone numbers.","goal_es":"Escuchar y decir la diferencia entre los números en -teen y en -ty, y decir precios y números de teléfono.","explain":["Numbers 13–19 end in -teen. The stress is on teen, and it is long: thir-TEEN, four-TEEN. Numbers 30, 40, 50… end in -ty. The stress is at the start, and the end is short: THIR-ty, FOR-ty. In American English, thirty sounds like 'THIR-dee'.","With a word after it, the stress can move: FIF-teen dollars. But the long 'teen' with n is still there. Say phone numbers one digit at a time: nine, one, three… For 0, say 'zero' or 'oh'."],"explain_es":["Los números del 13 al 19 terminan en -teen. El acento va en teen, y es largo: thir-TEEN, four-TEEN. Los números 30, 40, 50… terminan en -ty. El acento va al principio y el final es corto: THIR-ty, FOR-ty. En inglés americano, thirty suena casi 'THIR-di'.","Con otra palabra después, el acento puede moverse: FIF-teen dollars. Pero el 'teen' largo, con n, se mantiene. Los números de teléfono se dicen dígito por dígito: nine, one, three… Para el 0, di 'zero' u 'oh'."],"spanish":"Spanish speakers often say thirteen and thirty with the same rhythm, so people hear the wrong number. Make -teen long and strong, with a clear n; keep -ty short.","spanish_es":"Muchos hispanohablantes dicen thirteen y thirty con el mismo ritmo, y el otro escucha un número equivocado. Haz el -teen largo y fuerte, con una n clara; el -ty, corto.","ex":[{"t":"thirteen","how":"thir-TEEN","note":"long 'teen' with n"},{"t":"thirty","how":"THIR-dee","note":"short end; the t sounds like a soft d (British: a clear t)"},{"t":"fourteen, forty","how":"for-TEEN | FOR-dee"},{"t":"fifteen, fifty","how":"fif-TEEN | FIF-tee"},{"t":"eighteen, eighty","how":"ei-TEEN | EI-dee"},{"t":"fifteen dollars","how":"fif-teen DOL-erz","note":"the stress can move to FIF-, but 'teen' is still long"},{"t":"Gate nineteen","how":"geit nain-TEEN","note":"at the end, -TEEN is strong"},{"t":"9 1 3 0 7 4","how":"nine | one | three | zero | seven | four","note":"phone numbers: one digit at a time; 0 = zero or oh"}],"listen":[{"q":"Which number do you hear?","o":["13","30"],"pick":true,"why":"13 = thir-TEEN (long, with n); 30 = THIR-ty (short end)."},{"q":"Which gate do you hear?","o":["Gate 14","Gate 40"],"pick":true,"why":"14 = for-TEEN (long, with n); 40 = FOR-ty (short end)."},{"q":"Which price do you hear?","o":["$15","$50"],"pick":true,"why":"15 has a long 'teen' with n; 50 ends in a short 'tee'."},{"q":"Which number do you hear?","o":["17","70"],"pick":true,"why":"17 = seven-TEEN; 70 = SEV-en-ty."},{"q":"Which bus do you hear?","o":["Bus 18","Bus 80"],"pick":true,"why":"18 = ei-TEEN (long, with n); 80 = EI-dee (short end)."},{"q":"Where is the stress?","say":"nineteen","o":["first syllable: NINE-teen","second syllable: nine-TEEN"],"a":1,"why":"-teen numbers: the stress is on teen."},{"q":"Where is the stress?","say":"sixty","o":["first syllable: SIX-ty","second syllable: six-TY"],"a":0,"why":"-ty numbers: the stress is at the start."},{"q":"Which phone number do you hear?","say":"nine, one, three, zero, seven, four","o":["913 074","930 074","913 704"],"a":0,"why":"One digit at a time: nine, one, three, zero, seven, four."}],"mark":[{"mode":"stress","q":"Tap the stressed syllable.","w":["thir","teen"],"word":true,"a":[1],"why":"thir-TEEN"},{"mode":"stress","q":"Tap the stressed syllable.","w":["for","ty"],"word":true,"a":[0],"why":"FOR-ty"},{"mode":"stress","q":"Tap the stressed syllable.","w":["sev","en","teen"],"word":true,"a":[2],"why":"sev-en-TEEN"},{"mode":"stress","q":"Tap the stressed syllable.","w":["eigh","ty"],"word":true,"a":[0],"why":"EIGH-ty (EI-dee)"},{"mode":"find","q":"Tap the numbers with the stress at the end.","w":["thirteen","forty","fifteen","sixty","eighteen","ninety"],"a":[0,2,4],"why":"thir-TEEN, fif-TEEN, eigh-TEEN; FOR-ty, SIX-ty, NINE-ty."}],"dict":[{"say":"thirteen dollars","a":"thirteen dollars","alt":["13 dollars"],"how":"thir-teen DOL-erz","why":"The long 'teen' with n tells you it is 13, not 30."},{"say":"forty minutes","a":"forty minutes","alt":["40 minutes"],"how":"FOR-dee MIN-its","why":"FOR-ty: stress at the start; the t sounds like a soft d."},{"say":"Gate nineteen","a":"Gate nineteen","alt":["Gate 19"],"how":"geit nain-TEEN","why":"-TEEN at the end is long and strong."},{"say":"It's fifty dollars.","a":"It's fifty dollars.","alt":["It's 50 dollars."],"how":"its FIF-tee DOL-erz","why":"FIF-ty: stress at the start, a short end, no n."},{"say":"nine, one, three, zero","a":"9130","alt":["9 1 3 0","nine one three zero"],"how":"nine | one | three | zero","why":"Phone numbers go digit by digit: 'one, three', not 'thirteen'."}],"tip":"In class: say a -teen or -ty number; students open their arms wide for -teen (long) or clap once for -ty (short). Then pairs dictate prices and phone numbers to each other."},{"id":"a0-3","lv":"A0","n":3,"title":"Ship or sheep? Short i and long ee","focus":"sounds","goal":"Hear and say the difference between short /ɪ/ (ship) and long /iː/ (sheep).","goal_es":"Escuchar y decir la diferencia entre la /ɪ/ corta (ship) y la /iː/ larga (sheep).","explain":["English has two 'i' sounds. The long one, /iː/, is in sheep, seat and eat. It is like Spanish 'i', but longer and tense. Smile a little: sheeep.","The short one, /ɪ/, is in ship, sit and fish. Relax your mouth and keep it short: it is between Spanish 'i' and 'e'. Spelling help: ee and ea are often long (see, eat); one i is often short (sit)."],"explain_es":["El inglés tiene dos sonidos de 'i'. La larga, /iː/, está en sheep, seat y eat. Es como la 'i' del español, pero más larga y tensa. Sonríe un poco: sheeep.","La corta, /ɪ/, está en ship, sit y fish. Relaja la boca y hazla corta: suena entre la 'i' y la 'e' del español. Ayuda con la ortografía: ee y ea suelen ser largas (see, eat); una sola i suele ser corta (sit)."],"spanish":"Spanish has only one 'i', so Spanish speakers often say ship and sheep the same. Make /iː/ long, with a little smile, and /ɪ/ short and relaxed.","spanish_es":"El español tiene una sola 'i', por eso muchos dicen ship y sheep igual. Haz la /iː/ larga, con una pequeña sonrisa, y la /ɪ/ corta y relajada.","ex":[{"t":"ship, sheep","how":"ship | sheeep","note":"short | long"},{"t":"sit, seat","how":"sit | seeet"},{"t":"fill, feel","how":"fil | feeel"},{"t":"it, eat","how":"it | eeet"},{"t":"chip, cheap","how":"chip | cheeep"},{"t":"Where do you live?","how":"wer-da-yu LIV?","note":"live: short i"},{"t":"When do you leave?","how":"wen-da-yu LEEEV?","note":"leave: long ee"},{"t":"Sit in this seat.","how":"si-tin this SEEET","note":"three short, one long"}],"listen":[{"q":"Which word do you hear?","o":["ship","sheep"],"pick":true,"why":"ship is short and relaxed; sheep is long, with a smile."},{"q":"Which word do you hear?","o":["sit","seat"],"pick":true,"why":"sit is short; seat is long."},{"q":"Which word do you hear?","o":["fill","feel"],"pick":true,"why":"fill is short; feel is long."},{"q":"Which word do you hear?","o":["it","eat"],"pick":true,"why":"it is short; eat is long."},{"q":"Which word do you hear?","say":"I want to leave.","o":["live","leave"],"a":1,"why":"Long 'ee': leave (= go away)."},{"q":"Which sentence do you hear?","o":["Don't slip.","Don't sleep."],"pick":true,"why":"slip is short; sleep is long."},{"q":"Short or long?","say":"green","o":["short (like ship)","long (like sheep)"],"a":1,"why":"green has a long 'ee'."},{"q":"How many long 'ee' sounds do you hear?","say":"Please sit in this seat.","o":["1","2","3"],"a":1,"why":"please and seat are long; sit, in and this are short."}],"mark":[{"mode":"find","q":"Tap the words with a long 'ee' (like sheep).","w":["eat","it","seat","sit","feel"],"a":[0,2,4],"why":"eat, seat, feel = long; it, sit = short."},{"mode":"find","q":"Tap the words with a short 'i' (like ship).","w":["Is","this","your","seat?"],"a":[0,1],"why":"is, this = short; seat = long."},{"mode":"find","q":"Tap the words with a long 'ee' (like sheep).","w":["Meet","me","at","six"],"a":[0,1],"why":"meet, me = long; six = short."},{"mode":"find","q":"Tap the words with a short 'i' (like ship).","w":["Sit","in","the","green","seat"],"a":[0,1],"why":"sit, in = short; green, seat = long."},{"mode":"find","q":"Tap the words with a long 'ee' (like sheep).","w":["We","need","three","big","rooms"],"a":[0,1,2],"why":"we, need, three = long; big = short."}],"dict":[{"say":"a cheap ticket","a":"a cheap ticket","how":"a CHEEP TIK-it","why":"cheap = long ee; ticket = short i (TIK-it)."},{"say":"Please sit down.","a":"Please sit down.","how":"pleez sit DOWN","why":"please = long ee; sit = short i."},{"say":"I need six eggs.","a":"I need six eggs.","how":"ai need SIK-segz","why":"need = long ee; six = short i; six_eggs join."},{"say":"They live with me.","a":"They live with me.","how":"they LIV with mee","why":"live, with = short i; me = long ee."},{"say":"Is it free?","a":"Is it free?","how":"i-zit FREE?","why":"is, it = short i; free = long ee; is_it join."}],"tip":"In class: say one word from a pair (ship/sheep, sit/seat); students smile wide for the long 'ee' or relax their face for the short 'i'. Then pairs test each other."},{"id":"a0-4","lv":"A0","n":4,"title":"B and V: very, not berry","focus":"sounds","goal":"Say a real English v (top teeth on the lower lip) and hear the difference from b.","goal_es":"Pronunciar una v inglesa de verdad (dientes de arriba sobre el labio de abajo) y escuchar la diferencia con la b.","explain":["In Spanish, b and v sound the same. In English they are two different sounds. For b, close both lips and open them: boat, best, berry.","For v, put your top teeth on your lower lip and push air. You hear a buzz, like a bee: vvvery, vvvote. It is like f, but with your voice. Your lips do not close. Practice in a mirror!"],"explain_es":["En español, la b y la v suenan igual. En inglés son dos sonidos distintos. Para la b, cierra los dos labios y ábrelos: boat, best, berry.","Para la v, pon los dientes de arriba sobre el labio de abajo y empuja el aire. Se escucha un zumbido, como una abeja: vvvery, vvvote. Es como la f, pero con voz. Los labios no se cierran. ¡Practica frente a un espejo!"],"spanish":"Spanish speakers often say very like berry and vote like boat, because Spanish b and v are the same. For v, the top teeth touch the lower lip; for b, the lips close.","spanish_es":"Muchos hispanohablantes dicen very como berry y vote como boat, porque en español la b y la v suenan igual. Para la v, los dientes de arriba tocan el labio de abajo; para la b, se cierran los labios.","ex":[{"t":"very, berry","how":"vvvery | berry","note":"v: top teeth on the lower lip; b: lips together"},{"t":"vest, best","how":"vvvest | best"},{"t":"van, ban","how":"vvvan | ban"},{"t":"vote, boat","how":"vvvote | boat"},{"t":"curve, curb","how":"curvvv | curb","note":"the same at the end of a word"},{"t":"five, seven, eleven","how":"faivvv | SEV-en | i-LEV-en","note":"v at the end and in the middle"},{"t":"a big van","how":"a BIG VAN","note":"b, then v"},{"t":"I love my job.","how":"ai LUV my JOB","note":"love ends in v, not b or f"}],"listen":[{"q":"Which word do you hear?","o":["very","berry"],"pick":true,"why":"very: teeth on the lip; berry: lips together."},{"q":"Which word do you hear?","o":["vest","best"],"pick":true,"why":"vest starts with v; best starts with b."},{"q":"Which word do you hear?","o":["van","ban"],"pick":true,"why":"van starts with v; ban starts with b."},{"q":"Which word do you hear?","o":["vote","boat"],"pick":true,"why":"vote starts with v; boat starts with b."},{"q":"Which word do you hear?","o":["curve","curb"],"pick":true,"why":"curve ends in v; curb ends in b."},{"q":"How many v sounds do you hear?","say":"I have a very big van.","o":["2","3","4"],"a":1,"why":"have, very, van = 3; big has a b."},{"q":"Is the first sound b or v?","say":"vacation","o":["b","v"],"a":1,"why":"vacation starts with v: teeth on the lip."},{"q":"Where is the v sound?","say":"travel","o":["at the start","in the middle","at the end"],"a":1,"why":"TRAV-el: the v is in the middle."}],"mark":[{"mode":"find","q":"Tap the words with a v sound.","w":["vest","best","van","ban","five"],"a":[0,2,4],"why":"vest, van, five have v; best, ban have b."},{"mode":"find","q":"Tap the words with a v sound.","w":["I","love","the","beach","in","November"],"a":[1,5],"why":"love, November have v; beach has b."},{"mode":"find","q":"Tap the words with a b sound.","w":["Bob","has","a","very","big","bag"],"a":[0,4,5],"why":"Bob, big, bag have b; very has v."},{"mode":"find","q":"Tap the words with a v sound.","w":["Have","a","good","vacation"],"a":[0,3],"why":"have, vacation have v."},{"mode":"find","q":"Tap the words with a b sound.","w":["The","bus","is","very","busy"],"a":[1,4],"why":"bus, busy have b; very has v."}],"dict":[{"say":"very good","a":"very good","how":"VER-ee GOOD","why":"very: top teeth on the lower lip, not b."},{"say":"a big van","a":"a big van","how":"a BIG VAN","why":"big: lips together; van: teeth on the lip."},{"say":"I love it.","a":"I love it.","how":"ai LUH-vit","why":"love_it: the v joins the next vowel."},{"say":"Have a nice vacation.","a":"Have a nice vacation.","how":"ha-va NAIS vei-KEI-shen","why":"have_a: the v joins a; vacation starts with v."},{"say":"Five or seven?","a":"Five or seven?","alt":["5 or 7?"],"how":"FAI-vor SEV-en?","why":"five_or: the v joins or; seven has v in the middle."}],"tip":"In class: students use their phone camera as a mirror and say very/berry and vote/boat; the partner checks teeth on the lip for v and closed lips for b."},{"id":"a0-5","lv":"A0","n":5,"title":"Say the last sound","focus":"sounds","goal":"Say the last consonant of English words clearly, without dropping it, changing it or adding a vowel.","goal_es":"Decir claramente la última consonante de las palabras en inglés, sin comerla, cambiarla ni agregar una vocal.","explain":["Many Spanish words end in a vowel. English words often end in a consonant: red, cat, bag, bus, milk. Say the last sound clearly. If you drop it or change it, the word can change: card becomes car, white becomes why.","Keep the voice in b, d, g at the end: red, not 'ret'; bag, not 'back'. The vowel before them is a little longer. And don't add a vowel: stop, not 'stop-uh'. Just stop on the consonant."],"explain_es":["Muchas palabras en español terminan en vocal. En inglés, muchas terminan en consonante: red, cat, bag, bus, milk. Di el último sonido con claridad. Si lo pierdes o lo cambias, la palabra puede cambiar: card se vuelve car, white se vuelve why.","Mantén la voz en b, d, g al final: red, no 'ret'; bag, no 'back'. La vocal antes de ellas es un poco más larga. Y no agregues una vocal: stop, no 'stop-e'. Termina justo en la consonante."],"spanish":"Spanish speakers often drop the last sound (frien', mil', and in Chile bu' for bus) or change it (ret for red). Some add a vowel: stop-uh. Finish each word on its real last sound.","spanish_es":"Muchos hispanohablantes se comen el último sonido (frien', mil' y, en Chile, bu' por bus) o lo cambian (ret por red). Otros agregan una vocal: stop-e. Termina cada palabra en su último sonido real.","ex":[{"t":"red","how":"red (not 'ret')","note":"keep the voice in the d"},{"t":"cat","how":"kat","note":"end on a short t"},{"t":"bag, back","how":"baag | bak","note":"the vowel is longer before g"},{"t":"white, why","how":"why-t | why","note":"white ends in t"},{"t":"bus, milk","how":"bus (not 'bu') | milk (not 'mil')","note":"say the s; say the l and the k"},{"t":"my friend","how":"my FREND","note":"n + d at the end"},{"t":"Help me!","how":"HELP-mee","note":"close your lips on the p"},{"t":"Stop the bus.","how":"STOP-the BUS","note":"no 'stop-uh', no 'bu'"}],"listen":[{"q":"Which word do you hear?","o":["bag","back"],"pick":true,"why":"bag: longer a + g; back: shorter a + k."},{"q":"Which sentence do you hear?","o":["I need a card.","I need a car."],"pick":true,"why":"card ends in d; car ends in r."},{"q":"Which word do you hear?","o":["white","why"],"pick":true,"why":"white ends in t; why ends in a vowel."},{"q":"Which word do you hear?","o":["ice","eye"],"pick":true,"why":"ice ends in s; eye ends in a vowel."},{"q":"Which word do you hear?","o":["bed","bet"],"pick":true,"why":"bed: longer e + d; bet: shorter e + t."},{"q":"How many syllables?","say":"stop","o":["1","2"],"a":0,"why":"stop has one syllable: no 'uh' at the end."},{"q":"What is the last sound?","say":"friend","o":["n","d","s"],"a":1,"why":"friend ends in n + d: the last sound is d."},{"q":"What is the last sound?","say":"milk","o":["l","k"],"a":1,"why":"milk ends in l + k: the last sound is k."}],"mark":[{"mode":"find","q":"Tap the words that end in a d sound.","w":["red","bed","bet","card","car"],"a":[0,1,3],"why":"red, bed, card end in d."},{"mode":"find","q":"Tap the words that end in a t sound.","w":["white","why","cat","wait","way"],"a":[0,2,3],"why":"white, cat, wait end in t."},{"mode":"find","q":"Tap the words that end in a consonant sound.","w":["I","need","a","big","bag"],"a":[1,3,4],"why":"need (d), big (g), bag (g); I and a end in a vowel."},{"mode":"find","q":"Tap the words that end in an s sound.","w":["Let's","take","the","bus"],"a":[0,3],"why":"let's and bus end in s; take ends in k."},{"mode":"find","q":"Tap the words that end in a consonant sound.","w":["My","friend","needs","help"],"a":[1,2,3],"why":"friend (d), needs (z), help (p); my ends in a vowel."}],"dict":[{"say":"a red bag","a":"a red bag","how":"a RED BAG","why":"red ends in d, bag in g: keep the voice."},{"say":"I need milk.","a":"I need milk.","how":"ai need MILK","why":"need ends in d; milk ends in l + k."},{"say":"Help me, please.","a":"Help me, please.","how":"HELP-mee, pleez","why":"help: close your lips on the p; no extra vowel."},{"say":"Stop the bus!","a":"Stop the bus!","how":"STOP-the BUS","why":"stop: no 'stop-uh'; bus: say the s."},{"say":"a white cat","a":"a white cat","how":"a WHITE CAT","why":"white and cat end in t: short and quiet, but not dropped."}],"tip":"In class: play a word chain. A student says a word that ends in a consonant (bag), the next says a word that starts with that sound (good), and so on; a dropped or changed last sound loses a point."},{"id":"a0-6","lv":"A0","n":6,"title":"School, not eschool","focus":"sounds","goal":"Say words that start with s + consonant (school, speak, street) with no 'e' before the s.","goal_es":"Pronunciar palabras que empiezan con s + consonante (school, speak, street) sin una 'e' antes de la s.","explain":["Many English words start with s + a consonant: school, speak, Spain, small, street. There is no vowel before the s. The word starts with the s sound: 'sss-kool', not 'es-kool'.","Tip: start with a long 'sss', like a snake. Then say the rest: sss… + mile = smile. Keep your mouth almost closed for the s. In phrases too: 'my school', 'the bus stop' (one long s)."],"explain_es":["Muchas palabras en inglés empiezan con s + consonante: school, speak, Spain, small, street. No hay ninguna vocal antes de la s. La palabra empieza directamente con el sonido s: 'sss-kool', no 'es-kool'.","Truco: empieza con una 'sss' larga, como una serpiente. Después di el resto: sss… + mile = smile. Mantén la boca casi cerrada para la s. También en frases: 'my school', 'the bus stop' (una sola s larga)."],"spanish":"Spanish words almost never start with s + consonant, so Spanish speakers add an 'e' ('eschool', 'Espain'), and in Chile the s before a consonant often becomes a soft 'h' ('ehtudiante'). Fix: no 'e' at the start, and a clear, strong 'sss'.","spanish_es":"En español casi ninguna palabra empieza con s + consonante, por eso agregamos una 'e' ('eschool', 'Espain'), y en Chile la s antes de consonante muchas veces suena como una 'h' suave ('ehtudiante'). Solución: nada de 'e' al inicio, y una 'sss' clara y fuerte.","ex":[{"t":"school","how":"sss-kool","note":"1 syllable · not 'eschool'"},{"t":"speak","how":"sss-peek","note":"not 'espeak'"},{"t":"Spain","how":"sss-pain","note":"not 'Espain'"},{"t":"small","how":"sss-mawl","note":"s + m"},{"t":"student","how":"sss-TOO-dent","note":"s + t · not 'estudent'"},{"t":"street","how":"sss-treet","note":"three consonants: s-t-r"},{"t":"the bus stop","how":"thuh bu_sss-top","note":"the two s sounds join: one long s"},{"t":"I speak Spanish.","how":"I sss-peek SPAN-ish","note":"no 'e' after I"}],"listen":[{"q":"Which word do you hear?","o":["sleep","asleep"],"pick":true,"why":"sleep starts with s + l (1 syllable). asleep has a vowel first: a-sleep (2 syllables)."},{"q":"Which word do you hear?","o":["state","estate"],"pick":true,"why":"state starts with s + t. estate has a vowel before the s: e-state, like the mistake 'eschool'."},{"q":"Which word do you hear?","o":["small","mall"],"pick":true,"why":"small starts with a clear s + m. mall has no s."},{"q":"Which word do you hear?","o":["stop","top"],"pick":true,"why":"stop has a clear s before the t. top starts with t."},{"q":"Which word do you hear?","o":["sport","support"],"pick":true,"why":"sport: s and p together (1 syllable). support: a short vowel between them (suh-PORT)."},{"q":"How many syllables do you hear?","say":"school","o":["1","2"],"a":0,"why":"school has 1 syllable. 'E-school' has 2: that is the mistake."},{"q":"How many syllables do you hear?","say":"student","o":["1","2","3"],"a":1,"why":"stu-dent: 2 syllables, with no 'e' at the start (not 'es-tu-dent')."},{"q":"How many syllables do you hear?","say":"I speak Spanish.","o":["4","5","6"],"a":0,"why":"I-speak-Span-ish = 4. With 'espeak' you get 5."}],"mark":[{"mode":"find","q":"Tap the words that start with s + consonant.","w":["My","sister","is","a","student."],"a":[4],"why":"student = s + t. sister starts with s + a vowel (SIS-ter), so it is easy."},{"mode":"find","q":"Tap the words that start with s + consonant.","w":["I","speak","Spanish","and","English."],"a":[1,2],"why":"speak and Spanish start with s + p. Say them with no 'e'."},{"mode":"find","q":"Tap the words that start with s + consonant.","w":["The","school","is","very","small."],"a":[1,4],"why":"school (s + k) and small (s + m)."},{"mode":"link","q":"Tap where the words join.","w":["Go","to","the","bus","stop."],"a":[3],"why":"bus_stop: the s of bus and the s of stop make one long s: 'bu-sss-top', not 'bus estop'."},{"mode":"find","q":"Tap the words that start with s + consonant.","w":["See","you","at","the","station."],"a":[4],"why":"station = s + t (STAY-shun). See starts with s + a vowel."}],"dict":[{"say":"school","a":"school","how":"skool","why":"1 syllable: s + k together. Not 'eschool'."},{"say":"a small street","a":"a small street","how":"uh SMAWL STREET","why":"s + m and s + t + r: start each word with a clear s."},{"say":"I speak Spanish.","a":"I speak Spanish","how":"I SPEEK SPAN-ish","why":"Two words with s + p: no 'e' after I."},{"say":"I'm a student.","a":"I'm a student","how":"I'm_uh STOO-dent","why":"I'm_a joins; student starts with s + t, not 'estudent'."},{"say":"Speak slowly, please.","a":"Speak slowly, please","how":"SPEEK SLOH-lee, PLEEZ","why":"s + p and s + l: a clear s, no 'e' before it."}],"tip":"Snake start: students hold a long 'sss' and then jump into the word (sss… school, sss… Spain). Then in pairs they say 'I study at…' and 'My street is…' while the partner raises a hand if they hear an 'e' at the start."},{"id":"a0-7","lv":"A0","n":7,"title":"TH: think and this","focus":"sounds","goal":"Say the two TH sounds: /θ/ (only air) in think and /ð/ (with voice) in this.","goal_es":"Pronunciar los dos sonidos de la TH: /θ/ (solo aire) en think y /ð/ (con voz) en this.","explain":["English TH has two sounds. For both, put the tip of your tongue between your teeth. /θ/ is only air, like the 'z' in Spanish from Spain ('zapato'): think, three, thanks. /ð/ uses your voice, like a soft 'd' ('nada'): this, they, mother.","Don't change TH to t, d, s or f: 'three' is not 'tree' or 'free', and 'they' is not 'day'. Use a mirror: you can see your tongue for a moment. Small words like the, this, that and they use /ð/ (the TH with voice)."],"explain_es":["La TH del inglés tiene dos sonidos. Para los dos, pon la punta de la lengua entre los dientes. /θ/ es solo aire, como la 'z' del español de España ('zapato'): think, three, thanks. /ð/ usa la voz, como una 'd' suave ('nada'): this, they, mother.","No cambies la TH por t, d, s o f: 'three' no es 'tree' ni 'free', y 'they' no es 'day'. Usa un espejo: puedes ver tu lengua por un momento. Las palabras pequeñas como the, this, that y they usan /ð/ (la TH con voz)."],"spanish":"Spanish speakers often say 't' or 's' instead of /θ/ ('tank you', 'sank you') and 'd' instead of /ð/ ('dis', 'dey'). Fix: put the tip of your tongue out between your teeth; /θ/ is the 'z' of Spain, and /ð/ is a soft 'd' with the tongue further out.","spanish_es":"Muchos hispanohablantes dicen 't' o 's' en vez de /θ/ ('tank you', 'sank you') y 'd' en vez de /ð/ ('dis', 'dey'). Solución: saca la punta de la lengua entre los dientes; /θ/ es la 'z' de España, y /ð/ es una 'd' suave con la lengua más afuera.","ex":[{"t":"think","how":"th-ink (air)","note":"/θ/ · not 'tink' or 'sink'"},{"t":"three","how":"th-ree (air)","note":"/θ/ · not 'tree' or 'free'"},{"t":"thanks","how":"th-anks (air)","note":"/θ/ · not 'tanks'"},{"t":"Thursday","how":"THURZ-day (air)","note":"/θ/ at the start"},{"t":"mouth","how":"mou-th (air)","note":"/θ/ at the end · not 'mouse'"},{"t":"this","how":"dh-is (voice)","note":"/ð/ · not 'dis'"},{"t":"mother","how":"MUH-dher (voice)","note":"/ð/ in the middle"},{"t":"They think so.","how":"dhey THINK so","note":"both sounds: they /ð/, think /θ/"}],"listen":[{"q":"Which word do you hear?","o":["three","tree","free"],"pick":true,"why":"three: tongue between the teeth. tree: t. free: top teeth on the lip (f)."},{"q":"Which word do you hear?","o":["think","sink"],"pick":true,"why":"think: tongue out (/θ/). sink: tongue behind the teeth (s)."},{"q":"Which word do you hear?","o":["mouth","mouse"],"pick":true,"why":"mouth ends with /θ/ (tongue out). mouse ends with s."},{"q":"Which word do you hear?","o":["they","day"],"pick":true,"why":"they starts with /ð/ (tongue out, voice). day starts with d (tongue behind the teeth)."},{"q":"Which sentence do you hear?","o":["I'm thinking.","I'm sinking."],"pick":true,"why":"thinking: /θ/, tongue out. sinking: s (going down in the water)."},{"q":"Which TH sound do you hear?","say":"Thursday","o":["/θ/ only air (like think)","/ð/ with voice (like this)"],"a":0,"why":"Thursday starts with /θ/: only air, no voice."},{"q":"Which TH sound do you hear?","say":"mother","o":["/θ/ only air (like think)","/ð/ with voice (like this)"],"a":1,"why":"mother has /ð/ in the middle: your voice is on."},{"q":"How many TH sounds do you hear?","say":"This is my mother.","o":["1","2","3"],"a":1,"why":"This and mother: 2 TH sounds, both /ð/ (with voice)."}],"mark":[{"mode":"find","q":"Tap the words with /θ/ (only air, like think).","w":["My","birthday","is","this","Thursday."],"a":[1,4],"why":"birthday and Thursday have /θ/ (air). this has /ð/ (voice)."},{"mode":"find","q":"Tap the words with /ð/ (with voice, like this).","w":["There","are","three","of","them."],"a":[0,4],"why":"There and them have /ð/. three has /θ/."},{"mode":"find","q":"Tap the words with a TH sound. Listen carefully!","w":["Thomas","has","three","brothers."],"a":[2,3],"why":"three (/θ/) and brothers (/ð/). Thomas has no TH sound: it starts with t (TOM-us)."},{"mode":"find","q":"Tap the words with /ð/ (with voice, like this).","w":["Thanks,","that's","my","mother."],"a":[1,3],"why":"that's and mother have /ð/. Thanks has /θ/ (air)."},{"mode":"find","q":"Tap the words with /θ/ (only air, like think).","w":["I","think","they're","thirty."],"a":[1,3],"why":"think and thirty have /θ/. they're has /ð/."}],"dict":[{"say":"three","a":"three","how":"th-ree (air)","why":"/θ/: tongue out. Not 'tree' or 'free'."},{"say":"Thank you.","a":"Thank you","how":"THANK-yoo (air)","why":"/θ/ at the start: tongue out, only air."},{"say":"this Thursday","a":"this Thursday","how":"dhis THURZ-day","why":"this has /ð/ (voice); Thursday has /θ/ (air)."},{"say":"They think so.","a":"They think so","how":"dhey THINK so","why":"They: /ð/ with voice. think: /θ/, only air."},{"say":"Room thirty-three.","a":"Room thirty-three","alt":["Room 33"],"how":"room THUR-dee THREE","why":"thirty and three: /θ/. In American English the t in thirty sounds like a quick d."}],"tip":"Mirror pairs: one student says three or tree, think or sink, mouth or mouse; the partner watches the tongue and says which word it was. Then they swap."},{"id":"a0-8","lv":"A0","n":8,"title":"Word stress: hoTEL, BAnana?","focus":"stress","goal":"Put the stress on the right syllable in everyday words like COFfee, DOCtor, hoTEL and baNAna.","goal_es":"Poner el acento en la sílaba correcta en palabras comunes como COFfee, DOCtor, hoTEL y baNAna.","explain":["In English words with two or more syllables, one syllable is strong: longer, louder and higher. That is the stress. COF-fee = Oo, ho-TEL = oO, ba-NA-na = oOo (O = strong). The weak syllables are short: banana sounds like 'buh-NAN-uh'.","Many English words look like Spanish words, but the stress can be in a different place: Spanish doc-TOR, a-ni-MAL; English DOC-tor, AN-i-mal. Some are the same: ho-TEL, ba-NA-na. Learn the stress with the word, and clap on the strong syllable."],"explain_es":["En las palabras inglesas de dos o más sílabas, una sílaba es fuerte: más larga, con más volumen y más aguda. Ese es el acento. COF-fee = Oo, ho-TEL = oO, ba-NA-na = oOo (O = fuerte). Las sílabas débiles son cortas: banana suena como 'buh-NAN-uh'.","Muchas palabras en inglés se parecen al español, pero el acento puede estar en otro lugar: en español doc-TOR, a-ni-MAL; en inglés DOC-tor, AN-i-mal. Algunas son iguales: ho-TEL, ba-NA-na. Aprende el acento junto con la palabra y aplaude en la sílaba fuerte."],"spanish":"Spanish speakers often keep the Spanish stress ('docTOR', 'aniMAL', 'chocoLAte', 'restauRANT') and say every vowel clearly. Fix: make one syllable strong and the others short and weak: DOK-ter, CHAWK-lit, RES-tuh-rahnt.","spanish_es":"Muchos hispanohablantes mantienen el acento del español ('docTOR', 'aniMAL', 'chocoLAte', 'restauRANT') y pronuncian todas las vocales con claridad. Solución: haz una sílaba fuerte y las demás cortas y débiles: DOK-ter, CHAWK-lit, RES-tuh-rahnt.","ex":[{"t":"coffee","how":"KAW-fee","note":"Oo · Spanish: café"},{"t":"doctor","how":"DOK-ter","note":"Oo · Spanish: docTOR"},{"t":"hotel","how":"ho-TEL","note":"oO · the same as Spanish"},{"t":"banana","how":"buh-NAN-uh","note":"oOo · UK: buh-NAH-nuh"},{"t":"tomato","how":"tuh-MAY-doh","note":"oOo · UK: tuh-MAH-toh"},{"t":"computer","how":"kum-PYOO-der","note":"oOo · American t = a quick d"},{"t":"animal","how":"AN-ih-mul","note":"Ooo · Spanish: aniMAL"},{"t":"chocolate","how":"CHAWK-lit","note":"stress first · often only 2 syllables · Spanish: chocoLAte"}],"listen":[{"q":"Where is the stress? (CAPS = strong)","say":"hotel","o":["HO-tel (1st)","ho-TEL (2nd)"],"a":1,"why":"ho-TEL: the second syllable is strong, like in Spanish."},{"q":"Where is the stress? (CAPS = strong)","say":"doctor","o":["DOC-tor (1st)","doc-TOR (2nd)"],"a":0,"why":"DOC-tor (DOK-ter): the first syllable is strong, not like Spanish."},{"q":"Where is the stress? (CAPS = strong)","say":"coffee","o":["COF-fee (1st)","cof-FEE (2nd)"],"a":0,"why":"COF-fee: the first syllable is strong. Don't say it like café."},{"q":"Which pattern do you hear? (O = strong)","say":"banana","o":["Ooo (1st)","oOo (2nd)","ooO (3rd)"],"a":1,"why":"ba-NA-na: weak, STRONG, weak (buh-NAN-uh)."},{"q":"Which pattern do you hear? (O = strong)","say":"animal","o":["Ooo (1st)","oOo (2nd)","ooO (3rd)"],"a":0,"why":"AN-i-mal: STRONG, weak, weak. In Spanish it is aniMAL."},{"q":"Which syllable is strong?","say":"restaurant","o":["the first syllable","the last syllable"],"a":0,"why":"RES-tau-rant (often 'REST-rahnt'): stress at the start, not restauRANT."},{"q":"Which word do you hear? Listen for the stress.","o":["desert","dessert"],"pick":true,"why":"desert (DEZ-ert, a hot, dry place): stress first. dessert (dih-ZURT, sweet food): stress second."},{"q":"How many syllables do you hear?","say":"tomato","o":["2","3","4"],"a":1,"why":"to-MA-to: 3 syllables, stress in the middle (tuh-MAY-doh)."}],"mark":[{"mode":"stress","q":"Tap the stressed syllable.","w":["wa","ter"],"word":true,"a":[0],"why":"WA-ter (WAH-der): stress first. In American English the t sounds like a quick d."},{"mode":"stress","q":"Tap the stressed syllable.","w":["com","pu","ter"],"word":true,"a":[1],"why":"com-PU-ter (kum-PYOO-der): stress in the middle."},{"mode":"stress","q":"Tap the stressed syllable.","w":["choc","o","late"],"word":true,"a":[0],"why":"CHOC-o-late, often just 2 syllables: CHAWK-lit. In Spanish it is chocoLAte."},{"mode":"find","q":"Tap the words with stress on the FIRST syllable.","w":["coffee,","hotel,","doctor,","banana,","water"],"a":[0,2,4],"why":"COF-fee, DOC-tor, WA-ter. ho-TEL and ba-NA-na have the stress later."},{"mode":"find","q":"Tap the words with stress on the SECOND syllable.","w":["hotel,","animal,","tomato,","chocolate,","computer"],"a":[0,2,4],"why":"ho-TEL, to-MA-to, com-PU-ter. AN-i-mal and CHOC-o-late have the stress first."}],"dict":[{"say":"coffee","a":"coffee","how":"KAW-fee","why":"COF-fee: stress on the first syllable."},{"say":"Water, please.","a":"Water, please","how":"WAH-der, PLEEZ","why":"WA-ter: stress first; the American t sounds like a quick d."},{"say":"chocolate cake","a":"chocolate cake","how":"CHAWK-lit CAKE","why":"CHOC-o-late: stress first, often only 2 syllables."},{"say":"a good restaurant","a":"a good restaurant","how":"uh good RES-tuh-rahnt","why":"RES-tau-rant: stress at the start, not restauRANT."},{"say":"my new computer","a":"my new computer","how":"my new kum-PYOO-der","why":"com-PU-ter: stress in the middle."}],"tip":"Clap the stress: say a word (DOC-tor, ba-NA-na, AN-i-mal) and the class claps loudly on the strong syllable and taps quietly on the weak ones. Then say the Spanish word and clap again to feel the difference."},{"id":"a0-9","lv":"A0","n":9,"title":"Questions up, questions down","focus":"intonation","goal":"Make yes/no questions go up ↗, and wh- questions and statements go down ↘.","goal_es":"Hacer que las preguntas de sí/no suban ↗, y que las preguntas con wh- y las afirmaciones bajen ↘.","explain":["At the end of a sentence, your voice goes up ↗ or down ↘. Yes/no questions usually go up: 'Are you OK? ↗' 'Do you like coffee? ↗' They start with words like are, is, do or can, and the answer is yes or no.","Wh- questions (what, where, who, when, why, how) usually go down: 'Where do you live? ↘' Normal statements also go down: 'I live in Santiago. ↘' The voice moves on the last important word: LIVE, COFfee, NAME."],"explain_es":["Al final de una oración, la voz sube ↗ o baja ↘. Las preguntas de sí/no normalmente suben: 'Are you OK? ↗' 'Do you like coffee? ↗' Empiezan con palabras como are, is, do o can, y la respuesta es sí o no.","Las preguntas con wh- (what, where, who, when, why, how) normalmente bajan: 'Where do you live? ↘' Las afirmaciones normales también bajan: 'I live in Santiago. ↘' La voz se mueve en la última palabra importante: LIVE, COFfee, NAME."],"spanish":"Many learners think all questions go up, so they say 'Where do you live? ↗', and Spanish speakers often use a flatter voice in English. Fix: wh- questions go down ↘, yes/no questions go up ↗, and make the move bigger, on the last important word.","spanish_es":"Muchos estudiantes creen que todas las preguntas suben, y dicen 'Where do you live? ↗'; además, los hispanohablantes solemos usar una voz más plana en inglés. Solución: las preguntas con wh- bajan ↘, las de sí/no suben ↗, y el movimiento debe ser más grande, en la última palabra importante.","ex":[{"t":"I'm from Chile.","how":"I'm from CHIL-ee ↘","note":"statement → down"},{"t":"Are you OK?","how":"Are you o-KAY ↗","note":"yes/no question → up"},{"t":"Do you like coffee?","how":"Do you like COF-fee ↗","note":"yes/no questions start with do, are, is, can…"},{"t":"Are you a student?","how":"Are you a STOO-dent ↗","note":"the answer is yes or no → up"},{"t":"Where do you live?","how":"Where do you LIVE ↘","note":"wh- question → down"},{"t":"What's your name?","how":"What's your NAME ↘","note":"wh- question → down"},{"t":"Where are you from?","how":"Where are you FROM ↘","note":"wh- words: what, where, who, when, why, how"},{"t":"Really?","how":"REE-lee ↗","note":"one word with ? can go up too"}],"listen":[{"q":"Which do you hear: a question ↗ or a statement ↘?","o":["Really?","Really."],"pick":true,"why":"Really? goes up ↗: a question (surprise). Really. goes down ↘: a statement."},{"q":"Which do you hear: an offer ↗ or an answer ↘?","o":["Coffee?","Coffee."],"pick":true,"why":"Coffee? ↗ is an offer: 'Do you want coffee?' Coffee. ↘ is an answer."},{"q":"Which do you hear: a question ↗ or a statement ↘?","o":["You're from Chile?","You're from Chile."],"pick":true,"why":"Same words: going up ↗ makes it a question; going down ↘ makes it a statement."},{"q":"Which sentence do you hear?","o":["Is she a doctor?","She is a doctor."],"pick":true,"why":"Is she…? is a yes/no question ↗. She is… is a statement ↘."},{"q":"What kind of sentence is it?","say":"Where do you live?","o":["yes/no question ↗","wh- question ↘","statement ↘"],"a":1,"why":"Where… is a wh- question, so the voice usually goes down ↘."},{"q":"What kind of sentence is it?","say":"Are you a student?","o":["yes/no question ↗","wh- question ↘","statement ↘"],"a":0,"why":"Are you…? asks for yes or no, so the voice usually goes up ↗."},{"q":"What kind of sentence is it?","say":"How are you?","o":["yes/no question ↗","wh- question ↘","statement ↘"],"a":1,"why":"How is a wh- word too (what, where, who, when, why, how): the voice goes down ↘."},{"q":"Up ↗ or down ↘ at the end?","say":"My name is Ana.","o":["up ↗","down ↘"],"a":1,"why":"It is a statement: the voice goes down ↘ at the end."}],"mark":[{"mode":"stress","q":"Tap the word where the voice goes up ↗.","w":["Are","you","OK?"],"a":[2],"why":"Are you o-KAY ↗? A yes/no question goes up on the last important word."},{"mode":"stress","q":"Tap the word where the voice goes down ↘.","w":["Where","do","you","live?"],"a":[3],"why":"Where do you LIVE ↘? A wh- question goes down on the last important word."},{"mode":"stress","q":"Tap the word where the voice starts to go up ↗.","w":["Do","you","like","it?"],"a":[2],"why":"Do you LIKE it ↗? 'it' is a small word, so the voice starts going up on LIKE."},{"mode":"stress","q":"Tap the word where the voice starts to go down ↘.","w":["What","time","is","it?"],"a":[1],"why":"What TIME is it ↘? The voice falls from TIME; 'is it' is small and low."},{"mode":"stress","q":"This is a statement. Tap the word where the voice goes down ↘.","w":["I'm","from","Chile."],"a":[2],"why":"I'm from CHIL-ee ↘. Statements go down at the end."}],"dict":[{"say":"Are you OK?","a":"Are you OK?","alt":["Are you okay?"],"how":"Are you o-KAY ↗","why":"Yes/no question: the voice goes up ↗."},{"say":"Where do you live?","a":"Where do you live?","how":"Where d'ya LIVE ↘","why":"Wh- question: the voice goes down ↘. Fast 'do you' sounds like 'd'ya'."},{"say":"Do you like coffee?","a":"Do you like coffee?","how":"D'ya like COF-fee ↗","why":"Yes/no question: up ↗ on COF-fee."},{"say":"Where are you from?","a":"Where are you from?","how":"Wher-ya FROM ↘","why":"Wh- question: down ↘ on FROM."},{"say":"I'm from Chile.","a":"I'm from Chile","how":"I'm frum CHIL-ee ↘","why":"Statement: the voice goes down ↘ at the end."}],"tip":"Arms up, arms down: the teacher says a question or a sentence and the class moves an arm up ↗ for yes/no questions and down ↘ for wh- questions and statements. Then pairs ask each other 'Are you…?' and 'Where…?' questions with big arm moves."},{"id":"a1-1","lv":"A1","n":1,"title":"Works, plays, watches: three -s endings","focus":"sounds","goal":"Say the -s ending of plurals, verbs and 's correctly: /s/, /z/ or /ɪz/.","goal_es":"Pronunciar bien la terminación -s de plurales, verbos y 's: /s/, /z/ o /ɪz/.","explain":["English adds -s to plurals (cats), to verbs after he, she and it (works) and to 's (Tom's). The sound follows the same rule in all three. It depends on the last sound of the word, not on the spelling.","After p, t, k and f (sounds with no voice), say /s/: stops, cats, works, laughs. After a vowel or a voiced sound (b, d, g, v, l, m, n, r), say /z/, like a buzzing bee: plays, dogs, lives, calls. Touch your throat: /z/ vibrates, /s/ doesn't.","After the sounds s, z, sh, ch and j (as in orange), add a new syllable, /ɪz/ ('iz'): buses, boxes, washes, watches, oranges. Careful: the e in likes, makes and lives is silent. These words have only one syllable."],"explain_es":["En inglés se agrega -s a los plurales (cats), a los verbos con he, she e it (works) y al 's (Tom's). En los tres casos el sonido sigue la misma regla: depende del último sonido de la palabra, no de cómo se escribe.","Después de p, t, k y f (sonidos sin voz), di /s/: stops, cats, works, laughs. Después de una vocal o de un sonido con voz (b, d, g, v, l, m, n, r), di /z/, como el zumbido de una abeja: plays, dogs, lives, calls. Toca tu garganta: la /z/ vibra; la /s/, no.","Después de los sonidos s, z, sh, ch y la j inglesa (como en orange), agrega una sílaba nueva, /ɪz/ ('iz'): buses, boxes, washes, watches, oranges. Ojo: la e de likes, makes y lives es muda. Esas palabras tienen una sola sílaba."],"spanish":"Spanish speakers often say every -s as a hard /s/, or add a vowel because of the spelling ('lik-es', 'liv-es'). Use /z/ after vowels and voiced sounds, and add a syllable only after s, z, sh, ch and j sounds.","spanish_es":"Los hispanohablantes suelen pronunciar toda -s como una /s/ fuerte, o agregan una vocal por la ortografía ('lik-es', 'liv-es'). Usa /z/ después de vocales y sonidos con voz, y agrega una sílaba solo después de los sonidos s, z, sh, ch y j.","ex":[{"t":"works","how":"werks","note":"after k → /s/"},{"t":"plays","how":"pleiz","note":"after a vowel → /z/"},{"t":"friends","how":"frendz","note":"after d → /z/: say the d too!"},{"t":"Tom's car","how":"TAHMZ KAR","note":"'s follows the same rule: after m → /z/"},{"t":"watches","how":"WAH-chiz","note":"after ch → /ɪz/: two syllables"},{"t":"oranges","how":"OR-in-jiz","note":"after the j sound → /ɪz/"},{"t":"He lives in Chile.","how":"hee LIVZ_in CHI-lee","note":"lives = one syllable: the e is silent"},{"t":"She likes dogs and watches movies.","how":"shee LAIKS DOGZ_n WAH-chiz MOO-veez","note":"/s/ · /z/ · /ɪz/ · /z/"}],"listen":[{"q":"Which word do you hear?","o":["bus","buses"],"pick":true,"why":"buses has two syllables: BUH-siz."},{"q":"How many syllables?","say":"watches","o":["1","2","3"],"a":1,"why":"WAH-chiz: after ch, -es is a new syllable."},{"q":"Which word do you hear?","o":["place","plays"],"pick":true,"why":"place ends in /s/; plays ends in a buzzing /z/, with a longer vowel."},{"q":"Which ending do you hear?","say":"dogs","o":["/s/ as in works","/z/ as in plays","/ɪz/ as in watches"],"a":1,"why":"After g, a voiced sound, -s is /z/."},{"q":"Which word do you hear?","o":["ice","eyes"],"pick":true,"why":"ice ends in /s/ ('ais'); eyes ends in /z/ ('aiz')."},{"q":"How many syllables?","say":"makes","o":["1","2"],"a":0,"why":"makes = 'meiks': one syllable, because the e is silent."},{"q":"Which phrase do you hear?","o":["my friend","my friends"],"pick":true,"why":"friends ends in /dz/: say the d, then a buzzing z."},{"q":"Which ending do you hear?","say":"laughs","o":["/s/ as in works","/z/ as in plays","/ɪz/ as in watches"],"a":0,"why":"laughs ends in an f sound (spelled gh), so -s is /s/: 'lafs'."}],"mark":[{"mode":"find","q":"Tap the words with an extra syllable /ɪz/ ('iz').","w":["She","washes","the","dishes","and","cleans","the","kitchen"],"a":[1,3],"why":"WAH-shiz, DI-shiz: after sh → /ɪz/. cleans has only one syllable."},{"mode":"find","q":"Tap the words whose -s sounds /z/.","w":["My","brothers","like","cats","and","dogs"],"a":[1,5],"why":"brothers (after r) and dogs (after g) → /z/; cats (after t) → /s/."},{"mode":"find","q":"Tap the words whose -s sounds /s/.","w":["She","works","nights","and","sleeps","days"],"a":[1,2,4],"why":"works, nights, sleeps: after k, t, p → /s/; days: after a vowel → /z/."},{"mode":"find","q":"Tap the words where -s or 's adds a syllable.","w":["Max's","sister","watches","Tom's","kids"],"a":[0,2],"why":"MAK-siz, WAH-chiz: after the x (ks) and ch sounds. Tom's and kids just add /z/."},{"mode":"link","q":"Tap where the words join.","w":["My","friends","always","arrive","late"],"a":[1,2],"why":"friends_always_arrive: the /z/ sound joins the next vowel."}],"dict":[{"say":"She watches the news every night.","a":"She watches the news every night.","how":"shee WAH-chiz the NOOZ_EV-ree NAIT","why":"watches = two syllables (/ɪz/); news ends in /z/ and joins every."},{"say":"My brother lives near the beach.","a":"My brother lives near the beach.","how":"mai BRUH-ther LIVZ neer the BEECH","why":"lives = one syllable with /z/: the e is silent."},{"say":"He works and plays on weekends.","a":"He works and plays on weekends.","how":"hee WERKS_n PLEIZ_ahn WEEK-endz","why":"works /s/, plays /z/, weekends /z/; and is weak: 'n'."},{"say":"The buses and trains are full.","a":"The buses and trains are full.","how":"the BUH-siz_n TREINZ_er FUL","why":"buses = two syllables (/ɪz/); trains = one syllable (/z/)."},{"say":"My sister fixes old cars.","a":"My sister fixes old cars.","how":"mai SIS-ter FIK-siz_OULD KARZ","why":"fixes = FIK-siz (x sounds ks, so /ɪz/); cars ends in /z/."}],"tip":"In class: say a noun or verb (cat, play, watch, bus…) and students answer with the -s form, showing 1, 2 or 3 fingers for /s/, /z/ or /ɪz/. Then pairs tell each other three things a friend does every week."},{"id":"a1-2","lv":"A1","n":2,"title":"Worked, played, wanted: three -ed endings","focus":"sounds","goal":"Say the past -ed ending correctly: /t/, /d/ or /ɪd/.","goal_es":"Pronunciar bien la terminación -ed del pasado: /t/, /d/ o /ɪd/.","explain":["The past -ed ending has three sounds, and the rule depends on the last sound of the verb, not on the spelling. Most -ed verbs do NOT get an extra syllable: worked has one syllable, not 'work-ed'.","After p, k, f, s, sh and ch (sounds with no voice), -ed sounds /t/: stopped, worked, laughed, missed, washed, watched. After a vowel or a voiced sound (b, g, v, z, l, m, n, r), it sounds /d/: played, lived, called, cleaned.","Only after t or d does -ed add a new syllable, /ɪd/ ('id'): wanted, needed, started, decided. Tip: before a vowel, the /t/ or /d/ joins the next word: worked_at home, played_a game."],"explain_es":["La terminación -ed del pasado tiene tres sonidos, y la regla depende del último sonido del verbo, no de la ortografía. La mayoría de los verbos con -ed NO agregan una sílaba: worked tiene una sola sílaba, no 'work-ed'.","Después de p, k, f, s, sh y ch (sonidos sin voz), -ed suena /t/: stopped, worked, laughed, missed, washed, watched. Después de una vocal o de un sonido con voz (b, g, v, z, l, m, n, r), suena /d/: played, lived, called, cleaned.","Solo después de t o d, -ed agrega una sílaba nueva, /ɪd/ ('id'): wanted, needed, started, decided. Consejo: antes de una vocal, la /t/ o la /d/ se une a la palabra siguiente: worked_at home, played_a game."],"spanish":"Spanish speakers often say every -ed as 'ed' (work-ed, play-ed) or drop it completely (I work yesterday). Add a syllable only after t or d; with all other verbs, just add a quick /t/ or /d/ at the end.","spanish_es":"Los hispanohablantes suelen decir toda terminación -ed como 'ed' (work-ed, play-ed) o la omiten por completo (I work yesterday). Agrega una sílaba solo después de t o d; con todos los demás verbos, solo agrega una /t/ o /d/ rápida al final.","ex":[{"t":"worked","how":"werkt","note":"after k → /t/: one syllable"},{"t":"stopped","how":"stahpt","note":"after p → /t/"},{"t":"played","how":"pleid","note":"after a vowel → /d/"},{"t":"lived","how":"livd","note":"after v → /d/"},{"t":"wanted","how":"WAHN-tid","note":"after t → /ɪd/: two syllables"},{"t":"needed","how":"NEE-did","note":"after d → /ɪd/: two syllables"},{"t":"I watched a movie.","how":"ai WAHCH-ta MOO-vee","note":"watched = one syllable; its /t/ joins a"},{"t":"I cooked, cleaned and painted the kitchen.","how":"ai KUKT, KLEEND_n PEIN-tid the KI-chin","note":"/t/ · /d/ · /ɪd/"}],"listen":[{"q":"Which sentence do you hear?","o":["I work at home.","I worked at home."],"pick":true,"why":"In worked_at, the /t/ joins the next word: 'wer-ktat'."},{"q":"How many syllables?","say":"worked","o":["1","2"],"a":0,"why":"worked = 'werkt': no extra syllable after k."},{"q":"Which word do you hear?","o":["want","wanted"],"pick":true,"why":"wanted has two syllables: WAHN-tid."},{"q":"Which ending do you hear?","say":"cleaned","o":["/t/ as in stopped","/d/ as in lived","/ɪd/ as in needed"],"a":1,"why":"After n, a voiced sound, -ed is /d/: 'kleend'."},{"q":"Which sentence do you hear?","o":["We play a lot.","We played a lot."],"pick":true,"why":"played_a lot: the /d/ joins a: 'plei-da'."},{"q":"How many syllables?","say":"decided","o":["2","3","4"],"a":1,"why":"de-CI-ded: after d, -ed adds a syllable."},{"q":"Which sentence do you hear?","o":["I need it.","I needed it."],"pick":true,"why":"needed = NEE-did, with an extra syllable."},{"q":"Which ending do you hear?","say":"washed","o":["/t/ as in stopped","/d/ as in lived","/ɪd/ as in needed"],"a":0,"why":"After sh, a sound with no voice, -ed is /t/: 'wahsht'."}],"mark":[{"mode":"find","q":"Tap the verbs with an extra syllable /ɪd/ ('id').","w":["We","waited,","talked","and","decided","to","stay"],"a":[1,4],"why":"WEI-tid, di-SAI-did: after t and d → /ɪd/. talked = 'tahkt', one syllable."},{"mode":"find","q":"Tap the -ed verbs that end in a /t/ sound.","w":["I","walked","home,","cooked","dinner","and","called","Mom"],"a":[1,3],"why":"walked, cooked: after k → /t/. called: after l → /d/."},{"mode":"find","q":"Tap the words with only ONE syllable.","w":["worked","wanted","played","needed","lived","started"],"a":[0,2,4],"why":"worked, played, lived: one syllable. wanted, needed, started: after t or d, two syllables."},{"mode":"link","q":"Tap where the words join.","w":["I","worked","at","a","bank"],"a":[1,2],"why":"worked_at_a bank: the /t/ of worked joins at, and at joins a."},{"mode":"find","q":"Tap the -ed verbs that end in a /d/ sound.","w":["They","moved","to","Chile","and","opened","a","store"],"a":[1,5],"why":"moved, opened: after v and n → /d/, with no extra syllable."}],"dict":[{"say":"I worked at home yesterday.","a":"I worked at home yesterday.","how":"ai WERK-tat HOUM YES-ter-dei","why":"worked = one syllable (/t/), and the /t/ joins at."},{"say":"We watched a movie last night.","a":"We watched a movie last night.","how":"wee WAHCH-ta MOO-vee las NAIT","why":"watched = one syllable; its /t/ joins a. The t of last is almost silent."},{"say":"She needed a new phone.","a":"She needed a new phone.","how":"shee NEE-di-da NOO FOUN","why":"needed = two syllables (/ɪd/), and it joins a: NEE-di-da."},{"say":"They played soccer and then relaxed.","a":"They played soccer and then relaxed.","how":"thei PLEID SAH-ker_n then ri-LAKST","why":"played ends in /d/, relaxed ends in /t/: no extra syllables."},{"say":"We painted the house and moved in.","a":"We painted the house and moved in.","how":"wee PEIN-tid the HAUS_n MOOV-DIN","why":"painted = two syllables (/ɪd/); moved = one syllable, and its /d/ joins in."}],"tip":"In class: students tell a partner five things they did yesterday; the partner writes each verb in a /t/, /d/ or /ɪd/ column, and then they check together."},{"id":"a1-3","lv":"A1","n":3,"title":"Cat, cut, cot: three different a's","focus":"sounds","goal":"Hear and say three American vowels: /æ/ (cat), /ʌ/ (cut) and /ɑ/ (hot).","goal_es":"Oír y pronunciar tres vocales del inglés americano: /æ/ (cat), /ʌ/ (cut) y /ɑ/ (hot).","explain":["English has three vowels that Spanish speakers often hear as 'a'. /æ/ in cat, bad, man: open your mouth wide and spread your lips, between Spanish a and e. /ʌ/ in cut, bus, love, money: a short, relaxed 'uh', with the mouth half open.","/ɑ/ in hot, stop, job, father: open your mouth and say a long Spanish a: 'haht', 'stahp'. Yes, in American English the letter o in hot or stop sounds like 'a'!","Spelling doesn't help much: o can be /ʌ/ (love, money, come, son) or /ɑ/ (hot, job), and a can be /æ/ (cat) or /ɑ/ (father). UK note: British English says hot, stop and job with a short, round 'o'."],"explain_es":["El inglés tiene tres vocales que los hispanohablantes suelen oír como 'a'. /æ/ en cat, bad, man: abre bien la boca y estira los labios, entre la a y la e del español. /ʌ/ en cut, bus, love, money: un sonido corto y relajado, como una 'a' floja, con la boca medio abierta.","/ɑ/ en hot, stop, job, father: abre la boca y di una a larga, como en español. Sí: en inglés americano, la o de hot o stop suena como 'a'.","La ortografía no ayuda mucho: la o puede ser /ʌ/ (love, money, come, son) o /ɑ/ (hot, job), y la a puede ser /æ/ (cat) o /ɑ/ (father). Nota UK: en inglés británico, hot, stop y job se dicen con una 'o' corta y redondeada."],"spanish":"Spanish speakers often use their own 'a' for all three, or read the spelling: 'love' with o, 'bus' with u. Open wide for /æ/, relax for a short /ʌ/, and say American hot and stop with a long 'ah'.","spanish_es":"Los hispanohablantes suelen usar su 'a' para las tres, o leen la ortografía: 'love' con o, 'bus' con u. Abre bien la boca para /æ/, relájala para una /ʌ/ corta, y di hot y stop del inglés americano con una 'a' larga.","ex":[{"t":"cat","how":"kat","note":"/æ/: mouth wide, between Spanish a and e"},{"t":"cut","how":"kuht","note":"/ʌ/: short and relaxed"},{"t":"cot","how":"kaht","note":"/ɑ/: a long Spanish a"},{"t":"bad","how":"bad","note":"/æ/, like man, hat, black — not 'bed'"},{"t":"money","how":"MUH-nee","note":"/ʌ/: o sounds 'uh', like love, mother, come"},{"t":"father","how":"FAH-ther","note":"/ɑ/ spelled with a"},{"t":"Stop the bus!","how":"STAHP the BUHS","note":"/ɑ/ in stop, /ʌ/ in bus"},{"t":"My mother got a black cat.","how":"mai MUH-ther GAH-da BLAK KAT","note":"/ʌ/ mother · /ɑ/ got · /æ/ black, cat"}],"listen":[{"q":"Which word do you hear?","o":["cap","cup"],"pick":true,"why":"cap: mouth wide, /æ/; cup: a short, relaxed /ʌ/."},{"q":"Which vowel is in the first syllable?","say":"money","o":["/æ/ as in cat","/ʌ/ as in cut","/ɑ/ as in hot"],"a":1,"why":"money = MUH-nee: here the letter o sounds /ʌ/."},{"q":"Which word do you hear?","o":["hat","hot"],"pick":true,"why":"hat has /æ/ (mouth wide); hot has /ɑ/, a long 'ah'."},{"q":"Which vowel is in the first syllable?","say":"father","o":["/æ/ as in cat","/ʌ/ as in cut","/ɑ/ as in hot"],"a":2,"why":"father = FAH-ther: /ɑ/, like a long Spanish a."},{"q":"Which word do you hear?","o":["ban","bun"],"pick":true,"why":"ban has /æ/; bun has a short 'uh', /ʌ/."},{"q":"Which vowel do you hear?","say":"black","o":["/æ/ as in cat","/ʌ/ as in cut","/ɑ/ as in hot"],"a":0,"why":"black = /æ/: open your mouth wide and spread your lips."},{"q":"Which word do you hear?","o":["cat","cut","cot"],"pick":true,"why":"cat /æ/, cut /ʌ/, cot /ɑ/ ('kaht')."},{"q":"Which word do you hear?","o":["luck","lock"],"pick":true,"why":"luck has a short 'uh' (/ʌ/); lock has a long 'ah' (/ɑ/)."}],"mark":[{"mode":"find","q":"Tap the words with /æ/, as in cat.","w":["Dad","lost","his","black","hat"],"a":[0,3,4],"why":"Dad, black, hat: /æ/. lost and his have other vowels."},{"mode":"find","q":"Tap the words with /ʌ/, as in cut.","w":["My","son","comes","home","on","Mondays"],"a":[1,2,5],"why":"son, comes, Mondays: the letter o sounds 'uh'. home and on have other vowels."},{"mode":"find","q":"Tap the words with /ɑ/, as in hot.","w":["My","father","got","a","new","job"],"a":[1,2,5],"why":"father, got, job: a long 'ah', like Spanish a."},{"mode":"find","q":"Tap the words with the vowel of cup.","w":["love","home","some","phone","come","go","one"],"a":[0,2,4,6],"why":"love, some, come, one: 'uh' (/ʌ/). home, phone, go: 'ou'."},{"mode":"find","q":"Tap the words with the vowel of hot.","w":["stop","cup","box","bag","clock","bus","shop"],"a":[0,2,4,6],"why":"stop, box, clock, shop: 'ah' (/ɑ/). cup, bus: 'uh'. bag: /æ/."}],"dict":[{"say":"My dad has a black cat.","a":"My dad has a black cat.","how":"mai DAD haz_a BLAK KAT","why":"dad, black and cat have /æ/: open your mouth wide."},{"say":"Come on, the bus is coming!","a":"Come on, the bus is coming!","how":"kuh-MAHN, the BUH-siz KUH-ming","why":"come, bus, coming: /ʌ/ ('uh'); on: 'ahn'."},{"say":"My son has a new job.","a":"My son has a new job.","how":"mai SUHN haz_a NOO JAHB","why":"son sounds like sun (/ʌ/); job has /ɑ/: 'jahb'."},{"say":"Stop, that's not your hat!","a":"Stop, that's not your hat!","alt":["Stop, that is not your hat!"],"how":"STAHP, thats NAHT yer HAT","why":"stop, not: /ɑ/ ('ah'); that's, hat: /æ/."},{"say":"My mother drives a big truck.","a":"My mother drives a big truck.","how":"mai MUH-ther DRAIV-za BIG TRUHK","why":"mother and truck have /ʌ/ ('uh') — not a Spanish o or u."}],"tip":"In class: label three corners of the room cat, cut and hot; say words like bag, love, job, money, black and stop, and students walk to the right corner."},{"id":"a1-4","lv":"A1","n":4,"title":"H is not J","focus":"sounds","goal":"Say a soft English h, know when h is silent, and tell y (yes) from j (jet).","goal_es":"Pronunciar una h inglesa suave, saber cuándo la h es muda y distinguir la y (yes) de la j (jet).","explain":["English h is very soft: just breath, like when you clean your glasses with your breath. Say hello, house, happy, hungry. Don't use the strong Spanish j from the back of the throat. And don't drop the h in words like hotel, hospital or human: in English it is pronounced.","A few words have a silent h: hour, honest, honor. They start with a vowel sound, so we say an hour, an honest man. American English also says herb without h ('erb'); British English pronounces the h.","Two more letters: English y (yes, yet, you) is soft, like the i in Spanish 'tiene': yes sounds like 'iés'. English j (job, jet) is never the Spanish j: it sounds like 'dy', a ch with voice. G often has this sound too: Germany, gym."],"explain_es":["La h inglesa es muy suave: solo aire, como cuando empañas tus lentes para limpiarlos. Di hello, house, happy, hungry. No uses la j fuerte del español, que se hace al fondo de la garganta. Y no omitas la h en palabras como hotel, hospital o human: en inglés sí se pronuncia.","Algunas palabras tienen h muda: hour, honest, honor. Empiezan con sonido de vocal, por eso decimos an hour, an honest man. El inglés americano también dice herb sin h ('erb'); el británico sí pronuncia la h.","Dos letras más: la y inglesa (yes, yet, you) es suave, como la i de 'tiene': yes suena como 'iés'. La j inglesa (job, jet) nunca es la j española: suena como 'dy', una ch con voz. La g muchas veces tiene este sonido también: Germany, gym."],"spanish":"Spanish speakers often say h with the strong Spanish j sound, drop it in words like hotel, or read English j as the Spanish j (job, John). For h, just breathe out softly; for j, say 'dy'.","spanish_es":"Los hispanohablantes suelen decir la h con el sonido fuerte de la j española, la omiten en palabras como hotel, o leen la j inglesa como la j española (job, John). Para la h, solo suelta aire suavemente; para la j, di 'dy'.","ex":[{"t":"hello","how":"heh-LOU","note":"soft h: just breath"},{"t":"happy","how":"HA-pee","note":"soft h + /æ/"},{"t":"hotel","how":"hou-TEL","note":"say the h! (in Spanish hotel it is silent)"},{"t":"hungry","how":"HUHNG-gree","note":"soft h — not 'angry'"},{"t":"an hour","how":"a-NAUR","note":"silent h: hour sounds like 'our'"},{"t":"an honest man","how":"a-NAH-nist MAN","note":"silent h"},{"t":"Yes, I have a job.","how":"YES, ai HA-va JAHB","note":"y = soft 'i'; j = 'dy'"},{"t":"Hi John, are you hungry yet?","how":"HAI JAHN, ar-yuh HUHNG-gree YET?","note":"h, j and y in one question"}],"listen":[{"q":"Which word do you hear?","o":["hair","air"],"pick":true,"why":"hair starts with a soft breath; air starts with the vowel."},{"q":"Do you hear an h sound?","say":"hour","o":["Yes","No"],"a":1,"why":"hour sounds like 'our': the h is silent."},{"q":"Which sentence do you hear?","o":["I'm hungry.","I'm angry."],"pick":true,"why":"hungry starts with a soft h + 'uh'; angry has no h and starts with /æ/."},{"q":"Do you hear an h sound?","say":"hotel","o":["Yes","No"],"a":0,"why":"hotel: in English the h is pronounced — a soft breath."},{"q":"Which word do you hear?","o":["yet","jet"],"pick":true,"why":"yet starts with a soft y (like Spanish i); jet starts with 'dy'."},{"q":"Which word do you hear before hour?","say":"It takes an hour.","o":["a","an"],"a":1,"why":"an hour: the h is silent, so hour starts with a vowel sound."},{"q":"Which word do you hear?","o":["yolk","joke"],"pick":true,"why":"yolk (the yellow part of an egg) starts with y; joke starts with 'dy'."},{"q":"What is the first sound?","say":"Germany","o":["a y sound, as in yes","a j sound, as in jet","an h sound, as in hello"],"a":1,"why":"Here G sounds like the j in jet: JER-muh-nee."}],"mark":[{"mode":"find","q":"Tap the words with an h sound.","w":["The","hospital","is","behind","the","hotel"],"a":[1,3,5],"why":"hospital, behind, hotel: a soft h. These h's are not silent like in Spanish."},{"mode":"find","q":"Tap the words with a silent h.","w":["We","waited","an","hour","for","an","honest","answer"],"a":[3,6],"why":"hour ('aur') and honest ('AH-nist') start with a vowel sound, so we say an."},{"mode":"link","q":"Tap where the words join.","w":["I","need","an","hour"],"a":[1,2],"why":"need_an_hour: the h of hour is silent, so an joins it: 'NEE-da-NAUR'."},{"mode":"find","q":"Tap the words with a j sound, as in jet.","w":["Your","new","job","is","in","Germany"],"a":[2,5],"why":"job and Germany start with 'dy', the j of jet. Your starts with a soft y."},{"mode":"find","q":"Tap the words with a y sound, as in yes.","w":["Yes,","Jim","has","a","yellow","jacket"],"a":[0,4],"why":"Yes and yellow: a soft y, like Spanish i. Jim and jacket start with 'dy'."}],"dict":[{"say":"Hello, I'm happy to help.","a":"Hello, I'm happy to help.","how":"heh-LOU, aim HA-pee tuh HELP","why":"hello, happy, help: a soft h — just breath, not a Spanish j."},{"say":"The hotel is an hour away.","a":"The hotel is an hour away.","how":"the hou-TEL iz_a-NAUR_a-WEI","why":"hotel: say the h! hour: silent h, so an_hour joins."},{"say":"Do you have a job yet?","a":"Do you have a job yet?","how":"duh-yuh HA-va JAHB YET?","why":"job: j = 'dy'; yet: a soft y, like Spanish i."},{"say":"Yes, I go to the gym.","a":"Yes, I go to the gym.","how":"YES, ai GOU tuh the JIM","why":"yes: a soft y; gym: the g sounds like j ('dy')."},{"say":"I'm hungry, not angry!","a":"I'm hungry, not angry!","how":"aim HUHNG-gree, NAHT ANG-gree","why":"hungry: soft h + 'uh'; angry: no h, and /æ/."}],"tip":"In class: students hold a strip of paper in front of their lips; it should move a little for hello, house and hotel, but not for hour or honest."},{"id":"a1-5","lv":"A1","n":5,"title":"I'm, you're, don't: contractions","focus":"weak","goal":"Use and understand everyday contractions, and hear the difference between can and can't.","goal_es":"Usar y entender las contracciones del día a día, y oír la diferencia entre can y can't.","explain":["In everyday speech, English speakers use contractions: I'm, you're, he's, it's, we're, don't, doesn't, isn't, aren't. They are shorter and faster, and they sound natural. Full forms like I am or do not sound careful or strong; we use them mainly for emphasis.","Listen to the sounds: I'm = 'aim', you're = 'yer' (like your), we're = 'weer', it's = 'its', he's = 'heez'. Doesn't and isn't have two syllables: 'DUZ-nt', 'IZ-nt'. Don't has one syllable with 'ou': 'dount'.","Can and can't: in American English, can in the middle of a sentence is weak, 'kn': I can SWIM. Can't is strong, with the vowel of cat: I CAN'T SWIM. The t is very soft, so listen for the strong vowel. UK note: British can't sounds like 'kahnt'."],"explain_es":["En el habla diaria, los angloparlantes usan contracciones: I'm, you're, he's, it's, we're, don't, doesn't, isn't, aren't. Son más cortas y rápidas, y suenan naturales. Las formas completas como I am o do not suenan cuidadosas o fuertes; las usamos sobre todo para dar énfasis.","Escucha cómo suenan: I'm = 'aim', you're = 'yer' (como your), we're = 'weer', it's = 'its', he's = 'heez'. Doesn't e isn't tienen dos sílabas: 'DUZ-nt', 'IZ-nt'. Don't tiene una sola sílaba, con 'ou': 'dount'.","Can y can't: en inglés americano, can en medio de la oración es débil, 'kn': I can SWIM. Can't es fuerte, con la vocal de cat: I CAN'T SWIM. La t casi no se oye, así que fíjate en la vocal fuerte. Nota UK: en británico, can't suena como 'kahnt'."],"spanish":"Spanish speakers often use full forms (I am, do not), which can sound too formal or emphatic, and they say can and can't the same way. Use contractions, keep can weak ('kn'), and make can't strong: 'KANT'.","spanish_es":"Los hispanohablantes suelen usar las formas completas (I am, do not), que pueden sonar demasiado formales o enfáticas, y dicen can y can't igual. Usa contracciones, mantén can débil ('kn') y haz can't fuerte: 'KANT'.","ex":[{"t":"I'm fine.","how":"aim FAIN","note":"I'm = one syllable"},{"t":"You're late.","how":"yer LEIT","note":"you're sounds like your"},{"t":"It's OK, he's here.","how":"its ou-KEI, heez HEER","note":"it's ends in /s/; he's ends in /z/"},{"t":"We're at work.","how":"weer_at WERK","note":"we're = 'weer', one syllable"},{"t":"I don't eat meat.","how":"ai DOUNT_EET MEET","note":"don't = 'dount', one syllable"},{"t":"It isn't far, so he doesn't drive.","how":"it IZ-nt FAR, sou hee DUZ-nt DRAIV","note":"isn't and doesn't = two syllables"},{"t":"I can swim.","how":"ai kn SWIM","note":"weak can: 'kn'"},{"t":"I can't swim.","how":"ai KANT SWIM","note":"strong can't, with the vowel of cat"}],"listen":[{"q":"Which sentence do you hear?","o":["I can swim.","I can't swim."],"pick":true,"why":"can is a weak 'kn'; can't is a strong 'KANT' — listen for the vowel, not the t."},{"q":"How many syllables?","say":"doesn't","o":["1","2","3"],"a":1,"why":"doesn't = DUZ-nt: two syllables."},{"q":"Which sentence do you hear?","o":["We're at home.","We were at home."],"pick":true,"why":"We're = 'weer', one syllable; We were = 'wee wer', two words."},{"q":"Which do you hear?","say":"I'm a teacher.","o":["I'm","I am"],"a":0,"why":"I'm = 'aim': one short syllable."},{"q":"Which sentence do you hear?","o":["He can cook.","He can't cook."],"pick":true,"why":"can't has the strong vowel of cat; can is just 'kn'."},{"q":"How does can sound at the end?","say":"Yes, I can.","o":["weak: 'kn'","strong: 'kan'"],"a":1,"why":"At the end of a sentence, can is strong: 'yes, ai KAN'."},{"q":"Which sentence do you hear?","o":["It's open.","It isn't open."],"pick":true,"why":"isn't has two syllables: it IZ-nt OU-pn."},{"q":"Which word do you hear?","say":"We don't live here.","o":["don't","doesn't","didn't"],"a":0,"why":"don't = 'dount', one syllable; doesn't and didn't have two."}],"mark":[{"mode":"weak","q":"Tap the weak word.","w":["Peter","can","speak","Spanish"],"a":[1],"why":"can is weak in the middle: PEE-ter kn SPEAK SPA-nish."},{"mode":"stress","q":"Tap the stressed words.","w":["I","can't","swim"],"a":[1,2],"why":"can't is strong and stressed: ai KANT SWIM. Compare I can SWIM."},{"mode":"stress","q":"Tap the stressed words.","w":["Yes,","I","can"],"a":[0,2],"why":"At the end, can is strong and stressed: YES, ai KAN."},{"mode":"find","q":"Tap the words with two syllables.","w":["This","isn't","fair,","and","he","doesn't","care"],"a":[1,5],"why":"isn't = IZ-nt, doesn't = DUZ-nt. All the other words have one syllable."},{"mode":"find","q":"Tap the contractions that end in a /z/ sound.","w":["He's","here,","it's","late,","and","she's","tired"],"a":[0,5],"why":"he's, she's = 'heez', 'sheez' (/z/); it's = 'its' (/s/ after t)."}],"dict":[{"say":"I'm sorry, I can't come today.","a":"I'm sorry, I can't come today.","alt":["I'm sorry, I can not come today."],"how":"aim SAH-ree, ai KANT KUHM tuh-DEI","why":"I'm = 'aim'; can't is strong, and its t is almost silent before come."},{"say":"She doesn't work on Fridays.","a":"She doesn't work on Fridays.","how":"shee DUZ-nt WER-kahn FRAI-deiz","why":"doesn't = DUZ-nt, two syllables; work_on joins."},{"say":"We're not ready yet.","a":"We're not ready yet.","how":"weer NAHT RE-dee YET","why":"we're = 'weer', one syllable — not 'we-are'."},{"say":"It's late and they aren't here.","a":"It's late and they aren't here.","alt":["It is late and they aren't here."],"how":"its LEIT_n thei ARNT HEER","why":"it's = 'its'; aren't = 'arnt', one syllable; and is weak: 'n'."},{"say":"You're right. We can take a taxi.","a":"You're right. We can take a taxi.","how":"yer RAIT. wee kn TEI-ka TAK-see","why":"you're sounds like 'yer'; can is weak ('kn'); take_a joins."}],"tip":"In class: students say true sentences about their skills (I can cook, I can't dance) and the group shows a thumbs up for can or a thumbs down for can't."},{"id":"a1-6","lv":"A1","n":6,"title":"Fish 'n' chips: weak and, or, of","focus":"weak","goal":"Say and hear the weak forms of and ('n'), or ('er') and of ('uv') in everyday phrases.","goal_es":"Decir y reconocer las formas débiles de and ('n'), or ('er') y of ('uv') en frases de todos los días.","explain":["Small grammar words like and, or and of are usually weak in English: short, quick and quiet. The important words around them are strong: FISH 'n' CHIPS, TEA or COF-fee, a CUP of TEA. The weak word joins the word before it.","And often sounds like just 'n': rock 'n' roll, salt 'n' pepper. Or sounds like 'er': tea-er-coffee. Of sounds like 'uv', with an English v (top teeth on the lower lip), not an f: a cup-uv tea, a lot-uv people.","You hear these weak forms everywhere: in cafés, in shops, on TV. If you wait for a clear AND or OF, you may miss it. Listen for 'n', 'er' and 'uv'. UK note: in British English, or sounds like 'uh': tea-uh-coffee."],"explain_es":["Las palabras gramaticales pequeñas como and, or y of normalmente son débiles en inglés: cortas, rápidas y suaves. Las palabras importantes que las rodean son fuertes: FISH 'n' CHIPS, TEA or COF-fee, a CUP of TEA. La palabra débil se une a la palabra anterior.","And muchas veces suena solo como 'n': rock 'n' roll, salt 'n' pepper. Or suena como 'er': tea-er-coffee. Of suena como 'uv', con la v inglesa (los dientes de arriba sobre el labio de abajo), no con f: a cup-uv tea, a lot-uv people.","Vas a escuchar estas formas débiles en todas partes: en cafeterías, en tiendas, en la tele. Si esperas un AND o un OF claro, puede que no lo escuches. Pon atención a 'n', 'er' y 'uv'. Nota UK: en inglés británico, or suena como 'uh': tea-uh-coffee."],"spanish":"Spanish speakers often say every word fully and clearly: 'salt AND pepper', 'tea OR coffee', 'a cup OF tea' with an f. Fix: make and, or and of short and quiet ('n', 'er', 'uv') and join them to the word before.","spanish_es":"Los hispanohablantes suelen decir cada palabra completa y clara: 'salt AND pepper', 'tea OR coffee', 'a cup OF tea' con f. Solución: di and, or y of cortas y suaves ('n', 'er', 'uv') y únelas a la palabra anterior.","ex":[{"t":"fish and chips","how":"FISH-n-CHIPS","note":"and → 'n'"},{"t":"rock and roll","how":"ROCK-n-ROLL","note":"often written rock 'n' roll"},{"t":"salt and pepper","how":"SAWLT-n-PEP-er","note":"and → 'n', joined to salt"},{"t":"tea or coffee","how":"TEE-er-KAW-fee","note":"or → 'er' · UK: TEE-uh-KOF-ee"},{"t":"black or white","how":"BLACK-er-WHITE","note":"or → 'er'"},{"t":"a cup of tea","how":"uh-KUP-uv-TEE","note":"of → 'uv', with a v sound"},{"t":"a lot of people","how":"uh-LAH-duv-PEE-pul","note":"of → 'uv' · the t sounds like a quick d"},{"t":"I'd like a cup of coffee and a muffin.","how":"aid LIKE uh-KUP-uv-KAW-fee-uh-nuh-MUF-in","note":"of → 'uv'; and → 'un' after a vowel"}],"listen":[{"q":"Which do you hear?","o":["tea or coffee","tea and coffee"],"pick":true,"why":"or sounds like 'er' (TEE-er-KAW-fee); and sounds like 'un' (TEE-un-KAW-fee)."},{"q":"Which do you hear?","o":["salt and pepper","salt or pepper"],"pick":true,"why":"and → 'n' (SAWLT-n-PEP-er); or → 'er' (SAWLT-er-PEP-er)."},{"q":"Which question do you hear?","o":["Is it black or white?","Is it black and white?"],"pick":true,"why":"black or white = BLACK-er-WHITE; black and white = BLACK-n-WHITE."},{"q":"How many words do you hear?","say":"a cup of tea","o":["3","4","5"],"a":1,"why":"a + cup + of + tea = 4 words; of is short and weak: uh-KUP-uv-TEE."},{"q":"How many words do you hear?","say":"rock and roll","o":["2","3","4"],"a":1,"why":"rock 'n' roll: and is only 'n', but it is still a word: 3 words."},{"q":"Which word is in the gap? 'a glass ___ water'","say":"a glass of water","o":["of","or","and"],"a":0,"why":"uh-GLASS-uv-WAH-der: 'uv' is the weak form of of."},{"q":"Which word is in the gap? 'Do you want milk ___ sugar?'","say":"Do you want milk or sugar?","o":["and","or","of"],"a":1,"why":"MILK-er-SHUG-er: 'er' is the weak form of or."},{"q":"Which word is in the gap? 'My mom ___ dad are here.'","say":"My mom and dad are here.","o":["or","of","and"],"a":2,"why":"MOM-n-DAD: 'n' is the weak form of and."}],"mark":[{"mode":"weak","q":"Tap the weak word.","w":["salt","and","pepper"],"a":[1],"why":"salt 'n' pepper: and → 'n'."},{"mode":"weak","q":"Tap the weak word.","w":["Tea","or","coffee?"],"a":[1],"why":"TEE-er-KAW-fee: or → 'er'."},{"mode":"weak","q":"Tap the weak words.","w":["a","cup","of","tea"],"a":[0,2],"why":"a → 'uh', of → 'uv': uh-KUP-uv-TEE. Cup and tea are strong."},{"mode":"weak","q":"Tap the weak words.","w":["Fish","and","chips","or","pizza?"],"a":[1,3],"why":"FISH-n-CHIPS-er-PEET-suh: and → 'n', or → 'er'."},{"mode":"link","q":"Tap where a consonant joins a vowel.","w":["a","glass","of","orange","juice"],"a":[1,2],"why":"glass_of_orange: s + o, v + o → 'uh-GLA-suh-VOR-inj JOOS'."}],"dict":[{"say":"Salt and pepper, please.","a":"Salt and pepper, please.","how":"SAWLT-n-PEP-er, PLEEZ","why":"and → 'n', joined to salt."},{"say":"Do you want tea or coffee?","a":"Do you want tea or coffee?","how":"d'yuh WANT TEE-er-KAW-fee?","why":"or → 'er' between tea and coffee; do you → 'd'yuh'."},{"say":"Can I have a glass of water?","a":"Can I have a glass of water?","how":"k'n-ai HAV uh-GLA-suv-WAH-der?","why":"of → 'uv', joined to glass; can → 'k'n'."},{"say":"We had fish and chips for lunch.","a":"We had fish and chips for lunch.","how":"wee HAD FISH-n-CHIPS fer LUNCH","why":"and → 'n'; for is weak too: 'fer'."},{"say":"There were a lot of people.","a":"There were a lot of people.","how":"ther wer uh-LAH-duv-PEE-pul","why":"of → 'uv'; the t in lot sounds like a quick d."}],"tip":"In class: play 'café orders'. One student asks 'Tea or coffee?', 'Salt and pepper?', 'A cup of tea?' and the partner answers; the group listens for 'n', 'er' and 'uv' and stops anyone who says a full AND, OR or OF."},{"id":"a1-7","lv":"A1","n":7,"title":"PREsent or preSENT? Two-syllable words","focus":"stress","goal":"Stress the right syllable in two-syllable words, and hear the difference between a PREsent and to preSENT.","goal_es":"Acentuar la sílaba correcta en palabras de dos sílabas y escuchar la diferencia entre a PREsent y to preSENT.","explain":["In a two-syllable word, one syllable is strong: longer, louder and higher. Most two-syllable nouns and adjectives are strong on the first syllable: HAP-py, TA-ble, MO-ther, PROB-lem. The pattern is Oo (O = strong).","Many two-syllable verbs are strong on the second syllable: re-LAX, be-GIN, de-CIDE, for-GET. The pattern is oO. The weak syllable is short: relax sounds like 'rih-LAKS'. But not all verbs: AN-swer, FIN-ish and VIS-it are strong on the first syllable.","Some words are a noun and a verb with the same spelling. The stress tells you which one: a PRE-sent (a gift), but to pre-SENT (to show to a group); a RE-cord, but to re-CORD. Listen to the whole sentence."],"explain_es":["En una palabra de dos sílabas, una sílaba es fuerte: más larga, con más volumen y más aguda. La mayoría de los sustantivos y adjetivos de dos sílabas son fuertes en la primera sílaba: HAP-py, TA-ble, MO-ther, PROB-lem. El patrón es Oo (O = fuerte).","Muchos verbos de dos sílabas son fuertes en la segunda sílaba: re-LAX, be-GIN, de-CIDE, for-GET. El patrón es oO. La sílaba débil es corta: relax suena como 'rih-LAKS'. Pero no todos los verbos: AN-swer, FIN-ish y VIS-it son fuertes en la primera sílaba.","Algunas palabras son sustantivo y verbo, y se escriben igual. El acento te dice cuál es: a PRE-sent (un regalo), pero to pre-SENT (presentar); a RE-cord (un récord o un disco), pero to re-CORD (grabar). Escucha la oración completa."],"spanish":"Spanish speakers often give both syllables the same force and full vowels, or copy the Spanish stress (proBLEma → 'proBLEM'). Fix: one strong syllable and one short, weak syllable: PRAH-blum, rih-LAKS, a PREZ-unt.","spanish_es":"Los hispanohablantes suelen dar la misma fuerza y vocales completas a las dos sílabas, o copian el acento del español (proBLEma → 'proBLEM'). Solución: una sílaba fuerte y otra corta y débil: PRAH-blum, rih-LAKS, a PREZ-unt.","ex":[{"t":"happy","how":"HAP-ee","note":"adjective · Oo"},{"t":"mother","how":"MUH-ther","note":"noun · Oo"},{"t":"problem","how":"PRAH-blum","note":"noun · Oo · Spanish: proBLEma"},{"t":"relax","how":"rih-LAKS","note":"verb · oO"},{"t":"decide","how":"dih-SIDE","note":"verb · oO"},{"t":"Thanks for the present!","how":"THANKS fer thuh PREZ-unt!","note":"noun (a gift): PRE-sent"},{"t":"Let me present my team.","how":"let mee prih-ZENT my TEEM","note":"verb (to show to a group): pre-SENT"},{"t":"Can I record this call?","how":"k'n-ai rih-KORD this KAWL?","note":"verb: re-CORD · noun: a RE-cord (REK-erd)"}],"listen":[{"q":"Where is the stress? (O = strong)","say":"happy","o":["Oo: HAP-py","oO: hap-PY"],"a":0,"why":"HAP-py: adjectives usually stress the first syllable."},{"q":"Where is the stress? (O = strong)","say":"relax","o":["Oo: RE-lax","oO: re-LAX"],"a":1,"why":"re-LAX: many verbs stress the second syllable."},{"q":"Where is the stress? (O = strong)","say":"mother","o":["Oo: MO-ther","oO: mo-THER"],"a":0,"why":"MO-ther (MUH-ther): nouns usually stress the first syllable."},{"q":"Where is the stress? (O = strong)","say":"begin","o":["Oo: BE-gin","oO: be-GIN"],"a":1,"why":"be-GIN (bih-GIN) is a verb: stress on the second syllable."},{"q":"Which word is oO (strong second syllable)?","say":"table, forget, window","o":["table","forget","window"],"a":1,"why":"for-GET is a verb: oO. TA-ble and WIN-dow are nouns: Oo."},{"q":"Which word is Oo (strong first syllable)?","say":"decide, problem, enjoy","o":["decide","problem","enjoy"],"a":1,"why":"PROB-lem is a noun: Oo. de-CIDE and en-JOY are verbs: oO."},{"q":"Is present a noun or a verb here?","say":"Thanks for the present!","o":["noun: PRE-sent","verb: pre-SENT"],"a":0,"why":"the present = a gift, a noun: PREZ-unt."},{"q":"Is record a noun or a verb here?","say":"Can I record the meeting?","o":["noun: RE-cord","verb: re-CORD"],"a":1,"why":"to record = to save the sound, a verb: rih-KORD."}],"mark":[{"mode":"stress","q":"Tap the stressed syllable.","w":["hap","py"],"word":true,"a":[0],"why":"HAP-py: an adjective, stress on the first syllable."},{"mode":"stress","q":"Tap the stressed syllable.","w":["de","cide"],"word":true,"a":[1],"why":"de-CIDE (dih-SIDE): a verb, stress on the second syllable."},{"mode":"stress","q":"Tap the stressed syllable.","w":["prob","lem"],"word":true,"a":[0],"why":"PROB-lem (PRAH-blum): stress first. In Spanish it is proBLEma."},{"mode":"find","q":"Tap the words with stress on the second syllable (oO).","w":["arrive,","answer,","forget,","finish,","enjoy"],"a":[0,2,4],"why":"ar-RIVE, for-GET, en-JOY. AN-swer and FIN-ish are verbs too, but they stress the first syllable."},{"mode":"find","q":"Tap the words with stress on the second syllable.","w":["Please","present","your","project","today."],"a":[1,4],"why":"pre-SENT is a verb here, and to-DAY is oO. PRO-ject is a noun: stress first."}],"dict":[{"say":"I bought a present for my mother.","a":"I bought a present for my mother.","how":"ai BAWT uh PREZ-unt fer my MUH-ther","why":"PRE-sent (a noun) and MO-ther: stress on the first syllable."},{"say":"Relax and enjoy the music.","a":"Relax and enjoy the music.","how":"rih-LAKS-n-en-JOY thuh MYOO-zik","why":"re-LAX and en-JOY are verbs: oO. MU-sic is a noun: Oo."},{"say":"When does the movie begin?","a":"When does the movie begin?","how":"wen duz thuh MOO-vee bih-GIN?","why":"MO-vie (a noun): Oo. be-GIN (a verb): oO."},{"say":"They want to record a new album.","a":"They want to record a new album.","how":"they WANT tuh rih-KOR-duh NOO AL-bum","why":"re-CORD is a verb here: oO. AL-bum is a noun: Oo."},{"say":"We need to decide today.","a":"We need to decide today.","how":"wee NEED tuh dih-SIDE tuh-DAY","why":"de-CIDE and to-DAY: both oO, with a short weak first syllable."}],"tip":"In class: draw two columns, Oo and oO. Students call out two-syllable words from their work or daily life and the class decides the column; then pairs make one sentence with present or record as a noun and one as a verb."},{"id":"a1-8","lv":"A1","n":8,"title":"Turn it off: linking consonant to vowel","focus":"linking","goal":"Join a final consonant to the next vowel, as in turn_it_off and an_apple.","goal_es":"Unir la consonante final de una palabra con la vocal de la palabra siguiente, como en turn_it_off y an_apple.","explain":["In English, we don't say words one by one. When a word ends in a consonant sound and the next word starts with a vowel sound, we join them. Turn_it_off sounds like 'tur-ni-dawf'. An_apple sounds like 'a-napple'.","The last consonant moves to the next word. There is no stop and no extra sound: pick_it_up = 'pi-ki-dup', check_in = 'che-kin', look_at_it = 'loo-kuh-dit'. In American English, a t between two vowels often sounds like a quick d: get_up = 'ge-dup'.","You already do this in Spanish: 'los amigos' sounds like 'lo-sa-migos'. Linking makes your English smooth. It also helps you understand: a phrase like 'look at it' can sound like one long word."],"explain_es":["En inglés no decimos las palabras una por una. Cuando una palabra termina en sonido de consonante y la siguiente empieza con sonido de vocal, las unimos. Turn_it_off suena como 'tur-ni-dawf'. An_apple suena como 'a-napple'.","La última consonante pasa a la palabra siguiente. No hay pausa ni sonido extra: pick_it_up = 'pi-ki-dup', check_in = 'che-kin', look_at_it = 'loo-kuh-dit'. En inglés americano, una t entre dos vocales muchas veces suena como una d rápida: get_up = 'ge-dup'.","Esto ya lo haces en español: 'los amigos' suena como 'lo-sa-migos'. Unir las palabras hace que tu inglés suene fluido. Además, te ayuda a entender: una frase como 'look at it' puede sonar como una sola palabra larga."],"spanish":"Spanish speakers often stop between English words or drop the last consonant: 'tur… i… of', 'pi… i… up'. Fix: keep the final consonant and move it to the next word, as in Spanish 'los_amigos': tur-ni-DAWF, pi-ki-DUP.","spanish_es":"Los hispanohablantes suelen hacer pausas entre las palabras en inglés o se comen la última consonante: 'tur… i… of', 'pi… i… up'. Solución: mantén la consonante final y pásala a la palabra siguiente, como en 'los_amigos': tur-ni-DAWF, pi-ki-DUP.","ex":[{"t":"an apple","how":"an_apple → uh-NAP-ul","note":"n + a"},{"t":"get up","how":"get_up → ge-DUP","note":"t + u · the t sounds like a quick d"},{"t":"check in","how":"check_in → che-KIN","note":"k + i · at a hotel or an airport"},{"t":"Turn it off.","how":"turn_it_off → tur-ni-DAWF","note":"n + i, t + o"},{"t":"Pick it up.","how":"pick_it_up → pi-ki-DUP","note":"k + i, t + u"},{"t":"Look at it.","how":"look_at_it → LOO-kuh-dit","note":"k + a, t + i"},{"t":"Come in and sit down.","how":"come_in_and sit DOWN → kuh-MI-nun sit DOWN","note":"m + i, n + a"},{"t":"Can I have an egg?","how":"can_I have_an_egg → kuh-NAI ha-vuh-NEG?","note":"n + I, v + a, n + e"}],"listen":[{"q":"Which do you hear?","o":["Turn it on.","Turn it off."],"pick":true,"why":"turn_it_on = 'tur-ni-DAHN'; turn_it_off = 'tur-ni-DAWF'. Listen to the end."},{"q":"Which do you hear?","o":["check in","check out"],"pick":true,"why":"check_in sounds like 'che-KIN'; check_out sounds like 'che-KOUT'."},{"q":"Which do you hear?","o":["Look at it.","Look at this."],"pick":true,"why":"look_at_it = 'LOO-kuh-dit'; in 'look at this', th is a consonant, so at and this don't link."},{"q":"How many words do you hear?","say":"Turn it off.","o":["2","3","4"],"a":1,"why":"turn_it_off: 3 words that sound like one."},{"q":"How many words do you hear?","say":"Come in and sit down.","o":["4","5","6"],"a":1,"why":"come_in_and sounds like 'kuh-MI-nun', but it is 3 words: 5 in total."},{"q":"What's the last word?","say":"Can you pick it up?","o":["up","on","out"],"a":0,"why":"pick_it_up: the t of it joins up: 'pi-ki-DUP'."},{"q":"Which phrase do you hear?","say":"She has an old car.","o":["a new car","an old car","a nice car"],"a":1,"why":"an_old: the n joins old: 'uh-NOLD KAR'."},{"q":"Which phrase do you hear?","say":"Hold on a minute.","o":["hold on","hold up","hold it"],"a":0,"why":"hold_on_a: d + o, n + a → 'hol-DAH-nuh MIN-it'."}],"mark":[{"mode":"link","q":"Tap where a consonant joins a vowel.","w":["Please","turn","it","off."],"a":[1,2],"why":"turn_it_off: n + i, t + o → 'tur-ni-DAWF'. Please and turn don't link: two consonants."},{"mode":"link","q":"Tap where a consonant joins a vowel.","w":["I","need","an","answer."],"a":[1,2],"why":"need_an_answer: d + a, n + a → 'NEE-duh-NAN-ser'."},{"mode":"link","q":"Tap where a consonant joins a vowel.","w":["Look","at","it","now."],"a":[0,1],"why":"look_at_it: k + a, t + i. It and now don't link: t + n are two consonants."},{"mode":"link","q":"Tap where a consonant joins a vowel.","w":["We","check","in","at","six."],"a":[1,2],"why":"check_in_at: k + i, n + a → 'che-KI-nat SIKS'."},{"mode":"find","q":"Tap the words that start with a vowel sound.","w":["Get","up","and","open","the","window."],"a":[1,2,3],"why":"up, and, open start with a vowel sound, so they join the word before: get_up_and_open."}],"dict":[{"say":"Turn it off, please.","a":"Turn it off, please.","how":"tur-ni-DAWF, PLEEZ","why":"turn_it_off: n + i, t + o; the t sounds like a quick d."},{"say":"Put it on the table.","a":"Put it on the table.","how":"pu-di-DAHN thuh TAY-bul","why":"put_it_on: t + i, t + o; both t's sound like a quick d."},{"say":"I get up at seven.","a":"I get up at seven.","how":"ai ge-DU-pat SEV-un","why":"get_up_at: t + u, p + a."},{"say":"Let's check in at the hotel.","a":"Let's check in at the hotel.","how":"lets che-KI-nat thuh ho-TEL","why":"check_in_at: k + i, n + a."},{"say":"We need an umbrella.","a":"We need an umbrella.","how":"wee NEE-duh-num-BREL-uh","why":"need_an_umbrella: d + a, n + u."}],"tip":"In class: give quick commands at natural speed (Turn it off! Pick it up! Come in! Look at it!) and students act them out; then they write the commands and draw a linking arc wherever a consonant meets a vowel."},{"id":"a1-9","lv":"A1","n":9,"title":"I WANT a CUP of COFfee: stressed words","focus":"rhythm","goal":"Make content words strong and grammar words weak, and clap the rhythm of short sentences.","goal_es":"Hacer fuertes las palabras de contenido y débiles las palabras gramaticales, y marcar con las palmas el ritmo de oraciones cortas.","explain":["In an English sentence, some words are strong and some are weak. Content words carry the meaning: nouns (coffee), main verbs (want), adjectives (big), adverbs (today) and negatives (don't). They are strong: longer, louder and clearer.","Grammar words like a, the, of, to, in and is, and pronouns like I, me and she, are usually weak: short, quick and quiet. Strong and weak words make a rhythm, like music: I WANT a CUP of COF-fee. Clap on the strong syllables.","When you listen, catch the strong words first: WANT … CUP … COFFEE. They give you the message. When you speak, don't say every word the same way: make the important words strong."],"explain_es":["En una oración en inglés, algunas palabras son fuertes y otras son débiles. Las palabras de contenido llevan el significado: sustantivos (coffee), verbos principales (want), adjetivos (big), adverbios (today) y negaciones (don't). Son fuertes: más largas, con más volumen y más claras.","Las palabras gramaticales como a, the, of, to, in e is, y los pronombres como I, me y she, normalmente son débiles: cortas, rápidas y suaves. Las palabras fuertes y débiles forman un ritmo, como la música: I WANT a CUP of COF-fee. Aplaude en las sílabas fuertes.","Cuando escuches, fíjate primero en las palabras fuertes: WANT … CUP … COFFEE. Ellas te dan el mensaje. Cuando hables, no digas todas las palabras de la misma forma: haz fuertes las palabras importantes."],"spanish":"Spanish gives every syllable about the same time, so Spanish speakers often say every English word strong and clear: 'I – WANT – A – CUP – OF – COF-FEE'. Fix: stress the content words and say the grammar words quickly and softly between them.","spanish_es":"En español cada sílaba dura más o menos lo mismo, por eso los hispanohablantes suelen decir todas las palabras en inglés fuertes y claras: 'I – WANT – A – CUP – OF – COF-FEE'. Solución: haz fuertes las palabras de contenido y di las palabras gramaticales rápido y suave entre ellas.","ex":[{"t":"Coffee, please.","how":"KAW-fee, PLEEZ","note":"O o O"},{"t":"I like it.","how":"ai LAI-kit","note":"o O o"},{"t":"Call me later.","how":"KAWL mee LAY-der","note":"O o O o"},{"t":"I want a cup of coffee.","how":"ai WAN-tuh KUP-uv KAW-fee","note":"o O o O o O o · 3 beats"},{"t":"She works in a big bank.","how":"shee WURK-si-nuh BIG BANK","note":"strong: works, big, bank"},{"t":"They don't eat meat.","how":"they DOHNT EET MEET","note":"negatives are strong"},{"t":"The train is very late today.","how":"thuh TRAIN iz VER-ee LATE tuh-DAY","note":"4 beats: train, very, late, today"},{"t":"My friends are coming to dinner on Friday.","how":"my FRENZ er KUM-ing tuh DIN-er on FRY-day","note":"4 beats; the weak words are quick"}],"listen":[{"q":"How many strong words (beats) do you hear?","say":"I want a cup of coffee.","o":["2","3","4"],"a":1,"why":"Three beats: WANT, CUP, COF-fee. I, a and of are weak."},{"q":"Which words are strong?","say":"She works in a big bank.","o":["she, in, a","works, big, bank","she, works, in"],"a":1,"why":"The content words are strong: WORKS, BIG, BANK."},{"q":"Which rhythm do you hear? (O = strong, o = weak)","say":"Call me later.","o":["O o O o","o O o O","O O o o"],"a":0,"why":"CALL me LA-ter: me is a weak pronoun."},{"q":"Which rhythm do you hear? (O = strong, o = weak)","say":"It's a nice day.","o":["o o O O","O o O o","o O o O"],"a":0,"why":"it's a NICE DAY: it's and a are weak."},{"q":"The strong words are the same. Which sentence do you hear?","o":["Give me the book.","Give me a book."],"pick":true,"why":"the book = 'thuh BOOK'; a book = 'uh BOOK'. Listen for the quick weak word."},{"q":"Which word is weak?","say":"We bought a new car.","o":["bought","a","new","car"],"a":1,"why":"a is a grammar word: 'uh'. BOUGHT, NEW and CAR are strong."},{"q":"How many strong words (beats) do you hear?","say":"My brother is a doctor.","o":["2","3","4"],"a":0,"why":"Two beats: BRO-ther, DOC-tor. My, is and a are weak."},{"q":"The strong words are the same. Which sentence do you hear?","o":["Put it in the box.","Put it on the box."],"pick":true,"why":"PUT and BOX are strong; listen for the weak word in the middle: in or on."}],"mark":[{"mode":"stress","q":"Tap the strong words.","w":["I","want","a","cup","of","coffee."],"a":[1,3,5],"why":"I WANT a CUP of COF-fee: verb, noun, noun."},{"mode":"stress","q":"Tap the strong words.","w":["We","need","a","new","computer."],"a":[1,3,4],"why":"we NEED a NEW com-PU-ter: verb, adjective, noun."},{"mode":"stress","q":"Tap the strong words.","w":["She","doesn't","drink","coffee."],"a":[1,2,3],"why":"she DOES-n't DRINK COF-fee: negative, verb, noun."},{"mode":"weak","q":"Tap the weak (grammar) words.","w":["I","need","to","call","the","doctor."],"a":[0,2,4],"why":"I, to and the are weak. NEED, CALL and DOC-tor are strong."},{"mode":"weak","q":"Tap the weak (grammar) words.","w":["We","went","to","the","beach","on","Sunday."],"a":[0,2,3,5],"why":"We, to, the and on are weak. WENT, BEACH and SUN-day are strong."}],"dict":[{"say":"I'd like a piece of cake.","a":"I'd like a piece of cake.","how":"aid LIKE uh-PEE-suv KAKE","why":"3 beats: like, piece, cake. I'd, a and of are quick and weak."},{"say":"He lives in a small town.","a":"He lives in a small town.","how":"hee LIV-zi-nuh SMAWL TOWN","why":"Strong: lives, small, town. He, in and a are weak and join together."},{"say":"We don't have a car.","a":"We don't have a car.","how":"wee DOHNT HA-vuh KAR","why":"Strong: don't, have, car. We and a are weak."},{"say":"My sister is a teacher.","a":"My sister is a teacher.","how":"my SIS-ter i-zuh TEE-cher","why":"2 beats: SIS-ter, TEACH-er. My, is and a are weak."},{"say":"Can we have the check, please?","a":"Can we have the check, please?","how":"k'n-wee HAV thuh CHECK, PLEEZ?","why":"Strong: have, check, please. Can, we and the are weak. (UK: the bill.)"}],"tip":"In class: students tap the table on the strong words of a short sentence (I WANT a CUP of COFfee), then keep the same beat while the sentence grows: I WANT a CUP of COFfee and a PIECE of CAKE."},{"id":"a2-1","lv":"A2","n":1,"title":"Was, were, can, to: weak or strong?","focus":"weak","goal":"Use the weak forms of was, were, can, to, for and at in sentences, and the strong forms at the end and in short answers.","goal_es":"Usar las formas débiles de was, were, can, to, for y at dentro de la oración, y las formas fuertes al final y en las respuestas cortas.","explain":["Small grammar words like was, were, can, to, for and at are usually weak in a sentence: short, quick and with a schwa /ə/ (a relaxed 'uh'). I was tired = 'I w'z TIRED'. I can swim = 'I k'n SWIM'. I go to work = 'I go t' WORK'.","It's the same with were /wər/ (They were late), for /fər/ (This is for you) and at /ət/ (She's at home). The important words (late, you, home) stay strong and clear.","But these words are strong at the end of a sentence and in short answers: Yes, I was. Yes, I can. Who is it for? What are you looking at? Here you say the full vowel: 'wuz' (like does), 'can' (like cat), 'for', 'at'."],"explain_es":["Las palabras gramaticales pequeñas como was, were, can, to, for y at normalmente son débiles en la oración: cortas, rápidas y con schwa /ə/ (una 'uh' relajada). I was tired = 'I w'z TIRED'. I can swim = 'I k'n SWIM'. I go to work = 'I go t' WORK'.","Lo mismo pasa con were /wər/ (They were late), for /fər/ (This is for you) y at /ət/ (She's at home). Las palabras importantes (late, you, home) se mantienen fuertes y claras.","Pero estas palabras son fuertes al final de la oración y en las respuestas cortas: Yes, I was. Yes, I can. Who is it for? What are you looking at? Ahí se dice la vocal completa: 'wuz' (como does), 'can' (como cat), 'for', 'at'."],"spanish":"Spanish speakers often give every word a full, clear vowel ('ai uás taird'), so the sentence sounds slow and heavy, and when they listen, the weak words seem to disappear. Make the grammar words short with 'uh', and use the full vowel only at the end and in short answers.","spanish_es":"Los hispanohablantes suelen pronunciar cada palabra con su vocal completa y clara ('ai uás taird'), así que la oración suena lenta y pesada, y al escuchar, las palabras débiles parecen desaparecer. Haz cortas las palabras gramaticales, con 'uh', y usa la vocal completa solo al final y en las respuestas cortas.","ex":[{"t":"I was tired.","how":"I w'z TIRED","note":"was → weak /wəz/: very short"},{"t":"They were late.","how":"they w'r LATE","note":"were → weak /wər/"},{"t":"I can swim.","how":"I k'n SWIM","note":"can → weak /kən/; the verb is strong"},{"t":"I go to work by bus.","how":"I GO t' WORK by BUS","note":"to → weak /tə/"},{"t":"This is for you.","how":"this is f'r YOU","note":"for → weak /fər/"},{"t":"She's at home.","how":"she's_'t HOME","note":"at → weak /ət/"},{"t":"Were you at work? Yes, I was.","how":"w'r you_'t WORK? | YES, I WAS.","note":"short answer → strong was: 'wuz'"},{"t":"Who is it for? What are you looking at?","how":"WHO's_it for? | WHAT_'r you LOOKing at?","note":"at the end → full vowels: 'for', 'at' (like cat), not f'r, 't"}],"listen":[{"q":"Which sentence do you hear?","o":["I was tired.","I'm tired."],"pick":true,"why":"In I was tired, was is weak and quick (w'z), but you still hear the w and the z."},{"q":"Which sentence do you hear?","o":["Where were you?","Where are you?"],"pick":true,"why":"Where were you? has a quick 'w'r'; Where are you? has only a weak 'er'."},{"q":"Which sentence do you hear?","o":["It's for Ana.","It's from Ana."],"pick":true,"why":"for is a weak 'f'r'; from is a weak 'fr'm': listen for the m."},{"q":"Which sentence do you hear?","o":["I was at home.","I was home."],"pick":true,"why":"at is weak ('t), but it adds a small syllable: I w'z_'t home."},{"q":"Which sentence do you hear?","o":["I can swim.","I can't swim."],"pick":true,"why":"can is weak (k'n); can't has a clear, stressed 'a', like in cat."},{"q":"How does the last word, was, sound?","say":"Were you tired? Yes, I was.","o":["weak: a quick 'w'z'","strong: a clear 'wuz'"],"a":1,"why":"In a short answer, was is strong."},{"q":"How does for sound here?","say":"Who is this present for?","o":["weak: 'f'r'","strong: a clear 'for'"],"a":1,"why":"At the end of a sentence, for is strong."},{"q":"Which word is weak here?","say":"She drives to work every day.","o":["drives","to","work"],"a":1,"why":"to is a grammar word in the middle: weak 't'' (/tə/)."}],"mark":[{"mode":"weak","q":"Tap the weak words.","w":["Ana","was","at","work"],"a":[1,2],"why":"was → w'z, at → 't: weak grammar words between strong ones."},{"mode":"weak","q":"Tap the weak words.","w":["The","kids","were","late","for","school"],"a":[0,2,4],"why":"the → th', were → w'r, for → f'r."},{"mode":"weak","q":"Tap the weak words.","w":["Tom","can","drive","to","work"],"a":[1,3],"why":"can → k'n, to → t'. The verb drive is strong."},{"mode":"weak","q":"Tap the weak words. Careful with the last word!","w":["Who","was","the","message","for?"],"a":[1,2],"why":"was → w'z, the → th'. for is at the end, so it's strong."},{"mode":"stress","q":"Tap the stressed words.","w":["Yes,","she","can."],"a":[0,2],"why":"YES, she CAN: in a short answer, can is strong (like cat)."}],"dict":[{"say":"I was at home all day.","a":"I was at home all day.","how":"I w'z_'t HOME all DAY","why":"was → w'z, at → 't: weak and quick."},{"say":"They were late for the meeting.","a":"They were late for the meeting.","how":"they w'r LATE f'r th' MEEting","why":"were → w'r, for → f'r, the → th'."},{"say":"Can you come to my party?","a":"Can you come to my party?","how":"k'n you COME t' my PAR-dee?","why":"can → k'n at the start of a question; to → t'."},{"say":"Was it good? Yes, it was.","a":"Was it good? Yes, it was.","how":"w'z_it GOOD? | YES, it WAS.","why":"was is weak in the question and strong in the short answer."},{"say":"What are you waiting for?","a":"What are you waiting for?","how":"what_'r you WAY-ding for?","why":"are → weak 'r; for at the end is strong: a full 'for'."}],"tip":"In class: students ask each other quick questions (Were you at home last night? Can you drive? Was it good?) with weak forms (w'r, k'n, w'z) and answer with strong short answers (Yes, I was. No, I can't)."},{"id":"a2-2","lv":"A2","n":2,"title":"The schwa: the most common sound","focus":"sounds","goal":"Hear and say the schwa /ə/, the weak 'uh' sound in unstressed syllables and small words.","goal_es":"Escuchar y pronunciar la schwa /ə/, el sonido débil 'uh' de las sílabas sin acento y de las palabras pequeñas.","explain":["The schwa /ə/ is the most common vowel sound in English. It's a short, relaxed 'uh': mouth a little open, tongue resting in the middle. It is never stressed. You hear it in about (uh-BOUT), today (tuh-DAY) and banana (buh-NAN-uh).","Any vowel letter can be a schwa: a (about), e (problem), o (today, second), u (support). In American English, -er and -or at the end are a schwa + r: teacher, doctor (British: just 'uh'). Small words are often schwas too: a, the, of, to.","The rule: one syllable is stressed and clear; the others relax. Find the strong syllable, then say the rest quickly with 'uh': CAN-uh-duh, PROB-lum, CHAWK-lut."],"explain_es":["La schwa /ə/ es el sonido vocálico más común del inglés. Es una 'uh' corta y relajada: la boca un poco abierta y la lengua descansando en el medio. Nunca lleva acento. Se escucha en about (uh-BOUT), today (tuh-DAY) y banana (buh-NAN-uh).","Cualquier vocal escrita puede ser schwa: a (about), e (problem), o (today, second), u (support). En inglés americano, -er y -or al final son schwa + r: teacher, doctor (en inglés británico, solo 'uh'). Las palabras pequeñas también suelen tener schwa: a, the, of, to.","La regla: una sílaba lleva el acento y suena clara; las demás se relajan. Busca la sílaba fuerte y di el resto rápido con 'uh': CAN-uh-duh, PROB-lum, CHAWK-lut."],"spanish":"Spanish has no schwa, so Spanish speakers say every vowel as it is written: 'ba-na-na', 'Ca-na-dá', 'pro-blem'. Say only the stressed vowel clearly and relax all the others to a short 'uh': buh-NAN-uh, CAN-uh-duh.","spanish_es":"El español no tiene schwa, por eso los hispanohablantes pronuncian cada vocal tal como se escribe: 'ba-na-na', 'Ca-na-dá', 'pro-blem'. Di clara solo la vocal acentuada y relaja todas las demás en una 'uh' corta: buh-NAN-uh, CAN-uh-duh.","ex":[{"t":"about","how":"uh-BOUT","note":"a- = schwa"},{"t":"today","how":"tuh-DAY","note":"to- = schwa; the stress is on DAY"},{"t":"problem","how":"PROB-lum","note":"-lem sounds like 'lum', not 'lem'"},{"t":"teacher","how":"TEE-cher","note":"-er = schwa + r (British: TEE-chuh)"},{"t":"chocolate","how":"CHAWK-lut","note":"often 2 syllables; the end is 'lut', never 'late'"},{"t":"a banana","how":"uh buh-NAN-uh","note":"three schwas; only NA is clear"},{"t":"Canada","how":"CAN-uh-duh","note":"Spanish: Ca-na-DÁ · English: stress on CAN + two schwas"},{"t":"The doctor is at the hospital.","how":"thuh DOC-ter's_'t thuh HAH-spi-dul","note":"schwas in the, -or, at, the, -tal"}],"listen":[{"q":"Which word do you hear?","o":["police","please"],"pick":true,"why":"police has a tiny schwa: puh-LEESS; please has none."},{"q":"Which word do you hear?","o":["support","sport"],"pick":true,"why":"support starts with a quick schwa: suh-PORT; sport is one syllable."},{"q":"Which word do you hear?","o":["away","way"],"pick":true,"why":"away starts with a schwa: uh-WAY."},{"q":"Which word do you hear?","o":["around","round"],"pick":true,"why":"around starts with a schwa: uh-ROUND."},{"q":"Which is the stress pattern?","say":"today","o":["Oo (TO-day)","oO (to-DAY)"],"a":1,"why":"to- is a weak schwa (tuh); the stress is on DAY."},{"q":"How does the end of 'problem' sound?","say":"problem","o":["'lem', like in lemon","a weak 'lum'"],"a":1,"why":"The e is a schwa: PROB-lum."},{"q":"How does the end of 'chocolate' sound?","say":"chocolate","o":["'late', like late for work","a weak 'lut'"],"a":1,"why":"-late is not stressed, so it has a schwa: CHAWK-lut."},{"q":"How does 'a' sound before 'banana'?","say":"I'd like a banana, please.","o":["'ay', like the letter A","a quick 'uh'"],"a":1,"why":"The article a is almost always a schwa: uh buh-NAN-uh."}],"mark":[{"mode":"find","q":"Tap the syllables with a schwa.","w":["ba","na","na"],"word":true,"a":[0,2],"why":"buh-NAN-uh: only the stressed NA has a clear vowel."},{"mode":"find","q":"Tap the syllables with a schwa.","w":["Can","a","da"],"word":true,"a":[1,2],"why":"CAN-uh-duh: after the stress, both syllables are schwas."},{"mode":"stress","q":"Tap the stressed syllable.","w":["to","mor","row"],"word":true,"a":[1],"why":"tuh-MAR-oh: the first syllable is a weak schwa."},{"mode":"find","q":"Tap the syllable with a schwa.","w":["Sat","ur","day"],"word":true,"a":[1],"why":"SAT-er-day: -ur- is a weak 'er' (schwa + r)."},{"mode":"find","q":"Tap the words with a schwa.","w":["I","need","a","map","of","the","city"],"a":[2,4,5],"why":"a → uh, of → uv, the → thuh: small words are weak."}],"dict":[{"say":"The teacher is from Canada.","a":"The teacher is from Canada.","how":"thuh TEE-cher's frum CAN-uh-duh","why":"Schwas in the, -er, from and -a-da."},{"say":"I have a problem with my computer.","a":"I have a problem with my computer.","how":"I have_uh PROB-lum with my cum-PYOO-der","why":"a → uh, -lem → lum, com- → cum: all schwas."},{"say":"See you tomorrow at about seven.","a":"See you tomorrow at about seven.","how":"see you tuh-MAR-oh_'t_uh-BOUT SEV-un","why":"Schwas in to-, at, a- and -en."},{"say":"My sister is a doctor in America.","a":"My sister is a doctor in America.","how":"my SIS-ter's_uh DOC-ter in uh-MER-i-kuh","why":"-er, a, -or, A- and -ca are all schwas."},{"say":"I'd like a banana and some chocolate.","a":"I'd like a banana and some chocolate.","how":"I'd LIKE_uh buh-NAN-uh_'n sum CHAWK-lut","why":"a, ba-, -na, and, some and -late are all weak."}],"tip":"In class: write cognates on the board (Canada, banana, chocolate, problem, America); students underline the stressed syllable, change every other vowel to a relaxed 'uh', and compare with the Spanish pronunciation."},{"id":"a2-3","lv":"A2","n":3,"title":"Black coffee, bus stop: same sound, said once","focus":"linking","goal":"Join two words that share the same consonant sound, saying it once and a little longer.","goal_es":"Unir dos palabras que comparten el mismo sonido consonántico, diciéndolo una sola vez y un poco más largo.","explain":["When a word ends with a consonant sound and the next word starts with the same sound, say it only once, a little longer: black_coffee, bus_stop, this_song. Don't say it twice, don't stop between the words, and don't add a vowel ('big-e game').","With p, b, t, d, k and g, close once, hold for a moment, then open on the next word: good_day, big_game, want_to. With s, m, n, l and f, just make the sound longer: this_song, some_milk.","Think of sounds, not letters: black_coffee is k + k, nice_sweater is s + s. You already do this in Spanish: 'el lunes' has one long l."],"explain_es":["Cuando una palabra termina en un sonido consonántico y la siguiente empieza con el mismo sonido, dilo una sola vez, un poco más largo: black_coffee, bus_stop, this_song. No lo digas dos veces, no hagas una pausa entre las palabras y no agregues una vocal ('big-e game').","Con p, b, t, d, k y g, cierra una vez, mantén un momento y abre en la palabra siguiente: good_day, big_game, want_to. Con s, m, n, l y f, simplemente alarga el sonido: this_song, some_milk.","Piensa en sonidos, no en letras: black_coffee es k + k; nice_sweater es s + s. Esto ya lo haces en español: en 'el lunes' hay una sola l larga."],"spanish":"Spanish speakers often say the two sounds separately, with a small stop or an extra vowel ('big-e game'), and when listening they miss words hidden inside one long sound ('I'll leave' sounds almost like 'I leave'). Say the sound once, a little longer, and go straight into the next word.","spanish_es":"Los hispanohablantes suelen decir los dos sonidos por separado, con una pequeña pausa o una vocal extra ('big-e game'), y al escuchar se les pierden palabras escondidas dentro de un sonido largo ('I'll leave' suena casi como 'I leave'). Di el sonido una vez, un poco más largo, y pasa directo a la palabra siguiente.","ex":[{"t":"black coffee","how":"BLACK_COFfee","note":"ck + c = the same k sound: say it once, a little longer"},{"t":"bus stop","how":"BUS_stop","note":"one long s"},{"t":"good day","how":"good_DAY","note":"close for d once, hold, then open on 'day'"},{"t":"big game","how":"big_GAME","note":"one g, no vowel after big"},{"t":"this song","how":"this_SONG","note":"one long s"},{"t":"some milk","how":"some_MILK","note":"one long m"},{"t":"I want to go.","how":"I WAN_tuh GO","note":"want_to: one t (in very fast speech: wanna)"},{"t":"Take care and have a good day!","how":"take_CARE_and have a good_DAY","note":"take_care (k + k), good_day (d + d)"}],"listen":[{"q":"Which do you hear?","o":["this song","the song"],"pick":true,"why":"this_song: 'thi-sssong', with a long s; the song: 'thuh song', with a short s."},{"q":"Which sentence do you hear?","o":["I'll leave at six.","I leave at six."],"pick":true,"why":"I'll_leave has one long l (future); I leave has a short l."},{"q":"Which sentence do you hear?","o":["You'll like it.","You like it."],"pick":true,"why":"You'll_like has one long l (future); You like has a short l."},{"q":"How many k sounds do you hear?","say":"black coffee","o":["one, a little longer","two, with a small pause","two, with a vowel: black-uh coffee"],"a":0,"why":"ck + c = one long k: no pause, no vowel."},{"q":"Where do two words share one long sound?","say":"Let's meet at the bus stop.","o":["meet at","the bus","bus stop"],"a":2,"why":"bus_stop: s + s = one long s."},{"q":"What happens to the two d's in 'good day'?","say":"Have a good day!","o":["d, a pause, then d","one longer d","they change to t: 'goot tay'"],"a":1,"why":"Close for d once, hold it, and open on day."},{"q":"How many t sounds do you hear in 'want to'?","say":"I want to stay home.","o":["one: wan-tuh","two: want-tuh"],"a":0,"why":"t + t = one t, then a weak 'tuh'."},{"q":"Which two words share a sound?","say":"Can I have some milk, please?","o":["Can I","have some","some milk"],"a":2,"why":"some_milk: m + m = one long m."}],"mark":[{"mode":"link","q":"Tap where two words share the same sound.","w":["Let's","meet","at","the","bus","stop"],"a":[4],"why":"bus_stop: s + s. (meet_at also links, but that is t + a vowel.)"},{"mode":"link","q":"Tap where two words share the same sound.","w":["I'd","like","a","black","coffee"],"a":[3],"why":"black_coffee: k + k (the letters ck and c make the same sound)."},{"mode":"link","q":"Tap where two words share the same sound.","w":["Have","a","good","day","at","the","big","game"],"a":[2,6],"why":"good_day (d + d) and big_game (g + g)."},{"mode":"link","q":"Tap where two words share the same sound.","w":["Can","you","play","this","song","again?"],"a":[3],"why":"this_song: s + s = one long s."},{"mode":"find","q":"Tap the phrases where the two words share the same sound.","w":["black coffee","good idea","nice sweater","red car","gas station"],"a":[0,2,4],"why":"black_coffee (k + k), nice_sweater (s + s), gas_station (s + s). good idea: d + vowel; red car: d + k."}],"dict":[{"say":"Let's meet at the bus stop.","a":"Let's meet at the bus stop.","how":"let's MEE-dat the BUS_stop","why":"bus_stop: one long s; meet_at → 'mee-dat' (the t joins the vowel)."},{"say":"I'd like a black coffee, please.","a":"I'd like a black coffee, please.","how":"I'd LIKE_a BLACK_COFfee, PLEASE","why":"black_coffee: one long k, no vowel between the words."},{"say":"I want to stay home tonight.","a":"I want to stay home tonight.","how":"I WAN_tuh STAY home tuh-NIGHT","why":"want_to: one t, then a weak 'tuh'."},{"say":"We had dinner with some old friends.","a":"We had dinner with some old friends.","how":"we had_DINner with some_OLD FRIENDS","why":"had_dinner: one long d."},{"say":"I love this song, it's so good.","a":"I love this song, it's so good.","how":"I LOVE this_SONG, it's_so GOOD","why":"this_song and it's_so: one long s each time."}],"tip":"In class: students build same-sound phrases on the board (black coffee, bus stop, nice sweater, some milk, good day) and say them in a chain; the class catches anyone who says the sound twice or adds a vowel."},{"id":"a2-4","lv":"A2","n":4,"title":"Gonna, wanna, gotta","focus":"reduction","goal":"Understand gonna, wanna, gotta and gotcha in fast informal speech, and know when (not) to use them.","goal_es":"Entender gonna, wanna, gotta y gotcha en el habla rápida e informal, y saber cuándo usarlas (y cuándo no).","explain":["In fast, informal speech, some common phrases join and get shorter: going to → gonna (GUH-nuh), want to → wanna (WAH-nuh), have got to → gotta (GAH-duh), got you → gotcha (GAH-chuh). You hear them all the time in films, series, songs and with friends.","Gonna is only for going to + a verb (plans and predictions): I'm gonna eat. It's gonna rain. Not for places: I'm going to the bank (never 'gonna the bank'). Wanna = want to + a verb: I wanna sleep. Gotta = have to: I've gotta go (often just 'I gotta go').","These are spoken forms. Understand them, and use them with friends if you want, but never write them in emails, reports or work messages: write going to, want to, have to."],"explain_es":["En el habla rápida e informal, algunas frases comunes se juntan y se acortan: going to → gonna (GUH-nuh), want to → wanna (WAH-nuh), have got to → gotta (GAH-duh), got you → gotcha (GAH-chuh). Las escucharás todo el tiempo en películas, series, canciones y entre amigos.","Gonna es solo para going to + un verbo (planes y predicciones): I'm gonna eat. It's gonna rain. No para lugares: I'm going to the bank (nunca 'gonna the bank'). Wanna = want to + un verbo: I wanna sleep. Gotta = have to: I've gotta go (muchas veces solo 'I gotta go').","Son formas habladas. Entiéndelas y úsalas con amigos si quieres, pero nunca las escribas en correos, informes o mensajes de trabajo: escribe going to, want to, have to."],"spanish":"Spanish speakers usually learn only the full forms, so gonna, wanna and gotta are hard to recognize in films and real conversations, and some people then start using them in writing. Learn to hear them, say them only in relaxed conversation, and always write the full form.","spanish_es":"Los hispanohablantes suelen aprender solo las formas completas, así que gonna, wanna y gotta son difíciles de reconocer en películas y conversaciones reales, y después algunos empiezan a usarlas por escrito. Aprende a escucharlas, úsalas solo en conversaciones relajadas y escribe siempre la forma completa.","ex":[{"t":"I'm gonna eat.","how":"I'm GUH-nuh EAT","note":"gonna = going to + verb (a plan)"},{"t":"I wanna sleep.","how":"I WAH-nuh SLEEP","note":"wanna = want to + verb"},{"t":"I gotta go.","how":"I GAH-duh GO","note":"gotta = (have) got to = have to"},{"t":"Gotcha!","how":"GAH-chuh!","note":"got you = I understand (or: I caught you!)"},{"t":"I'm going to the bank.","how":"I'm GO-ing to the BANK","note":"a place → no 'gonna' here"},{"t":"What are you gonna do?","how":"what're you GUH-nuh DO?","note":"in questions too"},{"t":"We've gotta finish this today.","how":"we've GAH-duh FIN-ish this tuh-DAY","note":"gotta: the t sounds like a quick d"},{"t":"I'm gonna be late. Wanna start without me?","how":"I'm GUH-nuh be LATE. | WAH-nuh START with-OUT me?","note":"wanna start…? = (Do you) want to start…?"}],"listen":[{"q":"Which sentence do you hear?","o":["I'm gonna call you.","I wanna call you."],"pick":true,"why":"gonna = going to (a plan); wanna = want to (a wish)."},{"q":"Which sentence do you hear?","o":["I gotta go.","I wanna go."],"pick":true,"why":"gotta = have to; wanna = want to."},{"q":"Full form or short form? Which do you hear?","o":["We're going to eat.","We're gonna eat."],"pick":true,"why":"going to has three clear syllables; gonna has two quick ones: GUH-nuh."},{"q":"Which do you hear?","o":["Gotcha!","Got it!"],"pick":true,"why":"Gotcha = got you: t + y becomes ch. Got it ends with 'it'."},{"q":"What does it mean?","say":"I'm gonna see a movie tonight.","o":["I'm going to see a movie tonight.","I want to see a movie tonight.","I have to see a movie tonight."],"a":0,"why":"gonna = going to: a plan."},{"q":"What does it mean?","say":"I've gotta finish this report.","o":["I want to finish this report.","I have to finish this report.","I'm going to finish this report."],"a":1,"why":"gotta = have got to = have to."},{"q":"What is the speaker doing?","say":"Wanna grab a coffee?","o":["inviting you","saying sorry","asking for help"],"a":0,"why":"Wanna grab a coffee? = Do you want to get a coffee? A friendly invitation."},{"q":"Can 'going to' become 'gonna' here?","say":"I'm going to the bank.","o":["Yes: I'm gonna the bank.","No: here it's about a place, not a plan + verb."],"a":1,"why":"gonna only replaces going to + a verb."}],"mark":[{"mode":"find","q":"Tap the words that become 'gonna' in fast speech.","w":["I'm","going","to","call","my","mom","later."],"a":[1,2],"why":"going to + call (a verb) → gonna: I'm gonna call my mom later."},{"mode":"find","q":"Tap the words that become 'wanna'.","w":["Do","you","want","to","watch","a","movie?"],"a":[2,3],"why":"want to + watch → wanna: Do you wanna watch a movie?"},{"mode":"find","q":"Tap the words that can become 'gonna'. Careful: not before a place!","w":["We're","going","to","Lima.","We're","going","to","fly."],"a":[5,6],"why":"going to Lima = a place (no gonna); going to fly = a plan + verb → gonna."},{"mode":"find","q":"Tap the words that become 'gotta'.","w":["I've","got","to","go","now."],"a":[1,2],"why":"got to → gotta: I've gotta go now (the 've is very weak)."},{"mode":"stress","q":"Tap the stressed words.","w":["I'm","gonna","call","you","later."],"a":[2,4],"why":"I'm gonna CALL you LATer: gonna is quick and weak; the stress is on the important words."}],"dict":[{"say":"I'm gonna call you later.","a":"I'm going to call you later.","alt":["I'm gonna call you later."],"how":"I'm GUH-nuh CALL you LAY-der","why":"gonna = going to; in later, the t sounds like a quick d."},{"say":"Do you wanna get a pizza?","a":"Do you want to get a pizza?","alt":["Do you wanna get a pizza?"],"how":"d'you WAH-nuh GED-uh PEET-suh?","why":"wanna = want to; get_a → 'ged-uh'."},{"say":"I've gotta work this weekend.","a":"I've got to work this weekend.","alt":["I've gotta work this weekend."],"how":"I've GAH-duh WORK this WEEK-end","why":"gotta = got to (= have to); the 've is very weak."},{"say":"We're gonna be late. Hurry up!","a":"We're going to be late. Hurry up!","alt":["We're gonna be late. Hurry up!"],"how":"we're GUH-nuh be LATE. | HUR-ry_UP!","why":"gonna = going to; hurry_up sounds like one word."},{"say":"Gotcha. See you at eight.","a":"Got you. See you at eight.","alt":["Gotcha. See you at eight."],"how":"GAH-chuh. | SEE you_at EIGHT","why":"gotcha = got you (I understand): t + y → ch."}],"tip":"In class: say ten fast informal sentences (I'm gonna…, I wanna…, I've gotta…); students write each one in full, as they would in an email, and then say it fast again to a partner."},{"id":"a2-5","lv":"A2","n":5,"title":"Did you, would you: the j sound","focus":"reduction","goal":"Understand and say did you, would you, could you, what do you and don't you as they sound in fast speech.","goal_es":"Entender y pronunciar did you, would you, could you, what do you y don't you como suenan en el habla rápida.","explain":["When a word ending in d comes before you, the two sounds mix into a 'j' sound, like the English j in job: did you → didja, would you → wouldja, could you → couldja. When the word ends in t, you get 'ch': don't you → doncha, meet you → meetcha.","You is weak here too: 'ja', 'cha' or 'ya', with a schwa. In fast questions, what do you often becomes whaddaya: What do you do? sounds like 'whaddaya DO?'","You don't need to speak like this, but you need to understand it: it's everywhere in real conversation. In writing, always use the full words: did you, would you, what do you."],"explain_es":["Cuando una palabra que termina en d va antes de you, los dos sonidos se mezclan en un sonido 'j' como la j inglesa de job: did you → didja, would you → wouldja, could you → couldja. Si la palabra termina en t, sale 'ch': don't you → doncha, meet you → meetcha.","Aquí you también es débil: 'ja', 'cha' o 'ya', con schwa. En preguntas rápidas, what do you muchas veces se convierte en whaddaya: What do you do? suena como 'whaddaya DO?'.","No necesitas hablar así, pero sí necesitas entenderlo: está en todas las conversaciones reales. Por escrito, usa siempre las palabras completas: did you, would you, what do you."],"spanish":"Spanish speakers often say each word separately ('did… you') and then don't recognize 'didja' or 'whaddaya' in real conversation. Careful: this 'j' is the English j of job (close to a strong Spanish y, as in '¡yo!'), not the Spanish jota.","spanish_es":"Los hispanohablantes suelen decir cada palabra por separado ('did… you') y después no reconocen 'didja' ni 'whaddaya' en una conversación real. Ojo: esta 'j' es la j inglesa de job (parecida a una y fuerte, como en '¡yo!'), no la jota del español.","ex":[{"t":"Did you eat?","how":"didja EAT?","note":"d + you → 'j' (as in job)"},{"t":"Would you like tea?","how":"wouldja like TEA?","note":"an offer"},{"t":"Could you help me?","how":"couldja HELP me?","note":"a polite request"},{"t":"Don't you like it?","how":"doncha LIKE_it?","note":"t + you → 'ch' (as in chao)"},{"t":"Nice to meet you.","how":"NICE tuh MEET-cha","note":"t + you → 'ch'"},{"t":"What do you do?","how":"whaddaya DO?","note":"= What's your job?"},{"t":"Did you call your mom yesterday?","how":"didja CALL yer MOM YES-ter-day?","note":"your is weak too: 'yer'"},{"t":"What do you want to do this weekend?","how":"whaddaya WAH-nuh DO this WEEK-end?","note":"two reductions: whaddaya + wanna"}],"listen":[{"q":"Which question do you hear?","o":["Did you call her?","Do you call her?"],"pick":true,"why":"Did you → 'didja' (past); do you → 'd'you' (present)."},{"q":"Which question do you hear?","o":["Would you like tea?","Do you like tea?"],"pick":true,"why":"Would you like…? ('wouldja') is an offer; Do you like…? asks what you like."},{"q":"Which question do you hear?","o":["Could you help me?","Can you help me?"],"pick":true,"why":"could you → 'couldja'; can you → 'k'n you'."},{"q":"Which question do you hear?","o":["What do you want?","What did you want?"],"pick":true,"why":"what do you → 'whaddaya'; what did you → 'whadidja'."},{"q":"Which question do you hear?","o":["Don't you like it?","Do you like it?"],"pick":true,"why":"Don't you → 'doncha', with n + ch; do you has no n."},{"q":"What does the person want to know?","say":"What do you do?","o":["your job","what you're doing now","what you did yesterday"],"a":0,"why":"What do you do? ('whaddaya do?') asks about your job."},{"q":"Is the question about the past or the present?","say":"Did you finish the report?","o":["the past","the present"],"a":0,"why":"Did you ('didja') → a question about the past."},{"q":"Which answer is right?","say":"Where did you go on vacation?","o":["I go to the beach.","I went to the beach.","I'm going to the beach."],"a":1,"why":"Where did you ('whe-didja') asks about the past → I went."}],"mark":[{"mode":"link","q":"Tap where the words join with a 'j' sound.","w":["Where","did","you","park","the","car?"],"a":[1],"why":"did_you → 'didja': d + y = j."},{"mode":"link","q":"Tap where the words join with a 'ch' or 'j' sound.","w":["Nice","to","meet","you.","Did","you","find","us","OK?"],"a":[2,4],"why":"meet_you → 'meetcha' (t + y = ch); Did_you → 'didja' (d + y = j)."},{"mode":"find","q":"Tap the phrases that join with a 'j' sound (as in job).","w":["did you","are you","would you","can you","could you"],"a":[0,2,4],"why":"d + you = j: didja, wouldja, couldja. are you and can you have no d before you."},{"mode":"find","q":"Tap the phrases that join with a 'ch' sound.","w":["don't you","did you","meet you","got you","would you"],"a":[0,2,3],"why":"t + you = ch: doncha, meetcha, gotcha. did you and would you → j."},{"mode":"weak","q":"Tap the weak words.","w":["What","do","you","want","to","do?"],"a":[1,2,4],"why":"whaddaya wanna DO: do and you are weak, and to is a weak 'tuh'; the last do is the main verb, so it's strong."}],"dict":[{"say":"Did you see the game last night?","a":"Did you see the game last night?","how":"didja SEE the GAME las' NIGHT?","why":"did you → 'didja'; in last night the t almost disappears."},{"say":"Would you like a cup of coffee?","a":"Would you like a cup of coffee?","how":"wouldja LIKE_uh CUP_uh COFfee?","why":"would you → 'wouldja'; cup of → 'cuppa'."},{"say":"Could you send me the report?","a":"Could you send me the report?","how":"couldja SEND me the ruh-PORT?","why":"could you → 'couldja': d + y = j."},{"say":"What do you want for dinner?","a":"What do you want for dinner?","how":"whaddaya WANT fer DIN-ner?","why":"what do you → 'whaddaya'; for → a weak 'fer'."},{"say":"Don't you want to come with us?","a":"Don't you want to come with us?","how":"doncha WAH-nuh COME with_us?","why":"don't you → 'doncha' (t + y = ch); want to → 'wanna'."}],"tip":"In class: students interview a partner about last weekend with Did you…?, Where did you…? and What did you…?, saying 'didja' and 'whe-didja'; the partner writes each question down in full spelling."},{"id":"a2-6","lv":"A2","n":6,"title":"PHOtograph, phoTOgraphy: suffixes and stress","focus":"stress","goal":"Put the stress in the right place in long words with -tion, -sion, -ic, -ity and -graphy.","goal_es":"Poner el acento en el lugar correcto en palabras largas con -tion, -sion, -ic, -ity y -graphy.","explain":["A suffix is an ending, like -tion or -ic. Some suffixes move the stress. With -tion and -sion, stress the syllable just before the suffix: inforMAtion, converSAtion, deCIsion. The ending is short and weak: -tion sounds like 'shun', and -sion like 'shun' or 'zhun' (decision = 'di-SIZH-un').","-ic, -ity and -graphy work the same way: stress the syllable just before the suffix. fanTAStic, enerGEtic, uniVERsity, elecTRIcity, phoTOgraphy, geOgraphy. Good news: -ic is usually like Spanish -ico: fantástico → fanTAStic.","So in a word family, the stress can jump: PHOtograph, phoTOgrapher, phoTOgraphy, photoGRAPHic. ENergy → enerGEtic. eLECtric → elecTRIcity. When you learn a new word, learn its stress too."],"explain_es":["Un sufijo es una terminación, como -tion o -ic. Algunos sufijos cambian el acento de lugar. Con -tion y -sion, acentúa la sílaba justo antes del sufijo: inforMAtion, converSAtion, deCIsion. El final es corto y débil: -tion suena como 'shn', y -sion como 'shn' o 'zhn' (decision = 'di-SÍ-zhn').","-ic, -ity y -graphy funcionan igual: acentúa la sílaba justo antes del sufijo. fanTAStic, enerGEtic, uniVERsity, elecTRIcity, phoTOgraphy, geOgraphy. Buena noticia: -ic normalmente funciona como -ico en español: fantástico → fanTAStic.","Por eso, en una familia de palabras el acento puede saltar: PHOtograph, phoTOgrapher, phoTOgraphy, photoGRAPHic. ENergy → enerGEtic. eLECtric → elecTRIcity. Cuando aprendas una palabra nueva, aprende también su acento."],"spanish":"Spanish -ción and -sión are stressed (información, decisión), so learners often say 'informa-SHON' or 'deci-SHON'. Fix: stress the syllable before the suffix and make the ending short and weak: infor-MAY-shun, di-SIZH-un.","spanish_es":"En español, -ción y -sión llevan el acento (información, decisión), por eso es fácil decir 'informa-SHON' o 'deci-SHON'. Solución: acentúa la sílaba antes del sufijo y di el final corto y débil: infor-MÉI-shn, di-SÍ-zhn.","ex":[{"t":"information","how":"in-fer-MAY-shun","note":"-tion: stress the syllable before; 'shun' is weak"},{"t":"conversation","how":"kahn-ver-SAY-shun","note":"not 'conversa-SHON'"},{"t":"decision","how":"di-SIZH-un","note":"-sion after a vowel often sounds 'zhun'"},{"t":"fantastic","how":"fan-TAS-tik","note":"-ic: stress the syllable before (like fantástico)"},{"t":"energy, energetic","how":"EN-er-jee → en-er-JED-ik","note":"the stress jumps; the American t sounds like a quick d"},{"t":"university","how":"yoo-nuh-VER-suh-dee","note":"-ity: stress the syllable before (UK: a clear t, 'VER-si-tee')"},{"t":"photograph, photography, photographic","how":"FO-duh-graf → fuh-TAH-gruh-fee → fo-duh-GRAF-ik","note":"one family, three stress patterns"},{"t":"I'd like more information about the university.","how":"I'd like more in-fer-MAY-shun a-bout the yoo-nuh-VER-suh-dee","note":"keep the right stress in a sentence too"}],"listen":[{"q":"Which word do you hear?","o":["economy","economic"],"pick":true,"why":"e-CON-o-my vs ec-o-NOM-ic: -ic moves the stress to NOM."},{"q":"Which word do you hear?","o":["photograph","photography"],"pick":true,"why":"PHO-to-graph vs pho-TOG-ra-phy: -graphy moves the stress to TOG."},{"q":"Which word do you hear?","o":["electric","electricity"],"pick":true,"why":"e-LEC-tric vs e-lec-TRIC-i-ty: -ity moves the stress to TRIC."},{"q":"Where is the stress?","say":"information","o":["IN-for-ma-tion","in-FOR-ma-tion","in-for-MA-tion"],"a":2,"why":"in-for-MA-tion: the stress is just before -tion."},{"q":"Where is the stress?","say":"university","o":["U-ni-ver-si-ty","u-ni-VER-si-ty","u-ni-ver-SI-ty"],"a":1,"why":"u-ni-VER-si-ty: the stress is just before -ity."},{"q":"How many syllables?","say":"decision","o":["2","3","4"],"a":1,"why":"de-ci-sion: -sion is one short syllable, 'zhun'."},{"q":"Where is the stress?","say":"photographer","o":["PHO-tog-ra-pher","pho-TOG-ra-pher","pho-tog-RA-pher"],"a":1,"why":"pho-TOG-ra-pher, like pho-TOG-ra-phy (and like Spanish fotógrafo)."},{"q":"Which stress pattern?","say":"fantastic","o":["Ooo","oOo","ooO"],"a":1,"why":"fan-TAS-tic = oOo: the stress is just before -ic."}],"mark":[{"mode":"stress","q":"Tap the stressed syllable.","w":["con","ver","sa","tion"],"word":true,"a":[2],"why":"con-ver-SA-tion: the stress is just before -tion."},{"mode":"stress","q":"Tap the stressed syllable.","w":["en","er","get","ic"],"word":true,"a":[2],"why":"en-er-GET-ic: just before -ic. Compare EN-er-gy."},{"mode":"stress","q":"Tap the stressed syllable.","w":["pho","to","graph","ic"],"word":true,"a":[2],"why":"pho-to-GRAPH-ic: just before -ic. Compare pho-TOG-ra-phy."},{"mode":"stress","q":"Tap the stressed syllable.","w":["com","mu","ni","ty"],"word":true,"a":[1],"why":"com-MU-ni-ty: the stress is just before -ity."},{"mode":"find","q":"Tap the words with the stress on the 2nd syllable.","w":["decision","energy","fantastic","photograph","electric"],"a":[0,2,4],"why":"de-CI-sion, fan-TAS-tic, e-LEC-tric. EN-er-gy and PHO-to-graph have the stress on the 1st syllable."}],"dict":[{"say":"I need more information, please.","a":"I need more information, please.","how":"I need more in-fer-MAY-shun, please","why":"in-for-MA-tion: stress just before -tion; -tion = 'shun'."},{"say":"She studies photography in college.","a":"She studies photography in college.","how":"She STUD-eez fuh-TAH-gruh-fee in KAH-lij","why":"pho-TOG-ra-phy: stress just before -graphy."},{"say":"It was a difficult decision.","a":"It was a difficult decision.","how":"It wuz-uh DIF-i-kult di-SIZH-un","why":"de-CI-sion: -sion = 'zhun'; was a → 'wuz-uh'."},{"say":"Our new manager is very energetic.","a":"Our new manager is very energetic.","how":"Our new MAN-ij-er is ver-ee en-er-JED-ik","why":"en-er-GET-ic: stress just before -ic; the t sounds like a quick d."},{"say":"My sister works at the university.","a":"My sister works at the university.","how":"My SIS-ter work-sat the yoo-nuh-VER-suh-dee","why":"u-ni-VER-si-ty: stress just before -ity; works at → 'work-sat'."}],"tip":"In class: write base words on the board (photograph, energy, electric, inform, decide) and teams race to say a family word with a new suffix, clapping on the stressed syllable (phoTOgraphy, enerGEtic, elecTRIcity, inforMAtion, deCIsion)."},{"id":"a2-7","lv":"A2","n":7,"title":"Texts, months, asked: consonant groups","focus":"sounds","goal":"Say groups of consonants at the end of words (texts, asked, world) without adding a vowel or losing the last sound.","goal_es":"Pronunciar grupos de consonantes al final de las palabras (texts, asked, world) sin agregar una vocal ni perder el último sonido.","explain":["Many English words end in two or three consonants: help, world, friends, asked, texts, months. Don't add a vowel ('frien-des', 'ask-ed') and don't cut the end ('frien', 'wor'). The last sound is important: it often means plural (friends), past (asked) or he/she (texts).","Say all the sounds together, in one syllable: asked = 'askt', helped = 'helpt', world = 'wurld' (with l and d). Practice slowly, then faster: wor… worl… world.","Some groups are very hard, even for native speakers. In normal speech it's OK to drop a sound in the middle: texts → 'teks', months → 'munts', friends → 'frenz', clothes → 'cloze'. But keep the last sound!"],"explain_es":["Muchas palabras en inglés terminan en dos o tres consonantes: help, world, friends, asked, texts, months. No agregues una vocal ('frien-des', 'ask-ed') y no cortes el final ('frien', 'wor'). El último sonido es importante: muchas veces indica plural (friends), pasado (asked) o él/ella (texts).","Di todos los sonidos juntos, en una sola sílaba: asked = 'askt', helped = 'helpt', world = 'uerld' (con l y d). Practica lento y después más rápido: wor… worl… world.","Algunos grupos son muy difíciles, incluso para los nativos. Al hablar normal, está bien eliminar un sonido del medio: texts → 'teks', months → 'mants', friends → 'frenz', clothes → 'klouz'. ¡Pero mantén el último sonido!"],"spanish":"Spanish words almost never end in two consonants, and in Chile the final s is often soft or lost ('lo' amigo'), so learners add a vowel ('ask-ed') or drop the end ('friend' for 'friends'). Fix: always keep the last sound; you can drop one in the middle (texts → 'teks').","spanish_es":"En español casi ninguna palabra termina en dos consonantes, y en Chile la s final muchas veces se aspira o se pierde ('lo' amigo'), así que agregamos una vocal ('ask-ed') o cortamos el final ('friend' en vez de 'friends'). Solución: mantén siempre el último sonido; puedes eliminar uno del medio (texts → 'teks').","ex":[{"t":"help, helped","how":"help → helpt","note":"one syllable: 'helpt', not 'help-ed'"},{"t":"ask, asked","how":"ask → askt","note":"one syllable; in fast speech 'ast' is OK"},{"t":"word, world","how":"wurd → wurld","note":"world: say the l and the d"},{"t":"friend, friends","how":"frend → frendz (frenz)","note":"the d can go; keep the z"},{"t":"text, texts","how":"tekst → teksts (teks)","note":"the middle t can go; keep the s"},{"t":"month, months","how":"munth → munths (munts)","note":"fast speech: 'munts'"},{"t":"sixth, sixths","how":"siksth → siksths (sikss)","note":"very hard for everyone: 'sikss' is fine"},{"t":"She texts her friends every month.","how":"She teks her frenz ev-ree munth","note":"keep the last sound of each word"}],"listen":[{"q":"Which word do you hear?","o":["word","world"],"pick":true,"why":"world has l + d at the end: 'wurld'."},{"q":"Which word do you hear?","o":["ask","asked"],"pick":true,"why":"asked ends in k + t: 'askt'."},{"q":"Which word do you hear?","o":["friend","friends"],"pick":true,"why":"friends ends in a z sound: 'frendz' or 'frenz'."},{"q":"Which word do you hear?","o":["six","sixth"],"pick":true,"why":"sixth ends in k + s + th: 'siksth'."},{"q":"Which word do you hear?","o":["fine","find"],"pick":true,"why":"find ends in n + d. Don't drop the d."},{"q":"How many syllables?","say":"texts","o":["1","2","3"],"a":0,"why":"texts = 'teksts' (or 'teks'): one syllable. Not 'tex-tes'."},{"q":"What is the last sound?","say":"helped","o":["p","t","d"],"a":1,"why":"helped = 'helpt': after p, -ed sounds like t."},{"q":"Which sentence do you hear?","o":["She asked a question.","She asks a question."],"pick":true,"why":"asked a → 'ask-ta' (past); asks a → 'ask-sa' (present)."}],"mark":[{"mode":"find","q":"Tap the words that end in two or more consonant sounds.","w":["I","asked","my","best","friend."],"a":[1,3,4],"why":"asked = 'askt', best = 'st', friend = 'nd'. I and my end in a vowel sound."},{"mode":"find","q":"Tap the words that end in a t sound.","w":["asked","played","helped","texts","worked"],"a":[0,2,4],"why":"asked = 'askt', helped = 'helpt', worked = 'workt'. played ends in d; texts ends in s."},{"mode":"find","q":"Tap the words that end in a z sound.","w":["friends","texts","jobs","months","clothes"],"a":[0,2,4],"why":"friends = 'frenz', jobs = 'jobz', clothes = 'cloze'. texts and months end in s."},{"mode":"link","q":"Tap where the words join.","w":["We","walked","and","talked","a","lot."],"a":[1,3],"why":"walked_and → 'wok-tand', talked_a → 'tok-ta'. A vowel after the group makes it easier."},{"mode":"link","q":"Tap where the words join.","w":["Six","months","ago."],"a":[1],"why":"months_ago → 'mun-tsa-GO': the s moves to the next vowel."}],"dict":[{"say":"Yesterday I asked my friends for help.","a":"Yesterday I asked my friends for help.","how":"YES-ter-day I ast my frenz fer HELP","why":"asked → 'askt' or 'ast'; friends → 'frenz'; for → 'fer'."},{"say":"She texts me every day.","a":"She texts me every day.","how":"She teks me ev-ree DAY","why":"texts → 'teks': the middle t goes, the s stays."},{"say":"We lived there for six months.","a":"We lived there for six months.","how":"We livd there fer siks MUNTS","why":"lived → 'livd' (one syllable); months → 'munts'."},{"say":"I bought new clothes last month.","a":"I bought new clothes last month.","how":"I bawt new cloze las munth","why":"clothes → 'cloze'; last month → 'las month': the t goes between two consonants."},{"say":"It's the best restaurant in the world.","a":"It's the best restaurant in the world.","how":"It's the bes RES-trahnt in the WURLD","why":"best → 'bes' before a consonant; world: keep the l and the d."}],"tip":"In class: build groups step by step on the board (wor → worl → world; ask → askt; six → sixth → sixths), then pairs read chains like 'six months, sixth text, best friends' while the partner raises a hand at every extra 'e' sound."},{"id":"a2-8","lv":"A2","n":8,"title":"Tea or coffee? Lists and choices","focus":"intonation","goal":"Use ↗ ↗ ↘ in lists and choices, and hear the difference between a closed choice and an open question.","goal_es":"Usar ↗ ↗ ↘ en listas y en preguntas de elección, y distinguir una elección cerrada de una pregunta abierta.","explain":["In a list, your voice goes up ↗ on each item and down ↘ on the last one: 'I need eggs ↗, milk ↗ and bread ↘.' The fall tells people that the list is finished. Say 'and' short and weak: 'milk 'n bread'.","Choice questions with 'or' work the same way: up ↗ on the first option, down ↘ on the last one: 'Tea ↗ or coffee ↘?' This means 'Choose one.' Answer with one option: 'Coffee, please.' 'Or' is weak too: 'tea er coffee'.","But with only one rise at the end, it's a different question: 'Would you like tea or coffee? ↗' Now it means 'Would you like a drink?' Tea and coffee are only examples, so you can answer 'Yes, please', 'No, thanks' or ask for something else."],"explain_es":["En una lista, la voz sube ↗ en cada elemento y baja ↘ en el último: 'I need eggs ↗, milk ↗ and bread ↘.' La bajada indica que la lista terminó. Di 'and' corto y débil: 'milk 'n bread'.","Las preguntas de elección con 'or' funcionan igual: sube ↗ en la primera opción y baja ↘ en la última: 'Tea ↗ or coffee ↘?' Significa 'Elige una'. Responde con una opción: 'Coffee, please.' 'Or' también es débil: 'tea er coffee'.","Pero si la voz sube una sola vez, al final, es otra pregunta: 'Would you like tea or coffee? ↗' Ahora significa '¿Quieres algo para tomar?'. El té y el café son solo ejemplos, así que puedes responder 'Yes, please', 'No, thanks' o pedir otra cosa."],"spanish":"Spanish lists and choices have a similar melody, but English moves are bigger; learners often sound flat or go up on the last item, so the list sounds unfinished. Fix: make a big, clear fall ↘ on the last item, and say and/or short: 'milk 'n bread', 'tea er coffee'.","spanish_es":"En español las listas y las elecciones tienen una melodía parecida, pero en inglés el movimiento es más grande; muchas veces sonamos planos o subimos en el último elemento, y la lista parece no terminar. Solución: haz una bajada grande y clara ↘ en el último elemento, y di and/or cortos: 'milk 'n bread', 'tea er coffee'.","ex":[{"t":"Apples, bananas and grapes.","how":"AP-plz ↗, buh-NAN-uz ↗ 'n GRAPES ↘","note":"list: up, up… down at the end"},{"t":"I need eggs, milk and bread.","how":"I need EGGS ↗, MILK ↗ 'n BREAD ↘","note":"the fall says: the list is finished"},{"t":"Monday, Wednesday and Friday.","how":"MUN-day ↗, WENZ-day ↗ 'n FRY-day ↘","note":"Wednesday = 'WENZ-day'"},{"t":"Tea or coffee?","how":"TEA ↗ er COF-fee ↘","note":"closed choice: pick one"},{"t":"Window or aisle?","how":"WIN-doe ↗ er AISLE ↘","note":"at the airport; aisle = 'ile'"},{"t":"For here or to go?","how":"fer HERE ↗ er t' GO ↘","note":"at a café: pick one (UK: Eat in or take away?)"},{"t":"We have pasta, chicken or fish.","how":"We have PAH-stuh ↗, CHICK-en ↗ er FISH ↘","note":"three options: ↗ ↗ ↘"},{"t":"Would you like tea or coffee?","how":"Wud-ja like tea er COF-fee ↗","note":"one rise at the end = 'Would you like a drink?'"}],"listen":[{"q":"How many things are in the list?","say":"I need eggs, milk, bread and cheese.","o":["3","4","5"],"a":1,"why":"eggs ↗, milk ↗, bread ↗ and cheese ↘: four. The voice goes down on the last one."},{"q":"Which item has the final fall ↘?","say":"We visited Boston, Chicago and New York.","o":["Boston","Chicago","New York"],"a":2,"why":"The last item goes down ↘: it says 'the list is finished'."},{"q":"Is it a list or a choice?","say":"Cash or card?","o":["a list (all of them)","a choice (pick one)"],"a":1,"why":"'or' = a choice: cash ↗ or card ↘? Answer with one: 'Card, please.'"},{"q":"Is it a list or a choice?","say":"I speak Spanish, English and a little French.","o":["a list (all of them)","a choice (pick one)"],"a":0,"why":"'and' = a list: Spanish ↗, English ↗ and a little French ↘."},{"q":"What's a good answer?","say":"Which do you want, tea or coffee?","o":["Yes, please.","Coffee, please."],"a":1,"why":"Which…? is a closed choice: pick one. 'Yes, please' doesn't answer it."},{"q":"Which do you hear?","o":["Red or white?","Red and white."],"pick":true,"why":"'or' = a choice (red ↗ or white ↘?); 'and' = both, a short list."},{"q":"Which list do you hear?","o":["Monday, Tuesday and Friday.","Monday, Thursday and Friday."],"pick":true,"why":"Tuesday = 'TOOZ-day'; Thursday = 'THURZ-day'. Each day goes ↗, Friday goes ↘."},{"q":"How many choices are there?","say":"Do you want rice, salad or fries?","o":["2","3","4"],"a":1,"why":"rice ↗, salad ↗ or fries ↘: three choices. Pick one."}],"mark":[{"mode":"stress","q":"Tap the words where the voice goes up ↗.","w":["Apples,","bananas","and","grapes."],"a":[0,1],"why":"AP-ples ↗, ba-NA-nas ↗ and GRAPES ↘: up on each item, down on the last."},{"mode":"stress","q":"Tap the word where the voice goes down ↘.","w":["I","need","eggs,","milk","and","bread."],"a":[5],"why":"eggs ↗, milk ↗ and BREAD ↘: the fall is on the last item."},{"mode":"stress","q":"It's a closed choice (pick one). Tap the word where the voice goes up ↗.","w":["Tea","or","coffee?"],"a":[0],"why":"TEA ↗ or COF-fee ↘? Up on the first option, down on the last."},{"mode":"stress","q":"It means 'Would you like a drink?'. Tap the word where the voice goes up ↗.","w":["Would","you","like","tea","or","coffee?"],"a":[5],"why":"Would you like tea or COF-fee ↗? An open question has one rise, at the end."},{"mode":"link","q":"Tap where the words join.","w":["Is","that","for","here","or","to","go?"],"a":[3],"why":"here_or → 'hee-rer': the r joins the vowel of or."}],"dict":[{"say":"I need eggs, cheese and tomatoes.","a":"I need eggs, cheese and tomatoes.","how":"I need EGGS ↗, CHEESE ↗ 'n tuh-MAY-doze ↘","why":"List: up ↗ on each item, down ↘ on the last; and → 'n'."},{"say":"Is that for here or to go?","a":"Is that for here or to go?","how":"Is that fer HERE ↗ er t' GO ↘?","why":"Closed choice: here ↗, go ↘; for → 'fer', or → 'er', to → 't''."},{"say":"Would you like some cake or cookies?","a":"Would you like some cake or cookies?","how":"Wud-ja like sum cake er COOK-eez ↗","why":"An offer, open question: one rise at the end; would you → 'wud-ja'."},{"say":"We have class on Monday and Wednesday.","a":"We have class on Monday and Wednesday.","how":"We have class on MUN-day ↗ 'n WENZ-day ↘","why":"Two-item list: up ↗, then down ↘; Wednesday = 'WENZ-day'."},{"say":"Will that be cash or card?","a":"Will that be cash or card?","how":"Will that be CASH ↗ er CARD ↘?","why":"Closed choice at the store: cash ↗, card ↘; or → 'er'."}],"tip":"In class: play 'Shopping list' — each student repeats the list and adds one item (I bought apples, bread and…), moving a hand up on each item and down on the last; then pairs ask closed choices (Beach or mountains? Netflix or a movie theater?) and answer with one option."},{"id":"a2-9","lv":"A2","n":9,"title":"Sounding polite","focus":"intonation","goal":"Make requests, thanks and apologies sound friendly, with a voice that moves, not a flat one.","goal_es":"Hacer que tus peticiones, agradecimientos y disculpas suenen amables, con una voz que se mueve y no plana.","explain":["In English, the melody of your voice shows how you feel. A flat, low voice can sound bored or rude, even with polite words. A voice that starts high and moves up and down sounds friendly and interested.","For requests, use polite words (Could you…? Can I have…? please) and let your voice go up at the end: 'Could you help me? ↗' This sounds soft. A short, low fall can sound like an order.","For thanks and apologies, start high and make a big fall ↘ on the important word: 'Thanks so MUCH! ↘' 'I'm so SORry. ↘' A big fall sounds warm and sincere; a small, flat one sounds bored."],"explain_es":["En inglés, la melodía de la voz muestra cómo te sientes. Una voz plana y baja puede sonar aburrida o maleducada, incluso con palabras amables. Una voz que empieza alta y sube y baja suena simpática e interesada.","Para pedir algo, usa palabras amables (Could you…? Can I have…? please) y deja que la voz suba al final: 'Could you help me? ↗' Así suena suave. Una bajada corta y baja puede sonar como una orden.","Para agradecer o disculparte, empieza alto y haz una bajada grande ↘ en la palabra importante: 'Thanks so MUCH! ↘' 'I'm so SORry. ↘' Una bajada grande suena cálida y sincera; una pequeña y plana suena aburrida."],"spanish":"In a new language we focus on the words and our voice gets flat; also, direct translations like 'Give me a coffee' (from 'Dame un café') sound rude in English. Fix: use Could you… / Can I have… please, start high and let your voice move.","spanish_es":"Cuando hablamos otro idioma nos concentramos en las palabras y la voz se pone plana; además, traducir directo ('Dame un café' → 'Give me a coffee') suena maleducado en inglés. Solución: usa Could you… / Can I have… please, empieza alto y deja que la voz se mueva.","ex":[{"t":"Could you help me?","how":"Cud-ja HELP me ↗","note":"request: up at the end sounds soft"},{"t":"Can I have the menu, please?","how":"K'n I have the MEN-yoo, please ↗","note":"please makes it softer"},{"t":"Excuse me, where's the bathroom?","how":"Ex-KYOOZ me ↗ | where's the BATH-room ↘","note":"excuse me ↗ to get attention"},{"t":"Could you say that again?","how":"Cud-ja say tha-da-GAIN ↗","note":"when you don't understand"},{"t":"Thank you!","how":"THANK yoo ↘","note":"start high, then fall"},{"t":"Thanks so much!","how":"Thanks so MUCH ↘","note":"a big fall sounds warm"},{"t":"Sorry about that.","how":"SOR-ree uh-BOU' that ↘","note":"start high: it sounds sincere"},{"t":"I really appreciate it.","how":"I REE-lee uh-PREE-shee-ay-dit ↘","note":"warm thanks at work"}],"listen":[{"q":"Which do you hear: a soft request ↗ or a firm one ↘?","o":["Could you help me?","Could you help me."],"pick":true,"why":"With ↗ at the end it sounds soft and polite. With a low fall ↘ it sounds firm, almost like an order."},{"q":"Which do you hear: 'What did you say?' ↗ or an apology ↘?","o":["Sorry?","Sorry."],"pick":true,"why":"Sorry? ↗ asks the person to repeat (Americans also say 'Excuse me? ↗'). Sorry. ↘ is an apology: start high and fall."},{"q":"Which do you hear?","o":["Could I have the menu?","Could I have the menu, please?"],"pick":true,"why":"please makes a request softer; at the end it often goes up ↗."},{"q":"Which do you hear?","o":["I'd like a coffee, please.","I want a coffee, please."],"pick":true,"why":"I'd like ('aid-like') is softer and more polite than I want."},{"q":"Which word has the main stress?","say":"Could you say that again?","o":["could","say","again"],"a":2,"why":"Could you say that aGAIN? ↗ The main stress is on the last important word."},{"q":"Which word has the main stress?","say":"Thanks for your help.","o":["thanks","your","help"],"a":2,"why":"Thanks for your HELP ↘: the big fall is on help."},{"q":"What's a good answer?","say":"Sorry about that.","o":["Don't worry about it.","You're welcome.","Yes, please."],"a":0,"why":"Answer an apology with 'Don't worry about it' or 'That's OK'. 'You're welcome' answers thanks."},{"q":"Where is the stress?","say":"appreciate","o":["AP-pre-ci-ate","ap-PRE-ci-ate","ap-pre-ci-ATE"],"a":1,"why":"ap-PRE-ci-ate ('uh-PREE-shee-ate'), not like Spanish apreciar."}],"mark":[{"mode":"stress","q":"Tap the word with the main stress.","w":["Could","you","help","me?"],"a":[2],"why":"Could you HELP me ↗? The voice goes up from HELP: soft and polite."},{"mode":"stress","q":"Tap the word with the main stress.","w":["Thanks","for","your","help."],"a":[3],"why":"Thanks for your HELP ↘: a big fall on HELP sounds warm."},{"mode":"stress","q":"Tap the word with the main stress.","w":["Could","you","open","the","window?"],"a":[4],"why":"Could you open the WIN-dow ↗? The last important word carries the stress."},{"mode":"stress","q":"Tap the stressed syllable.","w":["a","pol","o","gize"],"word":true,"a":[1],"why":"a-POL-o-gize: 'I apologize for the delay' is a formal apology at work."},{"mode":"link","q":"Tap where the words join.","w":["Thanks","a","lot!"],"a":[0],"why":"Thanks_a lot → 'THANK-suh LOT'."}],"dict":[{"say":"Could you help me, please?","a":"Could you help me, please?","how":"Cud-ja HELP me, please ↗","why":"A soft request: the voice goes up ↗ at the end; could you → 'cud-ja'."},{"say":"Thank you so much for your help.","a":"Thank you so much for your help.","how":"THANK-yoo so much fer yer HELP ↘","why":"Warm thanks: start high and fall on HELP; for → 'fer', your → 'yer'."},{"say":"Could you say that again, please?","a":"Could you say that again, please?","how":"Cud-ja say tha-da-GAIN, please ↗","why":"that_again → 'tha-da-GAIN': the t sounds like a quick d; up ↗ at the end = polite."},{"say":"I really appreciate it.","a":"I really appreciate it.","how":"I REE-lee uh-PREE-shee-ay-dit ↘","why":"appreciate_it → 'ay-dit'; a clear fall ↘ sounds sincere."},{"say":"I'm so sorry about that.","a":"I'm so sorry about that.","how":"I'm so SOR-ree uh-BOU' that ↘","why":"Start high on SOR-ry and fall: it sounds sincere, not bored; the t of about is very short."}],"tip":"In class: give each student a secret feeling card (bored, angry, friendly); they say 'Could you help me?' or 'Thanks so much!' and the class guesses the feeling — then everyone repeats the friendly version with a big voice move."},{"id":"b1-1","lv":"B1","n":1,"title":"Go(w)out, I(y)agree: linking vowels","focus":"linking","goal":"Join a word that ends in a vowel to a word that starts with a vowel, using a light /w/ or a light /j/ (y).","explain":["When one word ends in a vowel sound and the next word starts with a vowel sound, English speakers don't stop between them. They slide from one vowel to the other with a tiny extra sound: a light /w/ or a light /j/ (the y in yes). You won't see it in the spelling, but you will hear it: go out sounds like 'go wout' and I agree like 'I yagree'.","Which one? Think about your mouth at the end of the first word. After an 'oo', 'oh' or 'ow' sound your lips are round, so a /w/ comes out: do_w_it, go_w_out, how_w_are you. After an 'ee', 'ay', 'eye' or 'oy' sound your tongue is high at the front, so a /j/ comes out: see_y_it, say_y_it, I_y_agree.","Before a vowel, the word the usually sounds like 'thee', so it links with a y too: the_y_end, the_y_office. Keep the extra sound very light. It also helps you when you listen: if you hear 'wout' or 'yagree', it is probably two words joined together."],"spanish":"Spanish speakers often put a tiny break between the words (go | out) or squeeze the two vowels into one syllable ('dwit' for do it). Keep both vowels and glide between them with a soft w or y, much lighter than the 'y' in Spanish 'yo'.","ex":[{"t":"Let's go out.","how":"let's go_w_out","note":"go ends in 'oh' → light w"},{"t":"Just do it.","how":"just do_w_it","note":"'oo' + vowel → light w"},{"t":"How are you?","how":"how_w_are you?","note":"'ow' + vowel → light w"},{"t":"I agree with you.","how":"I_y_agree with you","note":"'eye' + vowel → light y"},{"t":"Can you see it?","how":"can you see_y_it?","note":"'ee' + vowel → light y"},{"t":"We stayed until the end.","how":"we stayed until the_y_end","note":"the before a vowel = 'thee' + light y"},{"t":"Two of them are away all week.","how":"two_w_of them are away_y_all week","note":"w after two, y after away"},{"t":"So I asked her to say it again.","how":"so_w_I asked her to say_y_it_again","note":"w after so, y after say"}],"listen":[{"q":"Which light sound joins the two words?","say":"Go out!","o":["w","y"],"a":0,"why":"go ends in an 'oh' sound with round lips, so go_w_out."},{"q":"Which light sound joins the two words?","say":"I agree.","o":["w","y"],"a":1,"why":"I ends with the tongue in the 'ee' position, so I_y_agree."},{"q":"Which light sound joins who and is?","say":"Who is it?","o":["w","y"],"a":0,"why":"who ends in 'oo', so who_w_is it?"},{"q":"Where do you hear a light y?","say":"Can you see it from here?","o":["you see","see it","it from"],"a":1,"why":"see ends in 'ee' and it starts with a vowel: see_y_it."},{"q":"How many syllables do you hear?","say":"Do it.","o":["1","2","3"],"a":1,"why":"do_w_it is 'doo-wit': two syllables joined by a w, not squeezed into one."},{"q":"How many syllables do you hear?","say":"Go away.","o":["2","3","4"],"a":1,"why":"go_w_a-way: three syllables, joined by a light w."},{"q":"Which sentence do you hear?","o":["Say it again.","Say that again."],"pick":true,"why":"say_y_it_again sounds like 'say yit again'; say that has a clear th."},{"q":"Which sentence do you hear?","o":["She is ready.","She's ready."],"pick":true,"why":"she_y_is has two syllables joined by a light y; she's has only one."}],"mark":[{"mode":"link","q":"Tap where a light w joins the words.","w":["Go","out","and","do","it","now"],"a":[0,3],"why":"go_w_out, do_w_it. (out_and also links, but with the t, not with a w.)"},{"mode":"link","q":"Tap where a light y joins the words.","w":["I","agree","with","the","idea"],"a":[0,3],"why":"I_y_agree, the_y_idea (the = 'thee' before a vowel). with already starts with a w sound."},{"mode":"link","q":"Tap where a light w or y joins the words.","w":["We","all","go","out","on","Friday"],"a":[0,2],"why":"we_y_all, go_w_out. out_on also links, but with the t, not with w or y."},{"mode":"find","q":"Tap the words that end in an 'oh', 'oo' or 'ow' sound.","w":["Go","home","and","throw","it","away"],"a":[0,3],"why":"go and throw end in 'oh', so before a vowel they add a w: throw_w_it. away ends in 'ay' (a y-link)."},{"mode":"link","q":"Tap where a light y joins the words.","w":["Stay","in","the","office","until","three"],"a":[0,2],"why":"stay_y_in, the_y_office ('thee office'). office_until joins with the s, not with a y."}],"dict":[{"say":"Let's go out to eat this evening.","a":"Let's go out to eat this evening.","how":"Let's go_w_out tu_w_eat this evening.","why":"go_w_out and to_w_eat: 'oh' or 'oo' + vowel gives a light w."},{"say":"I agree, but who is going to do it?","a":"I agree, but who is going to do it?","how":"I_y_agree, but who_w_is going to do_w_it?","why":"A light y after I; a light w after who and do."},{"say":"Can you see it from the end of the road?","a":"Can you see it from the end of the road?","how":"Can you see_y_it from the_y_end_of the road?","why":"see_y_it and the_y_end: 'ee' + vowel gives a light y."},{"say":"Why are you so angry about it?","a":"Why are you so angry about it?","how":"Why_y_are you so_w_angry_y_about_it?","why":"y after why and angry, w after so; about_it links with the t."},{"say":"Two of us are free in the afternoon.","a":"Two of us are free in the afternoon.","how":"Two_w_of_us are free_y_in the_y_afternoon.","why":"w after two; y after free and the ('thee afternoon')."}],"tip":"In class: write go out, see it, how are you and the end on the board; students hold up a W or a Y card for each one, then say the phrases smoothly in pairs."},{"id":"b1-2","lv":"B1","n":2,"title":"Nex' day, las' night: disappearing t and d","focus":"reduction","goal":"Drop a t or d between consonants (next day, last night, sandwich) and still understand these words when other people drop it.","explain":["In relaxed American speech, a t or d that comes between two other consonants often disappears. Next day sounds like 'nex day', last night like 'las night' and just now like 'jus now'. This is not lazy or wrong: native speakers do it all the time, even on the news.","It happens inside words too: sandwich ('sanwich'), handbag ('hanbag'), friendship ('frenship'), mostly ('mosly'). It happens to -ed endings as well: missed the bus sounds like 'miss the bus'. But when the next word starts with a vowel, the t or d stays and joins it: first of all ('firs-tuv all'), just a minute ('jus-ta minute').","When you listen, don't wait for the missing sound: use the context. 'Yesterday I miss the bus' makes no sense, so it must be missed. And when you write, always put the letter back."],"spanish":"Spanish speakers often simplify these groups the wrong way ('nes day' for next day, losing the k sound too) or add a vowel ('nexte day'). Drop only the t or d and keep the other consonants: nex' day = 'neks day'.","ex":[{"t":"See you next week.","how":"see you nex' week","note":"t between ks and w"},{"t":"I didn't sleep last night.","how":"I didn't sleep las' night","note":"st + n → s + n"},{"t":"She left just now.","how":"she lef' jus' now","note":"two silent t's in a row"},{"t":"You must be Carla.","how":"you mus' be Carla","note":"must be → 'mus be'"},{"t":"A ham sandwich, please.","how":"a ham san'wich, please","note":"the d in sandwich is silent"},{"t":"Where's my handbag?","how":"where's my han'bag?","note":"nd + b → n + b"},{"t":"We mostly work from home.","how":"we mos'ly work from home","note":"st + l → s + l"},{"t":"I missed the last bus.","how":"I miss' the las' bus","note":"the -ed disappears too: the context tells you it's past"}],"listen":[{"q":"Which phrase do you hear?","o":["the next day","the last day"],"pick":true,"why":"Both lose the t ('nex day', 'las day'), so listen to the vowel: e or a."},{"q":"Which phrase do you hear?","o":["the first time","the worst time"],"pick":true,"why":"Both lose the t ('firs time', 'wors time'), so listen to the first sound: f or w."},{"q":"Which sentence do you hear?","o":["I left my keys.","I lost my keys."],"pick":true,"why":"Both lose the t before my ('lef my', 'los my'); the vowel and f or s tell you which."},{"q":"Which words do you hear?","say":"You must be tired after the trip.","o":["must be","might be","may be"],"a":0,"why":"mus' be: the t disappears before b, but the vowel of must is still clear."},{"q":"Which verb is it? Use the context.","say":"I missed the bus yesterday.","o":["miss","missed"],"a":1,"why":"The -ed of missed is often silent before the, but yesterday tells you it's past."},{"q":"Which word do you hear?","say":"It's mostly sunny in the summer.","o":["mostly","most","almost"],"a":0,"why":"mos'ly: the t disappears between s and l."},{"q":"Which verb do you hear?","say":"Send me the address.","o":["send","sell","set"],"a":0,"why":"sen' me: the d drops between n and m, but you still hear the n."},{"q":"Which verb is it? Use the context.","say":"They moved to Canada last month.","o":["move","moved"],"a":1,"why":"The d of moved disappears before to, but last month tells you it's past."}],"mark":[{"mode":"find","q":"Tap the words where the t or d is usually silent.","w":["My","best","friend","lives","next","door"],"a":[1,2,4],"why":"bes' frien' lives nex' door: each t or d is between two consonants."},{"mode":"find","q":"Tap the words where the t is usually silent.","w":["Last","night","was","the","first","of","many"],"a":[0],"why":"las' night: the t is between s and n. In first_of the t stays, because of starts with a vowel."},{"mode":"find","q":"Tap the words with a silent t or d inside them.","w":["sandwich","friendship","pasta","handbag","mostly","under"],"a":[0,1,3,4],"why":"san'wich, fren'ship, han'bag, mos'ly. In pasta and under a vowel comes next, so the t and d stay."},{"mode":"find","q":"Tap the words where the -ed ending is usually silent.","w":["She","worked","late","and","missed","the","train"],"a":[1,4],"why":"work' late, miss' the: the -ed sound is between two consonants. The context tells you it's past."},{"mode":"link","q":"Tap where a t stays and joins the next word.","w":["I","just","ate","a","sandwich"],"a":[1,2],"why":"jus_tate_a: before a vowel the t doesn't disappear, it joins the next word. (The d in sandwich is silent.)"}],"dict":[{"say":"I'll call you back next week.","a":"I'll call you back next week.","how":"I'll call you back nex' week.","why":"next week: the t drops between the ks sound and w."},{"say":"She must be at home by now.","a":"She must be at home by now.","how":"She mus' be at home by now.","why":"must be: the t drops between s and b."},{"say":"I just need a chicken sandwich.","a":"I just need a chicken sandwich.","how":"I jus' need a chicken san'wich.","why":"just need and sandwich: the t and the d are silent between consonants."},{"say":"My best friend moved to Canada last month.","a":"My best friend moved to Canada last month.","how":"My bes' frien' move' to Canada las' month.","why":"best friend, moved to, last month: t and d drop between consonants, but you write them."},{"say":"We mostly worked from home last year.","a":"We mostly worked from home last year.","how":"We mos'ly work' from home las' year.","why":"mostly and last year lose the t; worked from loses the -ed sound, but last year tells you it's past."}],"tip":"In class: read five sentences with next, last, just, must and some -ed verbs at natural speed; students write them down, then check whether they put back every silent t, d and -ed."},{"id":"b1-3","lv":"B1","n":3,"title":"Water, better, a lot of: the American flap T","focus":"sounds","goal":"Say the American flap T (water, better, a lot of) and know when the t stays clear.","explain":["In American English, a t between two vowel sounds usually becomes a flap: a very quick, soft sound, like a fast d. Water sounds like 'wader', better like 'bedder' and city like 'siddy'. It also happens after r: party ('pardy'), thirty ('thirdy'). The rule: the syllable after the t must be weak. In hotel, Italian or eighteen the t starts the stressed syllable, so it stays clear.","The flap also links words. When a word ends in t and the next word starts with a vowel, the t becomes a soft d: a lot of ('a lodda'), get it ('geddit'), what about ('whaddabout'), meet at eight ('meeda deight'). This is one reason why fast American English sounds so smooth.","UK note: British English usually keeps a clear t in water, better and city ('wa-tuh', 'be-tuh'), and some British speakers stop the air instead ('wa'er'). You will hear both in films and series, but the club's model is the American flap."],"spanish":"Spanish speakers usually say a hard, clear t, so water and better sound foreign. Use the quick tap of the Spanish r in 'pero' or 'cara' instead: the t in better is almost the same sound as the r in 'pero'.","ex":[{"t":"water","how":"WA-der","note":"t between vowels → quick soft d"},{"t":"better","how":"BEH-der","note":"like the r in Spanish 'pero'"},{"t":"The city is pretty.","how":"the SI-dee is PRI-dee","note":"city, pretty: weak syllable after the t"},{"t":"We're having a party on Saturday.","how":"we're having a PAR-dee on SA-der-day","note":"after r the t is soft too"},{"t":"a lot of people","how":"a LAH-da PEO-ple","note":"lot_of → 'lodda'"},{"t":"Get it? Got it.","how":"GEH-dit? GAH-dit.","note":"t + vowel across two words"},{"t":"What about you?","how":"wha-da-BOUT you?","note":"what_about: two flaps"},{"t":"hotel, Italian, eighteen","how":"ho-TEL | i-TAL-yan | eigh-TEEN","note":"the t starts the stressed syllable → clear t"}],"listen":[{"q":"Which number do you hear?","o":["eighty","eighteen"],"pick":true,"why":"EIGH-ty has a soft d ('eidy'); eigh-TEEN has a clear t because it starts the stressed syllable."},{"q":"Which number do you hear?","o":["thirty","thirteen"],"pick":true,"why":"THIR-ty sounds like 'thirdy'; thir-TEEN keeps a clear t: it starts the stressed syllable."},{"q":"Which word do you hear?","o":["water","waiter"],"pick":true,"why":"Both have the soft d, so listen to the vowel: 'wah-der' or 'way-der'."},{"q":"Do you hear a clear t or a quick, soft d?","say":"Italy","o":["clear t","soft d"],"a":1,"why":"IT-a-ly: the t is between vowels and the next syllable is weak."},{"q":"Do you hear a clear t or a quick, soft d?","say":"Italian","o":["clear t","soft d"],"a":0,"why":"i-TAL-ian: the t starts the stressed syllable, so it stays clear."},{"q":"Which word has the soft d sound?","say":"Better late than never.","o":["better","late","never"],"a":0,"why":"BEH-der: the t is between two vowels; in late a consonant comes next."},{"q":"What do you hear after 'Can you'?","say":"Can you get it for me?","o":["get it","get in","get a"],"a":0,"why":"get_it sounds like 'geddit': the t becomes a soft d before it."},{"q":"Which word do you hear?","say":"I'll see you later.","o":["later","letter","ladder"],"a":0,"why":"later sounds like 'layder': soft d, and the vowel 'ay'."}],"mark":[{"mode":"find","q":"Tap the words with a flap T (a quick, soft d).","w":["water","hotel","city","Italy","return","better"],"a":[0,2,3,5],"why":"WA-der, SI-dee, I-da-ly, BEH-der. In ho-TEL and re-TURN the t starts the stressed syllable, so it is clear."},{"mode":"find","q":"Tap the words whose t sounds like a soft d.","w":["I","ate","a","lot","of","pasta"],"a":[1,3],"why":"ate_a ('eida'), lot_of ('lodda'). In pasta the t comes after s, so it is not a flap."},{"mode":"link","q":"Tap where a t becomes a soft d and joins the next word.","w":["Put","it","on","the","table"],"a":[0,1],"why":"put_it_on ('puddidon'). In table the t starts a stressed syllable, so it is clear."},{"mode":"link","q":"Tap where a t becomes a soft d and joins the next word.","w":["Let's","meet","at","eight","tonight"],"a":[1,2],"why":"meet_at_eight ('meeda deight'). Before tonight the t is not between vowels."},{"mode":"find","q":"Tap the words with a flap T.","w":["thirty","thirteen","photo","photography","beautiful"],"a":[0,2,4],"why":"THIR-ty, PHO-to, BEAU-ti-ful have a weak syllable after the t. In thir-TEEN and pho-TOG-ra-phy the t starts the stressed syllable."}],"dict":[{"say":"Can I get a glass of water, please?","a":"Can I get a glass of water, please?","how":"Can I geh-da glass a wah-der, please?","why":"get_a and water: t between vowels becomes a soft d."},{"say":"We bought a lot of food for the party.","a":"We bought a lot of food for the party.","how":"We bough-da lah-da food fer the par-dee.","why":"bought_a, lot_of and party (after r) all have a flap T."},{"say":"It's better to wait a little.","a":"It's better to wait a little.","how":"It's beh-der ta way-da li-dl.","why":"better, wait_a and little all have a flap T."},{"say":"I think the city is beautiful at night.","a":"I think the city is beautiful at night.","how":"I think the si-dee is beau-di-ful at night.","why":"city and beautiful have a flap; in at night a consonant comes after the t."},{"say":"What about getting a taxi to the airport?","a":"What about getting a taxi to the airport?","how":"Wha-da-bout geh-ding a taxi to the airport?","why":"what_about and getting have flaps; in taxi the t starts the stressed syllable, so it is clear."}],"tip":"In class: students say Spanish 'pero' and then 'better' with the same tongue tap; then they role-play ordering at a café with 'a glass of water', 'a lot of ice' and 'a little sugar'."},{"id":"b1-4","lv":"B1","n":4,"title":"Whaddaya think? Weak do, does, have, has","focus":"weak","goal":"Say do, does, have and has weakly in questions and in the present perfect, and hear them in fast speech.","explain":["Auxiliaries are the small helping verbs in questions and tenses. In questions, do and does are usually weak, because the important words are the question word and the main verb. Do becomes /də/ ('duh', or just a d) and does becomes /dəz/ ('duz', or just 'dz'): What do you think? ≈ 'Whaddaya think?'; Where does she live? ≈ 'Where-d'z-she live?'.","In the present perfect, have and has are weak too. Have becomes /əv/ (often just 've') and has becomes /əz/ (often just 's' or 'z'), and the h usually disappears: I have been there ≈ 'I've been there'; She has finished ≈ 'She's finished'; The bus has left ≈ 'The bus-uz left'.","They are strong in short answers, at the end of a sentence and when they are the main verb: 'Yes, I do.' 'Yes, she has.' In 'What do you do?' the first do is weak and the second do (the main verb) is strong. In 'I have a car' have is the main verb, so it keeps its h and its vowel."],"spanish":"Spanish speakers often give every word the same full force ('WHAT DO YOU THINK?'), which sounds slow and robotic and makes fast questions hard to follow. Make do, does, have and has short and soft, and put the energy on the question word and the main verb.","ex":[{"t":"What do you think?","how":"WHAD-da-ya THINK?","note":"do you → 'da-ya'"},{"t":"Where do you work?","how":"WHERE d'ya WORK?","note":"do → just a d"},{"t":"Where does she live?","how":"WHERE d'z she LIVE?","note":"does → /dəz/, often just 'dz'"},{"t":"What does it mean?","how":"WHAD-d'zit MEAN?","note":"does links to it"},{"t":"I have been there.","how":"I've BEEN there","note":"have → /əv/, often just a v sound"},{"t":"She has finished.","how":"she's FIN-ished","note":"has → /əz/, often just a z sound"},{"t":"Have you ever been to Mexico?","how":"h'v-ya EV-er been ta MEX-i-co?","note":"at the start, have is short and quick"},{"t":"Yes, I have. Does she?","how":"YES, I HAVE. DOES she?","note":"short answers and short questions: strong"}],"listen":[{"q":"Which question do you hear?","o":["What do you think?","What did you think?"],"pick":true,"why":"do you sounds like 'da-ya' (whaddaya); did you sounds like 'didja' (whadja)."},{"q":"Which question do you hear?","o":["Where does she live?","Where did she live?"],"pick":true,"why":"does she has a z sound ('d'z she'); did she has a d sound and the vowel of 'it'."},{"q":"Which sentence do you hear?","o":["She has finished the report.","She finished the report."],"pick":true,"why":"she has finished has a short 'z' sound before finished: 'she'z finished'."},{"q":"Which question do you hear?","o":["How long have you lived here?","How long did you live here?"],"pick":true,"why":"have you is a soft 'v-ya'; did you is 'didja'."},{"q":"Which word is missing? Where ___ you been?","say":"Where have you been?","o":["have","has","did"],"a":0,"why":"where've you been: have is just a short 'v' sound, but you need it with you and been."},{"q":"Which word starts the question?","say":"Has anyone seen my phone?","o":["Has","Is","Have"],"a":0,"why":"Has is weak ('h'z'), but it's there; anyone takes has."},{"q":"Is has strong or weak here?","say":"Yes, she has.","o":["strong","weak"],"a":0,"why":"In a short answer, has is strong: a clear h and a full vowel."},{"q":"Which do is strong?","say":"What do you do?","o":["the first do","the second do"],"a":1,"why":"The first do is the auxiliary ('whaddaya'); the second do is the main verb, so it is strong."}],"mark":[{"mode":"weak","q":"Tap the weak form of do, does, have or has.","w":["Where","does","your","sister","work?"],"a":[1],"why":"Where d'z your sister work? The energy is on where, sister and work."},{"mode":"weak","q":"Tap the weak form of do, does, have or has.","w":["I","have","been","to","Peru","twice."],"a":[1],"why":"I've been to Peru twice: have is just 've'."},{"mode":"weak","q":"Tap the has that is weak.","w":["Has","she","finished?","Yes,","she","has."],"a":[0],"why":"At the start of the question has is weak ('h'z she'); in the short answer it is strong."},{"mode":"stress","q":"Tap the stressed words.","w":["Where","have","you","been?"],"a":[0,3],"why":"WHERE've you BEEN? have and you are weak."},{"mode":"weak","q":"Tap the weak forms of do, does, have or has.","w":["Ana","has","gone","home,","but","Tom","has","stayed."],"a":[1,6],"why":"Ana's gone home, but Tom's stayed: has is just a z sound after a name."}],"dict":[{"say":"What do you think about the new office?","a":"What do you think about the new office?","how":"Whaddaya think about the new office?","why":"do you is weak: 'da-ya'; the stress is on think and office."},{"say":"Where does your brother live now?","a":"Where does your brother live now?","how":"Where d'z yer brother live now?","why":"does is just 'dz' and your is weak: 'yer'."},{"say":"I have never been to Buenos Aires.","a":"I have never been to Buenos Aires.","how":"I've never been ta Buenos Aires.","why":"have is weak ('ve') and to is weak ('ta')."},{"say":"She has already finished the report.","a":"She has already finished the report.","how":"She'z already finished the report.","why":"has is weak: just a short z sound, with no h."},{"say":"How long have you worked here?","a":"How long have you worked here?","how":"How long'v-ya worked here?","why":"have you is weak: 'v-ya'."}],"tip":"In class: students interview a partner with Where do you…?, What does your…?, How long have you…? and Have you ever…?, keeping the auxiliary tiny and hitting the question word and the main verb."},{"id":"b1-5","lv":"B1","n":5,"title":"I'd, I'll, should've: more contractions","focus":"weak","goal":"Say and understand I'd, I'll, it'll, should've, could've, there's and who's in natural speech.","explain":["'d is short for would or had: I'd, you'd, she'd, we'd. To know which one, look at the next verb. I'd + base verb = I would: I'd like a coffee, I'd love to. I'd + past participle = I had: I'd already eaten, I'd never seen it. (I'd rather = I would rather; I'd better = I had better.) The d is tiny, so listen carefully.","Will becomes 'll: I'll sounds like 'aisle', we'll like 'wheel', and it'll like 'iddle' (with the soft American t). Would have, should have and could have become would've, should've, could've ('WUD-uv', 'SHUD-uv', 'KUD-uv'), and in fast speech often just woulda, shoulda, coulda. Always write should've or should have, never 'should of'.","'s can mean is or has: there's, that's, who's, what's. Who's coming? = who is coming; Who's seen my keys? = who has seen (seen is a past participle). Careful: who's and whose sound exactly the same, so use the context."],"spanish":"Spanish speakers often leave the contraction out: 'I like a coffee' (for I'd like) or 'I call you later' (for I'll call), and the meaning changes. Say the tiny d or l, and listen for it: I'd like, I'll call, we'll see.","ex":[{"t":"I'd like a coffee, please.","how":"I'd LIKE a COF-fee, please","note":"I'd + base verb = I would"},{"t":"I'd already eaten.","how":"I'd al-READ-y EA-ten","note":"I'd + past participle = I had"},{"t":"I'll call you later.","how":"I'll CALL ya LA-der","note":"I'll sounds like 'aisle'"},{"t":"We'll see.","how":"we'll SEE","note":"we'll sounds like 'wheel'"},{"t":"It'll be fine.","how":"ID-dl be FINE","note":"it'll = soft d + l: 'iddle'"},{"t":"You should've told me!","how":"you SHOULD-a TOLD me!","note":"should've ≈ 'shoulda'; also coulda, woulda"},{"t":"Who's that? There's someone at the door.","how":"who's THAT? there's SOME-one at the DOOR","note":"who's = who is; there's = there is"},{"t":"I would've helped if I'd known.","how":"I WOULD-a HELPED if I'd KNOWN","note":"would've + I'd known (= I had known)"}],"listen":[{"q":"Which sentence do you hear?","o":["I'd like a coffee.","I like coffee."],"pick":true,"why":"I'd like (= I would like) has a tiny d before like: a polite request."},{"q":"Which sentence do you hear?","o":["I'll walk to work.","I walk to work."],"pick":true,"why":"I'll walk has a dark l before walk ('aisle walk'); I walk has none."},{"q":"Which sentence do you hear?","o":["We could've won.","We could win."],"pick":true,"why":"could've is 'KUD-uv': an extra weak syllable before won."},{"q":"What does I'd mean here?","say":"I'd already left when you called.","o":["I had","I would"],"a":0,"why":"I'd + past participle (left) = I had."},{"q":"What does I'd mean here?","say":"I'd love to come to your party.","o":["I had","I would"],"a":1,"why":"I'd + base verb (love) = I would."},{"q":"How does the sentence start?","say":"It'll be cold tomorrow.","o":["It'll","It's","It was"],"a":0,"why":"it'll sounds like 'iddle': a soft d and an l, and tomorrow needs will."},{"q":"What does who's mean here?","say":"Who's coming to dinner tonight?","o":["who is","who has","whose"],"a":0,"why":"who's + coming (-ing) = who is."},{"q":"Which words do you hear?","say":"You should've called me first.","o":["should've called","should call","shouldn't call"],"a":0,"why":"should've called sounds like 'shoulda called': an extra 'uh' before called."}],"mark":[{"mode":"find","q":"Tap the I'd that means I would.","w":["I'd","like","to","go,","but","I'd","already","paid."],"a":[0],"why":"I'd like = I would like; I'd already paid = I had paid (paid is a past participle)."},{"mode":"find","q":"Tap the I'd that means I had.","w":["I'd","seen","the","movie,","so","I'd","rather","stay","home."],"a":[0],"why":"I'd seen = I had seen; I'd rather = I would rather."},{"mode":"find","q":"Tap the word where 's means has.","w":["Who's","taken","my","pen?","Who's","that?"],"a":[0],"why":"Who's taken = who has taken (past participle); Who's that? = who is that?"},{"mode":"find","q":"Tap the word where 's means is.","w":["There's","a","bus","that's","been","late","all","week."],"a":[0],"why":"There's a bus = there is; that's been late = that has been late."},{"mode":"weak","q":"Tap the word that becomes just 've or 'a' in fast speech.","w":["You","should","have","asked","me."],"a":[2],"why":"should have → should've → 'shoulda asked me'."}],"dict":[{"say":"I'd like a table for two, please.","a":"I'd like a table for two, please.","how":"I'd like a table fer two, please.","why":"I'd = I would: a tiny d before like."},{"say":"I'll call you when I get there.","a":"I'll call you when I get there.","how":"I'll call ya when I get there.","why":"I'll sounds like 'aisle'; you is weak: 'ya'."},{"say":"You should've told me about the meeting.","a":"You should've told me about the meeting.","alt":["You should have told me about the meeting."],"how":"You shoulda told me about the meeding.","why":"should've → 'shoulda'; meeting has a flap T."},{"say":"It'll be easier if we leave now.","a":"It'll be easier if we leave now.","alt":["It will be easier if we leave now."],"how":"Iddle be easier if we leave now.","why":"it'll = it will: a soft d and an l."},{"say":"There's a problem, and that's why I'm late.","a":"There's a problem, and that's why I'm late.","how":"There's a problem, an' that's why I'm late.","why":"there's = there is, that's = that is; and is weak: 'an''."}],"tip":"In class: play 'Regrets and plans': each student says one thing they should've done last week and one thing they'll do next week; the partner answers with I'd… or We'll…"},{"id":"b1-6","lv":"B1","n":6,"title":"BLACKboard or black BOARD? Compounds and phrasal verbs","focus":"stress","goal":"Stress compound nouns on the first part (BUS stop), adjective + noun on the noun (a black BOARD), and phrasal verbs on the particle (turn it OFF).","explain":["A compound noun is two words that make one new thing: blackboard, greenhouse, bus stop, cell phone, credit card. Some are written as one word and some as two, but most have the main stress on the first part: BLACKboard, BUS stop, CELL phone. An adjective + noun is different: the noun gets the main stress. A BLACKboard is for writing in class; a black BOARD is any board that is black.","Phrasal verbs (a verb + up, off, out, down, in…) stress the particle, because it carries the meaning: give UP, find OUT, turn it OFF, pick me UP. With it, me or them in the middle, the particle gets the main stress. With a noun at the end, the main stress usually moves to that noun: turn off the LIGHTS, but turn them OFF.","Many phrasal verbs have a noun form, and the noun follows the compound rule: a WORKout, a CHECKout, a TAKEoff (nouns) vs work OUT, check OUT, take OFF (verbs). UK note: a few compounds are stressed differently in British English, for example weekend: American WEEKend, British weekEND."],"spanish":"In Spanish the main stress of a phrase falls on the last word (tarjeta de CRÉdito), so learners also stress the last word in English: credit CARD, bus STOP. Fix: hit the first part of a compound noun hard, and never swallow the particle of a phrasal verb: turn it OFF, give UP.","ex":[{"t":"blackboard","how":"BLACK-board","note":"compound noun: the board in a classroom"},{"t":"a black board","how":"a black BOARD","note":"adjective + noun: any board that is black"},{"t":"a greenhouse","how":"a GREEN-house","note":"a glass building for plants (a green HOUSE is a house painted green)"},{"t":"Wait for me at the bus stop.","how":"WAIT for me_at the BUS stop.","note":"two written words, one compound: BUS stop, CELL phone, CREDit card"},{"t":"I left my credit card at the coffee shop.","how":"I left my CREDit card_at the COFfee shop.","note":"two compounds, both stressed on the first part"},{"t":"Please turn it off.","how":"Please turn_it_OFF.","note":"phrasal verb + it / me / them: the particle gets the main stress"},{"t":"Can you pick me up at the airport?","how":"C'n you pick me UP_at the AIR-port?","note":"pick me UP (phrasal verb) + AIRport (compound)"},{"t":"Is the checkout open? I want to check out.","how":"Is the CHECK-out open? | I want to check OUT.","note":"noun: stress the first part; verb: stress the particle"}],"listen":[{"q":"Which do you hear?","o":["a greenhouse","a green house"],"pick":true,"why":"A GREENhouse is a glass building for plants; a green HOUSE is a house painted green."},{"q":"Which do you hear?","o":["a blackboard","a black board"],"pick":true,"why":"A BLACKboard is for writing in class; a black BOARD is any board that is black."},{"q":"Where is the stress?","say":"sunglasses","o":["SUN-glass-es","sun-GLASS-es"],"a":0,"why":"SUNglasses is a compound noun: stress on the first part."},{"q":"Where is the stress?","say":"haircut","o":["HAIR-cut","hair-CUT"],"a":0,"why":"HAIRcut is a compound noun: stress on the first part."},{"q":"Noun or verb? Listen to the stress.","say":"Where's the checkout?","o":["CHECK-out (a noun)","check OUT (a verb)"],"a":0,"why":"the CHECKout = the place where you pay: a noun, stressed on the first part."},{"q":"Noun or verb? Listen to the stress.","say":"We have to check out at noon.","o":["CHECK-out (a noun)","check OUT (a verb)"],"a":1,"why":"check OUT = leave the hotel: a phrasal verb, stressed on the particle."},{"q":"Where is the main stress?","say":"Can you pick me up?","o":["PICK me up","pick me UP"],"a":1,"why":"Phrasal verb with me in the middle: the particle gets the main stress, pick me UP."},{"q":"Which do you hear?","o":["Turn it up.","Turn it down."],"pick":true,"why":"The particle carries the meaning (louder or quieter), so it is the stressed word: turn it UP / turn it DOWN."}],"mark":[{"mode":"stress","q":"Blackboard (the board in a classroom): tap the stressed part.","w":["black","board"],"word":true,"a":[0],"why":"BLACKboard: a compound noun, stress on the first part."},{"mode":"stress","q":"The house is painted green (adjective + noun). Tap the word with the main stress.","w":["They","live","in","a","green","house"],"a":[5],"why":"a green HOUSE: adjective + noun, so the noun gets the main stress."},{"mode":"stress","q":"Tap the stressed part of each compound noun.","w":["I","left","my","cell","phone","at","the","bus","stop"],"a":[3,7],"why":"CELL phone, BUS stop: written as two words, but stressed like one word, on the first part."},{"mode":"stress","q":"Tap the word with the main stress.","w":["Can","you","turn","it","down"],"a":[4],"why":"turn it DOWN: with it in the middle, the particle gets the main stress."},{"mode":"find","q":"Tap the compound nouns. Listen: they are stressed on the first part.","w":["bedroom","computer","haircut","hotel","notebook","idea"],"a":[0,2,4],"why":"BEDroom, HAIRcut, NOTEbook are compounds. comPUter, hoTEL and iDEa are not, and they are stressed later."}],"dict":[{"say":"I left my sunglasses at the bus stop.","a":"I left my sunglasses at the bus stop.","how":"I LEFT my SUN-glasses_at the BUS stop.","why":"Compound nouns SUNglasses and BUS stop: stress on the first part; sunglasses_at links."},{"say":"Can you pick me up at the airport?","a":"Can you pick me up at the airport?","how":"C'n you pick me UP_at the AIR-port?","why":"Phrasal verb pick me UP; compound noun AIRport; can is weak: c'n."},{"say":"Please turn off your cell phone in the meeting.","a":"Please turn off your cell phone in the meeting.","how":"Please turn_OFF your CELL phone_in the MEEting.","why":"turn_off links (n + o); CELL phone is a compound, stressed on the first part."},{"say":"I gave up coffee, but I can't give up chocolate.","a":"I gave up coffee, but I can't give up chocolate.","alt":["I gave up coffee, but I can not give up chocolate."],"how":"I gave_up COFfee | but I CAN'T give_up CHOK-lit.","why":"With a noun after the particle, the main stress moves to the noun; up still links: gave_up, give_up."},{"say":"Is the checkout open? I want to check out.","a":"Is the checkout open? I want to check out.","how":"Is the CHECK-out open? | I want to check OUT.","why":"Noun CHECKout (stress first) vs phrasal verb check OUT (stress on the particle)."}],"tip":"In class: write pairs on the board (a GREENhouse / a green HOUSE, a BLACKbird / a black BIRD, a WORKout / work OUT); one student says one, and the class says the meaning or shows it with a quick drawing or gesture."},{"id":"b1-7","lv":"B1","n":7,"title":"Thought groups and pauses","focus":"rhythm","goal":"Split long sentences, numbers and instructions into thought groups, with a short pause and one main stress in each.","explain":["In long sentences, speakers don't give every word the same weight. They split the sentence into thought groups: short chunks of words that go together, with a tiny pause between them. Each chunk has one main stress, usually on its last important word: When I got HOME | I made DINner | and called my MOM.","Pauses come at commas and periods, but also after a long subject, before and, but or because, and between the steps of instructions: Open the APP | choose a SEAT | and PAY. A pause in the wrong place can change the meaning: two plus three | times four = 20, but two | plus three times four = 14.","Numbers and addresses are chunked too. US phone numbers are said digit by digit in groups of 3 + 3 + 4, with the stress on the last digit of each group: five five FIVE | two one EIGHT | four nine six ZERO (0 can also be 'oh'). Street numbers are often said in pairs: 1520 Oak Street = fifteen twenty OAK Street."],"spanish":"Spanish speakers often read long English sentences word by word, or with no pauses at all, and they say phone numbers in pairs, as in Chile (nueve, ochenta y siete…). Fix: chunk the sentence into short groups, stress the last important word of each, and say phone numbers one digit at a time, in groups.","ex":[{"t":"When I got home, I made dinner and called my mom.","how":"When I got HOME | I made DINner | and called my MOM.","note":"three thought groups, one main stress each"},{"t":"The man in the blue shirt is my new boss.","how":"The man_in the blue SHIRT | is my new BOSS.","note":"a long subject is one group"},{"t":"Open the app, choose a seat, and pay.","how":"Open the APP | choose a SEAT | and PAY.","note":"instructions: one step per group"},{"t":"If you have any questions, send me an email.","how":"If you have_any QUEStions | send me_an Email.","note":"if-part | main part"},{"t":"My number is five five five, two one eight, four nine six zero.","how":"My NUMber is | five five FIVE | two one EIGHT | four nine six ZERO.","note":"US phone numbers: 3 + 3 + 4 digits"},{"t":"It's at fifteen twenty Oak Street, next to the bank.","how":"It's_at fifteen twenty OAK Street | next to the BANK.","note":"1520 = fifteen twenty; in street names, the name is stressed"},{"t":"Two plus three, times four, is twenty.","how":"two plus THREE | times FOUR | is TWENty.","note":"(2 + 3) × 4 = 20: the pause shows the brackets"}],"listen":[{"q":"What's the answer? Listen for the pause.","say":"Two plus three, times four.","o":["20","14"],"a":0,"why":"two plus three | times four = (2 + 3) × 4 = 20."},{"q":"Who is angry?","say":"Ana, said the boss, is angry.","o":["Ana","the boss"],"a":0,"why":"Ana | said the boss | is angry: the boss is talking about Ana."},{"q":"Which number do you hear?","say":"My number is five five five, two one eight, four nine six zero.","o":["555-218-4960","555-281-4960","555-218-4690"],"a":0,"why":"Three groups: 555 | 218 | 4960. The groups make the digits easier to hear."},{"q":"Which order do you hear?","o":["I'd like the chicken salad and soup.","I'd like the chicken, salad, and soup."],"pick":true,"why":"CHICKen salad with no pause = one dish; chicken | salad | and soup = three dishes."},{"q":"What's the answer? Listen for the pause.","say":"Two, plus three times four.","o":["20","14"],"a":1,"why":"two | plus three times four = 2 + (3 × 4) = 14."},{"q":"Who is angry?","say":"Ana said the boss is angry.","o":["Ana","the boss"],"a":1,"why":"No pauses: Ana said (that) the boss is angry."},{"q":"How many thought groups do you hear?","say":"Turn left, go past the bank, and stop at the light.","o":["2","3","4"],"a":1,"why":"Turn LEFT | go past the BANK | and stop at the LIGHT: one step per group."},{"q":"Where is the pause?","say":"If you have any questions, call me after lunch.","o":["If you have | any questions call me after lunch","If you have any questions | call me after lunch","If you have any questions call me | after lunch"],"a":1,"why":"The if-part is one group: If you have any QUEStions | call me after LUNCH."}],"mark":[{"mode":"stress","q":"Tap the main stress in each thought group.","w":["When","I","got","home,","I","made","dinner"],"a":[3,6],"why":"When I got HOME | I made DINner: the last important word of each group."},{"mode":"stress","q":"Three steps, three groups. Tap the main stress in each one.","w":["Open","the","app,","choose","a","seat,","and","pay"],"a":[2,5,7],"why":"Open the APP | choose a SEAT | and PAY."},{"mode":"stress","q":"A phone number in two groups: 555 | 2184. Tap the stressed number in each group.","w":["five","five","five,","two","one","eight","four"],"a":[2,6],"why":"five five FIVE | two one eight FOUR: the last digit of each group is stressed and a bit longer."},{"mode":"stress","q":"Two thought groups: tap the main stress in each.","w":["The","man","in","the","blue","shirt","is","my","boss"],"a":[5,8],"why":"The man in the blue SHIRT | is my BOSS: the long subject is one group."},{"mode":"link","q":"Tap where the words join. Careful: words don't link across a pause.","w":["Turn","off","the","lights,","and","lock","up"],"a":[0,5],"why":"Turn_off (n + o) and lock_up (k + u). After lights there is a pause, so lights and and do not link."}],"dict":[{"say":"When I got home, I made dinner and called my mom.","a":"When I got home, I made dinner and called my mom.","how":"When I got HOME | I made DINner | and called my MOM.","why":"Three thought groups, each with one main stress on its last important word."},{"say":"My number is five five five, two one eight, four nine six zero.","a":"My number is 555 218 4960","alt":["My number is five five five two one eight four nine six zero","My number is 555-218-4960"],"how":"My NUMber is | five five FIVE | two one EIGHT | four nine six ZERO.","why":"Phone numbers: digit by digit, in groups of 3 + 3 + 4, with the last digit of each group stressed."},{"say":"Turn left, go past the bank, and stop at the light.","a":"Turn left, go past the bank, and stop at the light.","how":"Turn LEFT | go past the BANK | and stop_at the LIGHT.","why":"Instructions: one step per thought group; stop_at links."},{"say":"If you have any questions, send me an email.","a":"If you have any questions, send me an email.","how":"If you have_any QUEStions | send me_an Email.","why":"Two groups: the if-part, a pause, then the main part; have_any and me_an link."},{"say":"It's at fifteen twenty Oak Street, next to the bank.","a":"It's at 1520 Oak Street, next to the bank.","alt":["It is at 1520 Oak Street, next to the bank.","It's at fifteen twenty Oak Street, next to the bank.","It is at fifteen twenty Oak Street, next to the bank."],"how":"It's_at fifteen twenty OAK Street | next to the BANK.","why":"Street number in pairs (15-20); in a street name the name is stressed: OAK Street."}],"tip":"In class: read a phone number or short directions twice, first with pauses in the wrong places and then in the right ones; students tap the desk at each pause and say which version was easier to follow."},{"id":"b1-8","lv":"B1","n":8,"title":"I said BLUE, not green: contrastive stress","focus":"rhythm","goal":"Move the main stress to the word you correct or contrast: I'd like a LARGE coffee, not a small one.","explain":["Normally the main stress of a sentence falls on the last important word: I'd like a large COFfee. But when you correct someone or compare two things, you move the main stress to the word that makes the difference: I'd like a LARGE coffee (not a small one). This is called contrastive stress.","Make the contrast word louder, longer and higher, and say the rest, which the listener already knows, quickly and low: 'Is it on Tuesday?' 'No, it's on THURSday.' Even small words like she, me or my can take the stress when they are the difference: 'Did you call her?' 'No, SHE called ME.'","Moving the stress changes the meaning: I didn't take YOUR pen (I took Ana's) vs I didn't TAKE your pen (I only used it for a minute). So when you listen, notice the stressed word: it tells you what the speaker is really saying."],"spanish":"Spanish often shows contrast with word order or extra words (Fui yo; Me llamó ella), so Spanish speakers keep the stress at the end of the English sentence and the correction gets lost. Fix: say the corrected word louder, longer and higher, and make the rest of the sentence quieter.","ex":[{"t":"I'd like a large coffee, not a small one.","how":"I'd like_a LARGE coffee | not_a SMALL one.","note":"correcting the size"},{"t":"I said blue, not green.","how":"I said BLUE | not GREEN.","note":"both contrast words are stressed"},{"t":"The meeting isn't on Tuesday. It's on Thursday.","how":"The meeting_isn't_on TUESday. It's_on THURSday.","note":"correcting the day"},{"t":"I didn't call her. She called me.","how":"I didn't call HER. SHE called ME.","note":"pronouns can take strong stress"},{"t":"It's my boss's car, not mine.","how":"It's my BOSS's car | not MINE.","note":"car is already known, so it stays low"},{"t":"I don't live in Lima. I work in Lima.","how":"I don't LIVE_in Lima. I WORK_in Lima.","note":"the repeated word (Lima) is low; the verbs carry the contrast"},{"t":"I didn't take your pen. I took Ana's.","how":"I didn't take YOUR pen. I took ANA's.","note":"whose pen? that is the difference"},{"t":"My flight is at seven fifty, not seven fifteen.","how":"My flight_is_at seven FIFty | not seven fifTEEN.","note":"the numbers carry the contrast"}],"listen":[{"q":"Which word in the first part gets the strongest stress?","say":"I'd like a large coffee, not a small one.","o":["like","large","coffee"],"a":1,"why":"LARGE contrasts with small, so it takes the main stress; coffee is not new."},{"q":"Listen to the question. Choose the natural answer.","say":"Is the meeting at three?","o":["No, at FOUR o'clock.","No, at four o'CLOCK."],"a":0,"why":"The correction is the number: at FOUR o'clock. o'clock is not new information."},{"q":"Listen to the question. Choose the natural answer.","say":"Did Carlos pay for dinner?","o":["No, she PAID.","No, SHE paid."],"a":1,"why":"The difference is the person (Carlos → she), so SHE gets the stress."},{"q":"In 'I sent it', which word has the main stress?","say":"Ana didn't send the report. I sent it.","o":["I","sent","it"],"a":0,"why":"Ana → I: the person is the contrast, so I is stressed; sent it is already known."},{"q":"Listen to the question. Choose the natural answer.","say":"Did you buy that car?","o":["No, I RENTed it.","No, I rented IT."],"a":0,"why":"buy → rent: the verb is the difference, so RENTed gets the stress."},{"q":"Listen to the question. Choose the natural answer.","say":"Is your office on the fifth floor?","o":["No, on the sixth FLOOR.","No, on the SIXTH floor."],"a":1,"why":"fifth → sixth: the number is the correction; floor is already known."},{"q":"In the second sentence, which word has the main stress?","say":"I don't need a new phone. I need a new laptop.","o":["need","new","laptop"],"a":2,"why":"phone → laptop is the contrast; new and need are repeated, so they stay low: a new LAPtop."},{"q":"Listen to the question. Choose the natural answer.","say":"So you live in Lima?","o":["No, I work in LIma.","No, I WORK in Lima."],"a":1,"why":"live → work: the verb is the correction; Lima is already known."}],"mark":[{"mode":"stress","q":"Tap the two words with the strongest stress.","w":["I'd","like","a","large","coffee,","not","a","small","one"],"a":[3,7],"why":"I'd like a LARGE coffee, not a SMALL one: the two sizes are the contrast."},{"mode":"stress","q":"'Did you call her?' 'No! …' Tap the two stressed words.","w":["She","called","me"],"a":[0,2],"why":"SHE called ME: the people are switched, so both pronouns are stressed."},{"mode":"stress","q":"'Is that your car?' 'No, …' Tap the word with the main stress.","w":["It's","my","boss's","car"],"a":[2],"why":"It's my BOSS's car: whose car is the difference; car is already known."},{"mode":"stress","q":"'Your flight's at seven fifteen?' Tap the word with the main stress in the answer.","w":["No,","seven","fifty"],"a":[2],"why":"No, seven FIFty: only the second number changes, so it carries the stress."},{"mode":"find","q":"Tap the two words that are contrasted (they both get strong stress).","w":["The","meeting","is","on","Monday,","not","Tuesday"],"a":[4,6],"why":"MONday vs TUESday: the two days are the contrast."}],"dict":[{"say":"I ordered a large coffee, not a small one.","a":"I ordered a large coffee, not a small one.","how":"I ordered_a LARGE coffee | not_a SMALL one.","why":"Contrast large / small; coffee and one are already known, so they are low."},{"say":"I didn't call her. She called me.","a":"I didn't call her. She called me.","how":"I didn't call HER. SHE called ME.","why":"The people are the contrast, so the pronouns her, she and me are stressed."},{"say":"The meeting isn't on Tuesday. It's on Thursday.","a":"The meeting isn't on Tuesday. It's on Thursday.","alt":["The meeting isn't on Tuesday. It is on Thursday."],"how":"The meeting_isn't_on TUESday. It's_on THURSday.","why":"The days are the contrast; isn't_on and it's_on link."},{"say":"I don't live in Lima. I just work there.","a":"I don't live in Lima. I just work there.","how":"I don't LIVE_in Lima. I just WORK there.","why":"live / work is the contrast; Lima and there are already known."},{"say":"She wants the blue folder, not the red one.","a":"She wants the blue folder, not the red one.","how":"She wants the BLUE folder | not the RED one.","why":"The colors are the contrast; folder and one stay low."}],"tip":"In class: say false sentences about the students ('Pablo drinks tea every morning'); the class corrects them, stressing only the word that changes: 'No, he drinks COFfee!' or 'No, CAMila drinks tea!'"},{"id":"b1-9","lv":"B1","n":9,"title":"Isn't it? Question tags","focus":"intonation","goal":"Use a falling tag ↘ to ask for agreement and a rising tag ↗ to ask a real question, and say tags fast and linked.","explain":["A question tag is a short question at the end of a sentence: isn't it?, aren't you?, did she? A positive sentence takes a negative tag (It's cold, isn't it?) and a negative sentence takes a positive tag (She didn't call, did she?). The tag uses the same helping verb as the sentence: is, are, do, did, have, can, will…","The voice falls or rises on the tag, and this changes the meaning. Falling ↘: you are sure and you just want the other person to agree; it is more a comment than a question: It's a nice day, isn't it? ↘ Rising ↗: you are not sure, so it is a real question: You're coming, aren't you? ↗ (I think so, but tell me).","Tags are short and linked: isn't it sounds like 'IZ-nit', aren't you like 'ARN-chu', didn't you like 'DIDN-chu', doesn't he like 'DUZ-nee'. The helping verb is stressed, and the fall or rise starts there. In American English, right? is also very common: You're coming, right? ↗ British speakers use question tags more often."],"spanish":"Spanish tags like ¿no? or ¿cierto? usually go up, so Spanish speakers often make every English tag rise and sound unsure, or they use 'no?' for everything. Fix: choose the right tag, and let your voice fall when you only want agreement.","ex":[{"t":"It's a beautiful day, isn't it?","how":"It's_a BEAUtiful DAY | IZ-nit? ↘","note":"small talk: you're sure, you want agreement"},{"t":"The food was great, wasn't it?","how":"The FOOD was GREAT | WUZ-nit? ↘","note":"after a nice meal: you're sure"},{"t":"We've met before, haven't we?","how":"We've MET beFORE | HAV-n-wee? ↘","note":"you remember the person and want them to agree"},{"t":"I'm not sure. You're coming tonight, aren't you?","how":"I'm NOT SURE. | Yer coming toNIGHT | ARN-chu? ↗","note":"not sure: a real question, so the tag rises"},{"t":"She didn't call you, did she?","how":"She DIDn't CALL you | DID-shee? ↗","note":"negative sentence → positive tag; a real question"},{"t":"Excuse me, this is the train to the airport, isn't it?","how":"Excuse me | this is the TRAIN to the AIR-port | IZ-nit? ↗","note":"checking information with a stranger"},{"t":"Your sister works at the bank, doesn't she?","how":"Yer SIS-ter works_at the BANK | DUZ-n-shee?","note":"works → doesn't she"},{"t":"You're coming, right?","how":"Yer COMing | RIGHT? ↗","note":"very common in American English instead of a tag"}],"listen":[{"q":"Listen to the situation. Does the tag fall or rise?","say":"What a beautiful day! It's really warm, isn't it?","o":["↘ It falls: I'm sure, please agree.","↗ It rises: I'm not sure, please tell me."],"a":0,"why":"Small talk about the weather: the speaker is sure and wants agreement, so the tag falls."},{"q":"Which tag do you hear?","say":"You're coming to the party, aren't you?","o":["aren't you","are you","don't you"],"a":0,"why":"aren't you sounds like 'ARN-chu': a positive sentence with are takes aren't."},{"q":"Listen to the situation. Does the tag fall or rise?","say":"I'm not sure about the time. The meeting is at ten, isn't it?","o":["↘ It falls: I'm sure, please agree.","↗ It rises: I'm not sure, please tell me."],"a":1,"why":"'I'm not sure': it is a real question, so the tag rises."},{"q":"Which tag do you hear?","say":"She didn't call you back, did she?","o":["did she","didn't she","does she"],"a":0,"why":"A negative sentence (didn't) takes a positive tag: did she?"},{"q":"Listen to the situation. Does the tag fall or rise?","say":"Dinner was delicious, wasn't it? Thank you so much!","o":["↘ It falls: I'm sure, please agree.","↗ It rises: I'm not sure, please tell me."],"a":0,"why":"The speaker is thanking the host and is sure the food was good, so the tag falls."},{"q":"Which tag do you hear?","say":"You can drive, can't you?","o":["can you","can't you","could you"],"a":1,"why":"can't you sounds like 'CAN-chu': the t and the y join into a ch sound."},{"q":"Listen to the situation. Does the tag fall or rise?","say":"Excuse me, I'm a bit lost. This bus goes downtown, doesn't it?","o":["↘ It falls: I'm sure, please agree.","↗ It rises: I'm not sure, please tell me."],"a":1,"why":"The speaker is lost and needs information: a real question, so the tag rises."},{"q":"Which tag do you hear?","say":"Your brother lives in Canada, doesn't he?","o":["isn't he","doesn't he","didn't he"],"a":1,"why":"lives (present simple) → doesn't he, which sounds like 'DUZ-nee'."}],"mark":[{"mode":"link","q":"Tap where the words join.","w":["It's","a","nice","day,","isn't","it"],"a":[0,4],"why":"It's_a (s + a) and isn't_it ('IZ-nit'). There is a pause at the comma, so day and isn't do not link."},{"mode":"stress","q":"Tap the stressed word in the tag.","w":["You're","coming,","aren't","you"],"a":[2],"why":"The helping verb is stressed: AREN'T you ('ARN-chu'). The voice falls or rises from there."},{"mode":"link","q":"Tap where the words join.","w":["You","didn't","forget","it,","did","you"],"a":[2,4],"why":"forget_it ('for-GEH-dit', with a soft American t) and did_you ('DID-joo': d + y = j)."},{"mode":"stress","q":"Tap the stressed word in the tag.","w":["We've","met","before,","haven't","we"],"a":[3],"why":"HAVEN'T we ('HAV-n-wee'): the helping verb carries the stress, not the pronoun."},{"mode":"stress","q":"Tap the main stress of the sentence and the stressed word of the tag (two words).","w":["The","food","was","great,","wasn't","it"],"a":[3,4],"why":"The food was GREAT | WASn't it: the main stress of the sentence, then the helping verb of the tag."}],"dict":[{"say":"It's a beautiful day, isn't it?","a":"It's a beautiful day, isn't it?","alt":["It is a beautiful day, isn't it?"],"how":"It's_a BEAUtiful DAY | IZ-nit? ↘","why":"isn't it → 'IZ-nit'; a falling tag: small talk, the speaker is sure."},{"say":"You're coming to the meeting, aren't you?","a":"You're coming to the meeting, aren't you?","how":"Yer coming to the MEEting | ARN-chu?","why":"you're → 'yer'; aren't you → 'ARN-chu' (t + y = ch)."},{"say":"She didn't call you back, did she?","a":"She didn't call you back, did she?","how":"She DIDn't call you BACK | DID-shee?","why":"Negative sentence → positive tag; call you BACK is a phrasal verb, stressed on the particle."},{"say":"You've been to Brazil before, haven't you?","a":"You've been to Brazil before, haven't you?","how":"You've been to bra-ZIL before | HAV-n-chu?","why":"haven't you → 'HAV-n-chu'; the stress is on haven't, not on you."},{"say":"Your sister works at the bank, doesn't she?","a":"Your sister works at the bank, doesn't she?","how":"Yer SIS-ter works_at the BANK | DUZ-n-shee?","why":"works → doesn't she; the t disappears: 'DUZ-n-shee'."}],"tip":"In class: students make tags about classmates they know a little ('You're from Concepción, aren't you?'); if they are sure, the tag falls, if they are guessing, it rises, and the partner answers."},{"id":"b2-1","lv":"B2","n":1,"title":"Don't you, meet you: t and d meet y","focus":"reduction","goal":"Recognize and use the 'ch' and 'j' sounds that appear when t or d meets you, your, yet or year.","explain":["When a word ends in t and the next word starts with a y sound (you, your, yet, year), the two sounds often melt into one: 'ch', as in chair. Meet you → 'MEE-chu', don't you → 'DOHN-chu', last year → 'las-CHEER'. When the word ends in d, you get 'j', as in job: would you → 'WOO-ju', did you know → 'DI-ju KNOW'.","This is called assimilation, and it is normal in relaxed American speech, especially with you and your: what your → 'WHA-cher', need your → 'NEE-jer'. With yet and year it is common but optional. You already make these sounds inside words: actually ('AK-chu-uh-lee'), nature ('NAY-cher'), education ('ed-juh-KAY-shun').","For listening: 'chu' or 'cher' after a verb usually hides t + you/your, and 'ju' or 'jer' hides d + you/your. For speaking: let the t or d slide straight into the y, with no pause and no extra vowel. In writing, always use the full words."],"spanish":"Spanish speakers tend to say each word separately ('meet… iu', 'did… iu') or use a strong Spanish y, so the natural 'MEE-chu' sounds like a new word. 'ch' is a Spanish sound, so it is easy to produce: the real job is to hear 'chu' and 'ju' as 'you'.","ex":[{"t":"Nice to meet you.","how":"NICE tuh MEE-chu","note":"t + you → ch"},{"t":"Don't you like it?","how":"DOHN-chu LIKE it?","note":"t + you → ch; the n stays"},{"t":"Would you mind?","how":"WOO-ju MIND?","note":"d + you → j, as in job"},{"t":"Did you know?","how":"DI-ju KNOW?","note":"d + you → j"},{"t":"We met last year.","how":"we MET las-CHEER","note":"t + year → ch (common, but optional)"},{"t":"I'll let you know.","how":"I'll LE-chu KNOW","note":"t + you → ch"},{"t":"Did you send your report?","how":"DI-ju SEN-jer rePORT?","note":"d + your → 'jer'"},{"t":"I told you what your boss said.","how":"i TOL-ju WHA-cher BOSS SAID","note":"d + you → j; t + your → ch"}],"listen":[{"q":"Which sentence do you hear?","o":["Nice to meet you.","Nice to see you."],"pick":true,"why":"meet you → 'MEE-chu' (t + you); see you has no t, so no ch."},{"q":"Which question do you hear?","o":["Didn't you call her?","Did you call her?"],"pick":true,"why":"Didn't you → 'DID-n-chu' (n + ch); did you → 'DI-ju'."},{"q":"Which question do you hear?","o":["Would you mind?","Do you mind?"],"pick":true,"why":"would you → 'WOO-ju'; do you is short: 'd'yu'."},{"q":"Which question do you hear?","o":["Can't you stay?","Can you stay?"],"pick":true,"why":"Can't you → 'KAN-chu' (t + you → ch); can you → 'k'n-yu'."},{"q":"Which word comes after 'last'?","say":"I started this job last year.","o":["ear","year","cheer"],"a":1,"why":"'las-CHEER' is last year: the t and the y join as ch."},{"q":"Which words make the 'LE-chu' sound in this sentence?","say":"I'll let you know tomorrow.","o":["let you","let your","lecture"],"a":0,"why":"I'll let you know: t + you → 'LE-chu'."},{"q":"How many words do you hear?","say":"Did you know that?","o":["3","4","5"],"a":1,"why":"Did you know that: 'DI-ju' is two words, did + you."},{"q":"What is the question?","say":"Why don't you ask your manager?","o":["Why don't you ask your manager?","Why do you ask your manager?","Why didn't you ask your manager?"],"a":0,"why":"'why DOHN-chu': the long 'oh' and the n + ch show don't you."}],"mark":[{"mode":"link","q":"Tap where t or d joins a y sound (→ ch or j).","w":["Nice","to","meet","you."],"a":[2],"why":"meet_you → 'MEE-chu'."},{"mode":"link","q":"Tap where t or d joins a y sound (→ ch or j).","w":["I","told","you","about","it","last","year."],"a":[1,5],"why":"told_you → 'TOL-ju' (d → j); last_year → 'las-CHEER' (t → ch)."},{"mode":"link","q":"Tap where d joins you or your (→ j).","w":["Could","you","send","your","report","today?"],"a":[0,2],"why":"could_you → 'COO-ju'; send_your → 'SEN-jer'."},{"mode":"find","q":"Tap the words whose last sound becomes 'ch' (t + you/your).","w":["I'll","let","you","know","what","your","boss","said."],"a":[1,4],"why":"let you → 'LE-chu'; what your → 'WHA-cher'."},{"mode":"find","q":"Tap the words whose last sound becomes 'j' (d + you/your).","w":["Did","you","find","your","keys","or","your","phone?"],"a":[0,2],"why":"Did you → 'DI-ju'; find your → 'FIN-jer'. 'or your' has no d."}],"dict":[{"say":"Nice to meet you, I've heard a lot about you.","a":"Nice to meet you, I've heard a lot about you.","how":"NICE tuh MEE-chu, i've HEARD uh LAH-duh-BOW-chu","why":"meet you and about you: t + you → ch; lot about: flap T ('LAH-duh')."},{"say":"Would you mind if I opened the window?","a":"Would you mind if I opened the window?","how":"WOO-ju MIND if i OH-pund the WINdow?","why":"would you → 'WOO-ju': d + you → j."},{"say":"Did you know that she moved here last year?","a":"Did you know that she moved here last year?","how":"DI-ju KNOW that she MOOVD here las-CHEER?","why":"did you → 'DI-ju' (j); last year → 'las-CHEER' (ch)."},{"say":"Why don't you call me when you get your results?","a":"Why don't you call me when you get your results?","how":"why DOHN-chu CALL me when you GE-cher reSULTS?","why":"don't you → 'DOHN-chu'; get your → 'GE-cher': t + y → ch."},{"say":"I told you we needed your signature by Friday.","a":"I told you we needed your signature by Friday.","how":"i TOL-ju we NEE-di-jer SIGnature by FRIday","why":"told you → 'TOL-ju'; needed your → 'NEE-di-jer': d + y → j."}],"tip":"In class: students ask each other fast 'Did you…? / Would you…? / Don't you…?' questions about last weekend; the listener answers, then repeats the question slowly, word by word, to show what was hidden."},{"id":"b2-2","lv":"B2","n":2,"title":"Tem pounds, goob boy: sounds that change place","focus":"reduction","goal":"Understand and use the n, t and d changes of fast speech: ten pounds → 'tem pounds', in case → 'ing case', good boy → 'goob boy'.","explain":["In fast speech, the last sound of a word often gets ready for the next one. This mostly happens to n, t and d, the sounds made with the tip of the tongue. Before p, b or m your lips are already closing, so n becomes m: ten pounds → 'tem POUNDS', in between → 'im-be-TWEEN', green bag → 'greem BAG'.","Before k or g the back of the tongue is already rising, so n becomes 'ng', the last sound of sing: in case → 'ing CASE', ten cups → 'teng CUPS'. t and d change too: before p, b or m, t sounds like p and d like b: that man → 'thap MAN', white board → 'WIPE-board', good boy → 'goob BOY'. In American English that t is often also a quick stop in the throat.","It only works one way: m, p and b never change into n, t or d. The changes are optional, and slow, careful speech keeps the original sounds. Your main job is to recognize the words: 'tem POUNDS' is still ten pounds and 'goob MORning' is still good morning."],"spanish":"Good news: Spanish does the same with n ('un beso' sounds like 'um beso', and 'tengo' has the 'ng' of sing), so use that habit in English too. The new part is t and d: don't release a strong t or d before p, b or m; close your lips early: 'thap MAN', 'goob BOY'.","ex":[{"t":"ten pounds","how":"tem POUNDS","note":"n → m before p, b, m"},{"t":"in between","how":"im-be-TWEEN","note":"n → m before b"},{"t":"a green bag","how":"uh greem BAG","note":"n → m before b"},{"t":"in case","how":"ing CASE","note":"n → ng (as in sing) before k, g"},{"t":"That man is my boss.","how":"thap MAN iz my BOSS","note":"t → p before m"},{"t":"Can you clean the whiteboard?","how":"k'n-yu CLEAN the WIPE-board?","note":"t → p before b"},{"t":"Goodbye, see you on Monday.","how":"goob-BYE, SEE you om MONday","note":"d → b before b; n → m before m"},{"t":"It's not bad, but I can come back.","how":"it's nahp BAD, but i k'ng come BACK","note":"t → p before b; n → ng before k"}],"listen":[{"q":"What is the first word?","say":"Ten people came to the meeting.","o":["Ten","Tim","Them"],"a":0,"why":"Before p, ten sounds like 'tem', but it is still ten."},{"q":"Which phrase do you hear?","o":["that man","the man"],"pick":true,"why":"that man → 'thap MAN' with the 'a' of cat; the man has a weak 'thuh'."},{"q":"In fast speech, 'in case' sounds like…","say":"in case","o":["im case","ing case"],"a":1,"why":"Before k, n moves back and becomes 'ng': 'ing CASE'."},{"q":"In fast speech, 'white board' sounds most like…","say":"white board","o":["wipe board","wide board"],"a":0,"why":"Before b, t changes to a p-like sound: 'WIPE-board'."},{"q":"In fast speech, 'good morning' sounds like…","say":"Good morning, everyone.","o":["goob morning","goog morning"],"a":0,"why":"Before m, d becomes a b-like sound: 'goob MORning'."},{"q":"How many cups does the speaker want?","say":"Bring ten cups, please.","o":["two","seven","ten"],"a":2,"why":"Before k, ten sounds like 'teng', but it is still ten."},{"q":"Which word's n becomes 'ng'?","say":"I can come back on Monday.","o":["can","on","Monday"],"a":0,"why":"can + come (k) → 'k'ng'; on + Monday (m) → 'om', not 'ng'."},{"q":"Where do they want to meet?","say":"Can we meet in between the bank and the station?","o":["in between the bank and the station","in the bank, near the station","at the station, behind the bank"],"a":0,"why":"'im-be-TWEEN' is in between: n → m before b."}],"mark":[{"mode":"find","q":"Tap the words whose last sound changes to m.","w":["Ten","people","were","in","between","the","green","cars."],"a":[0,3],"why":"Ten people → 'tem', in between → 'im'. Green cars → 'greeng' (ng, not m)."},{"mode":"find","q":"Tap the words whose final n becomes 'ng' (as in sing).","w":["I","can","go","in","case","Ben","calls."],"a":[1,3,5],"why":"n before g or k → ng: 'k'ng GO', 'ing CASE', 'Beng CALLS'."},{"mode":"link","q":"Tap where a sound changes to fit the next word.","w":["Ten","people","sat","by","the","green","door."],"a":[0,2],"why":"Ten_people → 'tem'; sat_by → 'sap BY'. green door: n and d are made in the same place, so no change."},{"mode":"find","q":"Tap the words whose final t or d becomes p or b.","w":["Not","bad!","I","had","a","good","meal","here."],"a":[0,5],"why":"Not bad → 'nahp BAD' (t → p); good meal → 'goob MEAL' (d → b). had a: no change before a vowel."},{"mode":"link","q":"Tap where n becomes m.","w":["I'll","be","in","Mexico","on","Monday."],"a":[2,4],"why":"in_Mexico → 'im MEXico'; on_Monday → 'om MONday'."}],"dict":[{"say":"That man in the green coat is my new boss.","a":"That man in the green coat is my new boss.","how":"thap MAN in the greeng COAT is my new BOSS","why":"that man: t → p; green coat: n → ng."},{"say":"I'll meet you in between the bank and the station.","a":"I'll meet you in between the bank and the station.","how":"I'll MEE-chu im-be-TWEEN the BANK and the STAtion","why":"in between: n → m; meet you: t + you → ch."},{"say":"Good morning, I've got ten minutes before the meeting.","a":"Good morning, I've got ten minutes before the meeting.","how":"goob MORning, i've GOT tem MINutes beFORE the MEETing","why":"good morning: d → b; ten minutes: n → m."},{"say":"In case you need it, there's a whiteboard in my office.","a":"In case you need it, there's a whiteboard in my office.","alt":["In case you need it, there's a white board in my office."],"how":"ing CASE you NEED it, there's a WIPE-board im my OFfice","why":"in case: n → ng; whiteboard: t → p; in my: n → m."},{"say":"Not bad, but I can come back on Monday.","a":"Not bad, but I can come back on Monday.","how":"nahp BAD, but i k'ng come BACK om MONday","why":"not bad: t → p; can come: n → ng; on Monday: n → m."}],"tip":"In class: dictate mixed pairs at full speed (ten pounds / ten dollars, good boy / good day, in case / in town); students write the words and say which ones changed sound and why."},{"id":"b2-3","lv":"B2","n":3,"title":"Button, mountain: the stopped T","focus":"sounds","goal":"Say and recognize the American 'stopped T' in words like button and mountain and in phrases like not now and can't do.","explain":["In American English, a t before an n sound is usually not a full t. You stop the air in your throat for a moment (like the break in 'uh-oh') and go straight to n through your nose, with no vowel in between: button → 'BUH'n', mountain → 'MOWN'n', certain → 'SUR'n', Latin → 'LA'n'. This is a glottal stop; in the sounds-like lines, ' marks it.","The same stopped T is common at the end of a word before a consonant: not now → 'nah' NOW', that one → 'tha' ONE', can't do → 'KAN' DO'. Your tongue may touch the top of your mouth, but the t is not released: no puff of air. Between vowels, Americans use the quick flap instead (water, better, city), not a stop.","UK note: many British speakers, especially in London, also stop the T between vowels and at the end of words: water → 'wa'er', better → 'be'er'. You will hear it in British films and series, but it is not the American model."],"spanish":"Spanish speakers usually read the letters: 'BU-ton', 'moun-TEIN', 'ser-TEIN', with a clear t, a full vowel and often the stress at the end. Keep the stress on the first syllable, stop the air and go straight to n: 'BUH'n', 'MOWN'n'.","ex":[{"t":"button","how":"BUH'n","note":"stop the air, then n through the nose"},{"t":"mountain, certain, Latin","how":"MOWN'n | SUR'n | LA'n","note":"no vowel between the stop and n"},{"t":"written, forgotten, important","how":"RI'n | fer-GAH'n | im-POR'nt","note":"the stopped T comes right after the stressed syllable"},{"t":"Not now, I'm busy.","how":"nah' NOW, i'm BIzy","note":"t before a consonant: stopped, not released"},{"t":"That one, please.","how":"tha' ONE, PLEASE","note":"the 'a' of cat, then a stop"},{"t":"I can't do it today.","how":"i KAN' DO it tuDAY","note":"can't = full 'a' + stop; can = weak 'k'n'"},{"t":"I'm certain I've forgotten something.","how":"i'm SUR'n i've fer-GAH'n SOMEthing","note":"two stopped Ts before n"},{"t":"It's not that important.","how":"it's nah' THA' im-POR'nt","note":"three stopped Ts in one short sentence"}],"listen":[{"q":"Which word do you hear?","o":["button","butter"],"pick":true,"why":"button = stop + n ('BUH'n'); butter = flap ('BUH-der')."},{"q":"Which word do you hear?","o":["Latin","latter"],"pick":true,"why":"Latin = stop + n ('LA'n'); latter = flap ('LA-der')."},{"q":"Which word do you hear?","o":["written","ridden"],"pick":true,"why":"written has a stopped T ('RI'n'); ridden has a real d ('RI-dn')."},{"q":"Which word do you hear?","o":["whiten","widen"],"pick":true,"why":"whiten has a stopped T ('WHY'n'); widen has a real d ('WHY-dn')."},{"q":"Which sentence do you hear?","o":["I can't do it on Monday.","I can do it on Monday."],"pick":true,"why":"can't has a full 'a' and a stop ('KAN' DO'); can is weak ('k'n DO')."},{"q":"How many syllables?","say":"certainly","o":["2","3","4"],"a":1,"why":"cer-tain-ly = 'SUR'n-lee': three syllables, with no vowel between the stop and n."},{"q":"Which words do you hear?","say":"Is that one yours?","o":["that one","the one","this one"],"a":0,"why":"'tha' ONE': the 'a' of cat, then a stopped T."},{"q":"Where is the stress in 'mountain'?","say":"We hiked up the mountain.","o":["MOUN-tain","moun-TAIN"],"a":0,"why":"'MOWN'n': stress on the first syllable; the second is just a stop + n."}],"mark":[{"mode":"find","q":"Tap the words with a stopped T (not a flap).","w":["button","butter","mountain","city","certain","water"],"a":[0,2,4],"why":"button, mountain, certain: t + n = stop. butter, city, water: t between vowels = flap."},{"mode":"find","q":"Tap the words where the T is stopped before a consonant.","w":["Not","now,","I","can't","do","that","one."],"a":[0,3,5],"why":"Not now, can't do, that one: t before n, d and w → stopped T."},{"mode":"stress","q":"Tap the stressed syllable.","w":["im","por","tant"],"word":true,"a":[1],"why":"imPORtant → 'im-POR'nt': stress, then stop + n."},{"mode":"stress","q":"Tap the stressed syllable.","w":["Man","hat","tan"],"word":true,"a":[1],"why":"ManHATtan → 'man-HA'n': the stopped T comes after the stress."},{"mode":"find","q":"Tap the words with a stopped T (stop + n).","w":["Britain","British","eaten","eating","written","writing"],"a":[0,2,4],"why":"Britain, eaten, written: t + n = stop. British, eating, writing: flap."}],"dict":[{"say":"I'm not sure that one is the right button.","a":"I'm not sure that one is the right button.","how":"i'm nah' SURE tha' ONE is the righ' BUH'n","why":"not, that, right: stopped before a consonant; button: stop + n."},{"say":"We spent the weekend in the mountains.","a":"We spent the weekend in the mountains.","how":"we SPEN' the WEEKend in the MOWN'nz","why":"spent the: stopped T; mountains: stop + n."},{"say":"I can't do it now, but I'm certain it's important.","a":"I can't do it now, but I'm certain it's important.","how":"i KAN' DO it NOW, but i'm SUR'n it's im-POR'nt","why":"can't do: stopped T; certain and important: stop + n."},{"say":"Have you written the report for the Latin American team?","a":"Have you written the report for the Latin American team?","how":"have you RI'n the rePORT for the LA'n uh-MER-i-kun TEAM?","why":"written and Latin: stop + n, no vowel before the n."},{"say":"Sorry, I've forgotten the name of that street.","a":"Sorry, I've forgotten the name of that street.","how":"SORry, i've fer-GAH'n the NAME of tha' STREET","why":"forgotten: stop + n; that street: stopped before s."}],"tip":"In class: students say 'button, mountain, certain, important' with a hand on the throat to feel the stop, then contrast them with 'butter, city, water' (flap) and guess which word a partner says."},{"id":"b2-4","lv":"B2","n":4,"title":"Kinda, sorta, lotta, tell 'em","focus":"reduction","goal":"Understand and use the casual forms kinda, sorta, a lotta, outta, 'em, 'im and 'er.","explain":["In relaxed speech, of usually loses its v and becomes a weak 'uh' that joins the word before it: kind of → 'KAIN-duh', sort of → 'SOR-duh', a lot of → 'uh LAH-duh', out of → 'OW-duh'. Notice the American flap T in sorta, lotta and outta. People write kinda, sorta, lotta and outta in texts and chats, but never in formal writing.","Unstressed pronouns lose sounds too. Them often becomes 'em: tell them → 'TELL-um', call them → 'CALL-um'. Him and her lose their h after another word: tell him → 'TELL-im', ask her → 'ASK-er', meet her → 'MEE-der'. The h stays at the start of a sentence (Her phone is off) and when the pronoun is stressed (I called HER, not him).","Kind of and sort of also have a meaning: 'a little, not completely' (I'm kinda tired). Because the words join, 'tell him' can sound like one word, so listen for the verb and expect a pronoun after it. These forms sound natural with friends and colleagues; use the full forms in presentations and in writing."],"spanish":"Spanish speakers tend to pronounce every letter ('kaind ov', 'tel dem') and say him/her with a strong Spanish j: 'tel jim'. When these words are not stressed, drop the v, the th and the h, and join them to the word before: 'TELL-im', 'KAIN-duh'.","ex":[{"t":"I'm kind of tired.","how":"i'm KAIN-duh TIRED","note":"kind of = a little"},{"t":"It's sort of complicated.","how":"it's SOR-duh COMplicated","note":"flap T + 'uh': 'SOR-duh'"},{"t":"We have a lot of work.","how":"we HAVE uh LAH-duh WORK","note":"of → 'uh'"},{"t":"Get out of here!","how":"GE-dow-duh HERE!","note":"out of → 'OW-duh'; it can also mean 'No way!'"},{"t":"Tell them I'm on my way.","how":"TELL-um i'm ON my WAY","note":"them → 'em"},{"t":"I'll call him later.","how":"I'll CALL-im LAter","note":"unstressed him loses its h"},{"t":"Ask her what she thinks.","how":"ASK-er what she THINKS","note":"unstressed her loses its h"},{"t":"We ran out of time, so I told them to email her.","how":"we RAN OW-duh TIME, so i TOLD-um tuh EE-mail-er","note":"out of, them and her all shrink"}],"listen":[{"q":"Which sentence do you hear?","o":["Tell him the news.","Tell them the news."],"pick":true,"why":"In fast speech: 'TELL-im' (him) vs 'TELL-um' (them): listen to the vowel."},{"q":"Which sentence do you hear?","o":["I called her.","I called him."],"pick":true,"why":"'CALL-der' (her) vs 'CALL-dim' (him): the h disappears, so listen to the vowel."},{"q":"Which sentence do you hear?","o":["He's out of the office.","He's in the office."],"pick":true,"why":"'OW-duh the' = out of the: the of shrinks to 'uh'."},{"q":"How many words do you hear?","say":"We have a lot of time.","o":["4","5","6"],"a":2,"why":"We have a lot of time: 'uh LAH-duh' hides three words."},{"q":"What is the problem?","say":"We ran out of milk.","o":["There's no milk left.","They went out for milk.","The milk is outside."],"a":0,"why":"ran out of → 'RAN OW-duh': there's none left."},{"q":"What does the speaker mean?","say":"I'm sort of interested.","o":["very interested","a little interested","not interested at all"],"a":1,"why":"sort of / kind of = a little, not completely."},{"q":"In fast speech, 'see him' usually sounds like…","say":"Did you see him?","o":["SEE-im","SEE-jim","SEE-hem"],"a":0,"why":"Unstressed him loses its h and joins the verb: 'SEE-im'."},{"q":"Which 'her' usually loses its h?","say":"Her phone is off, so I'll text her.","o":["the first one","the second one","both"],"a":1,"why":"At the start of a sentence the h stays; after a verb it disappears: 'TEXT-er'."}],"mark":[{"mode":"weak","q":"Tap the two words that lose a consonant.","w":["I've","told","them","lots","of","times."],"a":[2,4],"why":"them → 'em (no th), of → 'uh' (no v): i've TOLD-um LOT-suh TIMES."},{"mode":"link","q":"Tap where the words join.","w":["Get","out","of","here!"],"a":[0,1],"why":"'GE-dow-duh HERE': get_out_of with flap Ts; of → 'uh'."},{"mode":"find","q":"Tap the pronouns that lose their h.","w":["Her","boss","called","him","and","asked","her","to","stay."],"a":[3,6],"why":"called him → 'CALL-dim', asked her → 'ASK-ter'. Her at the start keeps its h."},{"mode":"weak","q":"Tap the words that shrink to 'uh'.","w":["It's","kind","of","a","long","story."],"a":[2,3],"why":"kind of a → 'KAIN-duh-uh': of and a are both 'uh'."},{"mode":"find","q":"Tap the words you would hear as 'em, 'im or 'er.","w":["Ask","them","if","Tom","wants","to","meet","her."],"a":[1,7],"why":"ask them → 'ASK-um'; meet her → 'MEE-der' (no h, so the t becomes a flap)."}],"dict":[{"say":"I'm kind of tired, so I'm going home.","a":"I'm kind of tired, so I'm going home.","alt":["I'm kinda tired, so I'm going home."],"how":"i'm KAIN-duh TIRED, so i'm GOing HOME","why":"kind of → 'KAIN-duh': of loses its v."},{"say":"There were a lot of people at the concert.","a":"There were a lot of people at the concert.","alt":["There were a lotta people at the concert."],"how":"there wer uh LAH-duh PEOple at the CONcert","why":"a lot of → 'uh LAH-duh': flap T + weak of."},{"say":"We ran out of coffee, so I bought some more.","a":"We ran out of coffee, so I bought some more.","alt":["We ran outta coffee, so I bought some more."],"how":"we RAN OW-duh COFfee, so i BOUGHT some MORE","why":"out of → 'OW-duh': flap T + weak of."},{"say":"Tell them I'll call him back in ten minutes.","a":"Tell them I'll call him back in ten minutes.","how":"TELL-um i'll CALL-im BACK in TEN MINutes","why":"them → 'em; him loses its h: 'CALL-im'."},{"say":"It was sort of strange, so I asked her about it.","a":"It was sort of strange, so I asked her about it.","alt":["It was sorta strange, so I asked her about it."],"how":"it was SOR-duh STRANGE, so i ASK-ter uh-BOU-dit","why":"sort of → 'SOR-duh'; asked her → 'ASK-ter' (no h)."}],"tip":"In class: give pairs a short dialogue written with full forms (kind of, a lot of, tell them, ask her); they rehearse it in a relaxed style, perform it, and the class calls out which full words were hidden."},{"id":"b2-5","lv":"B2","n":5,"title":"eCOnomy, ecoNOmic, eCOnomist: word families","focus":"stress","goal":"Move the stress correctly inside word families like photograph, photographer and photographic.","explain":["In English word families, the stress often moves when you add an ending, and the vowels change with it. PHOtograph, phoTOgrapher, photoGRAphic: three words, three different stressed syllables. The stressed vowel is long and clear; most unstressed vowels become a weak 'uh' /ə/. So the first o in photographer is 'uh', but the second is a strong 'ah': 'fuh-TAH-gruh-fer'.","Some endings are good guides. With -ic, -ical, -ian and -ion, the stress goes on the syllable just before the ending: ecoNOmic, demoCRAtic, poLItical, poliTIcian. Words ending in -cracy, -nomy, -graphy and -ysis stress the third syllable from the end: deMOcracy, eCOnomy, phoTOgraphy, aNAlysis. Words with -er and -ist usually follow the -y word: eCOnomist, phoTOgrapher.","Watch one famous exception: POlitics is stressed on the first syllable (but poLItical, poliTIcian). The best strategy is to learn words in families and say them aloud as a chain, feeling the stress jump: ANalyze, aNAlysis, anaLYtical."],"spanish":"Spanish cognates pull the stress to the wrong place: democracia, economía and política lead to 'demoCRAcy', 'econoMY' and 'poLItics'. Learn the English pattern for each family and make the unstressed vowels weak: 'di-MAH-kruh-see', 'i-KAH-nuh-mee', 'PAH-luh-tiks'.","ex":[{"t":"photograph, photographer, photographic","how":"FOH-duh-graf | fuh-TAH-gruh-fer | foh-duh-GRAF-ik","note":"the stress moves three times"},{"t":"politics, political, politician","how":"PAH-luh-tiks | puh-LI-di-kul | pah-luh-TI-shun","note":"POlitics, not poLItics like Spanish 'política'"},{"t":"analyze, analysis, analytical","how":"AN-uh-lyze | uh-NAL-uh-sis | an-uh-LI-di-kul","note":"-ysis: third syllable from the end"},{"t":"democracy, democratic, democrat","how":"di-MAH-kruh-see | dem-uh-KRA-dik | DEM-uh-krat","note":"-cracy: third from the end; -ic: just before it"},{"t":"economy, economic, economist","how":"i-KAH-nuh-mee | ek-uh-NAH-mik | i-KAH-nuh-mist","note":"economic can also start with 'ee': 'ee-kuh-NAH-mik'"},{"t":"Our economist says the economy is strong.","how":"our i-KAH-nuh-mist SAYS the i-KAH-nuh-mee is STRONG","note":"economist follows economy"},{"t":"She's a photographer, not a politician.","how":"she's a fuh-TAH-gruh-fer, NOT a pah-luh-TI-shun","note":"-er follows photography; -ian stresses the syllable before it"},{"t":"The analysis shows the economic impact.","how":"the uh-NAL-uh-sis SHOWS the ek-uh-NAH-mik IMpact","note":"two different stress positions in one family"}],"listen":[{"q":"Which word do you hear?","o":["economist","economics"],"pick":true,"why":"eCOnomist vs ecoNOmics: the stress moves, and the vowels change with it."},{"q":"Which word do you hear?","o":["photography","photographic"],"pick":true,"why":"phoTOgraphy (oOoo) vs photoGRAphic (ooOo)."},{"q":"Which syllable is stressed?","say":"photographer","o":["PHO-to-gra-pher","pho-TO-gra-pher","pho-to-GRA-pher"],"a":1,"why":"phoTOgrapher, like phoTOgraphy: 'fuh-TAH-gruh-fer'."},{"q":"Which syllable is stressed?","say":"politics","o":["PO-li-tics","po-LI-tics","po-li-TICS"],"a":0,"why":"POlitics: first syllable, unlike Spanish 'política'."},{"q":"Which stress pattern do you hear?","say":"politician","o":["Oooo","oOoo","ooOo"],"a":2,"why":"po-li-TI-cian: the stress goes just before -ian."},{"q":"Which stress pattern do you hear?","say":"democracy","o":["Oooo","oOoo","ooOo"],"a":1,"why":"de-MO-cra-cy: -cracy stresses the third syllable from the end."},{"q":"Which syllable is stressed?","say":"analytical","o":["A-na-ly-ti-cal","a-NA-ly-ti-cal","a-na-LY-ti-cal"],"a":2,"why":"anaLYtical: the stress goes just before -ical."},{"q":"How many syllables does 'economist' have?","say":"He's a well-known economist.","o":["3","4","5"],"a":1,"why":"e-co-no-mist: four syllables, stress on the second ('i-KAH-nuh-mist')."}],"mark":[{"mode":"stress","q":"Tap the stressed syllable.","w":["pho","to","gra","pher"],"word":true,"a":[1],"why":"phoTOgrapher: 'fuh-TAH-gruh-fer'."},{"mode":"stress","q":"Tap the stressed syllable.","w":["de","mo","crat","ic"],"word":true,"a":[2],"why":"demoCRATic: stress just before -ic."},{"mode":"stress","q":"Tap the stressed syllable.","w":["po","li","ti","cian"],"word":true,"a":[2],"why":"poliTIcian: stress just before -ian."},{"mode":"find","q":"Tap the words stressed on the second syllable.","w":["economy","economic","economist","political","politics"],"a":[0,2,3],"why":"eCOnomy, eCOnomist, poLItical. But ecoNOmic (third) and POlitics (first)."},{"mode":"find","q":"Tap the words stressed on the first syllable.","w":["photograph","photographer","politics","democrat","democracy","analyze"],"a":[0,2,3,5],"why":"PHOtograph, POlitics, DEmocrat, ANalyze. But phoTOgrapher and deMOcracy (second)."}],"dict":[{"say":"The photographer took a photograph of the politician.","a":"The photographer took a photograph of the politician.","how":"the fuh-TAH-gruh-fer TOOK a FOH-duh-graf of the pah-luh-TI-shun","why":"Three stress positions: phoTOgrapher, PHOtograph, poliTIcian."},{"say":"Economists say the economy will grow next year.","a":"Economists say the economy will grow next year.","how":"i-KAH-nuh-mists SAY the i-KAH-nuh-mee will GROW NEKS-cheer","why":"eCOnomists and eCOnomy share the stress; next year → 'NEKS-cheer'."},{"say":"We need a careful analysis of the economic data.","a":"We need a careful analysis of the economic data.","how":"we NEED a CAREful uh-NAL-uh-sis of the ek-uh-NAH-mik DAY-duh","why":"aNAlysis (third from the end), ecoNOmic (just before -ic)."},{"say":"She hates politics, but her job is very political.","a":"She hates politics, but her job is very political.","how":"she HATES PAH-luh-tiks, but her JOB is VERy puh-LI-di-kul","why":"POlitics vs poLItical: the stress moves one syllable."},{"say":"Is the new system more democratic than the old one?","a":"Is the new system more democratic than the old one?","how":"is the NEW SYStem more dem-uh-KRA-dik than the OLD one?","why":"demoCRAtic: stress just before -ic, weak 'uh' in 'mo'."}],"tip":"In class: give groups cards with word families (photograph, photographer, photographic…); students clap the stressed syllable as they say each word, then make one sentence that uses two words from the same family."},{"id":"b2-6","lv":"B2","n":6,"title":"English is stress-timed","focus":"rhythm","goal":"Keep a steady beat on the stressed syllables and squeeze the weak syllables in between, so you sound fluent and hear weak words in fast speech.","explain":["English rhythm is built on beats. The beats are the stressed syllables of the important words: nouns, main verbs, adjectives, adverbs and negatives. The small grammar words and unstressed syllables between them are squeezed: said faster, shorter and often with a weak schwa, 'uh'. So CATS CHASE MICE, the CATS will CHASE the MICE and the CATS have been CHASing the MICE all have three beats and take roughly similar time.","This is called stress-timing. The beats are not as regular as a clock, but English stretches stressed syllables and compresses the rest much more than Spanish, which gives syllables a more even length. In Spanish, more syllables simply take longer. In English, more syllables between two beats mostly means you say them faster.","To practice, find the beats first and tap them on the table at a steady speed. Then fit the weak words in quickly on the way to the next beat: I'd LIKE a CUP of COFfee → aid-LIKE-uh-CUP-uv-KAW-fee. Don't slow down for 'have been' or 'for a': they are the quick notes between the beats. Feeling this rhythm also helps you hear the weak words when people speak fast."],"spanish":"Spanish speakers often give every syllable similar length and force ('the CATS HAVE BEEN CHA-SING THE MICE'), which sounds slow and heavy and makes weak words hard to catch in fast speech. Fix: tap the beats and rush the small words: thuh-CATS-uv-bin-CHAY-sing-thuh-MICE.","ex":[{"t":"One, two, three, four.","how":"ONE | TWO | THREE | FOUR","note":"4 beats, 4 syllables"},{"t":"One and two and three and four.","how":"ONE-n-TWO-n-THREE-n-FOUR","note":"the same 4 beats; and → 'n', squeezed in"},{"t":"One and a two and a three and a four.","how":"ONE-n-uh-TWO-n-uh-THREE-n-uh-FOUR","note":"still 4 beats: the extra syllables just go faster"},{"t":"Cats chase mice.","how":"CATS | CHASE | MICE","note":"3 beats, 3 syllables"},{"t":"The cats will chase the mice.","how":"thuh-CATS-ul-CHASE-thuh-MICE","note":"3 beats, 6 syllables: will → 'ul'"},{"t":"The cats have been chasing the mice.","how":"thuh-CATS-uv-bin-CHAY-sing-thuh-MICE","note":"3 beats, 8 syllables: rush 'have been' and '-ing the'"},{"t":"I'd like a cup of coffee.","how":"aid-LIKE-uh-CUP-uv-KAW-fee","note":"3 beats: LIKE, CUP, COF-"},{"t":"She's been working at the bank for a couple of years.","how":"sheez-bin-WER-king-ut-thuh-BANK | fer-uh-CUP-luv-YEERZ","note":"4 beats, 13 syllables"}],"listen":[{"q":"How many beats (stressed syllables) do you hear?","say":"The cats have been chasing the mice.","o":["3","5","8"],"a":0,"why":"CATS, CHAS-, MICE: 3 beats. The other 5 syllables are squeezed between them (8 syllables in total)."},{"q":"Which sentence do you hear?","o":["The cats chase the mice.","The cats will chase the mice.","The cats have chased the mice."],"pick":true,"why":"All three have the same beats: CATS, CHASE, MICE. Only the quick part changes: will → 'ul'; have chased → 'uv-CHAYST'."},{"q":"How many beats do you hear?","say":"I'd like a cup of coffee, please.","o":["3","4","8"],"a":1,"why":"LIKE, CUP, COF-, PLEASE: 4 beats. I'd, a, of and -fee are squeezed (8 syllables in total)."},{"q":"Which sentence do you hear?","o":["I want to go.","I wanted to go.","I want you to go."],"pick":true,"why":"All have 2 beats (WANT, GO); the squeezed part changes: ai-WAN-tuh-GO, ai-WAN-id-tuh-GO, ai-WAN-chuh-tuh-GO."},{"q":"Which sentence do you hear?","o":["We're at the office.","We were at the office."],"pick":true,"why":"One beat (OF-) in both. 'We were' squeezes in one extra quick syllable: wee-wer-ut-thee-OF-fis."},{"q":"How many beats do you hear?","say":"I'll meet you at the station.","o":["2","4","7"],"a":0,"why":"MEET and STA-: only 2 beats. I'll, you, at, the and -tion are squeezed (7 syllables in total)."},{"q":"Which do you hear?","o":["one, two, three","one and two and three","one and a two and a three"],"pick":true,"why":"All three have 3 beats (ONE, TWO, THREE); 'n' and 'n-uh' are squeezed between them."},{"q":"Where are the beats?","say":"The meeting is at the end of the month.","o":["MEET – END – MONTH","THE – IS – AT – OF","MEET – AT – END"],"a":0,"why":"thuh-MEE-ding-iz-ut-thee-END-uv-thuh-MONTH: the beats fall on the content words; is, at, the and of are squeezed."}],"mark":[{"mode":"stress","q":"Tap the beats (the stressed words).","w":["The","cats","have","been","chasing","the","mice."],"a":[1,4,6],"why":"the CATS have been CHASing the MICE: 3 beats; the other words are squeezed between them."},{"mode":"stress","q":"Tap the beats.","w":["One","and","a","two","and","a","three."],"a":[0,3,6],"why":"ONE-n-uh-TWO-n-uh-THREE: and a → 'n-uh', quick and weak."},{"mode":"stress","q":"Tap the beats (the stressed words).","w":["I","need","to","talk","to","the","manager."],"a":[1,3,6],"why":"ai-NEED-tuh-TAWK-tuh-thuh-MAN-uh-jer: 3 beats; I, to, to and the are squeezed."},{"mode":"weak","q":"Tap the weak words that get squeezed.","w":["Tom","was","waiting","for","an","hour."],"a":[1,3,4],"why":"TOM-wuz-WAY-ding-fer-uh-NOUR: was → 'wuz', for → 'fer', an → 'un', linked to hour."},{"mode":"weak","q":"Tap the weak words that get squeezed.","w":["The","cats","will","chase","the","mice."],"a":[0,2,4],"why":"thuh-CATS-ul-CHASE-thuh-MICE: the → 'thuh', will → 'ul'."}],"dict":[{"say":"I've been waiting for you for an hour.","a":"I've been waiting for you for an hour.","how":"aiv-bin-WAY-ding-fer-yuh-fer-uh-NOUR","why":"Only 2 beats (WAIT-, HOUR): been → 'bin', for → 'fer', you → 'yuh', an hour → 'uh-NOUR'."},{"say":"Can you send me the report by Friday?","a":"Can you send me the report by Friday?","how":"k'n-yuh-SEND-me-thuh-ri-PORT-by-FRY-day?","why":"3 beats (SEND, -PORT, FRI-): can → 'k'n', the → 'thuh', re- → 'ri'."},{"say":"What time does the train leave for the airport?","a":"What time does the train leave for the airport?","how":"wut-TIME-duz-thuh-TRAIN-LEEV-fer-thee-AIR-port?","why":"Beats on TIME, TRAIN, LEAVE, AIR-; does → 'duz', for → 'fer', the → 'thuh' or 'thee' are squeezed."},{"say":"I'd like to book a table for two, please.","a":"I'd like to book a table for two, please.","alt":["I would like to book a table for two, please."],"how":"aid-LIKE-tuh-BOOK-uh-TAY-bul-fer-TWO | PLEEZ","why":"Beats on LIKE, BOOK, TA-, TWO, PLEASE; to → 'tuh', a → 'uh', for → 'fer'."},{"say":"She's been working at the bank for a couple of years.","a":"She's been working at the bank for a couple of years.","alt":["She has been working at the bank for a couple of years."],"how":"sheez-bin-WER-king-ut-thuh-BANK | fer-uh-CUP-luv-YEERZ","why":"4 beats and 9 quick syllables: been → 'bin', at → 'ut', for a → 'fer-uh', couple of → 'CUP-luv'."}],"tip":"In class: the group taps a steady beat on the table and says CATS CHASE MICE, then the longer versions (the cats will chase the mice…) without slowing the tapping; then students build their own 3-beat sentences and add more weak words each round."},{"id":"b2-7","lv":"B2","n":7,"title":"Really? Showing surprise, doubt and enthusiasm","focus":"intonation","goal":"Use a wide pitch range to sound surprised or enthusiastic, and recognize when a flat or low voice means bored, doubtful or sarcastic.","explain":["In English, the range of your voice — how far it goes up and down — shows your attitude. A wide range, with a big jump on the main word, sounds interested, surprised or excited. A narrow range, a flat voice that hardly moves, sounds bored or tired. Listeners often react to the music more than to the words: a flat 'that's great' does not sound great at all.","Surprise and doubt: 'Really? ↗↗' with a big rise means 'Wow, tell me more!' 'Really. ↘' with a short, low fall sounds flat and not very interested. A voice that falls and then rises (Really? ↘↗) sounds doubtful: 'Are you sure?' Echo questions like 'You did WHAT?' jump very high to show shock.","Enthusiasm: 'That's GREAT!' starts high on GREAT and falls a long way. Said low, slow and flat, the same words sound bored or sarcastic, and they mean the opposite. Context helps listeners too: 'Great. Another meeting.' is clearly sarcastic. To sound enthusiastic in English, exaggerate more than feels natural."],"spanish":"Spanish speakers often use a narrower pitch range in English than listeners expect, so a sincere 'Really? That's great!' can sound bored or even sarcastic. Fix: jump high on the main word and let your voice rise or fall much further than feels natural; at first it will feel like acting.","ex":[{"t":"Really?","how":"REE-lee ↗↗","note":"big rise = surprised, interested"},{"t":"Really.","how":"REE-lee ↘","note":"short, low fall = flat, not very interested"},{"t":"Really? Are you sure?","how":"REE-lee ↘↗ | ar-yuh-SHUR ↗","note":"fall-rise = doubt"},{"t":"You did what?","how":"yuh-did-WHUT ↗↗","note":"echo question: a very high rise = shock"},{"t":"No way! You got the job?","how":"no-WAY ↘ | yuh-got-thuh-JAHB ↗↗","note":"high fall, then a big rise = excited surprise"},{"t":"That's great!","how":"thats-GREAT ↗↘","note":"jump up on GREAT, then a long fall = enthusiastic"},{"t":"Great. Another meeting.","how":"great ↘ | uh-NUH-ther-MEE-ding ↘","note":"low, slow and flat = sarcastic (try it yourself: the app's voice can't do sarcasm)"},{"t":"Wow, that's amazing! Congratulations!","how":"WOW ↘ | thats-uh-MAY-zing ↘ | kun-gra-chuh-LAY-shunz ↘","note":"every main word starts high = real enthusiasm"}],"listen":[{"q":"Which do you hear?","o":["Really?","Really."],"pick":true,"why":"Really? ↗ rises: surprised and interested. Really. ↘ falls: flat, not very interested."},{"q":"Which do you hear?","o":["Seriously?","Seriously."],"pick":true,"why":"Seriously? ↗ asks 'Are you serious?' (surprise). Seriously. ↘ states it: 'I mean it.'"},{"q":"Which do you hear?","o":["You got the job?","You got the job."],"pick":true,"why":"With a rise ↗ it's a surprised question ('Really? You did?'); with a fall ↘ it's a calm statement."},{"q":"How does the speaker feel?","say":"Oh, great. Another meeting at seven in the morning.","o":["excited","sarcastic","surprised"],"a":1,"why":"A meeting at 7 a.m. is bad news, so 'great' here means the opposite. Said low and flat, it's sarcasm."},{"q":"Which do you hear?","o":["Is that right?","That's right."],"pick":true,"why":"Is that right? ↗ = 'Oh, really?' (interest or doubt). That's right. ↘ = 'Yes, correct.'"},{"q":"How does the speaker feel?","say":"Wait, you're moving to Japan? Since when?","o":["surprised","bored","sarcastic"],"a":0,"why":"'Wait' and 'Since when?' show the news is a big surprise: wide range, big rise on jaPAN ↗↗."},{"q":"Which do you hear?","o":["You fixed it yourself?","You fixed it yourself."],"pick":true,"why":"The rise ↗ shows surprise or doubt ('Really? You?'); the fall ↘ just says what happened."},{"q":"How does the speaker feel?","say":"Well, I'm not so sure that's a good idea.","o":["doubtful","enthusiastic","bored"],"a":0,"why":"'Well' + 'not so sure' = doubt; the voice often falls and rises on SURE ↘↗."}],"mark":[{"mode":"stress","q":"Shock: tap the word where the voice jumps highest.","w":["You","did","what?"],"a":[2],"why":"You did WHAT? ↗↗ The echo word gets the big jump: 'I can't believe it, say that again!'"},{"mode":"stress","q":"Surprise: tap the word where the big rise is.","w":["You","sold","your","car?"],"a":[3],"why":"You sold your CAR? ↗↗ The rise starts on the last stressed word."},{"mode":"stress","q":"Enthusiasm: tap the two words where the voice jumps high.","w":["Wow,","that's","amazing!"],"a":[0,2],"why":"WOW ↘, that's aMAZing ↘: a high start and a long fall on each main word."},{"mode":"find","q":"Sarcasm: tap the word that, said low and flat, means the opposite.","w":["Oh,","great.","Another","meeting."],"a":[1],"why":"great ↘, low and flat = 'not great at all'; 'another meeting' confirms the sarcasm."},{"mode":"stress","q":"Doubt: tap the word where the voice falls and rises.","w":["Are","you","sure","about","that?"],"a":[2],"why":"Are you SURE ↘↗ about that? 'About that' is old information, so it stays low."}],"dict":[{"say":"Really? I had no idea you could sing!","a":"Really? I had no idea you could sing!","how":"REE-lee ↗↗ | ai-had-NO-ai-DEE-uh-yuh-k'd-SING ↘","why":"Surprise: a big rise on Really, then a high fall on SING; could → 'k'd'."},{"say":"Oh, great. Another meeting at seven in the morning.","a":"Oh, great. Another meeting at seven in the morning.","how":"oh-GREAT ↘ | uh-NUH-ther-MEE-ding-ut-SEV-uh-nin-thuh-MOR-ning ↘","why":"Sarcasm: low and flat; at → 'ut', seven in → 'SEV-uh-nin', the → 'thuh'."},{"say":"Wait, you quit your job? Since when?","a":"Wait, you quit your job? Since when?","how":"WAIT | yuh-KWIT-yer-JAHB ↗↗ | sins-WHEN ↘","why":"Surprise: a big rise on JOB, then a high fall on WHEN; your → 'yer'."},{"say":"That's fantastic news! Congratulations to both of you!","a":"That's fantastic news! Congratulations to both of you!","alt":["That is fantastic news! Congratulations to both of you!"],"how":"thats-fan-TAS-tik-NOOZ ↘ | kun-gra-chuh-LAY-shunz-tuh-BOHTH-uv-yuh ↘","why":"Enthusiasm: high jumps on fan-TAS-tic and BOTH; to → 'tuh', of → 'uv'."},{"say":"Are you sure about that? It sounds a bit strange.","a":"Are you sure about that? It sounds a bit strange.","how":"ar-yuh-SHUR ↘↗ uh-bout-that | it-SOUNDZ-uh-bit-STRAINJ ↘","why":"Doubt: fall-rise on SURE; are you → 'ar-yuh', a bit → 'uh-bit'."}],"tip":"In class: one student shares a piece of news (real or invented) and a partner answers 'Really?' twice, once excited and once bored; the group says which was which, and the partner must exaggerate until everyone agrees."},{"id":"b2-8","lv":"B2","n":8,"title":"REcord or reCORD? Same spelling, different word","focus":"stress","goal":"Stress two-syllable noun–verb pairs correctly: the first syllable for the noun or adjective, the second for the verb.","explain":["Some two-syllable words can be a noun (or adjective) or a verb with exactly the same spelling. The stress shows which one you mean: nouns and adjectives usually stress the first syllable, verbs the second. A REcord / to reCORD, an OBject / to obJECT, a PERmit / to perMIT, a CONtract / to conTRACT, PERfect (adjective) / to perFECT.","The vowels change too, because the unstressed syllable gets weak: REcord 'REK-erd' but reCORD 'ri-KORD'; OBject 'AHB-jekt' but obJECT 'ub-JEKT'; PROduce 'PROH-doos' (fruit and vegetables) but proDUCE 'pruh-DOOS'. DEsert 'DEZ-ert' is a dry place; deSERT 'dih-ZURT' means to abandon someone, and it sounds exactly like dessert.","Use the grammar to decide: after a, the, my or an adjective it's a noun (a parking PERmit, the new CONtract); after to, can, will or a subject it's a verb (They don't perMIT dogs; I obJECT). Not every pair changes: reSPECT, rePORT, conTROL and deSIGN keep the stress on the second syllable in both. UK note: the noun produce is 'PROD-yoos'."],"spanish":"Spanish speakers often carry over the stress of the Spanish word: contrato and objeto lead to 'a conTRACT' and 'an obJECT' for the nouns. Fix: decide first, noun or verb? Then stress the first syllable for the noun (CONtract, OBject) and the second for the verb (conTRACT, obJECT).","ex":[{"t":"She broke the world record.","how":"shee-BROKE-thuh-wurld-REK-erd","note":"noun: REcord"},{"t":"Can I record this call?","how":"k'n-ai-ri-KORD-this-KAWL?","note":"verb: reCORD"},{"t":"You need a permit.","how":"yuh-NEED-uh-PER-mit","note":"noun: PERmit"},{"t":"They don't permit dogs inside.","how":"thay-DOHNT-per-MIT-DAWGZ-in-SIDE","note":"verb: perMIT"},{"t":"What's that strange object?","how":"wuts-that-STRAINJ-AHB-jekt?","note":"noun: OBject"},{"t":"I object to that.","how":"ai-ub-JEKT-tuh-that","note":"verb: obJECT"},{"t":"The produce at this market is really fresh.","how":"thuh-PROH-doos-ut-this-MAR-kit-iz-REE-lee-FRESH","note":"noun: PROduce (fruit and vegetables)"},{"t":"They produce cars and trucks.","how":"thay-pruh-DOOS-KARZ-n-TRUKS","note":"verb: proDUCE"}],"listen":[{"q":"Which word do you hear?","o":["desert","dessert"],"pick":true,"why":"desert (a dry place) is DEZ-ert, stress first; dessert (sweet food) is dih-ZURT, stress second, like the verb to desert."},{"q":"Which stress do you hear on 'record'?","say":"We're going to record the interview.","o":["REcord","reCORD"],"a":1,"why":"After 'going to' it's a verb: ri-KORD."},{"q":"Which stress do you hear on 'record'?","say":"It's a new world record!","o":["REcord","reCORD"],"a":0,"why":"After 'a new world' it's a noun: REK-erd."},{"q":"Oo or oO? Listen to 'permit'.","say":"You need a permit to park here.","o":["Oo: PER-mit","oO: per-MIT"],"a":0,"why":"a permit = noun: PER-mit."},{"q":"Is 'object' a noun or a verb here?","say":"Does anyone object to the plan?","o":["noun: OB-ject","verb: ob-JECT"],"a":1,"why":"'Does anyone ___ to the plan' needs a verb: ub-JEKT."},{"q":"Which stress do you hear on 'contract'?","say":"Please read the contract carefully.","o":["CON-tract","con-TRACT"],"a":0,"why":"the contract = noun: KAHN-trakt."},{"q":"Oo or oO? Listen to 'present'.","say":"Who's going to present the results?","o":["Oo: PRE-sent","oO: pre-SENT"],"a":1,"why":"to present = verb: pri-ZENT. The noun (a birthday present) is PREZ-unt."},{"q":"Which sentence do you hear?","o":["They want to record it.","They want a record of it."],"pick":true,"why":"to reCORD (verb, ri-KORD) vs a REcord (noun, REK-erd): the stress and the small word before it tell you which."}],"mark":[{"mode":"stress","q":"Tap the stressed syllable (adjective: a perfect day).","w":["per","fect"],"word":true,"a":[0],"why":"PER-fect (adjective). The verb is per-FECT: to perfect your English."},{"mode":"stress","q":"Tap the stressed syllable (verb: they produced a report).","w":["pro","duced"],"word":true,"a":[1],"why":"pruh-DOOST: the verb stresses the second syllable in every form (produces, produced, producing)."},{"mode":"find","q":"Tap the two-syllable word stressed on its SECOND syllable.","w":["We","need","a","permit","to","record","here."],"a":[5],"why":"a PER-mit (noun), to ri-KORD (verb)."},{"mode":"find","q":"Tap the two-syllable word stressed on its FIRST syllable.","w":["They","object","to","the","new","contract."],"a":[5],"why":"they ub-JEKT (verb), the KAHN-trakt (noun)."},{"mode":"find","q":"Tap the word stressed on its SECOND syllable.","w":["Local","farms","produce","most","of","our","produce."],"a":[2],"why":"farms pruh-DOOS (verb); our PROH-doos (noun); LO-cal is stressed first."}],"dict":[{"say":"They want to record a new album next year.","a":"They want to record a new album next year.","how":"thay-WAN-tuh-ri-KORD-uh-noo-AL-bum-nekst-YEER","why":"to reCORD = verb: ri-KORD; want to → 'WAN-tuh' or 'wanna'."},{"say":"You need a permit to work in this country.","a":"You need a permit to work in this country.","how":"yuh-NEED-uh-PER-mit-tuh-WURK-in-this-KUN-tree","why":"a PERmit = noun: PER-mit."},{"say":"Does anyone object to the new contract?","a":"Does anyone object to the new contract?","how":"duz-EN-ee-wun-ub-JEKT-tuh-thuh-noo-KAHN-trakt?","why":"obJECT (verb) and CONtract (noun): opposite patterns in one sentence."},{"say":"Most of the country is hot, dry desert.","a":"Most of the country is hot, dry desert.","how":"MOHST-uv-thuh-KUN-tree-iz-HOT | DRY-DEZ-ert","why":"DEsert = noun: DEZ-ert. Don't confuse it with dessert (dih-ZURT)."},{"say":"Who's going to conduct the interviews tomorrow?","a":"Who's going to conduct the interviews tomorrow?","alt":["Who is going to conduct the interviews tomorrow?"],"how":"hooz-GUH-nuh-kun-DUKT-thee-IN-ter-vyooz-tuh-MAR-oh?","why":"to conDUCT = verb: kun-DUKT. The noun (a code of CONduct) is KAHN-dukt."}],"tip":"In class: give pairs cards with sentences that use one word as a noun or a verb (You need a PERmit / They don't perMIT it); one student reads, the partner holds up N or V from the stress alone, then they swap."},{"id":"b2-9","lv":"B2","n":9,"title":"Jeet yet? Decoding fast conversation","focus":"reduction","goal":"Understand very fast everyday questions and answers in which several words melt together, like 'Jeet yet?', 'Whatcha doin'?' and 'I dunno'.","explain":["In fast, relaxed conversation, small words almost disappear and the sounds around them melt together. Did you eat yet? becomes 'Jeet yet?': did you shrinks to 'dj' (d + y = j) and joins eat. What are you doing? becomes 'Whatcha doin'?': are disappears, t + you becomes 'cha', and -ing becomes 'in'.","Other common ones: I don't know → 'I dunno', Let me see → 'Lemme see', Give me → 'Gimme', Do you want to → 'D'you wanna'. Careful: 'whatcha' can also be what do you ('Whatcha want?') or what have you ('Whatcha got?'); the next word tells you which. You don't need to speak like this, but you do need to understand it.","How to decode: catch the stressed words first, because they stay clear (EAT, YET, DO-, KNOW, SEE), and then rebuild the grammar around them. 'Jeet' + yet is a question about eating, so it must be Did you eat yet? You'll hear these forms with friends, on the phone and in series; don't write them in emails or reports. UK note: British English prefers Have you eaten yet? here."],"spanish":"Spanish speakers often listen word by word, waiting for a clear 'did' and 'you', so 'Jeet yet?' sounds like an unknown word. Fix: listen for the stressed words (eat, yet) and then add the small words that the grammar needs: Did you eat yet?","ex":[{"t":"Did you eat yet?","how":"JEET-YET?","note":"did you + eat → 'jeet'"},{"t":"No, did you?","how":"NO | DID-juh? (very fast: 'No, jew?')","note":"did you → 'didja'"},{"t":"What are you doing?","how":"whut-chuh-DOO-in?","note":"'Whatcha doin'?': are disappears; -ing → 'in'"},{"t":"I don't know.","how":"ai-duh-NO","note":"'I dunno': the t goes and the two n's become one"},{"t":"Let me see.","how":"lem-mee-SEE","note":"'Lemme see': the t disappears into the m"},{"t":"Give me a minute.","how":"gim-mee-uh-MIN-it","note":"'Gimme': the v disappears"},{"t":"Do you want to get something to eat?","how":"d'yuh-WAN-uh-GET-sum-thin-tuh-EAT?","note":"do you → 'd'yuh'; want to → 'wanna'; something → 'sumthin''"},{"t":"I don't know, let me check and get back to you.","how":"ai-duh-NO | lem-mee-CHECK-n-get-BACK-tuh-yuh","note":"dunno + lemme + and → 'n'"}],"listen":[{"q":"Which question do you hear?","o":["Did you eat yet?","Did you get it?"],"pick":true,"why":"'Jeet yet?' (did you eat yet) vs 'Didja GED-it?' (did you get it): listen for EAT or GET."},{"q":"Which question do you hear?","o":["What are you doing?","What were you doing?","What did you do?"],"pick":true,"why":"'Whatcha doin'?' (now) vs 'Whut-wer-yuh doin'?' (past) vs 'Whaddja DO?' (did you do)."},{"q":"Which do you hear?","o":["I don't know.","I didn't know."],"pick":true,"why":"'I dunno' (now) vs 'I DID-n know' (past): listen for the extra syllable 'did-n'."},{"q":"Which do you hear?","o":["Let me see.","Let's see."],"pick":true,"why":"'Lemme see' has two syllables before SEE (lem-mee); 'Let's see' has only one (lets)."},{"q":"Which do you hear?","o":["Give me a minute.","Give him a minute."],"pick":true,"why":"'Gimme a minute' vs 'Giv-im a minute': me → 'mee', him → 'im' (the h disappears)."},{"q":"Which fast version matches what you hear?","say":"What are you doing tonight?","o":["Whatcha doin' tonight?","Whaddja do tonight?","Whatcha wanna do tonight?"],"a":0,"why":"What are you → 'whatcha', doing → 'doin''. Whaddja = what did you; whatcha wanna = what do you want to."},{"q":"Which fast version matches what you hear?","say":"Give me a second, let me see.","o":["Gimme a second, lemme see.","Give 'im a second, lemme see.","Gimme a second, let's see."],"a":0,"why":"give me → 'gimme', let me → 'lemme'."},{"q":"'Jeet yet?' How many words is that?","say":"Did you eat yet?","o":["2","3","4"],"a":2,"why":"Did + you + eat + yet = 4 words, squeezed into 2 syllables: 'Jeet yet?'."}],"mark":[{"mode":"link","q":"Tap where the words melt into one syllable.","w":["Did","you","eat","yet?"],"a":[0,1],"why":"did_you_eat → 'jeet', one syllable; yet stays separate and clear."},{"mode":"weak","q":"Tap the word that disappears completely.","w":["What","are","you","doing?"],"a":[1],"why":"'Whatcha doin'?': are has no sound at all; you joins the t to make 'cha'."},{"mode":"link","q":"Tap where two words melt into one.","w":["Let","me","see."],"a":[0],"why":"let_me → 'lemme': the t disappears. See stays clear and stressed."},{"mode":"stress","q":"Tap the word with the main stress.","w":["I","don't","know."],"a":[2],"why":"'I duh-NO': know keeps the stress; don't shrinks to 'duh'."},{"mode":"find","q":"Tap the words that make 'whatcha'.","w":["What","are","you","doing","tonight?"],"a":[0,1,2],"why":"What + are + you → 'whatcha'; doing → 'doin''; tonight stays clear."}],"dict":[{"say":"Did you eat yet? I'm starving.","a":"Did you eat yet? I'm starving.","how":"JEET-YET? | aim-STAR-vin","why":"did you + eat melt into 'jeet'; -ing → 'in'."},{"say":"What are you doing this weekend?","a":"What are you doing this weekend?","how":"whut-chuh-DOO-in-this-WEEK-end?","why":"what are you → 'whatcha'; doing → 'doin''."},{"say":"I don't know, let me check my calendar.","a":"I don't know, let me check my calendar.","how":"ai-duh-NO | lem-mee-CHECK-my-KAL-un-der","why":"I don't know → 'I dunno'; let me → 'lemme'."},{"say":"Give me a minute, I'm almost ready.","a":"Give me a minute, I'm almost ready.","how":"gim-mee-uh-MIN-it | aim-AWL-mohst-RED-ee","why":"give me → 'gimme'; I'm → 'aim'."},{"say":"Do you want to grab something to eat after work?","a":"Do you want to grab something to eat after work?","how":"d'yuh-WAN-uh-GRAB-sum-thin-tuh-EAT-af-ter-WURK?","why":"do you → 'd'yuh', want to → 'wanna', something → 'sumthin'', to → 'tuh'."}],"tip":"In class: write fast forms on the board ('Jeet yet?', 'Whatcha doin'?', 'Gimme a sec', 'I dunno') and pairs race to write the full sentences; then each pair performs a four-line dialogue using them and the class writes down what they really said."},{"id":"c1-1","lv":"C1","n":1,"title":"New or known? Where the main stress goes","focus":"rhythm","goal":"Put the main stress on new information and keep known information low, so listeners hear at once what matters.","explain":["Every phrase in English has one main stress, the nucleus: the syllable where the voice moves most clearly, up or down. In a neutral sentence it falls on the last content word: I bought a new CAR. In this unit, the CAPITALS in the sounds-like lines show only that main stress.","But speakers move the main stress to the new information and de-accent what is already known: they say it lower and flatter, even when it is an important noun. 'I bought a car.' 'What kind of car?' 'A RED car.' Car has just been mentioned, so the stress moves back to red. 'A red CAR' here sounds strange, as if car were news.","Known information can come from the conversation or from the situation. If your friend is wearing a jacket you haven't seen, you ask 'Is that a NEW jacket?' Pronouns and words like one and there also stand for known things, so they stay unstressed: I've got a BIKE, but I never RIDE it. My laptop died, so I bought a NEW one.","This works in both directions. When you speak, ask yourself what is new for your listener and stress that. When you listen, the main stress tells you what the other person thinks is new or important."],"spanish":"Spanish usually shows new information with word order (Lo llamó María) and keeps the main stress near the end, so Spanish speakers tend to stress the last word every time: 'a red CAR', 'I don't drink TEA'. In English, keep the word order and move the stress: find the new word, stress it, and say repeated words low and flat.","ex":[{"t":"I bought a new car.","how":"I bought a new CAR.","note":"neutral: the main stress on the last content word"},{"t":"What kind of car? A red car.","how":"what KIND of car? | a RED car.","note":"car is known now, so it stays low"},{"t":"I've got a bike, but I never ride it.","how":"I've got a BIKE, | but I never RIDE_it.","note":"it = the bike: known, so unstressed"},{"t":"I dropped my phone, so I bought a new one.","how":"I dropped my PHONE, | so I bought a NEW one.","note":"one replaces phone and stays weak"},{"t":"Would you like some tea? Sorry, I don't drink tea.","how":"would you like some TEA? | sorry, I don't DRINK tea.","note":"tea is repeated, so the stress moves to drink"},{"t":"Is that your car? No, it's my sister's car.","how":"is that your CAR? | no, it's my SIS-ter's car.","note":"car is known; the owner is new"},{"t":"Is that a new jacket? I love it.","how":"is that a NEW jacket? | I LOVE_it!","note":"you can see the jacket, so it is known from the situation"},{"t":"Is the meeting on Monday morning? No, Monday afternoon.","how":"is the meeting on Monday MOR-ning? | no, Monday af-ter-NOON.","note":"Monday is known; only the part of the day is new"}],"listen":[{"q":"Listen to the question. Which answer has the main stress in the right place?","say":"What kind of car did you buy?","o":["A RED car.","A red CAR."],"a":0,"why":"Car is already in the question, so it stays low; the new word, red, gets the stress."},{"q":"Listen to the offer. Which reply sounds natural?","say":"Would you like some tea?","o":["Sorry, I don't drink TEA.","Sorry, I don't DRINK tea."],"a":1,"why":"Tea has just been said, so it is de-accented; the new point is that you don't drink it."},{"q":"Listen to the question. Which correction sounds natural?","say":"Is the meeting on Monday morning?","o":["No, on MON-day afternoon.","No, on Monday af-ter-NOON."],"a":1,"why":"Monday is known; only the part of the day is new, so the stress goes on af-ter-NOON."},{"q":"Listen to the question. Which answer has the main stress in the right place?","say":"Who sent you that email?","o":["My BOSS sent it.","My boss SENT it.","My boss sent IT."],"a":0,"why":"The sending and the email are in the question; only the person is new."},{"q":"Listen to the question. Which answer sounds natural?","say":"Is that your car?","o":["No, it's my SIS-ter's car.","No, it's my sister's CAR."],"a":0,"why":"Car is known; the new information is whose car it is."},{"q":"Listen. Which word in the second part is known information?","say":"My laptop is really slow, so I'm getting a new one.","o":["getting","new","one"],"a":2,"why":"One stands for the laptop, which is known, so it stays weak: I'm getting a NEW one."},{"q":"Listen. Which word should carry the main stress in the reply?","say":"I need a pen. There's one on my desk.","o":["There's","one","desk"],"a":2,"why":"One replaces pen (known), so it stays weak; on my DESK is the new information."},{"q":"Listen to the question. Everything in the answer is new: where does the main stress go?","say":"What did you do on the weekend?","o":["I PAINT-ed my apartment.","I painted my a-PART-ment."],"a":1,"why":"When the whole answer is new, the main stress goes on the last content word: a-PART-ment."}],"mark":[{"mode":"stress","q":"Tap the two main stresses: one in each part.","w":["I've","got","a","bike,","but","I","never","ride","it."],"a":[3,7],"why":"I've got a BIKE, but I never RIDE it: bike is new in part one; in part two it is known, so the stress moves to ride."},{"mode":"stress","q":"Context: 'Do you like jazz?' Tap the main stress in the reply.","w":["I","love","jazz."],"a":[1],"why":"Jazz is known from the question, so the stress goes on the new word: I LOVE jazz."},{"mode":"stress","q":"Context: you're wearing new shoes and your friend is looking at them. Tap the main stress in your question.","w":["Do","you","like","them?"],"a":[2],"why":"Them = the shoes, known from the situation, so it stays weak: Do you LIKE them?"},{"mode":"find","q":"Context: 'I love this song.' Tap the two words in the reply that repeat known information.","w":["Really?","I","can't","stand","this","song."],"a":[4,5],"why":"This song is repeated, so it is de-accented: Really? I can't STAND this song."},{"mode":"stress","q":"Context: 'Who's going to drive?' Tap the main stress in the answer.","w":["Carlos","is","going","to","drive."],"a":[0],"why":"Everything except the name repeats the question, so only CAR-los is stressed."}],"dict":[{"say":"I've got a bike, but to be honest, I never ride it.","a":"I've got a bike, but to be honest, I never ride it.","how":"I've got a BIKE, | but to be HON-est, | I never RIDE_it.","why":"Bike is new; in the last part it is known, so the main stress moves to ride."},{"say":"We asked for a quiet room, but they gave us a noisy one.","a":"We asked for a quiet room, but they gave us a noisy one.","how":"we asked for a quiet ROOM, | but they gave us a NOI-sy one.","why":"In the second part room is known, so one stays weak and the stress goes on noisy."},{"say":"Would you like some coffee? No thanks, I don't really drink coffee.","a":"Would you like some coffee? No thanks, I don't really drink coffee.","how":"would you like some COF-fee? | no THANKS, | I don't really DRINK coffee.","why":"Coffee is repeated, so it is de-accented; drink carries the main stress."},{"say":"Who's going to present the results? I think Laura is going to do it.","a":"Who's going to present the results? I think Laura is going to do it.","alt":["Who is going to present the results? I think Laura is going to do it."],"how":"who's gonna present the re-SULTS? | I think LAU-ra's gonna do_it.","why":"Only the name is new; going to do it repeats the question, so it stays low and fast."},{"say":"Is the meeting on Monday morning? No, on Monday afternoon at three.","a":"Is the meeting on Monday morning? No, on Monday afternoon at three.","alt":["Is the meeting on Monday morning? No, on Monday afternoon at 3."],"how":"is the meeting on Monday MOR-ning? | no, on Monday af-ter-NOON | at THREE.","why":"Monday is known, so it stays low the second time; afternoon and three are new."}],"tip":"In class: one student makes a statement (I bought a car), the next asks a question about it (What kind of car?), and the first answers stressing only the new word (A RED car). Keep the chain going around the room."},{"id":"c1-2","lv":"C1","n":2,"title":"Well, it's good… The fall-rise","focus":"intonation","goal":"Use a fall-rise ↘↗ to agree only partly, disagree politely or hint at an unspoken 'but', and notice it when other people use it.","explain":["A fall-rise ↘↗ is a fall on the key word followed by a rise at the end of the phrase. A plain fall ↘ sounds complete and certain; a fall-rise sounds unfinished, as if the speaker were saying 'there's more, but I won't say it'. Compare 'The food was GOOD ↘' (it was good, full stop) with 'The food was GOOD ↘↗…' (…but something else wasn't).","It is the tune of reservations and partial agreement: 'I LIKE him ↘↗…' (but I don't trust him), 'That's TRUE ↘↗, but…', 'In THEory ↘↗…'. Short answers can carry it too: 'MOSTly ↘↗', 'SOMEtimes ↘↗', 'In a WAY ↘↗'. Listeners hear the 'but' even when you don't say it.","It is also a polite way to disagree or correct someone. If a colleague says the new design is fantastic, 'Well, it's not BAD ↘↗' disagrees gently. 'ACtually ↘↗, the meeting's on Thursday' corrects without sounding rude, while a sharp fall on actually can sound much more direct.","Where does the movement happen? The fall starts on the stressed syllable of the key word, and the rise comes at the very end: in 'I LIKE him', the fall is on like and the rise on him. Don't confuse it with a simple rise ↗, which sounds more like a question."],"spanish":"Spanish speakers often keep a flat or simply falling tone and add the reservation with words (more or less, but…). In English a falling 'It was good ↘' sounds like full praise. Let the tune say it: a clear fall on the key word, a rise at the very end, and then stop.","ex":[{"t":"The food was good…","how":"the food was GOOD ↘↗…","note":"…but the service wasn't"},{"t":"I like him…","how":"I LIKE him ↘↗…","note":"…but I don't trust him"},{"t":"That's true, but it's not the whole story.","how":"that's TRUE ↘↗ | but it's not the WHOLE story ↘","note":"partial agreement, then a final fall"},{"t":"Do you enjoy your job? Mostly.","how":"do you enjoy your JOB ↗? | MOST-ly ↘↗","note":"= but not always"},{"t":"Is it a good plan? In theory.","how":"is it a good PLAN ↗? | in THE-o-ry ↘↗","note":"= but in practice, maybe not"},{"t":"Well, it's not bad, but I've had better.","how":"well, it's not BAD ↘↗ | but I've had BET-ter ↘","note":"cautious, polite praise"},{"t":"Actually, the meeting is on Thursday.","how":"AK-chuh-lee ↘↗ | the meeting is on THURS-day ↘","note":"a soft, polite correction"}],"listen":[{"q":"Listen. What is the speaker suggesting?","say":"How was the hotel? Well, the location was great.","o":["Everything about the hotel was great.","Other things about the hotel weren't so great."],"a":1,"why":"Praising only one thing, with a fall-rise, hints at a 'but': the rest wasn't as good."},{"q":"Listen. In 'I like him', where does the fall of the fall-rise start?","say":"I like him, but I wouldn't lend him money.","o":["on I","on like","on him"],"a":1,"why":"I LIKE him ↘↗: the fall starts on like, and the voice rises again on him."},{"q":"Listen. Which tune fits 'In theory' best?","say":"Do you agree with the plan? In theory, yes.","o":["↘ a fall: complete agreement","↘↗ a fall-rise: agreement with a hidden 'but'","↗ a rise: a question"],"a":1,"why":"In theory suggests 'but in practice, maybe not', so it takes a fall-rise: in THEory ↘↗."},{"q":"Listen. Which tune fits the reply best?","say":"Did you enjoy the course? Yes, I loved every minute of it.","o":["↘ a fall: a complete, positive answer","↘↗ a fall-rise: a polite 'but…'"],"a":0,"why":"Nothing is left unsaid, so the voice simply falls at the end. A fall-rise here would sound strange."},{"q":"Listen. What does the reply probably hide?","say":"Is she a good manager? Well, she's very organized.","o":["Nothing: she's an excellent manager.","Some doubts about other parts of her job."],"a":1,"why":"Well plus a single positive point, said with a fall-rise (she's very OR-ga-nized ↘↗), hints at a 'but'."},{"q":"Listen. What is the speaker not saying?","say":"Can you work this Saturday? I can work in the morning.","o":["I can work all day.","I can't work in the afternoon.","I can't work at all."],"a":1,"why":"With a fall-rise on MOR-ning, the speaker hints that the afternoon is a problem."},{"q":"Listen. What does 'Well, it's not bad' mean here?","say":"The new design is fantastic, isn't it? Well, it's not bad.","o":["It's fantastic.","It's OK, but I'm not very impressed.","It's terrible."],"a":1,"why":"It's not BAD ↘↗ is polite, partial praise: the speaker doesn't quite agree."},{"q":"Listen to the suggestion. Which reply is a polite way to disagree?","say":"We should cancel the whole project.","o":["Absolutely ↘","Good idea ↘","Well, POS-si-bly ↘↗…"],"a":2,"why":"Well, POSsibly ↘↗ agrees only on the surface; the fall-rise says 'but I don't think so'."}],"mark":[{"mode":"stress","q":"The speaker means '…but I don't trust him'. Tap the word where the fall-rise starts.","w":["I","like","him…"],"a":[1],"why":"I LIKE him ↘↗: him is a pronoun, so the fall starts on like and the rise comes on him."},{"mode":"stress","q":"The speaker thinks it's OK but not great. Tap the word where the fall-rise starts.","w":["It's","not","bad…"],"a":[2],"why":"It's not BAD ↘↗: the fall starts on bad and the voice rises at the end."},{"mode":"stress","q":"Tap the word that carries the fall-rise ↘↗ (partial agreement).","w":["That's","true,","but","it's","really","expensive."],"a":[1],"why":"That's TRUE ↘↗ agrees only partly; then the voice falls on ex-PEN-sive ↘."},{"mode":"stress","q":"Context: 'Can you work this weekend?' The speaker hints that Sunday is impossible. Tap the word where the fall-rise starts.","w":["I","can","work","on","Saturday…"],"a":[4],"why":"I can work on SAT-ur-day ↘↗: the hidden message is 'but not on Sunday'."},{"mode":"find","q":"Someone asks 'Do you enjoy your job?' Tap the replies that hint at a 'but' and would usually take a fall-rise ↘↗.","w":["Mostly.","Absolutely!","In a way.","Of course!","Sometimes."],"a":[0,2,4],"why":"MOSTly ↘↗, in a WAY ↘↗ and SOMEtimes ↘↗ mean 'yes, but…'. Absolutely! and Of course! are complete yeses with a fall ↘."}],"dict":[{"say":"The food was really good, but the service was incredibly slow.","a":"The food was really good, but the service was incredibly slow.","how":"the food was really GOOD ↘↗ | but the SER-vice was in-CRED-i-bly SLOW ↘","why":"A fall-rise on good opens the door to 'but'; the final fall closes the sentence."},{"say":"I like the idea in theory, but I'm not sure it'll work in practice.","a":"I like the idea in theory, but I'm not sure it'll work in practice.","how":"I like the i-DEE-uh in THE-o-ry ↘↗ | but I'm not sure it'll work in PRAC-tice ↘","why":"In theory takes the fall-rise and in practice the final fall; it'll sounds like 'ID-ul'."},{"say":"Well, it's not a bad price, but I've seen it cheaper online.","a":"Well, it's not a bad price, but I've seen it cheaper online.","alt":["Well, it is not a bad price, but I have seen it cheaper online."],"how":"well, it's not a BAD price ↘↗ | but I've seen_it CHEAP-er online ↘","why":"Not BAD ↘↗ is cautious praise; the but-part explains the reservation."},{"say":"Usually I'm happy to help, but this week I'm really busy.","a":"Usually I'm happy to help, but this week I'm really busy.","how":"YOO-zhuh-lee I'm happy to help ↘↗ | but THIS week I'm really BIZ-ee ↘","why":"The fall-rise on usually sets up the contrast with this week."},{"say":"Actually, I think the deadline is Friday, not Thursday.","a":"Actually, I think the deadline is Friday, not Thursday.","how":"AK-chuh-lee ↘↗ | I think the deadline is FRI-day ↘ | not THURS-day","why":"A fall-rise on actually softens the correction; Friday gets the main fall."}],"tip":"In class: ask quick personal questions (Do you like your job? Is your neighborhood quiet?); students answer with a short phrase and a fall-rise (MOSTly ↘↗, in the DAYtime ↘↗), and the class guesses the hidden 'but'."},{"id":"c1-3","lv":"C1","n":3,"title":"Prob'ly, int'resting: vowels that vanish","focus":"reduction","goal":"Recognize and use the shorter everyday forms of words like probably, interesting, comfortable and family, where a weak vowel disappears.","explain":["In natural speech, a weak vowel (usually a schwa, 'uh') just after the stressed syllable often disappears, and the word loses a syllable. It happens most often before r, l or n (camera → 'KAM-ruh', family → 'FAM-lee', different → 'DIF-rent', interesting → 'IN-tres-ting'), but not only there: probably → 'PRAH-blee'. The stress stays where it was, on the first syllable.","Some short forms are simply the normal American pronunciation: every is 'EV-ree', chocolate 'CHAWK-lit', vegetable 'VEJ-tuh-bul' and comfortable 'KUMF-ter-bul' (not com-for-ta-ble). Others, like family, camera, different and interesting, can be said in full when people speak slowly, but in conversation you will usually hear the short version.","The same thing happens in many other words: favorite ('FAY-vrit'), several ('SEV-rul'), evening ('EEV-ning'), restaurant ('REST-rahnt'). Before the stress, a weak vowel can vanish too in quick speech: suppose → 's'pose', police → 'p'lice', tonight → 't'night'. So when you listen, expect a three-syllable word to reach your ear as two.","UK note: in words ending in -ary and -ory, British speakers often drop a vowel that Americans keep: secretary is 'SEK-ruh-tree' in London but 'SEK-ruh-tair-ee' in New York. Use the short forms when you speak; they sound natural, not lazy. But always write the full word."],"spanish":"Spanish pronounces every vowel clearly, so Spanish speakers say all the syllables (fa-mi-ly, ve-ge-ta-ble) and often stress the Spanish way: confortable → com-for-TA-ble, interesante → in-ter-EST-ing. Put the stress on the first syllable and let the weak vowel after it disappear: KUMF-ter-bul, IN-tres-ting, VEJ-tuh-bul.","ex":[{"t":"It's probably going to rain.","how":"it's PRAH-blee gonna RAIN","note":"probably: 3 syllables → 2"},{"t":"That's a really interesting idea.","how":"that's a really IN-tres-ting i-DEE-uh","note":"interesting: 4 → 3, stress on IN"},{"t":"This sofa is so comfortable.","how":"this SO-fuh is so KUMF-ter-bul","note":"not com-for-TA-ble"},{"t":"My family lives in the south.","how":"my FAM-lee lives in the SOUTH","note":"family: 3 → 2"},{"t":"We need a different camera for this.","how":"we need a DIF-rent KAM-ruh for this","note":"two words, two vowels gone"},{"t":"I eat chocolate every day.","how":"I eat CHAWK-lit EV-ree DAY","note":"chocolate and every: two syllables each"},{"t":"We grow our own vegetables.","how":"we grow_our own VEJ-tuh-bulz","note":"vegetable: 4 → 3"},{"t":"What's your favorite restaurant around here?","how":"what's your FAY-vrit REST-rahnt_a-round HERE?","note":"favorite and restaurant lose a vowel too"}],"listen":[{"q":"Listen. In natural American speech, how many syllables does this word have?","say":"every","o":["1","2","3"],"a":1,"why":"EV-ree: the middle e disappears. Three syllables (ev-er-y) sounds like reading the spelling."},{"q":"Listen. In natural American speech, how many syllables does this word have?","say":"vegetable","o":["2","3","4"],"a":1,"why":"VEJ-tuh-bul: the e after g disappears."},{"q":"Listen. Which is the usual American pronunciation of this word?","say":"comfortable","o":["kum-for-TAY-bul","KUMF-ter-bul","kum-FOR-tuh-bul"],"a":1,"why":"The stress is on the first syllable, and com-for- collapses into 'KUMF': KUMF-ter-bul."},{"q":"Listen. In fast speech, which vowel disappears in this word?","say":"camera","o":["the a in cam-","the e in the middle","the a at the end"],"a":1,"why":"KAM-ruh: the e between m and r goes; the final a stays as a weak 'uh'."},{"q":"In fast speech these two can sound very close. Which word do you hear?","o":["police","please"],"pick":true,"why":"Police is 'puh-LEES': a tiny weak vowel, stress on the second syllable and a final s. Please is one syllable ending in a z sound."},{"q":"Which sentence do you hear?","o":["She's probably right.","She's possibly right."],"pick":true,"why":"Probably → 'PRAH-blee', with pr and b; possibly → 'PAH-suh-blee', with p and s."},{"q":"Listen. Which two words usually lose a syllable in relaxed speech?","say":"It was an interesting talk, but it was probably too long.","o":["interesting, probably","talk, long","interesting, talk"],"a":0,"why":"IN-tres-ting (4 → 3) and PRAH-blee (3 → 2). Talk and long have only one syllable."},{"q":"Listen. In fast speech, how many syllables do family and different have?","say":"My family is quite different from yours.","o":["2 and 2","3 and 3","2 and 3"],"a":0,"why":"FAM-lee and DIF-rent: both lose their middle vowel."}],"mark":[{"mode":"stress","word":true,"q":"Tap the stressed syllable.","w":["in","ter","est","ing"],"a":[0],"why":"IN-tres-ting: the stress is on the first syllable (not in-ter-EST-ing), and the e after it often disappears."},{"mode":"find","word":true,"q":"Tap the syllable that disappears in fast speech.","w":["fam","i","ly"],"a":[1],"why":"FAM-lee: the i between m and l goes, so the word has two syllables."},{"mode":"find","word":true,"q":"Tap the syllable that disappears.","w":["choc","o","late"],"a":[1],"why":"CHAWK-lit: the middle o goes, and -late sounds like 'lit'."},{"mode":"find","q":"Tap the words that usually have fewer syllables than their spelling suggests.","w":["Every","family","needs","a","comfortable","sofa."],"a":[0,1,4],"why":"EV-ree, FAM-lee, KUMF-ter-bul. Needs and sofa keep all their syllables."},{"mode":"find","q":"Tap the words that lose a syllable in relaxed speech.","w":["We","probably","need","different","vegetables","for","dinner."],"a":[1,3,4],"why":"PRAH-blee, DIF-rent, VEJ-tuh-bulz. Dinner keeps both its syllables."}],"dict":[{"say":"We'll probably have chocolate cake and coffee after dinner.","a":"We'll probably have chocolate cake and coffee after dinner.","how":"we'll PRAH-blee have CHAWK-lit CAKE_and COF-fee_af-ter DIN-ner","why":"Probably → 'PRAH-blee' and chocolate → 'CHAWK-lit': each loses a syllable."},{"say":"That was an interesting talk, but it was very different from last year.","a":"That was an interesting talk, but it was very different from last year.","how":"that was_an IN-tres-ting TALK, but_it was very DIF-rent from last YEAR","why":"Interesting 4 → 3 syllables, different 3 → 2."},{"say":"Is this chair comfortable enough, or do you want a different one?","a":"Is this chair comfortable enough, or do you want a different one?","how":"is this chair KUMF-ter-bul_e-NUF, or do you want a DIF-rent one?","why":"Comfortable → 'KUMF-ter-bul' and different → 'DIF-rent'."},{"say":"Every evening my family sits down together and talks about the day.","a":"Every evening my family sits down together and talks about the day.","how":"EV-ree EEV-ning my FAM-lee sits DOWN to-GETH-er_and TALKS_a-bout the DAY","why":"Every and evening always have two syllables; family usually does too."},{"say":"Don't forget the camera, because we'll probably want some photos.","a":"Don't forget the camera, because we'll probably want some photos.","how":"don't for-GET the KAM-ruh, b'cuz we'll PRAH-blee want some PHO-tos","why":"Camera → 'KAM-ruh', probably → 'PRAH-blee', and because loses its first vowel: 'b'cuz'."}],"tip":"In class: write probably, family, camera, comfortable, chocolate and vegetable on the board; students cross out the vanishing vowel, then tell a partner about their family's favorite food using as many of the words as they can."},{"id":"c1-4","lv":"C1","n":4,"title":"Out of, in front of, kind of: fixed phrases in fast speech","focus":"reduction","goal":"Understand and say frequent chunks like out of the question, in front of, as a matter of fact and I'm going to have to as single, fast units.","explain":["Fluent speakers don't build every phrase word by word. They store frequent chunks and say them as one quick unit, with only one or two strong beats and everything else squeezed in between: as a MAT-ter of FACT, at the END of the DAY, OUT of the QUES-tion. If you listen for each word separately, a chunk can sound like one long word.","Three things happen inside them. Before a consonant, of often loses its v and becomes 'uh': kind of → 'KIN-duh', in front of the → 'in FRUN-uh the'. A t between vowels becomes a quick d, the American flap: out of → 'OW-duh', matter → 'MAD-er'. And have to becomes 'HAF-tuh', with an f, because the t makes the v voiceless.","Before a vowel, of usually keeps its v and links to the next word: first of all → 'FIR-stuh-VAWL', most of it → 'MOS-tuh-vit'. Longer chunks combine several changes: I'm going to have to → 'I'm gonna HAF-tuh'; what do you mean → 'whaddaya MEAN?'; as a matter of fact → 'az-uh MAD-er-uh FACT'.","UK note: British speakers usually keep a real t, or use a glottal stop (a tiny catch in the throat), instead of the flap: 'MAT-uh of fact', not 'MAD-er-uh fact'. When you speak, don't force the reductions: say the chunk smoothly, with the stress on its key words, and they will come by themselves. In writing, always use the full words."],"spanish":"Spanish speakers tend to pronounce every word fully and evenly (out-of-the-ques-tion), often saying of like 'off', so the chunk sounds slow and heavy, and the fast versions are hard to recognize. Learn each chunk as one unit, with strong beats only on its key words: az-uh MAD-er-uh FACT.","ex":[{"t":"Sorry, that's out of the question.","how":"sorry, that's_OW-duh the QUES-chun","note":"out of → 'OW-duh': flap t, of = 'uh'"},{"t":"I'll meet you in front of the station.","how":"I'll meet you in FRUN-uh the STAY-shun","note":"front of the → 'FRUN-uh the'"},{"t":"As a matter of fact, I've already finished.","how":"az-uh MAD-er-uh FACT, I've_al-READ-y FIN-isht","note":"matter → 'MAD-er'; of → 'uh'"},{"t":"At the end of the day, it's your decision.","how":"at thee_END-uh the DAY, it's your di-SIZH-un","note":"end of the → 'END-uh the'"},{"t":"I'm going to have to call you back.","how":"I'm gonna HAF-tuh call you BACK","note":"have to → 'HAF-tuh' (f, not v)"},{"t":"What do you mean by that?","how":"whaddaya MEAN by that?","note":"what do you → 'whaddaya'"},{"t":"It's kind of a long story.","how":"it's KIN-duh-vuh LONG STOR-ee","note":"of keeps its v before a vowel: kind of a → 'KIN-duh-vuh'"},{"t":"First of all, thank you all for coming.","how":"FIR-stuh-VAWL, THANK you all for COM-ing","note":"of + vowel → the v links"}],"listen":[{"q":"In fast speech these are close. Which question do you hear?","o":["What do you mean?","What did you mean?"],"pick":true,"why":"What do you → 'whaddaya'; what did you → 'whadja', with a j sound from did you."},{"q":"Which sentence do you hear?","o":["We have to talk.","We had to talk."],"pick":true,"why":"Have to = 'HAF-tuh', with an f; had to = 'HAT-tuh', with no f."},{"q":"Listen. Which fixed phrase do you hear at the start?","say":"As a matter of fact, I've already booked the tickets.","o":["As a matter of fact","As a result","As far as I know"],"a":0,"why":"'az-uh MAD-er-uh FACT': five words, but only two strong beats."},{"q":"Listen. How many words are there before 'we'?","say":"At the end of the day, we all want the same thing.","o":["4","5","6"],"a":2,"why":"At the end of the day = six words, squeezed around two beats: at thee END-uh the DAY."},{"q":"Listen. Which words come before 'leave'?","say":"I'm going to have to leave a bit early today.","o":["I'm going to","I'm going to have to","I have to"],"a":1,"why":"'I'm gonna HAF-tuh': going to → gonna, have to → 'HAF-tuh'."},{"q":"Listen. In fast speech, what often happens to 'of' here?","say":"There's a great café right in front of the hotel.","o":["It keeps a clear v.","It becomes a quick 'uh'.","It sounds like 'off'."],"a":1,"why":"Before a consonant (the), of often loses its v: in FRUN-uh the ho-TEL."},{"q":"Listen. Does 'of' lose its v here?","say":"First of all, I'd like to thank everyone for coming.","o":["Yes: 'FIR-stuh all'","No: it links to all, 'FIR-stuh-VAWL'"],"a":1,"why":"Before a vowel, of keeps its v and links: FIR-stuh-VAWL."},{"q":"Listen. In fast American speech, how does 'out of' sound here?","say":"Honestly, a second meeting this week is out of the question.","o":["'OW-tuv', with a clear t and v","'OW-duh', with a quick d sound","'OWT-off', like off"],"a":1,"why":"The t between vowels becomes a flap (a quick d), and of loses its v before the: OW-duh the QUES-chun."}],"mark":[{"mode":"link","q":"Tap where a consonant joins the vowel of the next word.","w":["That's","out","of","the","question."],"a":[0,1],"why":"That's_out (s + ou) and out_of (a flap: 'OW-duh'). Before the, of loses its v, so nothing links there."},{"mode":"find","q":"Tap the two words that shrink to 'uh' and 'thuh' in fast speech.","w":["We","parked","in","front","of","the","hotel."],"a":[4,5],"why":"In FRUN-uh the ho-TEL: of → 'uh', the → 'thuh'."},{"mode":"stress","q":"Tap the two strong words in this chunk.","w":["As","a","matter","of","fact"],"a":[2,4],"why":"As a MAT-ter of FACT ('az-uh MAD-er-uh FACT'): only matter and fact are strong."},{"mode":"find","q":"Tap the four words that become 'gonna HAF-tuh' in fast speech.","w":["I'm","going","to","have","to","work","late."],"a":[1,2,3,4],"why":"Going to → 'gonna', have to → 'HAF-tuh': I'm gonna HAF-tuh work LATE."},{"mode":"link","q":"Tap where the words link (a consonant or a y sound joining a vowel).","w":["At","the","end","of","the","day"],"a":[1,2],"why":"The_end ('thee-yend') and end_of ('END-uh'). At the, of the and the day don't join a vowel."}],"dict":[{"say":"I'm afraid another delay is completely out of the question.","a":"I'm afraid another delay is completely out of the question.","how":"I'm a-FRAID a-NOTH-er de-LAY_is com-PLETE-ly OW-duh the QUES-chun","why":"Out of the → 'OW-duh the': flap t, and of becomes 'uh'."},{"say":"As a matter of fact, I left my keys in front of the door.","a":"As a matter of fact, I left my keys in front of the door.","how":"az-uh MAD-er-uh FACT, I left my KEYS in FRUN-uh the DOOR","why":"Matter has a flap t; both of's become 'uh' before a consonant."},{"say":"I'm gonna have to leave a little early today, sorry.","a":"I'm going to have to leave a little early today, sorry.","alt":["I'm gonna have to leave a little early today, sorry."],"how":"I'm gonna HAF-tuh leave_a LID-dle EAR-ly to-DAY, SOR-ry","why":"Going to → 'gonna', have to → 'HAF-tuh', and little has a flap: 'LID-dle'."},{"say":"What do you mean? At the end of the day, it's not our decision.","a":"What do you mean? At the end of the day, it's not our decision.","alt":["What do you mean? At the end of the day, it is not our decision."],"how":"whaddaya MEAN? | at thee_END-uh the DAY, it's not_our di-SIZH-un","why":"What do you → 'whaddaya'; end of the → 'END-uh the'."},{"say":"It was kind of a long meeting, and most of it was a waste of time.","a":"It was kind of a long meeting, and most of it was a waste of time.","how":"it was KIN-duh-vuh LONG MEET-ing, and MOS-tuh-vit was_a WAY-stuh TIME","why":"Of keeps its v before a vowel (kind of a, most of it) but becomes 'uh' before a consonant (waste of time)."}],"tip":"In class: say five chunks at natural speed (out of the question, in front of, as a matter of fact, at the end of the day, what do you mean); students write how many words they heard, then build a short dialogue that uses all five."},{"id":"c1-5","lv":"C1","n":5,"title":"What I NEED is…: stress for emphasis","focus":"rhythm","goal":"Use emphatic do/did, cleft sentences and so/such/really with the right stress to insist, correct someone or show strong feeling.","explain":["English has special structures for emphasis, and each one has its own stress pattern. Emphatic do, does or did goes before the main verb and is always strong: 'You didn't call me!' 'I DID call you!' It contradicts what someone said or thought. In a neutral sentence there is no do at all (I called you), so the extra word and its strong stress do the work.","Cleft sentences split the information to focus on one part. In a wh-cleft (What I need is a break), the key word of the first part gets a stress, often with a rise, and the new information at the end gets the main fall: What I NEED ↗ is a BREAK ↘. In an it-cleft (It was John who called), the main stress goes on the focused word and the rest stays low: It was JOHN who called.","Intensifiers carry extra emphasis too: It was SO good. We had SUCH a good time. I REALLY appreciate it. Make the stressed syllable longer and higher than usual, but keep the small words (a, it, was) weak. You can also stress an auxiliary instead of contracting it: I AM listening! (not I'm listening). She HAS finished!"],"spanish":"Spanish adds words for this (Sí te llamé, De verdad que…) and has no emphatic auxiliary, so Spanish speakers often drop the did ('I called you!') or say it weakly. Make do, did, so and such clearly strong and long, and keep the rest of the sentence lower so the contrast is heard.","ex":[{"t":"You didn't call me! I did call you!","how":"you DID-n't call me! | I DID call you!","note":"emphatic did contradicts"},{"t":"I do like your idea, but it's too expensive.","how":"I DO like your i-DEE-uh, but it's TOO ex-PEN-sive","note":"a strong yes before a 'but'"},{"t":"What I need is a long vacation.","how":"what I NEED ↗ is_a LONG va-CAY-shun ↘","note":"wh-cleft: a rise on need, the main fall at the end"},{"t":"What she said was completely true.","how":"what she SAID ↗ was com-PLETE-ly TRUE ↘","note":"wh-cleft"},{"t":"It was Laura who found the mistake, not me.","how":"it was LAU-ra who found the mistake, | not ME","note":"it-cleft: who found the mistake stays low"},{"t":"The concert was so good!","how":"the CON-cert was SO good!","note":"so: longer and higher"},{"t":"We had such a great time!","how":"we had SUCH_a great time!","note":"such + a + adjective + noun"},{"t":"I really appreciate your help.","how":"I REAL-ly ap-PREE-shee-ate your HELP","note":"really is stressed on its first syllable"}],"listen":[{"q":"Which sentence do you hear?","o":["I did call you.","I called you."],"pick":true,"why":"I DID call you is the emphatic version: it answers 'You didn't call me!'. The did is always strong."},{"q":"Which sentence do you hear?","o":["What I need is a break.","I need a break."],"pick":true,"why":"What I need is… is a wh-cleft: it builds up to the new information, with the main stress on BREAK."},{"q":"Which sentence do you hear?","o":["We had such a good time.","We had a very good time."],"pick":true,"why":"SUCH comes before a and is strongly stressed; very comes after a."},{"q":"Listen. Which word carries the strongest stress in the reply?","say":"You didn't lock the door. I did lock it!","o":["I","did","lock","it"],"a":1,"why":"I DID lock it: emphatic did contradicts the first speaker."},{"q":"Listen. Which word carries the main stress in the first part?","say":"It was the client who canceled the meeting, not my boss.","o":["client","canceled","meeting"],"a":0,"why":"In an it-cleft the focus word gets the main stress: it was the CLI-ent who canceled the meeting."},{"q":"Listen. Why does the speaker use do here?","say":"Do come in and make yourself at home.","o":["to ask a question","to make the invitation warmer and stronger","because the sentence is negative"],"a":1,"why":"Emphatic DO before an imperative makes a warm, insistent invitation; do is strong, never 'duh'."},{"q":"Listen. Where does the new, most important information come?","say":"What I'd really like is a quiet weekend at home.","o":["in the first part (What I'd really like)","after is (a quiet weekend at home)"],"a":1,"why":"A wh-cleft saves the new information for the end, where the main fall comes."},{"q":"Listen. Which two words add emphasis?","say":"I really do think you should apply for the job.","o":["really, do","think, should","apply, job"],"a":0,"why":"REAL-ly and emphatic DO both strengthen I think, and both are stressed."}],"mark":[{"mode":"stress","q":"Context: 'You never help me!' Tap the word with the strongest stress in the reply.","w":["I","do","help","you!"],"a":[1],"why":"I DO help you! Emphatic do contradicts 'never' and is always strong."},{"mode":"stress","q":"Tap the two stressed words.","w":["What","I","need","is","a","break."],"a":[2,5],"why":"What I NEED ↗ is a BREAK ↘: what, I, is and a are weak."},{"mode":"stress","q":"Context: 'Did Pedro send the email?' Tap the main stress in the reply.","w":["It","was","Ana","who","sent","it."],"a":[2],"why":"It was A-na who sent it: the sending is known, so only the name is stressed."},{"mode":"find","q":"Tap the two words that carry extra emphasis.","w":["It's","such","a","nice","place,","and","so","quiet."],"a":[1,6],"why":"It's SUCH a nice place, and SO quiet: such and so are long and high."},{"mode":"stress","q":"Context: 'You're not listening!' Tap the word with the strongest stress in the reply.","w":["I","am","listening!"],"a":[1],"why":"I AM listening! The full, stressed am contradicts the other speaker; a neutral sentence would use I'm."}],"dict":[{"say":"I did send you the report, but it might be in your spam folder.","a":"I did send you the report, but it might be in your spam folder.","how":"I DID send you the re-PORT, but_it might be_in your SPAM folder","why":"Emphatic did is strong; spam folder is a compound, stressed on the first word."},{"say":"What I really need right now is a long weekend somewhere quiet.","a":"What I really need right now is a long weekend somewhere quiet.","how":"what I really NEED right now ↗ | is_a long WEEK-end somewhere QUI-et ↘","why":"Wh-cleft: a rise on need, then the new information, with the main fall at the end."},{"say":"It was my manager who made the final decision, not the client.","a":"It was my manager who made the final decision, not the client.","how":"it was my MAN-a-ger who made the final decision, | NOT the CLI-ent","why":"It-cleft: manager carries the main stress; who made the final decision stays low."},{"say":"We had such a good time that we're going back next summer.","a":"We had such a good time that we're going back next summer.","how":"we had SUCH_a good time that we're going BACK next summer","why":"Such is long and high; a good time stays lower."},{"say":"I do understand your point, but I really don't think it'll work.","a":"I do understand your point, but I really don't think it'll work.","how":"I DO un-der-STAND your point, but I REAL-ly don't think_it'll WORK","why":"Emphatic do and really are strong; your point is known, so it stays low."}],"tip":"In class: students make false claims about each other (You didn't do your homework! You hate coffee!); the partner corrects them with emphatic do/did or a cleft (I DID do it! What I hate is TEA!)."},{"id":"c1-6","lv":"C1","n":6,"title":"Wednesday, receipt, island: tricky words","focus":"sounds","goal":"Say common words with silent letters and surprising spellings (Wednesday, receipt, island, colonel, recipe…) the way Americans really say them.","explain":["English spelling is old. Some letters stopped being pronounced centuries ago, and others were added by scholars to make words look like Latin, but were never said. So the b in debt and subtle is silent ('det', 'SUH-dl'), and so are the p in receipt ('ri-SEET'), the s in island ('EYE-lund'), the l in salmon ('SAM-un'), the t in mortgage ('MOR-gij') and the first d in Wednesday, which has only two syllables: 'WENZ-day'.","Other words simply don't sound the way they look. Colonel is 'KER-nul', exactly like kernel. A hotel suite is 'sweet' (but a suit rhymes with boot). Queue is just 'kyoo', like the letter Q. Clothes has one syllable: 'klohthz', and in normal speech often just 'klohz', like the verb close. Recipe goes the other way: its final e is pronounced, so it has three syllables, 'RES-uh-pee', and it doesn't rhyme with type.","Often is special: most Americans say 'OFF-un', with a silent t as in listen and soften, but 'OFF-tun' is also correct. In American English the r is always pronounced, so it's 'MOR-gij' and 'KER-nul'; British speakers drop it in both words. Americans usually say line, not queue, for people waiting; queue is common for phone calls and computers (a print queue). Learn each of these words as a sound, not as a spelling."],"spanish":"Spanish is written almost exactly as it is spoken, so Spanish speakers tend to pronounce every letter: 're-SEIPT', 'IS-land', 'SAL-mon', 'co-lo-NEL', 'clo-thes'. Fix: learn these words by ear, and when a word looks strange, check how it sounds before you use it.","ex":[{"t":"We spent Wednesday on the island.","how":"we SPENT WENZ-day on the EYE-lund","note":"Wednesday: 2 syllables, first d silent; island: no s"},{"t":"Could I have a receipt, please?","how":"kud-eye HAV-uh ri-SEET, PLEASE?","note":"receipt rhymes with seat: the p is silent"},{"t":"I left my clothes in the hotel suite.","how":"i LEFT my KLOHZ in the ho-TEL SWEET","note":"clothes: one syllable; suite = sweet"},{"t":"We're still paying off the mortgage, but we have no other debt.","how":"we're STILL PAY-ing OFF the MOR-gij | but we have NO other DET","note":"mortgage: silent t; debt: silent b"},{"t":"The colonel ordered the salmon.","how":"the KER-nul OR-derd the SAM-un","note":"colonel sounds exactly like kernel; salmon has no l sound"},{"t":"She often makes subtle jokes.","how":"she OFF-un MAKES SUH-dl JOKES","note":"often: t usually silent; subtle: silent b, and the t is a quick American d"},{"t":"Can you send me the recipe?","how":"k'n-yuh SEND me the RES-uh-pee?","note":"three syllables: the final e is pronounced"},{"t":"Your call is in a queue, so please don't hang up.","how":"yer CALL iz_in_uh KYOO | so PLEASE don't HANG_UP","note":"queue = cue = the letter Q"}],"listen":[{"q":"Which word do you hear?","o":["island","Iceland"],"pick":true,"why":"island is 'EYE-lund', with no s sound; Iceland has a clear s: 'ICE-lund'."},{"q":"Which word do you hear?","o":["suite","suit"],"pick":true,"why":"suite sounds exactly like sweet; suit rhymes with boot."},{"q":"Which word do you hear?","o":["receipt","recipe"],"pick":true,"why":"receipt is 'ri-SEET' (2 syllables, stress at the end); recipe is 'RES-uh-pee' (3 syllables, stress at the start)."},{"q":"How many syllables do you hear?","say":"Wednesday","o":["1","2","3"],"a":1,"why":"'WENZ-day': the first d and the second e are silent, so there are only two syllables."},{"q":"This word sounds exactly like…","say":"colonel","o":["kernel","colon","corner"],"a":0,"why":"colonel is 'KER-nul', the same sound as kernel. The spelling hides an r sound."},{"q":"Which letter is silent in this word?","say":"mortgage","o":["r","t","g"],"a":1,"why":"'MOR-gij': the t is silent. In American English the r is pronounced."},{"q":"How many syllables do you hear?","say":"clothes","o":["1","2"],"a":0,"why":"clothes is one syllable, 'klohthz' or just 'klohz', never 'clo-thes'."},{"q":"This word sounds exactly like…","say":"queue","o":["cue","coo","cow"],"a":0,"why":"queue = cue = the letter Q: 'kyoo', with a y sound before the oo."}],"mark":[{"mode":"find","q":"Tap the two words with a silent consonant.","w":["Can","I","have","a","receipt","for","the","salmon,","please?"],"a":[4,7],"why":"receipt: silent p ('ri-SEET'); salmon: silent l ('SAM-un')."},{"mode":"find","q":"Tap the two words with a silent consonant.","w":["The","mortgage","is","our","largest","debt."],"a":[1,5],"why":"mortgage: silent t ('MOR-gij'); debt: silent b ('det')."},{"mode":"find","q":"Tap the two words with a silent consonant.","w":["We","spent","Wednesday","on","a","tiny","island."],"a":[2,6],"why":"Wednesday: the first d is silent ('WENZ-day'); island: the s is silent ('EYE-lund')."},{"mode":"stress","q":"Tap the stressed syllable.","w":["rec","i","pe"],"word":true,"a":[0],"why":"REC-i-pe → 'RES-uh-pee': three syllables, stress on the first, and the final e is pronounced."},{"mode":"stress","q":"Tap the stressed syllable.","w":["mort","gage"],"word":true,"a":[0],"why":"MORT-gage → 'MOR-gij': stress on the first syllable; the second is weak ('gij', not 'gage') and the t is silent."}],"dict":[{"say":"Could I get a receipt for the salmon and the wine?","a":"Could I get a receipt for the salmon and the wine?","how":"kud-eye GED-uh ri-SEET fer the SAM-un_un the WINE?","why":"receipt: silent p; salmon: silent l; get a → flap T ('GED-uh'); and → 'un'."},{"say":"I often wear casual clothes on Wednesdays, but not when I meet clients.","a":"I often wear casual clothes on Wednesdays, but not when I meet clients.","how":"i OFF-un wear KAZH-oo-ul KLOHZ on WENZ-dayz | but NOT when i MEET CLI-ents","why":"often: silent t; clothes: one syllable; Wednesdays: 'WENZ-dayz'."},{"say":"The change was subtle, but the colonel noticed it right away.","a":"The change was subtle, but the colonel noticed it right away.","how":"the CHANGE wuz SUH-dl | but the KER-nul NOH-dist_it RIGHT_uh-WAY","why":"subtle: silent b; colonel = 'KER-nul'; noticed_it and right_away link."},{"say":"Our suite had a balcony with a view of the whole island.","a":"Our suite had a balcony with a view of the whole island.","how":"our SWEET had_uh BAL-kuh-nee with_uh VYOO of the WHOLE EYE-lund","why":"suite = 'sweet'; island = 'EYE-lund', no s."},{"say":"The print queue is stuck, so I'll email you the mortgage documents.","a":"The print queue is stuck, so I'll email you the mortgage documents.","how":"the PRINT KYOO iz STUCK | so i'll EE-mail you the MOR-gij DOCK-yuh-ments","why":"queue = 'kyoo'; mortgage = 'MOR-gij', silent t."}],"tip":"In class: dictate the 13 words one by one; students write them, cross out every silent letter and read them aloud. Then play 'catch the mistake': one student says a word wrong on purpose ('re-SEIPT', 'IS-land') and the others correct it."},{"id":"c1-7","lv":"C1","n":7,"title":"Fifteen or fifty? Numbers and figures in fast speech","focus":"sounds","goal":"Hear and say figures clearly under pressure: fifteen vs fifty, decimals, millions, years, decades, fractions and ranges, with the stress in the right place.","explain":["Fifteen or fifty? Said alone, -teen numbers are stressed at the end and -ty numbers at the start: fif-TEEN, FIF-tee. But before a noun the stress of -teen often moves forward (FIF-teen DOL-lerz), so stress alone is not enough. Listen for the other clues: -teen has a clear t, a long ee and a final n; -ty is short, and in thirty, forty and eighty the American t becomes a quick d: 'THUR-dee', 'FOR-dee', 'AY-dee'. When it matters, check: 'Fifteen, one-five?'","Say big numbers in chunks, with the main stress on the last part: two point five MILLion. Americans usually leave out and (one hundred twenty); British speakers keep it (one hundred and twenty). After the decimal point, say each digit: 2.75 = 'two point seven five', never 'two point seventy-five'. Zero can be 'zero' or 'oh': 0.05% = 'zero point zero five percent' or just 'point oh five percent' (British: 'nought point nought five').","Years go in pairs: 1990 = 'nineteen NINEty', 2025 = 'twenty twenty-FIVE' (also 'two thousand twenty-five'), but 2005 = 'two thousand FIVE'. A decade is plural: the 1990s = 'the nineteen NINEties', or just 'the NINEties'. Fractions: 3/4 = 'three QUARters' or 'three FOURTHS'. Ranges use a weak to: 2020–2025 = 'from twenty twenty tuh twenty twenty-five'; Americans also say 'Monday through Friday'. And 24/7 is 'twenty-four SEVen'.","Dates: Americans say 'March thirteenth' (British: 'the thirteenth of March'). With several figures in one sentence, make a tiny pause between the chunks so each one is clear: 'two point five million | in twenty twenty-four'."],"spanish":"In Chile you write 2,5 and say 'dos coma cinco', so Spanish speakers often say 'two comma five' or read decimals as one number ('two point seventy-five'): in English say 'point' and then each digit, 'two point seven five'. Also make -teen long, with a clear n (fif-TEEN), and -ty short (FIF-tee).","ex":[{"t":"The meeting is in room 15, not 50.","how":"the MEE-ding's in room fif-TEEN | not FIF-tee","note":"-teen: long ee + n; -ty: short, no n"},{"t":"That's thirty, three oh, not thirteen.","how":"that's THUR-dee | THREE OH | not thur-TEEN","note":"check a number by saying its digits; thirty has a quick d"},{"t":"Sales reached 2.5 million last year.","how":"SALES reached | two point five MIL-yun | last YEAR","note":"say 'point'; main stress on MILLion"},{"t":"Prices went up by point oh five percent.","how":"PRI-sez went UP by point oh FIVE per-CENT","note":"0.05%: also 'zero point zero five percent'"},{"t":"The company grew fast in the 1990s.","how":"the COM-puh-nee grew FAST in the nineteen NINE-teez","note":"a decade: plural, stress on NINEties"},{"t":"About three quarters of our clients are in Santiago.","how":"uh-BOUT three KWOR-derz of our CLI-ents are in san-tee-AH-go","note":"3/4 = three quarters or three fourths"},{"t":"The project runs from 2020 to 2025.","how":"the PROJ-ect runs from twenty TWEN-ty tuh twenty twenty-FIVE","note":"years in pairs; to is a weak 'tuh'"},{"t":"Our help desk is open twenty-four seven.","how":"our HELP desk iz OH-pun twenty-four SEV-un","note":"24/7 = all day, every day; stress on seven"}],"listen":[{"q":"Which number do you hear?","o":["15","50"],"pick":true,"why":"15 = fif-TEEN: long ee + n; 50 = FIF-tee: short, no n."},{"q":"Which price do you hear?","o":["It's $14.","It's $40."],"pick":true,"why":"Before a noun both can start strong, so listen for the end: four-TEEN (long ee + n) vs FOR-dee (quick d, short ee)."},{"q":"Which figure do you hear?","o":["2.5 million","25 million"],"pick":true,"why":"2.5 = 'two point five'; 25 = 'twenty-five'."},{"q":"When is the conference?","say":"The conference is on March 13th.","o":["March 13","March 30","March 3"],"a":0,"why":"'thur-TEENTH': a clear t, long ee and n; March 30 would be 'THUR-dee-ith'."},{"q":"Which figure do you hear?","say":"Our sales grew by 2.75% last quarter.","o":["2.75%","2.075%","27.5%"],"a":0,"why":"'two point seven five percent': after the point, each digit is said separately."},{"q":"When did he live in Chicago?","say":"He lived in Chicago in the 1980s.","o":["only in 1980","from 1980 to 1989","in 1918"],"a":1,"why":"'the nineteen EIGHT-eez' is a whole decade; 1918 would be 'nineteen eigh-TEEN'."},{"q":"Which fraction do you hear?","say":"Nearly three quarters of the staff work from home.","o":["3/4","1/4","3/5"],"a":0,"why":"three quarters = 3/4 (Americans also say three fourths)."},{"q":"What will happen to prices?","say":"Prices will rise by two to three percent next year.","o":["2–3%","23%","2.3%"],"a":0,"why":"'two tuh three': the weak to makes a range; twenty-three would be 'TWEN-ee-three'."}],"mark":[{"mode":"stress","q":"Said alone: tap the stressed syllable.","w":["thir","teen"],"word":true,"a":[1],"why":"thir-TEEN: long ee + n. Compare thirty: THIR-ty ('THUR-dee')."},{"mode":"stress","q":"Tap the word with the main stress.","w":["It","was","built","in","the","nineteen","nineties."],"a":[6],"why":"the nineteen NINEties: in years and decades the main stress goes on the last part."},{"mode":"stress","q":"Tap the word with the main stress.","w":["The","hotel","gym","is","open","twenty-four","seven."],"a":[6],"why":"open twenty-four SEVen: the stress goes at the end of the expression."},{"mode":"link","q":"Tap where the words join.","w":["About","eight","and","a","half","million."],"a":[0,1,2],"why":"About_eight_and_a → 'uh-BOW-DAY-dun-uh', with a quick American d; half million does not link."},{"mode":"weak","q":"Tap the weak words.","w":["The","project","ran","from","2020","to","2025."],"a":[0,3,5],"why":"the /ðə/, from /frəm/, to /tə/ ('tuh'): the years carry the stress."}],"dict":[{"say":"We need 15 chairs for the meeting, not 50.","a":"We need 15 chairs for the meeting, not 50.","alt":["We need fifteen chairs for the meeting, not fifty."],"how":"we need FIF-teen CHAIRS for the MEE-ding | not FIF-tee","why":"before a noun fifteen may start strong (FIF-teen CHAIRS), so listen for the long ee + n; fifty is short."},{"say":"Our sales reached 2.5 million dollars last year.","a":"Our sales reached 2.5 million dollars last year.","alt":["Our sales reached two point five million dollars last year.","Our sales reached $2.5 million last year."],"how":"our SALES reached | two point five MIL-yun DOL-lerz | last YEAR","why":"decimal point = 'point'; the figure is one chunk with the stress at the end."},{"say":"Consumer prices rose by just point oh five percent in March.","a":"Consumer prices rose by just 0.05% in March.","alt":["Consumer prices rose by just .05% in March.","Consumer prices rose by just 0.05 percent in March.","Consumer prices rose by just .05 percent in March.","Consumer prices rose by just point oh five percent in March.","Consumer prices rose by just point zero five percent in March."],"how":"con-SOO-mer PRI-sez rose by JUST | point oh FIVE per-CENT | in MARCH","why":"zero can be 'oh'; each digit after the point is said separately; per-CENT."},{"say":"Nearly three quarters of the budget was spent between 2020 and 2023.","a":"Nearly three quarters of the budget was spent between 2020 and 2023.","alt":["Nearly 3/4 of the budget was spent between 2020 and 2023.","Nearly three quarters of the budget was spent between twenty twenty and twenty twenty-three."],"how":"NEAR-lee three KWOR-derz of the BUD-jit wuz SPENT | b'tween twenty TWEN-ty un twenty twenty-THREE","why":"3/4 = three quarters; years in pairs; and is a weak 'un'."},{"say":"Our support team is available twenty-four seven, even on holidays.","a":"Our support team is available 24/7, even on holidays.","alt":["Our support team is available twenty-four seven, even on holidays.","Our support team is available 24 7, even on holidays."],"how":"our suh-PORT team iz uh-VAY-luh-bl twenty-four SEV-un | EE-vun on HOL-uh-dayz","why":"24/7 = 'twenty-four SEVen'; available has four syllables."}],"tip":"In class: one student reads a short 'market report' full of figures (prices, percentages, years, a range) while the others write the figures down; then they compare, and the reader confirms doubtful ones the American way: 'That's one-five, not five-oh.'"},{"id":"c1-8","lv":"C1","n":8,"title":"Presenting: pause, pace and punch","focus":"rhythm","goal":"Deliver a short presentation with clear pauses, a slower pace for key numbers, strong contrast stress, rising signposts and falling conclusions.","explain":["Pause. Good presenters use silence. Pause between ideas, and pause just before a key word or number, so the audience is already listening when it arrives: 'The answer is simple | training.' A one-second pause feels long to you, but to the audience it sounds calm and confident. Don't fill it with 'uh' or 'um': just stop, breathe and go on.","Pace. Slow down for what matters: numbers, names and your main message. Say a key number word by word, with a pause before it: 'Our profit this year? | Twelve | million | dollars.' Move a little faster through the small words (the, of, for, to), which stay weak. This contrast between fast and slow is the rhythm that keeps an audience awake.","Punch. Stress the words that contrast: 'It's not a COST, it's an INVESTMENT.' 'Costs went down by eigh-TEEN percent, not EIGHT.' When you announce your structure, the voice rises a little on the signpost and pauses: 'First ↗ | our sales. Second ↗ | our costs.' In a list, it goes up on each item and down on the last: 'cost ↗, speed ↗ and quality ↘'.","End with a clear fall ↘: 'So, to sum up, we're on time and under budget ↘.' A rise at the end sounds like a question, as if you weren't sure of your own message. Falling doesn't mean getting quiet: keep your volume up until the last word."],"spanish":"Spanish speakers often fill pauses with 'eh…' or 'este…', speak at the same speed all the way through, and use a flat voice, so the key words don't stand out. Fix: use silent pauses, slow down for numbers and key words, punch the contrast words and finish each conclusion with a clear, confident fall.","ex":[{"t":"Good morning, everyone. Today I'd like to talk about our results.","how":"good MOR-ning, EV-ree-wun ↘ | to-DAY I'd like to TALK_about our re-SULTS ↘","note":"short pause after the greeting; a clear fall at the end"},{"t":"First, our sales. Second, our costs. And finally, our plans.","how":"FIRST ↗ | our SALES ↘ | SEC-ond ↗ | our COSTS ↘ | and FI-nuh-lee ↗ | our PLANS ↘","note":"signposts rise a little, then pause"},{"t":"And our profit this year? Twelve million dollars.","how":"and our PROF-it this YEAR ↗ | TWELVE | MILL-yun | DOL-lerz ↘","note":"pause before the key number, then say it slowly"},{"t":"Costs went down by eighteen percent, not eight.","how":"COSTS went DOWN by eigh-TEEN per-cent | not EIGHT ↘","note":"contrast: stress the part that is different"},{"t":"We didn't lose customers; we lost time.","how":"we DID-n't lose CUS-tuh-merz | we lost TIME ↘","note":"stress the two words that contrast"},{"t":"The solution is simple: better training.","how":"the suh-LOO-shun is SIM-ple | BED-er TRAIN-ing ↘","note":"pause before the key words"},{"t":"We have three priorities: cost, speed and quality.","how":"we have THREE pry-OR-uh-teez | COST ↗ | SPEED ↗ | and QUAL-uh-tee ↘","note":"a list: up, up, down"},{"t":"So, to sum up, we're on time and under budget.","how":"SO | tuh SUM_UP | we're on TIME_and UN-der BUD-jet ↘","note":"conclusion: slow down and finish with a clear fall"}],"listen":[{"q":"Which sentence do you hear? Listen for the pauses.","o":["The director said the client is wrong.","The director, said the client, is wrong."],"pick":true,"why":"With two pauses, 'said the client' is an insert: the client is saying that the director is wrong."},{"q":"Which sentence do you hear?","o":["The answer is simple: training.","The answer is simple training."],"pick":true,"why":"A pause before 'training' makes it the key word; with no pause, 'simple training' is just a kind of training."},{"q":"A confident conclusion or a question?","o":["So we're ready to launch.","So we're ready to launch?"],"pick":true,"why":"A falling end ↘ is a confident conclusion; a rise ↗ asks a question."},{"q":"In 'but we got forty', which word should get the strongest stress?","say":"We expected twenty new clients, but we got forty.","o":["but","got","forty"],"a":2,"why":"forty contrasts with twenty, so it gets the punch."},{"q":"Which word carries the contrast in the second sentence?","say":"Sales didn't fall in March. They fell in April.","o":["They","fell","April"],"a":2,"why":"April contrasts with March; fell only repeats old information."},{"q":"What is the speaker's second point?","say":"I have three points: first, the cost; second, the timing; and finally, the risk.","o":["the cost","the timing","the risk"],"a":1,"why":"Second ↗ | the timing: the signpost and a pause, then the point."},{"q":"How many thought groups (chunks with a pause between them) do you hear?","say":"In 2024, our team grew by 40%.","o":["1","2","3"],"a":1,"why":"In twenty twenty-four | our team grew by forty percent: an intro, a pause, then the main idea."},{"q":"Why does the speaker pause after 'this one'?","say":"And the most important number today is this one: ninety-five percent.","o":["to make the key number stand out","because it is a question","to change the topic"],"a":0,"why":"A pause just before a key number makes the audience listen for it."}],"mark":[{"mode":"stress","q":"Tap the two contrast words that carry the strongest stress.","w":["We","didn't","lose","customers,","we","lost","time."],"a":[3,6],"why":"We didn't lose CUSTOMERS, we lost TIME: the two things that contrast get the punch."},{"mode":"find","q":"Tap the words where the voice goes up (the list isn't finished yet).","w":["We","focus","on","cost,","speed","and","quality."],"a":[3,4],"why":"cost ↗, speed ↗ and quality ↘: up on each item, down on the last one."},{"mode":"find","q":"Tap the key word that a presenter would pause before.","w":["Our","number","one","priority","next","year","is","safety."],"a":[7],"why":"Our number one priority next year is | SAFETY: the pause makes the key word stand out."},{"mode":"weak","q":"Tap the weak words.","w":["Let's","look","at","the","results","for","the","first","quarter."],"a":[2,3,5,6],"why":"at /ət/, the /ðə/, for /fər/: quick and quiet, so results and first quarter stand out."},{"mode":"stress","q":"Tap the two contrast words that carry the strongest stress.","w":["It's","not","a","cost,","it's","an","investment."],"a":[3,6],"why":"It's not a COST, it's an INVESTMENT: stress the contrast, not the small words."}],"dict":[{"say":"First, let's look at the results for the last quarter.","a":"First, let's look at the results for the last quarter.","how":"FIRST ↗ | let's LOOK_at the re-SULTS fer the LAST KWOR-der ↘","why":"a small rise on First and a pause; at, the, for are weak; quarter has a quick American d."},{"say":"Our costs didn't go up by twelve percent; they went down.","a":"Our costs didn't go up by 12%; they went down.","alt":["Our costs didn't go up by twelve percent; they went down.","Our costs didn't go up by 12 percent; they went down."],"how":"our COSTS DID-n't go UP by twelve per-CENT | they went DOWN ↘","why":"contrast stress on UP and DOWN; a pause between the two ideas."},{"say":"The answer to all of these problems is simple: better training.","a":"The answer to all of these problems is simple: better training.","how":"the AN-ser tuh ALL_uv these PROB-lumz iz SIM-ple | BED-er TRAIN-ing ↘","why":"a pause before the key words; all_of links; better has a quick American d."},{"say":"We have three goals for next year: growth, quality and customer service.","a":"We have three goals for next year: growth, quality and customer service.","how":"we have THREE GOALS fer next YEAR | GROWTH ↗ | QUAL-uh-tee ↗ | and CUS-tuh-mer SER-vis ↘","why":"a pause before the list; up, up, down."},{"say":"To conclude, this was our best year in the company's history.","a":"To conclude, this was our best year in the company's history.","how":"tuh con-CLUDE | this wuz our BEST YEAR in the COM-puh-neez HIS-tuh-ree ↘","why":"a signpost and a pause, then a clear fall at the end of the conclusion."}],"tip":"In class: each student gives a 60-second mini-report with three points and one key number; the group gives feedback on three things only: one pause, one punch (contrast stress) and the final fall."},{"id":"c1-9","lv":"C1","n":9,"title":"Oh, GREAT. Sarcasm and irony","focus":"intonation","goal":"Recognize sarcastic and ironic intonation (flat or exaggerated) and make your sincere 'great' and 'thanks' really sound sincere.","explain":["In sarcasm, the words say one thing and the voice says the opposite. 'Oh, great.' after 'Your flight is delayed six hours' means 'This is terrible.' Listeners notice the clash between the situation and the words, and the voice confirms it. American English has two common sarcastic voices: flat and exaggerated.","The flat, or deadpan, voice: low pitch, very little movement, slow, with a long stressed vowel and a low fall: 'Oh, grrreat ↘.' 'Thanks a lot ↘.' It sounds bored or tired, the opposite of real enthusiasm. The exaggerated voice: a big, slow rise-fall and extra stress on small words like just, so and really: 'That's JUST what I needed.' 'I'm SO excited.' The over-acting is the signal.","To sound sincere, do the opposite: start higher, use a clear, natural fall, keep a normal speed and let your voice sound bright (a smile changes the sound). Add warm words that a sarcastic speaker wouldn't: 'Oh, great! Congratulations!' 'Thanks so much, that's really kind.' A bare 'Great.' or 'Thanks.' in a flat voice is risky.","Be careful at work: sarcasm is common between friends and colleagues, but with clients or a new boss it can sound rude. In writing there is no voice, so a one-word 'Great.' in an email can look sarcastic. UK note: British irony is often even flatter (deadpan) and harder to spot."],"spanish":"Spanish speakers often use a narrow, flat pitch in English, so a sincere 'Great.' or 'Thanks.' can sound sarcastic or bored to Americans. When you mean it, start higher, use a big clear fall and add warm words: 'Great, thanks so much!'","ex":[{"t":"Your flight is delayed six hours. Oh, great.","how":"your FLIGHT iz de-LAYD six HOURS ↘ | oh, GRRREAT ↘ (low, flat, slow)","note":"sarcastic: the situation is bad"},{"t":"You got the job? Oh, great! Congratulations!","how":"you got the JOB ↗ | oh, GREAT ↘ (high start, bright) | con-grat-chuh-LAY-shunz ↘","note":"sincere: high, lively voice and warm words"},{"t":"The printer's broken again. That's just what I needed.","how":"the PRIN-terz BRO-ken uh-GEN ↘ | that's JUUUST what_I NEED-ed ↘ (exaggerated)","note":"heavy stress on 'just' signals sarcasm"},{"t":"Thanks a lot for telling me at the last minute.","how":"THANKS_uh LOT ↘ (low, flat) | fer TELL-ing me at the LAST MIN-it","note":"the situation + a flat 'thanks' = sarcasm"},{"t":"We lost the client and the server crashed. Well, that went well.","how":"WELL | THAT went WELL ↘ (slow, deadpan)","note":"irony: saying the opposite of the facts"},{"t":"It's pouring rain. Perfect weather for a barbecue.","how":"PER-fect WEATH-er fer_uh BAR-buh-cue ↘ (slow, stretched)","note":"ironic praise"},{"t":"Thank you so much, that's really kind of you.","how":"THANK you so MUCH ↘ | that's REAL-ly KIND_of you ↘ (warm, bright)","note":"sincere: warm words + a lively voice"},{"t":"Yeah, right. Like that's going to happen.","how":"YEAH ↘ | RIGHT ↘ (flat) | LIKE that's gonna HAP-pen ↘","note":"two 'yes' words that mean 'no'"}],"listen":[{"q":"Is the last part sincere or sarcastic?","say":"My car broke down on the way to the interview. Oh, great.","o":["sincere","sarcastic"],"a":1,"why":"A breakdown on the way to an interview is bad news, so 'Oh, great' means the opposite."},{"q":"Is the last part sincere or sarcastic?","say":"They loved your proposal? Oh, great! That's fantastic news.","o":["sincere","sarcastic"],"a":0,"why":"Good news plus warm words ('fantastic news'): real enthusiasm."},{"q":"Is the last part sincere or sarcastic?","say":"Another meeting at six on a Friday. That's just what I needed.","o":["sincere","sarcastic"],"a":1,"why":"Nobody wants a meeting at six on a Friday: 'just what I needed' is ironic."},{"q":"Is the last part sincere or sarcastic?","say":"You fixed my laptop? Thanks a lot, you're a lifesaver.","o":["sincere","sarcastic"],"a":0,"why":"Someone helped, and 'you're a lifesaver' adds warm, real thanks."},{"q":"What does the speaker really mean?","say":"The client canceled, the server crashed, and I spilled my coffee. Well, that went well.","o":["The day went well.","The day went badly.","The speaker isn't sure how it went."],"a":1,"why":"After three disasters, 'that went well' is irony: it means the opposite."},{"q":"Does the speaker think the boss will give them a raise?","say":"Yeah, right. Like the boss is going to give us a raise.","o":["Yes, definitely.","No, not at all.","Maybe, they're not sure."],"a":1,"why":"'Yeah, right' is a sarcastic no: two positive words with a negative meaning."},{"q":"How does the speaker really feel?","say":"I'm stuck in traffic for the third time this week. Lucky me.","o":["lucky","annoyed","excited"],"a":1,"why":"Being stuck three times is bad luck, so 'Lucky me' is ironic."},{"q":"Your friend says this. Which reply sounds most sincere?","say":"I got the job!","o":["Oh, great.","That's amazing! Congratulations!","Well, that's just great."],"a":1,"why":"Warm extra words make it clearly sincere; a bare 'Oh, great.' or 'just great' can easily sound sarcastic."}],"mark":[{"mode":"stress","q":"A sarcastic speaker stretches one word. Tap it.","w":["That's","just","what","I","needed."],"a":[1],"why":"That's JUUUST what I needed: an over-stressed 'just' is a classic sarcastic signal."},{"mode":"stress","q":"A sarcastic speaker stretches one word. Tap it.","w":["I'm","so","excited","about","the","meeting."],"a":[1],"why":"I'm SOOO excited: over-stressing a small intensifier (so, just, really) sounds like over-acting."},{"mode":"stress","q":"Tap the word with the main stress.","w":["What","a","surprise."],"a":[2],"why":"What a sur-PRIIISE ↘: low, slow and stretched when it's no surprise at all."},{"mode":"stress","q":"A sarcastic speaker stretches one word. Tap it.","w":["Oh,","I","love","waiting","in","line."],"a":[2],"why":"Oh, I LOOOVE waiting in line: the ironic word gets the big, exaggerated stress."},{"mode":"link","q":"Tap where the words join.","w":["Well,","that's","an","excellent","idea."],"a":[1,2,3],"why":"that's_an_excellent_idea → 'that-sa-NEX-uh-lun-tie-DEE-uh'. After the comma in 'Well,' there is a pause, so no link."}],"dict":[{"say":"Oh, great. The train is late again, and it's raining.","a":"Oh, great. The train is late again, and it's raining.","how":"oh, GRRREAT ↘ (flat) | the TRAIN iz LAY-duh-GEN | and it's RAIN-ing ↘","why":"flat, low 'great' = sarcasm; late_again links with a quick American d."},{"say":"That's just what I needed on a Monday morning.","a":"That's just what I needed on a Monday morning.","how":"that's JUUUST wha-dai NEED-ed | on_uh MUN-day MOR-ning ↘","why":"exaggerated stress on just; what_I → 'wha-dai' (flap T)."},{"say":"Thanks a lot for telling me about the meeting five minutes before it started.","a":"Thanks a lot for telling me about the meeting five minutes before it started.","how":"THANKS_uh LOT ↘ | fer TELL-ing me uh-BOUT the MEE-ding | FIVE MIN-its be-FORE_it STAR-did","why":"flat, low 'thanks a lot' = sarcasm; thanks_a and before_it link."},{"say":"Congratulations, I'm really happy for you, you totally deserve it.","a":"Congratulations, I'm really happy for you, you totally deserve it.","how":"con-grat-chuh-LAY-shunz ↘ | i'm REAL-ly HAP-py for you | you TOE-duh-lee de-ZER-vit ↘","why":"sincere: warm words and a lively voice; deserve_it links; totally has a quick American d."},{"say":"Yeah, right, like the boss is going to let us leave early.","a":"Yeah, right, like the boss is going to let us leave early.","how":"YEAH ↘ | RIGHT ↘ | like the BOSS iz gonna LET_us LEAVE ER-lee ↘","why":"'Yeah, right' = a sarcastic no; going to → 'gonna'; let_us links."}],"tip":"In class: give pairs a card with a situation and a line (Oh, great. / Thanks a lot. / Nice job.); they say it sincerely or sarcastically and the class guesses which, then explains what in the voice gave it away."},{"id":"c2-1","lv":"C2","n":1,"title":"Implying more than you say","focus":"intonation","goal":"Use a high fall, a low fall or a fall-rise to show your attitude and to hint at what you are not saying.","explain":["At this level, the tune on one key word can say more than the words themselves. In statements, three tones on the key word (the nucleus) do most of the work: a high fall (start high, drop a long way: real enthusiasm, strong certainty), a low fall (start low, drop a little: neutral, final, sometimes cool or bored) and a fall-rise ↘↗ (drop, then lift at the end: 'there's something I'm not saying').","The fall-rise is the main tool of tact. Put it on a modal, a quantifier or a 'safe' word and the listener hears the opposite: 'You ↘↗COULD do that' (= I wouldn't), '↘↗SOME people might think so' (= I don't), 'In ↘↗THEory, yes' (= in practice, no). Put it on one small piece of praise and it criticizes everything else: 'Well, the ↘↗COFfee was nice.'","One word, three attitudes: 'Yes!' with a high fall = absolutely; 'Yes.' with a low fall = flat, uninvolved; 'Ye-es…' with a fall-rise = yes, but… The same works for maybe, sometimes and I suppose so. In meetings, a hedge plus a fall-rise is a polite way to disagree: 'I'm not ↘SURE that's the best ap↗PROACH.'","UK note: in British English 'It's quite good' often sounds lukewarm ('only fairly good'); for most American listeners 'quite good' means 'very good'."],"spanish":"Spanish speakers often use a narrower pitch range and end statements with a simple fall, so their tactful 'You could do that' sounds like real advice, and the hidden 'but…' in other people's speech goes unnoticed. Fix: find the key word (could, some, theory, nice), fall on it and lift at the end, and listen for that lift when others speak.","ex":[{"t":"Yes, absolutely!","how":"yes, ab-suh-↘LOOT-lee!","note":"high fall: total, enthusiastic agreement"},{"t":"Yes, I suppose so.","how":"yes, i suh-↘POSE so","note":"low fall: agreeing, but with no energy"},{"t":"That's interesting.","how":"that's ↘INteresting (low and flat)","note":"a low fall can mean 'not really interested'"},{"t":"You could do that…","how":"you ↘↗COULD do that…","note":"fall-rise on the modal = 'but I wouldn't'"},{"t":"Some people might think so.","how":"↘↗SOME people might think so","note":"fall-rise on the quantifier = 'but I don't'"},{"t":"In theory, it should work.","how":"in ↘↗THEory | it should ↘WORK","note":"= in practice, I doubt it"},{"t":"Well, the coffee was nice.","how":"WELL | the ↘↗COFfee was nice","note":"faint praise: nothing else was good"},{"t":"I'm not sure that's the best approach.","how":"i'm not ↘SURE that's the best ap↗PROACH","note":"a split fall-rise: down on SURE, up at the end = a polite 'no'"}],"listen":[{"q":"Which reaction do you hear?","o":["Oh, really?","Oh, really."],"pick":true,"why":"Really? ↗ rises: surprised or interested. Really. ↘ with a low fall sounds flat, even unimpressed."},{"q":"Which sentence do you hear?","o":["You could do that.","You couldn't do that."],"pick":true,"why":"couldn't ends in a quick 'dnt' ('KUD-nt'). 'You COULD do that' with a fall-rise is a tactful way of saying 'I wouldn't'."},{"q":"Which reply do you hear?","o":["That's one way to do it.","That's the way to do it."],"pick":true,"why":"'That's ONE way to do it' (fall-rise) hints there are better ways; 'That's THE way to do it!' is full approval."},{"q":"Which reply do you hear?","o":["Yes, absolutely!","Yes, I suppose so."],"pick":true,"why":"absolutely, with a high fall = full agreement; I suppose so, with a low fall = reluctant agreement."},{"q":"Listen to the question and the answer. What is the second speaker implying?","say":"Did you like the hotel? Well, the breakfast was nice.","o":["The whole hotel was excellent.","Not much else about the hotel was good.","The speaker didn't have breakfast."],"a":1,"why":"Praising one small detail, with a fall-rise on BREAKfast, suggests the rest was disappointing."},{"q":"Listen to the request and the reply. How does the second speaker feel?","say":"Can you cover my shift on Sunday? I could, I suppose.","o":["Delighted to help","Willing, but not keen","Completely unable to help"],"a":1,"why":"'I ↘↗COULD, I suppose': possible, but reluctant. A keen yes would be 'Sure, no problem!' with a high fall."},{"q":"What does the speaker really mean?","say":"Some people might think so.","o":["Everyone agrees with you.","I don't agree, but I'm being polite.","I'm not sure what you mean."],"a":1,"why":"With a fall-rise on SOME it means 'but not me': a tactful way to disagree."},{"q":"What is the speaker suggesting?","say":"In theory, the new system should save us time.","o":["It will definitely save time.","In practice, it may not save time.","It has already saved a lot of time."],"a":1,"why":"'In ↘↗THEory' sets up a contrast with practice: the speaker doubts it will work."}],"mark":[{"mode":"stress","q":"'Should I email the client tonight?' — 'You could do that…' (= but I wouldn't). Tap the word with the fall-rise.","w":["You","could","do","that…"],"a":[1],"why":"You ↘↗COULD do that: the fall-rise on the modal turns it into a polite warning."},{"mode":"stress","q":"'Everyone loves the new logo!' Tap the word with the fall-rise in the reply (= but I don't).","w":["Well,","some","people","might."],"a":[1],"why":"Well, ↘↗SOME people might: everyone → some is the contrast, so SOME carries the fall-rise."},{"mode":"stress","q":"'Was the conference useful?' — 'The lunch was good.' (= the talks weren't). Tap the word with the fall-rise.","w":["The","lunch","was","good."],"a":[1],"why":"The ↘↗LUNCH was good: the contrasted item (lunch, not the talks) takes the fall-rise; 'was good' carries the rise."},{"mode":"stress","q":"'Want to join us for dinner?' Tap the word with the high fall in this enthusiastic reply.","w":["Oh,","I'd","love","to!"],"a":[2],"why":"Oh, I'd ↘LOVE to! A big drop from high on LOVE sounds genuinely happy; to stays weak."},{"mode":"stress","q":"Tap the word with the fall-rise (= but in practice, I doubt it).","w":["In","theory,","that","should","work."],"a":[1],"why":"in ↘↗THEory | that should ↘WORK: the fall-rise on THEORY prepares the unspoken 'but'."}],"dict":[{"say":"You could do that, but I'm not sure the client would be happy.","a":"You could do that, but I'm not sure the client would be happy.","how":"you ↘↗COULD do that | but i'm not SURE the CLIent'd be ↘HAPpy","why":"fall-rise on COULD = 'I wouldn't'; client would → 'CLIent'd'."},{"say":"Some people might think so, but I'd want to see the numbers first.","a":"Some people might think so, but I'd want to see the numbers first.","alt":["Some people might think so, but I would want to see the numbers first."],"how":"↘↗SOME people might think so | but i'd WANna see the NUMbers ↘FIRST","why":"fall-rise on SOME = 'but not me'; want to → 'wanna'."},{"say":"In theory, the new schedule should work, but in practice I have my doubts.","a":"In theory, the new schedule should work, but in practice I have my doubts.","how":"in ↘↗THEory | the new SKEDjule should WORK | but in ↘PRACtice | i have my ↘DOUBTS","why":"fall-rise on THEORY sets up the contrast; PRACTICE and DOUBTS fall clearly."},{"say":"Well, the location was great, I'll give them that.","a":"Well, the location was great, I'll give them that.","how":"WELL | the lo↘↗CAtion was great | i'll ↘GIVE 'em that","why":"fall-rise on LOCATION: only that was good; them → ''em'."},{"say":"I wouldn't say it was a disaster, but it could have gone better.","a":"I wouldn't say it was a disaster, but it could have gone better.","how":"i WOULDn't say it was a dis↘↗ASter | but it could-uv gone ↘BETter","why":"fall-rise on DISASTER softens the criticism; could have → 'could-uv'."}],"tip":"In class: students say 'Yes', 'Maybe' or 'The hotel was clean' with a high fall, a low fall or a fall-rise; the group holds up 1, 2 or 3 fingers and says what the speaker really means."},{"id":"c2-2","lv":"C2","n":2,"title":"Tempo, pausing and asides","focus":"rhythm","goal":"Say asides quicker and lower, slow down for emphasis and pause for effect, and follow the main line when others do it.","explain":["Fluent speakers change gear. For an aside (a comment, a clarification, a quick joke) they drop the pitch, speed up, often lower the volume, and frame it with short pauses. Then they return to the main sentence at the pitch where they left it: 'My BOSS | (who, by the way, never reads emails) | asked aGAIN.' Listeners treat the low, fast part as extra and keep track of the main line.","Common asides: non-defining relative clauses (who lives in Lima), comment phrases (to be fair, as far as I know, believe it or not) and self-interruptions (and I mean this). In writing, commas, dashes and parentheses usually mark them. The pauses can change the meaning: 'My sister, who lives in Lima, is a nurse' (one sister) vs 'My sister who lives in Lima is a nurse' (I have more than one).","The opposite move is slowing down for emphasis: space the words out ('Every. Single. Time.'), stretch the stressed syllable, or pause just before the key word ('And the new head of sales is… | Marta'). Used once or twice, it makes people listen; used all the time, it sounds theatrical."],"spanish":"Spanish gives syllables a more even length, so Spanish speakers often say an aside at the same speed, pitch and volume as the main message, and listeners lose the thread. Fix: compress the aside (weak forms, fewer stresses, lower pitch), pause briefly on both sides, then pick up the main sentence at your old pitch.","ex":[{"t":"My boss, who never reads emails, asked again.","how":"my BOSS | (who never reads emails) | asked a↘GAIN","note":"aside: quicker and lower, between two pauses"},{"t":"The results, to be fair, weren't that bad.","how":"the reSULTS | (to be fair) | weren't ↘THAT bad","note":"a comment aside"},{"t":"Carlos, our new designer, will present the ideas.","how":"CARlos | (our new deSIGNer) | will preSENT the i↘DEAS","note":"a name, then who he is"},{"t":"It was, and I'm not exaggerating, the longest meeting of my life.","how":"it WAS | (and i'm not ig-ZAJ-uh-ray-ting) | the LONGest MEETing of my ↘LIFE","note":"an aside about the speaker"},{"t":"We need this done. Today.","how":"we need this ↘DONE | ↘TO-DAY","note":"a separate word, slow and heavy"},{"t":"He's late. Every. Single. Time.","how":"he's ↘LATE | ↘EV-ery | ↘SIN-gle | ↘TIME","note":"slow, separate words = strong emphasis"},{"t":"And the new head of sales is… Marta.","how":"and the new head of SALES is | … | ↘MARta","note":"a pause for effect before the key word"},{"t":"Look, I'll say this once: the data is wrong.","how":"↘LOOK | i'll say this ↘ONCE | the DAta is ↘WRONG","note":"short pauses before the point"}],"listen":[{"q":"What is the main message?","say":"My boss, who by the way never reads emails, asked me again.","o":["My boss never reads emails.","My boss asked me again.","I asked my boss again."],"a":1,"why":"The part between the pauses is an aside; the main line is 'My boss… asked me again.'"},{"q":"Which sentence do you hear? Listen for pauses.","o":["My sister, who lives in Toronto, is a nurse.","My sister who lives in Toronto is a nurse."],"pick":true,"why":"With pauses, the who-part is an aside (one sister). With no pauses, it says which sister (there is more than one)."},{"q":"Did all the employees get a bonus?","say":"The employees who worked late got a bonus.","o":["Yes, all of them.","No, only the ones who worked late."],"a":1,"why":"No pauses around 'who worked late': it picks out which employees. With pauses (an aside) it would mean all of them."},{"q":"What does the pause build up to?","say":"And the person who found the mistake was… the intern.","o":["the person","the mistake","the intern"],"a":2,"why":"A pause just before the key information creates suspense: was | … | the INtern."},{"q":"Which word completes the main sentence after the aside?","say":"This is not, and I want to be very clear about this, optional.","o":["clear","this","optional"],"a":2,"why":"The aside interrupts 'This is not… optional'; the main line comes back after the second pause."},{"q":"Which word does the speaker isolate for emphasis?","say":"We need this finished. Today. Not tomorrow.","o":["need","this","today"],"a":2,"why":"TODAY is said as its own short chunk, slowly, with a full fall: that is emphasis through tempo."},{"q":"Which part would a speaker say quicker and lower?","say":"The meeting, as far as I know, has been moved to Thursday.","o":["The meeting","as far as I know","moved to Thursday"],"a":1,"why":"'as far as I know' is a comment aside, so it is compressed; the main line is 'The meeting has been moved to Thursday.'"},{"q":"What does the aside add?","say":"Honestly, and I'm not just saying this, it was the best talk of the day.","o":["A new fact about the talk","The speaker's sincerity","A change of topic"],"a":1,"why":"'and I'm not just saying this' comments on the speaker's own honesty; the main line is about the talk."}],"mark":[{"mode":"find","q":"Tap all the words of the aside (the part said quicker and lower).","w":["My","boss,","who","never","reads","emails,","asked","again."],"a":[2,3,4,5],"why":"My BOSS | (who never reads emails) | asked aGAIN."},{"mode":"link","q":"Tap where the words link. The commas are pauses: words don't link across a pause.","w":["Then,","out","of","nowhere,","a","man","ran","in."],"a":[1,6],"why":"out_of → 'OU-dov' and ran_in → 'ra-NIN'. After Then and nowhere there are pauses, so no linking (not even the r of nowhere)."},{"mode":"stress","q":"'So the training is optional, right?' Tap the word the speaker slows down on and stresses most in the reply.","w":["This","is","not","optional."],"a":[2],"why":"This is ↘NOT optional: optional is already known, so the slow, heavy stress goes on NOT."},{"mode":"stress","q":"Slowing down for emphasis: tap the three words said one by one.","w":["He's","late.","Every.","Single.","Time."],"a":[2,3,4],"why":"he's LATE | EV-ery | SIN-gle | TIME: each word is its own chunk, with a pause after it."},{"mode":"find","q":"Tap all the words of the aside.","w":["Is","it,","and","be","honest,","a","good","idea?"],"a":[2,3,4],"why":"Is it | (and be honest) | a good i↗DEA? The question goes on after the aside."}],"dict":[{"say":"My boss, who by the way never reads emails, asked me for the report again.","a":"My boss, who by the way never reads emails, asked me for the report again.","how":"my BOSS | who-by-the-way-never-reads-EMAILS | asked me for the rePORT aGAIN","why":"the aside is quick and low between two pauses; the main sentence comes back at its old pitch."},{"say":"The new system, as far as I can tell, is actually slower than the old one.","a":"The new system, as far as I can tell, is actually slower than the old one.","how":"the new SYStem | as-far-as-i-can-TELL | is ACtually SLOWer than the ↘OLD one","why":"a comment aside, compressed; one is weak at the end: 'the OLD wun'."},{"say":"And the person who finally fixed the problem was… the intern.","a":"And the person who finally fixed the problem was the intern.","alt":["And the person who finally fixed the problem was… the intern."],"how":"and the PERson who FInally fixed the PROBlem was | … | the ↘INtern","why":"a pause for effect just before the key information."},{"say":"We tried it once, and only once, and it was a total disaster.","a":"We tried it once, and only once, and it was a total disaster.","how":"we TRIED it ↘ONCE | and ↘ON-ly ↘ONCE | and it was a TOtal dis↘ASter","why":"'and only once' is slowed down, with heavy stress on both words, framed by pauses."},{"say":"This is, and I can't stress this enough, a very strict deadline.","a":"This is, and I can't stress this enough, a very strict deadline.","alt":["This is, and I can not stress this enough, a very strict deadline."],"how":"this IS | and-i-can't-STRESS-this-enough | a VERy strict ↘DEADline","why":"the speaker holds is, adds a quick aside, then returns to the main line at the same pitch."}],"tip":"In class: give pairs a plain sentence ('The meeting was moved to Friday') and a card with an aside ('believe it or not', 'and this is the funny part'); they insert it quicker and lower, and the class repeats only the main sentence."},{"id":"c2-3","lv":"C2","n":3,"title":"D'you, whatcha, I'unno: extreme casual speech","focus":"reduction","goal":"Understand very fast casual forms like d'you, whatcha, I'unno, you gonna, s'go and howdja, and know when (not) to use them.","explain":["Among friends, Americans squeeze frequent chunks until only a trace is left. Do you → d'you or d'ya; what are you → whatcha; how did you → howdja; are you going to → you gonna (the are disappears); let's go → s'go; I don't know → I'unno, where most consonants vanish but the three-beat tune remains. You hear these in series, podcasts and casual chats every day.","The stressed words survive, so rebuild the grammar from them. Look at the verb: an -ing form points to are you (whatcha DOIN'?), a bare verb to do you (d'you WANT one?), and a past context to did you (howdja KNOW?). In the fastest speech did you and do you can sound almost the same, so the context decides.","These forms are mainly for listening. Use them only in very relaxed moments with people you know well, and never write them at work. In a meeting, normal fast speech (d'you, gonna) is fine, but I'unno or s'go would sound careless."],"spanish":"Spanish speakers usually listen for every word, so when are, did or don't almost vanish, the whole question is lost; when speaking, they use full forms and can sound stiff with friends. Fix: anchor on the stressed verb, rebuild the question around it, and learn the chunks as single words (whatcha, howdja).","ex":[{"t":"Do you want some?","how":"d'you WANT some?","note":"do you → d'you: one quick syllable"},{"t":"What are you doing?","how":"whatcha ↘DOIN'?","note":"what are you → whatcha"},{"t":"I don't know.","how":"i'unno (three quick syllables, almost hummed)","note":"the d and the t vanish; the tune stays"},{"t":"Are you going to eat that?","how":"you gonna EAT that?","note":"are disappears; going to → gonna"},{"t":"Let's go.","how":"s'↘GO","note":"let's → just the s"},{"t":"How did you know?","how":"HOWdja ↘KNOW?","note":"how did you → howdja"},{"t":"What do you want to do?","how":"whaddaya wanna ↘DO?","note":"what do you → whaddaya (a bare verb follows)"},{"t":"I don't know what you're talking about.","how":"i'UNno whatcher ↘TALKin' about","note":"what you're → whatcher"}],"listen":[{"q":"Which question do you hear?","o":["What are you working on?","What do you work on?"],"pick":true,"why":"'Whatcha WORKin' on?' (are you + -ing) vs 'Whaddaya WORK on?' (do you + bare verb): the verb form tells you which."},{"q":"Which question do you hear?","o":["Are you gonna stay?","Do you wanna stay?"],"pick":true,"why":"'You gonna STAY?' (a plan) vs 'D'you wanna STAY?' (a wish). The first words almost vanish, so hold on to gonna vs wanna."},{"q":"Which question do you hear?","o":["How did you find out?","How do you find out?"],"pick":true,"why":"how did you → 'howdja', how do you → 'how d'ya'. In very fast speech they can sound almost the same, so the context (past or general) is the real clue."},{"q":"Which casual version is the same sentence?","say":"I don't know what you're talking about.","o":["I'unno whatcher talkin' about.","I'unno whatcha talked about.","I know whatcher talkin' about."],"a":0,"why":"I don't know → I'unno; what you're → 'whatcher'. The second is past (talked); the third means the opposite (I know)."},{"q":"Which casual version is the same sentence?","say":"Do you think she'll mind?","o":["D'you think she'll mind?","Didja think she'd mind?","Don'tcha think she'll mind?"],"a":0,"why":"do you → d'you, one quick syllable. Didja = did you; don'tcha = don't you."},{"q":"Which part can shrink to 's'go' in very fast speech?","say":"Let's go, the taxi's waiting outside.","o":["Let's go","the taxi's","outside"],"a":0,"why":"let's go → s'GO: the le- disappears and only the s is left before go."},{"q":"In very fast speech, which word often disappears completely?","say":"Are you going to need the car tonight?","o":["are","need","car"],"a":0,"why":"'You gonna NEED the CAR tonight?': are drops out; the content words always stay."},{"q":"Which casual version is the same sentence?","say":"What are you going to do about it?","o":["Whatcha gonna do about it?","Whaddaya wanna do about it?","Whatcha gotta do about it?"],"a":0,"why":"what are you → whatcha; going to → gonna. Whaddaya wanna = what do you want to; whatcha gotta = what have you got to."}],"mark":[{"mode":"find","q":"Tap the words a relaxed speaker squeezes into 'whatcha'.","w":["So","what","are","you","doing","later?"],"a":[1,2,3],"why":"what are you → whatcha: 'So whatcha DOIN' later?'"},{"mode":"find","q":"Tap the words a relaxed speaker squeezes into 'I'unno'.","w":["Honestly,","I","don't","know","yet."],"a":[1,2,3],"why":"I don't know → I'unno: the consonants go, the three-beat tune stays."},{"mode":"find","q":"Tap the words hidden in 'howdja'.","w":["So","how","did","you","two","meet?"],"a":[1,2,3],"why":"how did you → howdja: 'So HOWdja two MEET?'"},{"mode":"weak","q":"Tap the word so weak that it disappears completely.","w":["Are","you","going","to","tell","her?"],"a":[0],"why":"'You gonna TELL 'er?': are vanishes, going to → gonna, her → ''er'."},{"mode":"stress","q":"Even in very fast speech, the content words stay clear. Tap the two stressed words.","w":["Are","you","going","to","need","the","car?"],"a":[4,6],"why":"'You gonna NEED the CAR?': everything else is squeezed between the two stresses."}],"dict":[{"say":"What are you going to do if they say no?","a":"What are you going to do if they say no?","alt":["What are you gonna do if they say no?"],"how":"whatcha gonna DO if they say ↘NO?","why":"what are you → whatcha; going to → gonna."},{"say":"Do you know if the store is still open?","a":"Do you know if the store is still open?","alt":["Do you know if the store's still open?"],"how":"d'you KNOW if the STORE's still OPen?","why":"do you → d'you (one syllable); store is → store's."},{"say":"I don't know, I haven't really thought about it yet.","a":"I don't know, I haven't really thought about it yet.","how":"i'unno | i HAV-n REE-lee THAW-duh-bou-dit ↘YET","why":"I don't know → I'unno; thought about it → 'THAW-duh-bou-dit' with flap t's."},{"say":"How did you manage to finish it so quickly?","a":"How did you manage to finish it so quickly?","how":"HOWdja MANage ta FINish it so ↘QUICKly?","why":"how did you → howdja; to → 'ta'."},{"say":"Let's go, we're going to miss the start of the movie.","a":"Let's go, we're going to miss the start of the movie.","alt":["Let's go, we're gonna miss the start of the movie."],"how":"s'GO | we're gonna MISS the STAR-duh-the ↘MOVie","why":"let's go → s'go; we're going to → we're gonna; start of the → 'STAR-duh-the'."}],"tip":"In class: the teacher fires quick casual questions ('Whatcha doin' later?', 'Howdja get here?'); students write the full form on mini whiteboards, then answer naturally."},{"id":"c2-4","lv":"C2","n":4,"title":"Pick it UP, pick UP the kids: stress in multi-word verbs","focus":"stress","goal":"Stress multi-word verbs and the nouns made from them correctly: pick it UP, pick up the KIDS, a BREAKdown.","explain":["Phrasal verbs (verb + adverb particle) stress the particle, and at the end of a phrase it carries the main stress: break DOWN, give UP, it set us BACK. A pronoun object goes in the middle and stays weak, so the particle is still the peak: pick it UP, look it UP, put it OFF.","With a noun object, the noun normally takes the main stress, but the particle keeps a clear stress and a full vowel: pick UP the KIDS, put OFF the MEETing. Prepositions are different: in look at, look for or listen to, the small word is weak and the verb is stressed: I'm LOOKing for it ('fer it').","Turn the verb into a noun and the stress jumps to the front: a BREAKdown, a WALKout, a SETback, a TAKEover, a LAYoff, a WORKout, a BACKup, a FOLLOW-up. This front stress is how listeners tell 'We need a BACKup' from 'We need to back UP'."],"spanish":"Spanish speakers tend to stress the verb and swallow the particle ('PICK it up'), or give every word equal weight, which hides the meaning, since the particle often carries it (pick up vs pick out). Fix: hit the particle, keep the pronoun tiny, and move the stress to the front for the noun: a BREAKdown.","ex":[{"t":"There was a breakdown.","how":"there was a ↘BREAKdown","note":"noun: stress the first part"},{"t":"My car broke down.","how":"my CAR broke ↘DOWN","note":"verb: stress the particle"},{"t":"Pick it up.","how":"pick it ↘UP ('pi-ki-DUP')","note":"pronoun in the middle → the particle is the peak"},{"t":"I have to pick up the kids.","how":"i HAFta pick UP the ↘KIDS","note":"noun object: it takes the main stress; up stays strong"},{"t":"It was a major setback.","how":"it was a MAjor ↘SETback","note":"noun: SET-back"},{"t":"Don't let it set you back.","how":"don't let it set you ↘BACK","note":"verb: set BACK"},{"t":"Just look it up.","how":"just look it ↘UP ('loo-ki-DUP')","note":"up is an adverb particle: stressed"},{"t":"I'm looking for it.","how":"i'm ↘LOOKing fer it","note":"for is a preposition: weak, and the verb takes the stress"}],"listen":[{"q":"Where is the stress?","say":"setback","o":["SET-back","set-BACK"],"a":0,"why":"A noun from a phrasal verb: the stress goes on the first part, SET-back."},{"q":"Where is the stress?","say":"takeover","o":["TAKE-o-ver","take-O-ver","take-o-VER"],"a":0,"why":"TAKE-o-ver (noun); the verb is take O-ver."},{"q":"Which sentence do you hear?","o":["We need a backup.","We need to back up."],"pick":true,"why":"a BACKup (noun: stress first) vs back UP (verb: stress on the particle)."},{"q":"Which sentence do you hear?","o":["It's a great workout.","It'll work out great."],"pick":true,"why":"a WORKout (noun: stress first) vs work OUT (verb: the particle is stressed)."},{"q":"Where is the stress in 'layoffs'?","say":"The company announced more layoffs.","o":["LAY-offs","lay-OFFS"],"a":0,"why":"LAY-offs: a noun, so the first part is stressed. The verb is lay OFF."},{"q":"Which word carries the main stress?","say":"I'll look it up.","o":["look","it","up"],"a":2,"why":"look it UP: the pronoun is weak, so the particle at the end is the peak."},{"q":"Which word is weak?","say":"I'm looking for my keys.","o":["looking","for","keys"],"a":1,"why":"for is a preposition here, so it is weak ('fer'). Adverb particles like up, out and off are stressed."},{"q":"Which word carries the main stress?","say":"We had to put off the meeting.","o":["put","off","meeting"],"a":2,"why":"With a noun object the noun takes the main stress (MEETing); off keeps a clear stress, never weak."}],"mark":[{"mode":"stress","q":"The noun 'a breakdown': tap the stressed syllable.","w":["break","down"],"word":true,"a":[0],"why":"BREAK-down: nouns from phrasal verbs stress the first part."},{"mode":"stress","q":"The noun 'a takeover': tap the stressed syllable.","w":["take","o","ver"],"word":true,"a":[0],"why":"TAKE-o-ver, not take-O-ver (that's the verb)."},{"mode":"stress","q":"Tap the word with the main stress.","w":["Don't","let","it","set","you","back."],"a":[5],"why":"don't let it set you BACK: a verb + pronoun + particle, so the particle is the peak."},{"mode":"find","q":"Tap the two particles (they carry the stress).","w":["Take","it","out,","then","put","it","back."],"a":[2,6],"why":"take it OUT | then put it BACK: the pronouns stay weak, the particles are the peaks."},{"mode":"stress","q":"Tap the word with the main stress.","w":["I","need","to","pick","up","the","kids."],"a":[6],"why":"pick UP the KIDS: the noun object takes the main stress; up keeps a clear, secondary stress."}],"dict":[{"say":"The strike turned into a walkout when the talks broke down.","a":"The strike turned into a walkout when the talks broke down.","how":"the STRIKE turned into a WALKout when the TALKS broke ↘DOWN","why":"WALKout (noun: stress first) vs broke DOWN (verb: stress on the particle)."},{"say":"Losing the contract was a setback, but it won't set us back for long.","a":"Losing the contract was a setback, but it won't set us back for long.","how":"LOSing the CONtract was a SETback | but it won't set us BACK for ↘LONG","why":"SETback (noun) vs set us BACK (verb, pronoun in the middle)."},{"say":"If you don't know the word, just look it up online.","a":"If you don't know the word, just look it up online.","how":"if you don't KNOW the word | just look it UP on↘LINE","why":"look it UP: the pronoun links and stays weak ('loo-ki-DUP')."},{"say":"Can you pick up the kids after the meeting?","a":"Can you pick up the kids after the meeting?","how":"can you pick UP the KIDS after the ↘MEETing?","why":"noun object: KIDS is strongly stressed and up keeps its stress."},{"say":"After the takeover, they laid off half the sales team.","a":"After the takeover, they laid off half the sales team.","how":"after the TAKEover | they laid OFF HALF the ↘SALES team","why":"TAKEover (noun: stress first) vs laid OFF (verb + particle); SALES team is a compound."}],"tip":"In class: call out a noun or a verb ('a backup!', 'back it up!'); students clap on the stressed part, then make a work sentence that uses both forms."},{"id":"c2-5","lv":"C2","n":5,"title":"Their, there, they're: homophones in fast speech","focus":"sounds","goal":"Decode homophones like their, there and they're in fast speech and write the right one from the context.","explain":["Homophones sound exactly the same but differ in spelling and meaning. In American English their, there and they're are all 'thair'; would and wood rhyme with good; allowed and aloud are 'uh-LOUD'; right and write are 'rite'; sight, site and cite are 'site'; principal and principle are 'PRIN-suh-pul'. For most Americans weather and whether are also identical, because wh is just w.","Fast speech makes it harder: their, there and they're often weaken to 'thr', and would can shrink to 'wuhd' or just a d (I'd like). You can't hear a difference, so decode with grammar and meaning: their + noun (their car); there + be or a place (there's, over there); they're + -ing or an adjective (they're late).","Use the same logic for the others: whether + a choice (whether or not); weather = rain and sun; allowed = permitted, aloud = out loud; principal = main, or the head of a school, principle = a rule or belief; cite = quote a source, site = a place or website, sight = vision or something you see."],"spanish":"Because Spanish spelling matches sound, learners expect different spellings to sound different, and in dictation they write the first spelling that comes to mind; many also stress principal like Spanish prin-ci-PAL. Fix: say each pair exactly the same (PRIN-suh-pul) and choose the spelling from the grammar around it.","ex":[{"t":"They're over there with their friends.","how":"thair OH-ver THAIR with thr ↘FRIENDS","note":"three spellings, one sound"},{"t":"I wonder whether the weather will change.","how":"i WONder weh-ther the WEH-ther'll ↘CHANGE","note":"the same sound for most Americans"},{"t":"I would, if I had the wood.","how":"i ↘WOULD | if i HAD the ↘WOOD","note":"strong would and wood sound the same (they rhyme with good)"},{"t":"You're not allowed to read it aloud.","how":"yer NOT uh-LOUD-tuh READ it uh-↘LOUD","note":"allowed = aloud"},{"t":"Write the right answer.","how":"RITE the RITE ↘ANswer","note":"write = right"},{"t":"Please cite the site you mentioned.","how":"please SITE the SITE you ↘MENtioned","note":"sight, site and cite are all 'site'"},{"t":"The principal explained the principle.","how":"the PRIN-suh-pul exPLAINED the ↘PRIN-suh-pul","note":"same sound; the grammar tells you which"},{"t":"Their idea is right there in the report.","how":"thair_i-DEE-uh is RITE THAIR in the re↘PORT","note":"the r links to a vowel: their_idea"}],"listen":[{"q":"Which sentence do you hear?","o":["They're over there.","They were over there."],"pick":true,"why":"they're usually sounds just like there ('thair'), one syllable; they were has two: 'thay-wer'."},{"q":"Which sentence do you hear?","o":["They lost their keys.","They lost the keys."],"pick":true,"why":"Weak their is 'thr', with an r sound; the is 'thuh', with no r."},{"q":"Which sentence do you hear?","o":["I'd like the window seat.","I like the window seat."],"pick":true,"why":"I'd like → 'aid-like': would shrinks to a quick d. With no d, it's a general preference, not a request."},{"q":"The two words sound the same. Which one fits?","say":"I'm not sure whether we'll make it.","o":["weather","whether"],"a":1,"why":"whether introduces a choice (… or not); weather is rain and sun. Most Americans say both as 'WEH-ther'."},{"q":"Which spellings are correct, in order?","say":"We weren't allowed to say the names aloud.","o":["allowed … aloud","aloud … allowed","aloud … aloud"],"a":0,"why":"weren't allowed (= permitted) to say them aloud (= out loud): both are 'uh-LOUD'."},{"q":"Which spelling fits?","say":"The principal reason is the cost.","o":["principal","principle"],"a":0,"why":"principal = main (an adjective here). principle is a noun: a rule or belief."},{"q":"Which spelling fits?","say":"Please cite your sources at the end.","o":["sight","site","cite"],"a":2,"why":"cite = quote or name a source; site = a place or website; sight = vision."},{"q":"Which spellings are correct, in order?","say":"They're bringing their laptops over there.","o":["They're … their … there","There … their … they're","Their … they're … there"],"a":0,"why":"They're + -ing (they are), their + noun (their laptops), there = a place (over there)."}],"mark":[{"mode":"find","q":"Tap every word that sounds like 'thair'.","w":["They're","sure","their","bags","are","over","there."],"a":[0,2,6],"why":"They're (they are), their (belonging to them), there (a place): one sound, three spellings."},{"mode":"link","q":"Tap where an r links to the next vowel.","w":["They're","over","there","in","their","office."],"a":[0,2,4],"why":"They're_over, there_in, their_office: American English keeps the r, and it joins the next vowel ('thai-ROH-ver')."},{"mode":"find","q":"Tap every word that sounds exactly like 'right'.","w":["Write","the","right","answer","right","now."],"a":[0,2,4],"why":"Write (put on paper), right (correct) and right (immediately) are all 'rite'."},{"mode":"find","q":"Tap the two words that sound exactly the same.","w":["Read","it","aloud","if","you're","allowed."],"a":[2,5],"why":"aloud (out loud) and allowed (permitted) are both 'uh-LOUD'."},{"mode":"stress","q":"'The principal reason…' Tap the stressed syllable.","w":["prin","ci","pal"],"word":true,"a":[0],"why":"PRIN-suh-pul, not Spanish prin-ci-PAL. principle has exactly the same stress and sound."}],"dict":[{"say":"They're worried their flight will be delayed, so they're staying there tonight.","a":"They're worried their flight will be delayed, so they're staying there tonight.","how":"thair WORried thr FLIGHT'll be deLAYED | so thair STAYing there to↘NIGHT","why":"they're, their and there all sound like 'thair' (or 'thr' when weak): the grammar tells you which to write."},{"say":"I'm not sure whether the weather will let us fly tomorrow.","a":"I'm not sure whether the weather will let us fly tomorrow.","how":"i'm not SURE weh-ther the WEH-ther'll LET us FLY to↘MORrow","why":"whether (a choice) and weather (rain and sun) sound the same for most Americans."},{"say":"Students aren't allowed to read their answers aloud during the exam.","a":"Students aren't allowed to read their answers aloud during the exam.","how":"STUdents AREN'T uh-LOUD-tuh READ thr ANswers uh-LOUD during the ex↘AM","why":"allowed (permitted) and aloud (out loud) are both 'uh-LOUD'; their is weak 'thr'."},{"say":"Make sure you cite every site you visited in your report.","a":"Make sure you cite every site you visited in your report.","how":"make SURE you CITE every SITE you VISited in your re↘PORT","why":"cite (name a source) and site (a website) are both 'site'."},{"say":"The principal said the main principle is respect for everyone.","a":"The principal said the main principle is respect for everyone.","how":"the PRIN-suh-pul SAID the MAIN PRIN-suh-pul is reSPECT for ↘EVeryone","why":"principal (the head of a school) and principle (a basic rule) sound exactly the same."}],"tip":"In class: dictate three fast sentences full of homophones ('They're sure their bags are over there'); pairs compare their spellings and justify each choice with a grammar clue."},{"id":"c2-6","lv":"C2","n":6,"title":"Decoding dialogue from films and series","focus":"reduction","goal":"Decode fast film and TV dialogue in which several reductions happen at once: gonna hafta, whaddaya, didja, y'know.","explain":["On screen, actors talk at real speed, so several features of connected speech pile up in a single line. 'I'm going to have to call you back' becomes 'I'm gonna hafta call ya back': going to → gonna, have to → hafta (the v turns into f before the t), you → ya. Each change is small, but together they can turn a sentence you know perfectly well into what sounds like one long new word.","Most of it follows a few patterns. Small words weaken: to → 'tuh', you → 'ya', and of loses its v → 'uh' (kinda, outta, a lotta). D or t + you becomes 'j' or 'ch': did you → didja, don't you → doncha. A t between vowels becomes a quick d, even across words: get out of → 'ge-DOW-duh', what are you → whaddaya. Unstressed him and them lose their first sound: tell 'em, ask 'im.","One spoken form can hide different words, so let the grammar decide. Whaddaya + base verb is what do you (Whaddaya want?), but whaddaya + -ing is what are you (Whaddaya doing?). 'Ya' is usually you, and 'yer' can be your or you're. Frequent chunks shrink the most: you know → y'know, because → 'cuz', kind of → kinda.","The strategy: don't chase every sound. Catch the stressed words first (WANT, DO, CALL, BACK), then rebuild the small words from the grammar. Watch a scene with English subtitles, then again without them. In writing, use the full forms: gonna and wanna belong only in very informal messages and in scripts."],"spanish":"Spanish vowels keep their full sound even in fast speech, so Spanish speakers expect to hear every written word, and a line like 'Whaddaya want me to do?' sounds like one unknown word. Fix: listen for the two or three stressed words first, then fill in the reduced ones from the grammar.","ex":[{"t":"I'm going to have to call you back.","how":"I'm gonna HAFta CALL ya BACK","note":"going to → gonna; have to → hafta (v → f); you → ya"},{"t":"What do you want me to do?","how":"whaddaya WANT me tuh DO?","note":"what do you → whaddaya; to → tuh"},{"t":"Did you see that?","how":"didja SEE that?","note":"d + you → j: didja"},{"t":"You know what I mean?","how":"y'know wha-dai MEAN?","note":"you know → y'know; what I → 'wha-dai' (quick d)"},{"t":"Tell them I'll be there in a minute.","how":"TEL-um I'll be THERE in uh MIN-it","note":"them → 'em: the th disappears"},{"t":"Why don't you just ask him?","how":"why DOHN-chuh just ASK-im?","note":"don't you → doncha; him → 'im (no h)"},{"t":"Give me a second, let me grab my jacket.","how":"GIM-me uh SEC-und | LEM-me GRAB my JACK-it","note":"give me → gimme; let me → lemme"},{"t":"I've got to get out of here before anyone sees me.","how":"I've GOT-tuh ge-DOW-duh HERE | beFORE ANyone SEES me","note":"got to → gotta; get out of → 'ge-DOW-duh' (quick d, of → uh)"}],"listen":[{"q":"Which line do you hear?","o":["I'm gonna have to call you back.","I'm gonna have you call me back."],"pick":true,"why":"'HAF-tuh CALL ya back' is have to call you back; 'have you call me' keeps the v: 'HAV-yuh'."},{"q":"Which question do you hear?","o":["What do you want me to do?","What did you want me to do?"],"pick":true,"why":"Whaddaya is what do you; what did you shrinks to 'whad-didja' or 'whadja'."},{"q":"Which question do you hear?","o":["Did you see that?","Do you see that?"],"pick":true,"why":"Did you gives a 'j' sound (didja); do you is just 'd'yuh'."},{"q":"Which line do you hear?","o":["Tell them I'm busy.","Tell him I'm busy."],"pick":true,"why":"In fast speech them → 'em ('TEL-um') and him → 'im ('TEL-im'), so listen for the vowel."},{"q":"Which question do you hear?","o":["You know what I mean?","You know what I meant?"],"pick":true,"why":"Mean has a long ee; meant has a short e and ends in a t."},{"q":"'Whaddaya' can stand for two things. Which one is in this line?","say":"What are you doing after work?","o":["what do you","what are you"],"a":1,"why":"An -ing verb needs are: whaddaya doing = what are you doing."},{"q":"What do you hear after 'We're'?","say":"We're gonna have to leave early.","o":["going to have to","going to","have to"],"a":0,"why":"Gonna hafta = going to have to: in films you often hear both reductions in a row."},{"q":"What is the full form of this line?","say":"I've gotta get out of here.","o":["I've got to get out of here.","I got to get out here.","I've got to go out there."],"a":0,"why":"Gotta = got to; 'ge-DOW-duh HERE' = get out of here (quick d, of → uh)."}],"mark":[{"mode":"find","q":"Tap the words that merge into 'whaddaya'.","w":["What","do","you","want","me","to","do?"],"a":[0,1,2],"why":"What do you → 'whaddaya': the t of what melts into the d of do, then do → 'duh' and you → 'yuh'."},{"mode":"find","q":"Tap the words that become 'gonna hafta'.","w":["I'm","going","to","have","to","call","you","back."],"a":[1,2,3,4],"why":"going to → gonna; have to → hafta. Four words, two quick chunks."},{"mode":"link","q":"Tap where the words join. (In fast speech the h of him disappears.)","w":["I'll","pick","him","up","at","eight."],"a":[1,2,3,4],"why":"pick_'im_up_at_eight → 'PI-ki-MUH-puh-DATE': no h, and the t of at becomes a quick d."},{"mode":"link","q":"Tap where the words join.","w":["Get","out","of","my","way!"],"a":[0,1],"why":"Get_out_of → 'ge-DOW-duh': t + vowel becomes a quick d, and of loses its v before my."},{"mode":"weak","q":"Tap the three words that shrink to a quick 'uh'.","w":["I","kind","of","need","a","lot","of","help."],"a":[2,4,6],"why":"kind of → 'KINE-duh', a → 'uh', lot of → 'LAH-duh': 'I KINE-duh NEED uh LAH-duh HELP'."}],"dict":[{"say":"I'm gonna have to call you back, my boss just walked in.","a":"I'm going to have to call you back, my boss just walked in.","alt":["I'm gonna have to call you back, my boss just walked in."],"how":"I'm gonna HAFta CALL ya BACK | my BOSS just WALK-tin","why":"gonna (going to), hafta (have to: v → f), ya (you); walked_in links: 'WALK-tin'."},{"say":"What do you want me to do, just sit here and wait?","a":"What do you want me to do, just sit here and wait?","how":"whaddaya WANT me tuh DO | just SIT here 'n WAIT?","why":"what do you → whaddaya; to → tuh; and → 'n."},{"say":"Did you see that? He just walked out of the meeting without a word.","a":"Did you see that? He just walked out of the meeting without a word.","how":"didja SEE that? | he just WALK-tow-duh the MEETing with-OW-duh WORD","why":"did you → didja; walked_out_of → 'WALK-tow-duh' (linking, quick d, of → uh); without a → 'with-OW-duh'."},{"say":"I kinda wanted to tell them first, you know what I mean?","a":"I kind of wanted to tell them first, you know what I mean?","alt":["I kinda wanted to tell them first, you know what I mean?"],"how":"i KINE-duh WAN-nid tuh TEL-um FIRST | y'know wha-dai MEAN?","why":"kind of → kinda; wanted → 'WAN-nid' (the t after n disappears); them → 'em; you know → y'know."},{"say":"You've got to give them a chance, they're doing a lot of good work.","a":"You've got to give them a chance, they're doing a lot of good work.","how":"you've GOT-tuh GIV-um uh CHANCE | they're DOin' uh LAH-duh GOOD WORK","why":"got to → gotta; give them → 'GIV-um'; doing → doin'; a lot of → 'uh LAH-duh'."}],"tip":"In class: play a 20-second scene from a series twice; students write down only the stressed words they catch, rebuild the full lines in pairs, and then check with the subtitles."},{"id":"c2-7","lv":"C2","n":7,"title":"Genre, entrepreneur, Worcestershire: loanwords and names","focus":"sounds","goal":"Pronounce common loanwords and tricky place names the way Americans say them, not the way they are spelled.","explain":["English borrows freely and often keeps part of the original sound, so spelling is a poor guide. From French, three patterns are common: g or j can sound like 'zh' /ʒ/, as in measure (genre ZHAHN-ruh, beige, déjà vu); ch often sounds like 'sh' (chef, machine, brochure, even Chicago and Michigan); and the stress often moves to the end, where final letters may be silent (ballet ba-LAY, buffet buh-FAY, cliché klee-SHAY).","But don't assume that French means final stress. Entrepreneur ends strong (ahn-truh-pruh-NUR), while rendezvous (RAHN-day-voo) and genre start strong. Facade (also spelled façade) has just two syllables, fuh-SAHD, and déjà vu is day-zhah VOO. Quinoa, which reached English from Quechua through Spanish, is KEEN-wah. UK note: British English often moves the stress forward: CLEE-shay, BAL-ay, CAF-ay.","Place names keep old spellings long after the sounds have worn away. Many English towns ending in -cester lose letters: Leicester is LES-ter and Worcester is WUSS-ter, so Worcestershire sauce is WUSS-ter-sher. Some US states keep a French silent s: Illinois (il-ih-NOY) and Arkansas (AR-kun-saw), while Kansas keeps its s (KAN-zus). Spanish-origin names are anglicized too: Florida is FLOR-ih-duh, and Los Angeles has a 'j' sound.","With a new name, don't guess from the spelling: check a dictionary with audio, or simply ask ('Sorry, how do you pronounce your company's name?'). Getting names right, whether clients, cities or dishes, is a small sign of respect that people notice."],"spanish":"Spanish speakers tend to read loanwords letter by letter, the Spanish way: 'gen-re' with a Spanish g, 'fa-ca-de', 'qui-no-a' with three syllables, 'ar-kan-SAS'. Fix: learn each one as a sound unit, the way you learn a person's name, and check its stress and silent letters before using it at work.","ex":[{"t":"Every movie in that genre is full of clichés.","how":"EVery MOVie in that ZHAHN-ruh is FULL of klee-SHAYZ","note":"genre: 'zh' as in measure; cliché: US stress at the end (UK: CLEE-shay)"},{"t":"She's a very successful entrepreneur.","how":"she's a VERy sukSESSful ahn-truh-pruh-NUR","note":"4 syllables, main stress on the last one"},{"t":"They restored the old facade of the building.","how":"they reSTORED the OLD fuh-SAHD of the BUILDing","note":"2 syllables: the c sounds like s, the final e is silent"},{"t":"I had a strange feeling of déjà vu.","how":"i had a STRANGE FEELing of day-zhah VOO","note":"j = 'zh'; main stress on VOO"},{"t":"Can I get the quinoa salad, please?","how":"can i GET the KEEN-wah SALad, PLEASE?","note":"2 syllables: KEEN-wah"},{"t":"Let's rendezvous at the hotel at nine.","how":"let's RAHN-day-voo at the hoTEL at NINE","note":"the z and the s are silent; stress on RAHN"},{"t":"Add a little Worcestershire sauce to the burgers.","how":"ADD a little WUSS-ter-sher SAUCE to the BURgers","note":"Worcester = WUSS-ter; -shire = a quick 'sher'"},{"t":"She grew up in Illinois, studied in Leicester, and now lives in Arkansas.","how":"she grew UP in il-ih-NOY | STUdied in LES-ter | and NOW lives in AR-kun-saw","note":"silent s in Illinois and Arkansas; Leicester sounds like Lester"}],"listen":[{"q":"Which word do you hear?","o":["valet","ballet"],"pick":true,"why":"Valet starts with v (top teeth on the lower lip); ballet starts with b (both lips) and ends in a silent t: ba-LAY."},{"q":"Which word do you hear?","o":["suite","suit"],"pick":true,"why":"Suite (a set of hotel rooms) sounds like sweet; suit rhymes with boot."},{"q":"Which state do you hear?","o":["Kansas","Arkansas"],"pick":true,"why":"Kansas is KAN-zus; Arkansas is AR-kun-saw, with a silent final s: the names don't rhyme."},{"q":"Which syllable has the main stress?","say":"entrepreneur","o":["EN-tre-pre-neur","en-TRE-pre-neur","en-tre-PRE-neur","en-tre-pre-NEUR"],"a":3,"why":"ahn-truh-pruh-NUR: the main stress is on the last syllable."},{"q":"What sound does 'genre' start with?","say":"genre","o":["'zh', as in measure","'j', as in job","'h', like the Spanish g in 'género'"],"a":0,"why":"ZHAHN-ruh: genre keeps the French 'zh' sound."},{"q":"Which word rhymes with the name you hear?","say":"Leicester","o":["jester","toaster","sister"],"a":0,"why":"Leicester is LES-ter: the 'ice' in the middle is silent, so it rhymes with jester."},{"q":"Which syllable of 'cliché' is stressed?","say":"Honestly, the ending was a total cliché.","o":["CLEE-shay","clee-SHAY"],"a":1,"why":"American English stresses the end: clee-SHAY (British speakers often say CLEE-shay)."},{"q":"Do you hear an s or z sound at the end of 'Illinois'?","say":"Chicago is the biggest city in Illinois.","o":["No: il-ih-NOY","Yes: il-ih-NOYZ"],"a":0,"why":"The final s of Illinois is silent, as in many French spellings."}],"mark":[{"mode":"stress","word":true,"q":"Tap the stressed syllable.","w":["ren","dez","vous"],"a":[0],"why":"RAHN-day-voo: in American English the stress is at the start, and the z and s are silent."},{"mode":"stress","word":true,"q":"Tap the stressed syllable.","w":["fa","cade"],"a":[1],"why":"fuh-SAHD: two syllables; the c sounds like s and the final e is silent."},{"mode":"find","q":"Tap the words with a 'zh' sound, as in measure.","w":["genre","general","beige","collage","giant","measure"],"a":[0,2,3,5],"why":"genre, beige, collage and measure have 'zh'; general and giant have 'j', as in job."},{"mode":"find","q":"Tap the words with a silent final s.","w":["Illinois","Kansas","Arkansas","Texas","rendezvous","Paris"],"a":[0,2,4],"why":"il-ih-NOY, AR-kun-saw, RAHN-day-voo. Kansas, Texas and Paris (in English) keep their s."},{"mode":"find","q":"Tap the words where ch sounds like 'sh'.","w":["chef","cheese","Chicago","machine","chicken","brochure","Michigan"],"a":[0,2,3,5,6],"why":"chef, shih-KAH-go, ma-SHEEN, bro-SHOOR, MISH-ih-gun come from French spellings; cheese and chicken have a normal 'ch'."}],"dict":[{"say":"My favorite genre is science fiction, even though it's full of clichés.","a":"My favorite genre is science fiction, even though it's full of clichés.","alt":["My favorite genre is science fiction, even though it's full of cliches."],"how":"my FAvorite ZHAHN-ruh is SCIence FICtion | even though it's FULL of klee-SHAYZ","why":"genre starts with 'zh'; cliché is stressed at the end in American English."},{"say":"The young entrepreneur wants to restore the facade and open a quinoa restaurant.","a":"The young entrepreneur wants to restore the facade and open a quinoa restaurant.","alt":["The young entrepreneur wants to restore the façade and open a quinoa restaurant."],"how":"the YOUNG ahn-truh-pruh-NUR wants to reSTORE the fuh-SAHD and OPen a KEEN-wah RESTaurant","why":"entrepreneur: stress at the end; facade: 2 syllables; quinoa: KEEN-wah."},{"say":"I had a strange feeling of déjà vu when we arrived in Leicester.","a":"I had a strange feeling of déjà vu when we arrived in Leicester.","alt":["I had a strange feeling of deja vu when we arrived in Leicester."],"how":"i had a STRANGE FEELing of day-zhah VOO when we arRIVED in LES-ter","why":"déjà vu: 'zh' and stress on VOO; Leicester: two syllables, LES-ter."},{"say":"Could you pass me the Worcestershire sauce for the burgers, please?","a":"Could you pass me the Worcestershire sauce for the burgers, please?","how":"could you PASS me the WUSS-ter-sher SAUCE for the BURgers, PLEASE?","why":"Worcestershire: three syllables, WUSS-ter-sher; most of the spelling is silent."},{"say":"She moved from Illinois to Arkansas to work for a tech startup.","a":"She moved from Illinois to Arkansas to work for a tech startup.","how":"she MOVED from il-ih-NOY to AR-kun-saw to WORK for a TECH STARTup","why":"Both states end in a silent s: il-ih-NOY, AR-kun-saw."}],"tip":"In class: students bring three names they need at work (clients, cities, brands, dishes); the group predicts the stress and the silent letters, then checks with a dictionary's audio."},{"id":"c2-8","lv":"C2","n":8,"title":"Telling a story: suspense, quotes and voices","focus":"intonation","goal":"Tell a story with a slow, low build-up, quotes in a different voice, and a punchline framed by a pause and a strong stress.","explain":["Good storytellers play with their voice to pull the listener in. In the build-up they slow down, drop the pitch and often the volume, and use short sentences with pauses: 'It was late. | The office was empty. | And then | I heard the door.' Slower and lower tells the listener: pay attention, something is coming. Casual stories often switch to the present tense for the same effect: 'So I'm walking home…'","Stories are full of quotes, and the voice marks them. Americans introduce quotes with goes, is like or is all: 'And he goes, \"No way!\"' 'So I'm like, \"Seriously?\"' The quotative is quick and unstressed; then, after a tiny break, you act the character: a higher or lower pitch, a different speed, the original emotion. A quoted yes/no question still rises, and an order or a shocked reaction falls.","The punchline is the payoff, so frame it with silence. Set it up, pause for a beat, then say the key word with a strong stress and a clear fall: 'And who was sitting in my seat? | My BOSS.' A question to the audience before the pause ('And guess what?') makes it even stronger. Don't rush the pause, don't fill it with 'um', and don't laugh before the punchline."],"spanish":"In a second language, many Spanish speakers focus on grammar and tell stories at one steady speed and pitch, often reporting speech with 'he said that…', so the suspense and the punchline get lost. You already act out quotes in Spanish ('y él me dice: ¡no!'), so do the same in English: slow down, change voice, pause.","ex":[{"t":"It was two in the morning. The house was completely silent.","how":"it was TWO in the MORNing ↘ | the HOUSE was comPLETEly SIlent ↘","note":"suspense: slower, lower, a pause between sentences"},{"t":"And then, out of nowhere, someone knocked on the door.","how":"and THEN | OUT of NOwhere | someone KNOCKED on the DOOR ↘","note":"a pause after 'and then' holds the listener"},{"t":"And he goes, 'No way!'","how":"and he goes | 'no WAY!' ↘","note":"'he goes' is quick; then act the quote"},{"t":"So I'm like, 'Are you serious?' and she's like, 'Totally.'","how":"so i'm like | 'are you SERious?' ↗ | and she's like | 'TOtally.' ↘","note":"two voices: a rising question, then a flat, sure answer"},{"t":"My boss looks at me and says, 'You're late. Again.'","how":"my BOSS LOOKS at me and says | 'you're LATE ↘ | aGAIN.' ↘","note":"present tense for drama; the pause makes 'again' sting"},{"t":"So who do you think was sitting in my seat? My boss.","how":"so WHO do you THINK was SITting in my SEAT? ↘ | my BOSS ↘","note":"set-up question, pause, punchline"},{"t":"I opened the envelope, and inside there was nothing. Absolutely nothing.","how":"i OPened the ENvelope | and inSIDE there was | NOTHing ↘ | ABsolutely NOTHing ↘","note":"a pause before the key word, then repeat it for effect"},{"t":"And you know what he said? 'I thought you knew.'","how":"and you KNOW what he SAID? ↘ | 'i THOUGHT you KNEW.' ↘","note":"a question to the listener, then the quote as the punchline"}],"listen":[{"q":"Which quote do you hear?","o":["And he goes, 'You're quitting?'","And he goes, 'You're quitting.'"],"pick":true,"why":"With a question mark the voice rises: he's shocked and asking; with a full stop it falls: he's stating a fact."},{"q":"How does the listener react?","o":["No way!","No way?"],"pick":true,"why":"No way! falls: pure amazement; No way? rises: 'Is that really true?'"},{"q":"Which version do you hear?","o":["And who was standing at the door? My ex.","And my ex was standing at the door."],"pick":true,"why":"The first is the storyteller's version: a set-up question, a pause, then a one-word punchline."},{"q":"This is the build-up of a story. How would a good storyteller say it?","say":"It was late, the street was empty, and I could hear footsteps behind me.","o":["Slower and lower, with short pauses","Faster and higher, like good news","Flat and quick, like reading a list"],"a":0,"why":"Suspense: slow down, lower the pitch and pause between the details."},{"q":"Which word tells you that a quote is coming?","say":"And my sister goes, 'I'm not paying for that!'","o":["goes","sister","paying"],"a":0,"why":"In casual stories goes (or is like) introduces a quote: that's where the voice changes."},{"q":"How many different people are quoted?","say":"So I'm like, 'What are you doing here?' and he's all, 'Surprise!'","o":["1","2","3"],"a":1,"why":"I'm like… and he's all… introduce two voices: the speaker's and his."},{"q":"Where should the storyteller make the longest pause?","say":"I opened the box, and inside there was nothing.","o":["before 'nothing'","after 'opened'","before 'box'"],"a":0,"why":"A pause right before the key word builds suspense; then 'nothing' gets a strong stress."},{"q":"How does the waiter's quoted question end?","say":"And the waiter looks at my plate and says, 'Are you sure?'","o":["↗ It rises: a yes/no question","↘ It falls: a wh- question"],"a":0,"why":"A quoted yes/no question keeps its rise, even inside the story."}],"mark":[{"mode":"find","q":"Tap the quotative words that warn you a new voice is coming.","w":["So","I'm","like,","Seriously?","And","he","goes,","Yep."],"a":[2,6],"why":"like and goes introduce the quotes: say them quickly, then switch voice."},{"mode":"find","q":"Tap the words you would say in the boss's voice.","w":["And","my","boss","goes,","Who","ate","my","lunch?"],"a":[4,5,6,7],"why":"The quote is 'Who ate my lunch?': act it out; 'And my boss goes' is the narrator's voice."},{"mode":"stress","q":"Tap the word with the main stress in the quote.","w":["And","he","goes,","You","did","what?"],"a":[5],"why":"You did WHAT? is an echo question: the wh-word gets a strong stress and a high pitch."},{"mode":"stress","q":"The punchline corrects the listener's guess. Tap the word with the main stress in the punchline.","w":["It","wasn't","a","bear.","It","was","my","neighbor."],"a":[7],"why":"It was my NEIGHBOR: the new, surprising word carries the stress and the fall."},{"mode":"stress","q":"Tap the word with the main stress in the punchline.","w":["And","who","was","waiting","at","the","door?","My","ex."],"a":[8],"why":"Question, pause, then my EX: the punchline word gets the strongest stress and a clear fall."}],"dict":[{"say":"So I'm standing in line, and this guy goes, 'Are you even listening?'","a":"So I'm standing in line, and this guy goes, 'Are you even listening?'","how":"so i'm STANDing in LINE | and this GUY goes | 'are you EVen LIStening?' ↗","why":"goes introduces the quote; the quoted yes/no question rises; even carries the annoyance."},{"say":"And then, just when we thought it was over, the lights went out again.","a":"And then, just when we thought it was over, the lights went out again.","how":"and THEN | just when we THOUGHT it was OVer | the LIGHTS went OUT aGAIN ↘","why":"Suspense: pauses after 'and then' and before the main clause, slower and lower."},{"say":"She looked me straight in the eye and said, 'You're fired.'","a":"She looked me straight in the eye and said, 'You're fired.'","how":"she LOOKED me STRAIGHT in the EYE and said | 'you're FIRED.' ↘","why":"Build-up, a short pause, then the quote in a cold, falling voice."},{"say":"So guess who was sitting at our table? My old boss.","a":"So guess who was sitting at our table? My old boss.","how":"so GUESS who was SITting at our TAble? ↘ | my old BOSS ↘","why":"A question to the listener, a pause, then the punchline with a strong stress."},{"say":"And he's like, 'Relax, it's just a scratch,' but the car was totally ruined.","a":"And he's like, 'Relax, it's just a scratch,' but the car was totally ruined.","how":"and he's like | 'reLAX | it's JUST a SCRATCH' | but the CAR was TOtally RUined ↘","why":"he's like introduces a calm, casual quote; then the narrator's voice returns for the twist."}],"tip":"In class: students tell a one-minute 'worst day at work' story twice, first flat, then with a slow build-up, one quote in a different voice and a pause before the punchline; partners say which version kept them listening."},{"id":"c2-9","lv":"C2","n":9,"title":"Rhetoric: the rule of three and the pause","focus":"rhythm","goal":"Deliver persuasive lines with triplets (rise, rise, fall), stressed contrasts and well-timed dramatic pauses.","explain":["Persuasive speakers rely on rhythm. The rule of three groups ideas in threes, often with the same structure: 'We will listen, we will learn, and we will lead.' Give each part the same beat: the repeated frame (we will) stays light, and the new word takes the stress: LISten, LEARN, LEAD. The pitch usually rises on the first two parts (more is coming) and falls on the third (that's it, the list is complete).","Antithesis puts two opposite ideas side by side: 'It's not what you SAY, it's what you DO.' The repeated frame (it's what you…) is said lightly, and the two contrasting words get the strongest stress. A small pause at the comma lets the first half land before the second half answers it. Common frames: not… but…, less… more…, we didn't come here to… we came here to…","The dramatic pause is silence used on purpose, usually just before the key word or right after a big claim: 'There's only one thing we can't afford to lose: | trust.' Hold it for a full second, keep eye contact, and don't fill it with 'um' or 'eh'. Then say the key word slowly, with a clear fall. One well-placed pause does more than ten fast sentences."],"spanish":"Spanish gives syllables a more even length, so in English speeches Spanish speakers often stress every word and the contrast words don't stand out; nerves also make them speed up and fill every silence with 'eh…'. Fix: keep the repeated words light, hit the contrasting words hard, and dare to stay silent for a second.","ex":[{"t":"We will listen, we will learn, and we will lead.","how":"we will LISten ↗ | we will LEARN ↗ | and we will LEAD ↘","note":"three parts, same beat: rise, rise, fall"},{"t":"Our service is fast, our prices are fair, and our people care.","how":"our SERvice is FAST ↗ | our PRICes are FAIR ↗ | and our PEOple CARE ↘","note":"a parallel triplet"},{"t":"This plan is simple, it's affordable, and it works.","how":"this PLAN is SIMple ↗ | it's afFORDable ↗ | and it WORKS ↘","note":"a short last part sounds final"},{"t":"Less talk, more action.","how":"LESS TALK | MORE ACtion ↘","note":"short antithesis: four strong beats"},{"t":"People judge you not by what you say, but by what you do.","how":"PEOple JUDGE you NOT by what you SAY | but by what you DO ↘","note":"antithesis with not… but…: stress the contrasting pair"},{"t":"We didn't come here to make promises. We came here to keep them.","how":"we DIDn't come here to MAKE promises | we came here to KEEP them ↘","note":"make and keep carry the contrast; 'them' stays weak"},{"t":"There's only one thing we can't afford to lose: trust.","how":"there's ONly ONE thing we CAN'T afFORD to LOSE || TRUST ↘","note":"a dramatic pause before the key word"},{"t":"And the result, after two very difficult years, is clear: we made it.","how":"and the reSULT | AFter two VERy DIFficult YEARS | is CLEAR || we MADE it ↘","note":"an aside, then a pause before the payoff"}],"listen":[{"q":"On which part does the voice fall to close the list?","say":"This team has the talent, the experience, and the will to win.","o":["the talent","the experience","the will to win"],"a":2,"why":"Rise, rise, fall: the fall on the last part tells the audience the list is complete."},{"q":"Which version do you hear?","o":["We will listen, we will learn, and we will lead.","We will listen, we will learn, we will lead."],"pick":true,"why":"The second drops 'and': that sounds even more forceful, as if the list could go on."},{"q":"How many parallel parts does this list have?","say":"We'll cut our costs, we'll train our people, and we'll grow our sales.","o":["2","3","4"],"a":1,"why":"Three parts with the same frame: we'll cut… we'll train… and we'll grow…"},{"q":"Which two words carry the contrast?","say":"It's not what you say that matters, it's what you do.","o":["say / do","not / it's","what / matters"],"a":0,"why":"The frame repeats, so the contrasting words, say and do, get the strongest stress."},{"q":"Which words carry the contrast?","say":"We didn't come here to talk about the problem. We came here to solve it.","o":["talk about / solve","problem / it","here / here"],"a":0,"why":"Problem and it are the same idea; the contrast is talking versus solving."},{"q":"Where would a skilled speaker make a dramatic pause?","say":"There's only one thing that can stop us now, and that's fear.","o":["before 'fear'","before 'only'","after 'There's'"],"a":0,"why":"Pause just before the key word, then say it with a strong fall."},{"q":"Which ideas are in contrast?","say":"Some people wait for change. Others make it happen.","o":["waiting for change / making it happen","people / change","change / it"],"a":0,"why":"Wait for and make it happen are the opposites, so they carry the stress."},{"q":"Which delivery fits this line best in a speech?","say":"Our goal is simple: better schools, better jobs, and better lives.","o":["a pause after 'simple', then rise, rise, fall","no pauses and the same pitch on all three","a strong fall on every 'better'"],"a":0,"why":"The colon invites a pause; then the triplet rises, rises, and falls on 'lives'."}],"mark":[{"mode":"stress","q":"Tap the three words that carry the beats of the triplet.","w":["We'll","listen,","we'll","learn,","and","we'll","lead."],"a":[1,3,6],"why":"we'll LISten ↗ | we'll LEARN ↗ | and we'll LEAD ↘: the frame stays light."},{"mode":"stress","q":"Tap the two words that carry the contrast.","w":["It's","not","what","you","say,","it's","what","you","do."],"a":[4,8],"why":"it's not what you SAY | it's what you DO: the repeated frame stays light."},{"mode":"stress","q":"'Clear' repeats in every part. Tap the three words that get the strongest stress.","w":["Clear","goals,","clear","roles,","clear","results."],"a":[1,3,5],"why":"The repeated word gets lighter; goals, roles and reSULTS carry the beat (rise, rise, fall)."},{"mode":"find","q":"A speaker pauses for drama just before the key word. Tap the key word.","w":["The","one","thing","we","can't","lose","is","trust."],"a":[7],"why":"The one thing we can't lose is || TRUST ↘: silence first, then the key word, slow and falling."},{"mode":"weak","q":"Tap the weak words that stay light between the beats.","w":["Better","for","you","and","better","for","the","planet."],"a":[1,3,5,6],"why":"for ('fer'), and ('n'), the ('thuh') stay quick: BETter for YOU | and BETter for the PLANet."}],"dict":[{"say":"We'll work harder, we'll work smarter, and we'll work together.","a":"We'll work harder, we'll work smarter, and we'll work together.","how":"we'll work HARDer ↗ | we'll work SMARTer ↗ | and we'll work toGETHer ↘","why":"Rule of three: the frame 'we'll work' stays light; harder, smarter, together take the beat: rise, rise, fall."},{"say":"It's not what you say that matters, it's what you do every day.","a":"It's not what you say that matters, it's what you do every day.","how":"it's NOT what you SAY that MATters | it's what you DO every DAY ↘","why":"Antithesis: say and do carry the contrast; a short pause at the comma."},{"say":"We didn't come here to make promises; we came here to keep them.","a":"We didn't come here to make promises; we came here to keep them.","how":"we DIDn't come here to MAKE promises | we came here to KEEP them ↘","why":"make versus keep carry the contrast; 'them' is old information, so it stays weak."},{"say":"There's only one thing that can stop this team, and that's fear.","a":"There's only one thing that can stop this team, and that's fear.","how":"there's ONly ONE thing that can STOP this TEAM | and that's || FEAR ↘","why":"A dramatic pause before the key word, then a slow, strong fall."},{"say":"Our clients want three things: speed, quality, and honesty, in that order.","a":"Our clients want three things: speed, quality, and honesty, in that order.","how":"our CLIents want THREE THINGS | SPEED ↗ | QUALity ↗ | and HONesty ↘ | in THAT ORder","why":"A pause at the colon, then a triplet: rise, rise, fall; the last phrase is an aside."}],"tip":"In class: give each student a product or a cause; they write one triplet, one 'not… but…' line and one line with a dramatic pause, then deliver them standing up while the group taps the table on every beat."}];
